window.SITUATIONAL = {"version":"2026-10-18","durationSeconds":3600,"pointsPerItem":0.5,"passScore":7,"distribution":{"L":5,"R":5,"B":4,"H":2,"P":2,"C":2},"resources":{"L":{"name":"Legea nr. 198/2023","url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"},"R":{"name":"ROFUIP · OME nr. 5.726/2024","url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"},"B":{"name":"Tony Bush · capitolele I–III","url":"https://ccecp.github.io/Bush_1/"},"H":{"name":"John Hattie · capitolul 9","url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/"},"P":{"name":"Profilul profesional · OMEC nr. 3.934/2026","url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"},"C":{"name":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},"tests":[{"id":1,"title":"Simularea 01","items":[{"id":"L01","theme":"L","prompt":"Un CA cu 11 membri este reconvocat legal pentru o hotărâre privind personalul care nu a putut fi adoptată. Sunt prezenți 7 membri și există 4 voturi pentru. Care este rezultatul?","options":["Hotărârea este adoptată, deoarece cele 4 voturi reprezintă majoritatea prezentă.","Hotărârea este amânată, fiind obligatorie încă o reconvocare pe aceeași regulă.","Ședința este nevalabilă, deoarece trebuiau prezenți minimum 8 membri.","Ședința este valabilă, dar adoptarea necesita minimum 5 voturi pentru."],"answer":3,"explanation":"La reconvocare, cvorumul este jumătate plus unu din cei 11 membri: minimum 6. Adoptarea cere 2/3 din cei 7 prezenți, adică minimum 5 voturi. Reconvocarea este permisă o singură dată.","source":{"title":"Legea nr. 198/2023","locator":"Art. 128 alin. (11)","quote":"unitatea de învățământ. (11) În cazul în care hotărârile consiliului de administrație nu pot fi luate conform alin. (10), acesta va fi reconvocat o singură dată. La următoarea ședință cvorumul de ședință necesar adoptării este de jumătate plus unu din membrii consiliului de administrație, iar hotărârile consiliului de administrație se adoptă cu 2/3 din voturile celor prezenți. Dacă în urma votului nu se obține numărul de 2/3 din voturile celor prezenți, hotărârea nu poate fi adoptată. (12) Hotărârile consiliului de administrație se adoptă cu majoritatea voturilor celor prezenți, cu excepția celor prevăzute la alin. (11). Hotărârile consiliului de administrație care vizează","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R01","theme":"R","prompt":"Consiliul profesoral are 47 de membri cu norma de bază. La ședință se prezintă 31. Directorul dorește să înceapă deliberarea. Ce rezultă din regula cvorumului?","options":["Mai este necesar un membru pentru atingerea cvorumului.","Mai sunt necesari șase membri pentru atingerea cvorumului.","Sunt necesari toți cei 47 de membri pentru întrunire.","Sunt suficienți cei 31 de membri pentru întrunirea legală."],"answer":0,"explanation":"Două treimi din 47 înseamnă 31,33..., deci minimum 32 de membri. Cvorumul nu se rotunjește în jos.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 54 alin. (4)","quote":"profesoral din unitatea de învățământ unde are norma de bază se consideră abatere disciplinară și se sancționează conform legii. Cvorumul necesar pentru întrunirea în ședință a consiliului profesoral este de 2/3 din numărul total al membrilor, cadre didactice cu norma de bază în unitatea de învățământ. Hotărârile se adoptă prin vot deschis sau secret, cu cel puțin jumătate plus unu din numărul total al membrilor consiliului profesoral cu norma de bază în unitate, și sunt obligatorii pentru personalul unității de învățământ, precum și pentru beneficiarii primari, părinți/reprezentanți legali. Modalitatea de vot se stabilește la începutul ședinței. Directorul","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B01","theme":"B","prompt":"Directorul verifică zilnic registre și proceduri, dar nu discută scopurile învățării sau valorile școlii. Ce risc conceptual descrie Bush în această situație?","options":["Leadership distribuit: expertiza tuturor profesorilor determină deciziile școlii.","Leadership moral: valorile educaționale ghidează toate deciziile instituției.","Management colegial: consensul profesional stabilește scopurile instituției.","Managerialism: mijloacele administrative ajung să domine scopurile educaționale."],"answer":3,"explanation":"Managerialismul deplasează accentul spre proceduri în detrimentul scopurilor și valorilor educaționale. Simpla existență a procedurilor nu este problema, ci substituirea scopului prin mijloc.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 13","quote":"Dacă legătura dintre scop şi management nu este clar definită, apare pericolul alunecării în „managerialism”, cu „un accent pe proceduri în detrimentul scopurilor şi valorilor educaţionale” (Bush, 1999: 240). Managerialismul pune mai curând accent pe eficienţa managerială decât pe scopurile şi obiectivele","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H01","theme":"H","prompt":"Directorul analizează efectele activității profesorilor. Echipa propune să evalueze doar ce au predat, fără să urmărească ce au învățat elevii. Ce orientare corespunde capitolului despre profesor?","options":["Confirmarea exclusivă a vechimii profesorului în școală.","Inventarierea exclusivă a capitolelor predate de profesor.","Investigarea impactului predării asupra învățării elevilor.","Numărarea exclusivă a fișelor distribuite la fiecare clasă."],"answer":2,"explanation":"Capitolul mută atenția de la simpla desfășurare a predării la efectele asupra învățării. Activitățile profesorului sunt mijloace, nu dovada suficientă a impactului.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 1, p. 225–228","quote":"când adaugi asistenții profesorului și pozițiile de conducere, raportul dintre adulți și elevi a crescut în mod clar. Din 1987, numărul elevilor a crescut cu 19%, iar al profesorilor cu 46%. Mai cărunt Procentul profesorilor de peste 50 de ani a crescut (33% în peste 50 de țări din OCDE), dar e probabil ca această tendință să se inverseze pe măsură ce căutăm","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s1","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=1"}},{"id":"L02","theme":"L","prompt":"Într-un consiliu profesoral cu 47 de membri, 15 profesori solicită o ședință extraordinară. Directorul verifică pragul de o treime prevăzut de lege. Ce constată?","options":["Solicitarea este suficientă numai dacă primește votul consiliului elevilor.","Solicitarea este suficientă, deoarece fracția se rotunjește în jos.","Solicitarea mai necesită nouă membri pentru majoritatea absolută.","Solicitarea mai necesită un membru pentru atingerea pragului legal."],"answer":3,"explanation":"O treime din 47 este 15,66..., deci sunt necesare minimum 16 persoane. Nu se poate coborî sub prag prin rotunjire.","source":{"title":"Legea nr. 198/2023","locator":"Art. 129","quote":"prezidat de către director și se întrunește lunar sau ori de câte ori este nevoie, la propunerea directorului sau la solicitarea a minimum o treime dintre membrii săi. (2) Atribuțiile principale ale consiliului profesoral sunt următoarele: a) gestionează și asigură calitatea actului didactic; b) stabilește și monitorizează aplicarea Codului de etică profesională elaborat în conformitate cu codul-cadru de etică profesională aprobat prin ordin al ministrului educației; c) propune consiliului de administrație fișele de evaluare a personalului angajat al unității de învățământ, în baza cărora se stabilește calificativul anual; d) propune consiliului de administrație","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R02","theme":"R","prompt":"Consiliul clasei are 12 membri. La ședință sunt prezenți 8, iar o propunere primește 6 voturi pentru. Cum se apreciază rezultatul?","options":["Cvorumul este îndeplinit, dar hotărârea necesita 7 voturi pentru.","Cvorumul este îndeplinit, iar hotărârea este adoptată cu 6 voturi pentru.","Cvorumul nu este îndeplinit, fiind necesară prezența tuturor membrilor.","Cvorumul nu este îndeplinit, fiind necesari minimum 9 membri prezenți."],"answer":0,"explanation":"Cvorumul este 2/3 din total: 8. Adoptarea cere jumătate plus unu din totalul celor 12 membri: 7. Cele două praguri sunt diferite.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 59 alin. (1)","quote":"Consiliul clasei se întrunește în prezența a cel puțin 2/3 din totalul membrilor și adoptă hotărâri cu votul a jumătate plus unu din totalul membrilor săi. La sfârșitul fiecărei ședințe a consiliului clasei, toți membrii au obligația să semneze procesul- verbal de ședință. Procesele-verbale se scriu în registrul de procese-verbale ale consiliilor clasei, constituit pe fiecare clasă sau nivel de învățământ. Registrul de procese- verbale se numerotează pe fiecare pagină și se înregistrează. Registrul de procese-verbale al consiliului clasei este însoțit de un dosar care conține anexele proceselor, numerotate și îndosariate pentru fiecare ședință.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"P01","theme":"P","prompt":"Directorul pregătește o reorganizare: analizează contextul, definește obiective măsurabile, discută rezistența echipei și consolidează noile practici prin rutine. Ce competență specifică este descrisă cel mai direct?","options":["Cercetare, inovație pedagogică și conceptualizare strategică","Dezvoltare și transformare organizațională","Managementul schimbării, adaptare și gestionarea presiunilor","Reziliență și managementul riscului"],"answer":2,"explanation":"Ansamblul urmărește proiectarea, conducerea și consolidarea schimbării. Nu este vorba doar de gestionarea unui risc sau de cercetarea unei practici pedagogice.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"1.1. Managementul schimbării, adaptare și gestionarea presiunilor","quote":"Inițiază, conduce și consolidează procese de transformare instituțională, mobilizând resursele organizației și gestionând rezistența la schimbare pentru atingerea obiectivelor strategice. proiectează și planifică procese de schimbare pe baza unei analize clare a contextului instituțional; definește obiectivele schimbării în termeni specifici, măsurabili și comunicabili echipei; facilitează sesiuni de planificare participativă pentru a coagula echipa în jurul viziunii de transformare; gestionează rezistența la schimbare prin dialog deschis, claritate și argumente centrate pe beneficiile elevilor; monitorizează progresul transformării și ajustează strategiile pe baza feedbackului colectat sistematic; consolidează noile practici prin reguli, proceduri și rutine instituționale; utilizează metodologii recunoscute de management al schimbării, d","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"C01","theme":"C","prompt":"O școală tratează managementul curriculumului doar ca întocmire de documente. Echipa nu urmărește aplicarea lor în clase. Ce două operațiuni trebuie cuprinse potrivit capitolului 10?","options":["Aprobarea manualelor naționale și numirea autorilor programelor școlare.","Clasificarea profesorilor după vechime și repartizarea concediilor anuale.","Inspecția financiară a furnizorilor și autorizarea editurilor școlare.","Organizarea implementării curriculumului și monitorizarea acestui proces."],"answer":3,"explanation":"Managementul curriculumului include organizarea implementării și monitorizarea ei, nu numai existența documentelor.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"CADRUL DE REFERINȚĂ AL CURRICULUMULUI NAȚIONAL Capitolul 10 – Managementul curriculumului la nivelul școlii Material integral pentru studiu și ascultare · 20 de itemi interactivi Material integral Ascultă materialul 20 de itemi 10. Managementul curriculumului la nivelul școlii Școala – cadru de aplicare contextualizată a Curriculumului Național. Școala asigură un context structurat pentru aplicarea planurilor-cadru de învățământ și a programelor școlare (directori de școală, comisii etc.). Managementul curriculumului implică organizarea implementării curriculumului și monitorizarea acestui proces, la nivelul","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L03","theme":"L","prompt":"Directorul a formulat obiectivele privind calitatea educației și dorește să le adopte singur, prin decizie. Ce corecție procedurală impune Legea 198?","options":["Obiectivele sunt propuse spre aprobare autorității administrației publice locale.","Obiectivele sunt propuse spre aprobare consiliului de administrație.","Obiectivele sunt propuse spre aprobare consiliului reprezentativ al părinților.","Obiectivele sunt propuse spre aprobare consiliului școlar al elevilor."],"answer":1,"explanation":"Directorul propune obiectivele, iar CA le aprobă. Inițierea și aprobarea sunt atribuții diferite.","source":{"title":"Legea nr. 198/2023","locator":"Art. 195 alin. (2) lit. j)","quote":"datele statistice pentru sistemul național de indicatori privind educația; j) propune spre aprobare consiliului de administrație obiectivele unității de învățământ preuniversitar privind asigurarea calității educației, prin raportare la cadrul general privind politicile educaționale, scopurile, obiectivele și standardele stabilite de Ministerul Educației. Îndeplinirea obiectivelor unității de învățământ privind asigurarea calității educației reprezintă criteriu în evaluarea managerială realizată de directorul general al DJIP/DMBIP și este verificată periodic de ARACIIP; k) colaborează cu consiliul școlar al elevilor, structurile asociative ale părinților și federațiile","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R03","theme":"R","prompt":"Două treimi dintre membrii CA propun motivat eliberarea directorului adjunct numit prin concurs. Secretarul pregătește direct decizia directorului școlii. Care etapă lipsește?","options":["Auditul comitetului de părinți, urmat de decizia finală a consiliului local.","Auditul consiliului clasei, urmat de decizia finală a consiliului profesoral.","Raportul comisiei de la ISJ/ISMB, urmat de decizia finală a CA al inspectoratului.","Raportul comisiei de la primărie, urmat de decizia finală a directorului școlii."],"answer":2,"explanation":"Pentru această cale ROFUIP cere raport de evaluare realizat de o comisie la nivelul inspectoratului. Decizia finală aparține CA al inspectoratului.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 25 alin. (7) lit. b)","quote":"al ISJ/ISMB; b) la propunerea motivată a 2/3 dintre membrii consiliului de administrație al unității de învățământ urmată de un raport de evaluare a activității directorului adjunct, realizat de către o comisie constituită la nivelul ISJ/ISMB, decizia finală aparținând consiliului de administrație al inspectoratului școlar; c) la propunerea consiliului profesoral, cu votul secret a 2/3 dintre membri. În această situație, este obligatorie realizarea unui audit de către ISJ/ISMB. Rezultatele auditului se analizează în consiliul de administrație al ISJ/ISMB. În funcție de hotărârea consiliului de administrație al ISJ/ISMB, inspectorul școlar general emite decizia de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B02","theme":"B","prompt":"Directorul declară că obiectivele sale personale sunt automat obiectivele întregii școli. Profesorii indică priorități diferite. Ce precauție din Bush este relevantă?","options":["Obiectivele individuale coincid obligatoriu cu cele atribuite organizației.","Obiectivele individuale pot fi incompatibile cu cele atribuite organizației.","Obiectivele organizației elimină automat interesele tuturor membrilor ei.","Obiectivele organizației sunt independente de orice influență a liderilor."],"answer":1,"explanation":"Bush atrage atenția că obiectivele organizaționale nu sunt neapărat împărtășite de toți membrii și pot reflecta scopurile liderilor ori ale unor grupuri.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 15","quote":"să presupunem că cei mai mulţi dintre profesori doresc ca şcoala sau colegiul în care lucrează să adopte politici concordante propriilor interese şi preferinţe. Acest aspect va fi explorat pe parcursul volumului, cu precădere în capitolul 6. Stabilirea obiectivelor Procesul de determinare a obiectivelor organizaţiei se află în centrul managementului educaţional.","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H02","theme":"H","prompt":"La observarea lecțiilor, directorul vede un profesor sigur pe rolul său, entuziast și orientat spre dezvoltarea elevilor. Ce interpretare prudentă permite discuția despre personalitate?","options":["Aceste trăsături garantează performanța, fără a mai fi necesară evaluarea învățării elevilor.","Aceste trăsături înlocuiesc competența didactică, fără a mai fi necesară pregătirea lecțiilor.","Aceste trăsături justifică selectarea profesorilor exclusiv după preferințele personale ale directorului.","Aceste trăsături sunt relevante, fără a transforma personalitatea într-o garanție a performanței."],"answer":3,"explanation":"Hattie discută asocieri între anumite dimensiuni ale personalității și performanță. O asociere nu justifică o garanție individuală sau renunțarea la evaluarea impactului.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 2, p. 229–229","quote":"cea mai puternică se corelează cu maximizarea performanței elevilor, prin manifestarea de siguranță în calitate de profesor, de entuziasm față de slujbă și de discernământ. Ceilalți factori ai personalității au puține sau zero corelații. Tabelul 9.3. Corelațiile între atributele de personalitate ale profesorului și progresul în performanța elevilor","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s2","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=5"}},{"id":"L04","theme":"L","prompt":"După concurs, directorul întocmește planul de management administrativ-financiar pentru mandat. Care este traseul acestuia potrivit textului Legii 198?","options":["Aprobare în CA al școlii, apoi avizare de către prefect.","Aprobare în consiliul profesoral, apoi avizare de către primar.","Avizare în CA al școlii, apoi aprobare de către primar.","Avizare în consiliul local, apoi aprobare de către director."],"answer":2,"explanation":"Articolul distinge avizul CA al unității de aprobarea primarului. Contractul administrativ-financiar se încheie cu primarul.","source":{"title":"Legea nr. 198/2023","locator":"Art. 196 alin. (5)","quote":"concurs, directorul supune avizării consiliului de administrație al unității de învățământ și, ulterior, primarului, în vederea aprobării, planul de management administrativ-financiar pentru perioada mandatului de 4 ani și încheie cu primarul un contract de management administrativ-financiar. (6) Conținutul contractului de management educațional și al contractului de management administrativ-financiar este aprobat prin ordin al ministrului educației și conține indicatori de performanță care iau în calcul specificul unității de învățământ, obiectivele naționale și locale în zona educației. (7) Anual, autoritatea publică locală efectuează evaluarea respectării planului de management","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R04","theme":"R","prompt":"O școală gimnazială are 25 de clase, internat și cantină. Directorul verifică posibilitatea normării unui adjunct. Ce încadrare este corectă?","options":["Îndeplinește condiția de 20–30 de clase, cu internat și cantină.","Îndeplinește condiția numai dacă toate clasele au profil tehnologic.","Nu îndeplinește condiția, deoarece adjunctul se normează numai la liceu.","Nu îndeplinește condiția, fiind necesare obligatoriu peste 30 de clase."],"answer":0,"explanation":"ROFUIP permite normarea unei funcții pentru unitățile cu 20–30 de clase care au internat și cantină. Nu este necesară depășirea a 30 de clase în acest caz.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 24 alin. (2) lit. c)","quote":"română într-o unitate școlară cu predare într-o limbă a minorităților; c) unitățile de învățământ care au între 20 și 30 de clase și au internat și cantină; d) unitățile de învățământ liceal/postliceal care au peste 25 de clase; e) unitățile de învățământ liceal/postliceal care au între 20 și 25 de clase și îndeplinesc una din condițiile: au cel puțin 10 clase din învățământul primar și/sau grupe din învățământul antepreșcolar/preșcolar sau au secții cu predare în limbile minorităților într-o unitate școlară cu predare în limba română sau au secții cu predare în limba română într-o unitate școlară cu predare într-o limbă a minorităților; f) unitățile de învățământ","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B03","theme":"B","prompt":"O reformă este formal adoptată, dar profesorii care trebuie să o aplice nu au fost implicați și o execută superficial. Ce condiție a inovării este neglijată?","options":["Angajamentul celor care implementează efectiv schimbarea.","Autoritatea exclusivă a celor care verifică documentele.","Eliminarea tuturor inițiativelor care pornesc din clasă.","Uniformitatea completă a tuturor intereselor individuale."],"answer":0,"explanation":"Adoptarea formală nu garantează implementarea. Bush subliniază necesitatea angajamentului celor care trebuie să pună schimbarea în practică.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 17","quote":"în anumite instituţii de învăţământ. Guvernele au puterea constituţională de a‑şi impune voinţa, dar inovaţiile de succes reclamă angajamentul celor care trebuie să implementeze aceste schimbări. Dacă profesorii şi liderii consideră că o iniţiativă este nepotrivită pentru copiii sau pentru elevii lor, este improbabil ca aceştia să o implementeze cu entuziasm.","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"P02","theme":"P","prompt":"Directorul implică actorii școlii în inovare, folosește date pentru decizii, valorifică bune practici și dezvoltă învățarea organizațională. Ce competență specifică reunește aceste comportamente?","options":["Cercetare, inovație pedagogică și conceptualizare strategică","Conformitate juridică și etică profesională","Dezvoltare și transformare organizațională","Managementul schimbării, adaptare și gestionarea presiunilor"],"answer":2,"explanation":"Cazul urmărește dezvoltarea și transformarea organizațională prin participare, inovare și decizii fundamentate pe date. Nu se reduce la planificarea unei singure schimbări.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"1.2. Dezvoltare și transformare organizațională","quote":"Implică activ actorii ecosistemului educațional și conduce procesele de inovare instituțională, adoptând decizii fundamentate pe date. consultă și implică profesori, elevi și părinți în inițiativele de îmbunătățire instituțională; adoptă decizii manageriale fundamentate pe date și indicatori de performanță relevanți; aplică tehnici de coaching și feedback constructiv în lucrul cu personalul didactic și administrativ; mobilizează personalul și stimulează cultura organizațională orientată spre performanță și colaborare; gestionează conflictele și crizele la diferite niveluri cu calm și profesionalism; valorifică bunele practici interne și externe și stimulează învățarea organizațională; asigură un răspuns agil la nevoile organizației prin mobilizarea și atragerea resurselor relevante.","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"L05","theme":"L","prompt":"La concursul pentru director general DJIP candidează un titular cu licență, gradul I, 8 ani vechime și fără condamnări incompatibile. Ce condiție îi lipsește?","options":["Experiența obligatorie de 2 ani ca inspector general.","Experiența obligatorie de 4 ani ca director adjunct.","Vechimea minimă de 10 ani în învățământ.","Vechimea minimă de 5 ani în învățământ."],"answer":2,"explanation":"Pentru această funcție legea cere cumulativ gradul I și cel puțin 10 ani vechime. Nu se confundă cu pragul de 5 ani pentru directorul de școală.","source":{"title":"Legea nr. 198/2023","locator":"Art. 199 alin. (2)","quote":"care îndeplinește următoarele condiții: a) are diplomă de licență; b) deține gradul didactic I; c) are o vechime în învățământ de cel puțin 10 ani; d) nu a fost condamnat, pentru fapte incompatibile cu funcția didactică, în conformitate cu prevederile art. 168 alin. (7). (3) Metodologia de organizare și desfășurare a concursului pentru ocuparea funcției de director general/director general adjunct al DJIP/DMBIP se aprobă prin ordin al ministrului educației. (4) Persoanele care au câștigat concursul sunt numite în funcția de director general/director general adjunct al DJIP/DMBIP pentru o perioadă de 4 ani, prin ordin al ministrului educației. De la data numirii, în","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R05","theme":"R","prompt":"Școala stabilește persoana care va coordona proiectele educaționale europene. Directorul dorește o numire fără implicarea CP și CA. Ce traseu prevede ROFUIP pentru alegerea coordonatorului?","options":["Propus de compartimentul financiar și aprobat de primarul localității.","Propus de consiliul elevilor și aprobat de comitetul de părinți.","Propus de consiliul profesoral și aprobat de consiliul de administrație.","Propus de operatorul economic și aprobat de consiliul clasei."],"answer":2,"explanation":"Articolul 62 prevede un cadru didactic titular propus de CP și aprobat de CA, în baza criteriilor specifice aprobate de CA.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 62","quote":"Coordonatorul pentru proiecte educaționale europene este un cadru didactic titular, propus de consiliul profesoral și aprobat de către consiliul de administrație, în baza unor criterii specifice aprobate de către consiliul de administrație al unității de învățământ. Coordonatorul pentru proiecte educaționale europene coordonează activitatea de identificare a surselor de finanțare, informează instituția cu privire la apelurile lansate, participă la scrierea cererilor de finanțare, sprijină implementarea, monitorizează aspecte ale proiectelor implementate la nivelul unității de învățământ. Coordonatorul pentru proiecte educaționale","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B04","theme":"B","prompt":"Un profesor fără funcție managerială convinge colegii să îmbunătățească evaluarea și îi mobilizează spre un scop comun. Cum poate fi interpretată influența sa?","options":["Administrație care rezultă exclusiv din puterea unei semnături.","Birocrație care exclude influența exercitată de către persoane.","Leadership care nu depinde de ocuparea unei poziții formale.","Management care necesită obligatoriu o funcție de director adjunct."],"answer":2,"explanation":"Leadershipul este asociat influenței și poate exista independent de autoritatea poziției. Lipsa unei funcții nu exclude rolul de lider.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 18","quote":"în poziţii formale, precum cea de director, în timp ce primul poate fi exercitat de oricine din şcoală sau din colegiu. Leadershipul este independent de autoritatea poziţiei, însă managementul este direct legat de aceasta. • Procesul este intenţionat. Individul care doreşte să îşi exercite influenţa o face pentru a atinge anumite scopuri. • Influenţa poate fi exercitată atât de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"C02","theme":"C","prompt":"Școala cumpără resurse fără să analizeze nevoile elevilor sau specificul comunității. Ce punct de pornire recomandă CRCNR pentru folosirea resurselor?","options":["Copierea listei de achiziții a școlii cu cele mai multe dotări.","Identificarea nevoilor reale de învățare și a specificului comunității.","Preluarea preferințelor personale ale furnizorilor de materiale didactice.","Repartizarea identică a resurselor fără examinarea nevoilor de învățare."],"answer":1,"explanation":"Resursele umane, materiale, financiare și de timp trebuie raportate la nevoile reale ale elevilor și la context, nu selectate independent de acestea.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"a documentelor curriculare reglatoare. O provocare în implementarea Curriculum Național centrat pe formarea de competențe este utilizarea resurselor școlii (umane, materiale, financiare, de timp), plecând de la identificarea nevoilor reale de învățare pe care le au elevii, de la cunoașterea specificului comunității din care face parte școala, astfel încât: elevii să își valorifice propriul traseu de învățare, să particularizeze acest traseu, prin disciplinele opționale pe care le pot alege, să se implice activ în învățare, conștienți că achizițiile dobândite le sunt utile pentru viață, pe termen lung, în afara școlii; profesorii să acționeze ca agenți care induc învățarea, o","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}}]},{"id":2,"title":"Simularea 02","items":[{"id":"R06","theme":"R","prompt":"Colectivul de lucru finalizează regulamentul propriu al școlii, iar CP îl dezbate. Cine îi conferă aprobarea potrivit ROFUIP?","options":["CA al unității, prin hotărâre.","CP al unității, prin proces-verbal.","Directorul adjunct, prin notă internă.","Primarul localității, prin dispoziție."],"answer":0,"explanation":"Dezbaterea în CP este diferită de aprobarea regulamentului. ROFUIP atribuie aprobarea și modificările ulterioare CA, prin hotărâre.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 2 alin. (5)","quote":"și administrativ. (5) Regulamentul de organizare și funcționare a unității de învățământ, precum și modificările ulterioare ale acestuia se aprobă, prin hotărâre, de către consiliul de administrație. (6) După aprobare, regulamentul de organizare și funcționare a unității de învățământ se înregistrează la secretariatul unității. Pentru aducerea la cunoștința personalului unității de învățământ, a părinților/reprezentanților legali și a beneficiarilor primari, regulamentul de organizare și funcționare a unității de învățământ se afișează pe site-ul unității de învățământ și prin orice altă formă de comunicare publică existentă la nivelul unității de învățământ. (7)","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B05","theme":"B","prompt":"Directorul refuză o soluție eficientă financiar care ar exclude elevii vulnerabili, explicând public valorile de echitate care îi ghidează decizia. Ce dimensiune a leadershipului este evidențiată?","options":["Fundamentarea acțiunii exclusiv pe reducerea imediată a cheltuielilor.","Fundamentarea acțiunii exclusiv pe statutul formal al directorului.","Fundamentarea acțiunii pe evitarea oricărei justificări publice.","Fundamentarea acțiunii pe valori personale și profesionale clare."],"answer":3,"explanation":"Bush leagă leadershipul de valori. Cazul arată folosirea valorilor educaționale pentru alegerea și justificarea unei decizii.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 18","quote":"vedere. Cu toate acestea, leadershipul este asociat tot mai mult cu valorile. Aşteptările sunt ca liderii să‑şi fundamenteze acţiunile pe valori personale şi profesionale clare. Greenfield şi Ribbins (1993) susţin că leadershipul începe cu „caracterul” liderilor, exprimat în termeni de valori personale, conştiinţă de sine, precum şi în capacitate","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H03","theme":"H","prompt":"Un candidat are un discurs foarte fluent. Directorul afirmă că această abilitate garantează singură succesul său didactic. Ce concluzie este compatibilă cu analiza lui Hattie?","options":["Abilitatea verbală face inutile observațiile asupra învățării elevilor din clasă.","Abilitatea verbală înlocuiește orice nevoie de pregătire pedagogică pentru predare.","Abilitatea verbală singură garantează progresul tuturor elevilor de la orice clasă.","Abilitatea verbală singură nu este suficientă pentru a garanta eficacitatea la clasă."],"answer":3,"explanation":"Analiza arată că relația este mai slabă decât unele afirmații optimiste și că buna abilitate verbală, singură, nu schimbă semnificativ lucrurile.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 3, p. 230–230","quote":"puternică pe cât au pretins mulți și, într-adevăr, slăbește odată cu experiența la clasă. Au concluzionat că „a avea profesori doar cu o bună abilitate verbală probabil că nu va schimba semnificativ lucrurile în clasele noastre” (p. 620; observați cuvântul „doar”). Este posibil ca o competență academică sau intelectuală generalizată să fie un factor esențial în primii ani,","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s3","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=6"}},{"id":"L07","theme":"L","prompt":"CA discută acordarea unui calificativ unui profesor. Președintele propune vot deschis pentru transparență. Cum trebuie procedat potrivit legii?","options":["Se folosește vot consultativ, deoarece decizia aparține consiliului profesoral.","Se folosește vot deschis, deoarece orice calificativ trebuie public justificat.","Se folosește vot nominal, deoarece anonimatul exclude răspunderea membrilor.","Se folosește vot secret, deoarece hotărârea vizează personalul unității."],"answer":3,"explanation":"Hotărârile privind personalul, inclusiv calificativele, se iau prin vot secret. Transparența instituțională nu anulează această regulă.","source":{"title":"Legea nr. 198/2023","locator":"Art. 128 alin. (12)","quote":"gradației de merit, restrângerea de activitate, acordarea calificativelor, aplicarea de sancțiuni și altele asemenea, se iau prin vot secret. Membrii consiliului de administrație care se află în conflict de interese nu participă la vot. (13) Hotărârile privind bugetul și patrimoniul unității de învățământ se iau cu majoritatea voturilor membrilor consiliului de administrație. Componența consiliului de administrație, precum și hotărârile adoptate de acesta se publică la avizierul școlar, precum și pe websiteul unității de învățământ preuniversitar. (14) Directorul unității de învățământ emite deciziile conform hotărârilor consiliului de administrație. (15)","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R07","theme":"R","prompt":"Directorul solicită secretariatului să redacteze și să își asume RAEI în locul structurii competente. Cine are atribuția de întocmire potrivit ROFUIP?","options":["Comisia pentru evaluarea și asigurarea calității educației.","Comisia pentru inventarierea anuală a patrimoniului școlii.","Comitetul de părinți al clasei cu cele mai bune rezultate.","Compartimentul financiar-contabil al unității de învățământ."],"answer":0,"explanation":"RAEI este întocmit de comisia pentru evaluarea și asigurarea calității. Secretariatul nu îi preia responsabilitatea de evaluare internă.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 32","quote":"(1) Raportul anual de evaluare internă (RAEI) se întocmește de către comisia pentru evaluarea și asigurarea calității educației, se prezintă, spre analiză și validare consiliului profesoral și se aprobă de către consiliul de administrație, la propunerea coordonatorului comisiei, și se prezintă, spre analiză, consiliului profesoral. (2) Raportul anual de evaluare internă este adus la cunoștință tuturor beneficiarilor prin afișare sau publicare.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"P03","theme":"P","prompt":"Conducerea lucrează pentru siguranța și starea de bine a elevilor și personalului, cultivă respectul și un climat în care fiecare se simte protejat. Ce competență specifică este centrală?","options":["Asigurarea succesului școlar al elevilor și a performanței cadrelor didactice","Colectarea datelor, analiza și formularea de strategii de îmbunătățire a calității","Leadership incluziv, stare de bine a elevilor și a personalului școlii, securitate și siguranță școlară","Managementul incluziunii și al diversității în profilurile de învățare"],"answer":2,"explanation":"Accentul este climatul incluziv, starea de bine și securitatea întregii comunități. Managementul adaptărilor pentru profiluri de învățare are un accent diferit.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"1.3. Leadership incluziv, stare de bine a elevilor și a personalului școlii, securitate și siguranță școlară","quote":"creează și întreține un climat în care elevii se simt protejați, respectați și valorizați; implementează și monitorizează protocoalele de siguranță fizică — PSI, SSM, proceduri de urgență; asigură funcționarea mecanismelor antihărțuire și antibullying și intervine prompt în situații de criză; promovează măsuri de protecție a copilului — prevenirea abuzului, neglijării, violenței; monitorizează indicatori ai climatului școlar — siguranță, incluziune, stare de bine — și acționează pe baza lor; sprijină personalul și elevii în perioade de stres și situații dificile; inspiră încredere și gestionează echipe diverse printr-un stil de conducere empatic și participativ.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"C03","theme":"C","prompt":"Directorul impune o planificare identică tuturor claselor paralele, indiferent de ritmurile și nivelurile elevilor. Ce principiu al proiectării este afectat?","options":["Autonomia responsabilă a profesorului de a adapta aplicarea curriculumului la elevi.","Competența directorului de a înlocui integral programa școlară a disciplinei.","Obligația elevilor de a învăța în același ritm indiferent de sprijinul primit.","Obligația profesorului de a elimina competențele specifice din programa națională."],"answer":0,"explanation":"Profesorul are libertatea și responsabilitatea aplicării curriculumului pentru progresul fiecărui elev, ținând cont de ritmuri, performanță și potențial.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"De exemplu, în planificarea calendaristică, în proiectarea unităților de învățare și a lecției/ activității de învățare, profesorul este autonom să se orienteze în funcție de ritmurile de învățare ale elevilor, de nivelurile lor de performanță și de potențialul lor de învățare. Schemele de mai jos ilustrează demersul logic secvențial al planificării și proiectării activității didactice la clasă (planificarea calendaristică, proiectarea unității de învățare, proiectarea lecției/ activității de învățare). Toate aceste componente ale proiectării sunt interdependente și trebuie privite global, ca un sistem unitar. Demersuri orientative de planificare și de proiectare","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L08","theme":"L","prompt":"Un profesor ales pentru CA prezintă o sancțiune disciplinară încă neradiată. Conducerea susține că alegerea prin vot înlătură incompatibilitatea. Ce se aplică?","options":["Alegerea înlătură interdicția dacă părinții emit un aviz favorabil.","Alegerea înlătură interdicția dacă profesorul obține majoritatea voturilor CP.","Alegerea nu înlătură interdicția legală de a face parte din CA.","Alegerea suspendă sancțiunea până la terminarea mandatului în CA."],"answer":2,"explanation":"Condiția legală de eligibilitate nu poate fi înlocuită prin vot. Sancțiunea disciplinară neradiată împiedică participarea în CA.","source":{"title":"Legea nr. 198/2023","locator":"Art. 128 alin. (8)","quote":"penală săvârșită cu intenție, până la intervenirea unei situații care înlătură consecințele condamnării, sau cadrul didactic care are o sancțiune disciplinară neradiată. (9) Consiliul de administrație are următoarele atribuții principale: a) adoptă proiectul de buget și avizează execuția bugetară la nivelul unității de învățământ; b) aprobă planul de dezvoltare instituțională, respectiv planul de acțiune al unității de învățământ preuniversitar, la propunerea directorului unității de învățământ; c) aprobă, la propunerea consiliului profesoral și după consultarea consiliului școlar al elevilor și părinților, curriculumul la decizia elevului din oferta școlii; d) analizează și aprobă","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R08","theme":"R","prompt":"O echipă propune un PDI pentru un singur an școlar, motivând că toate documentele conducerii au aceeași durată. Cum trebuie corectat orizontul PDI?","options":["Planificare exclusiv lunară, pentru perioada cursurilor curente.","Planificare exclusiv zilnică, pentru activitățile directorului.","Planificare pe termen lung, pentru o perioadă de 3–5 ani.","Planificare pe termen scurt, pentru o perioadă de 3–5 luni."],"answer":2,"explanation":"PDI este document de prognoză pe termen lung, elaborat pentru 3–5 ani. Planul managerial anual este un document diferit.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 34 alin. (1)","quote":"constituie documentul de prognoză pe termen lung și se elaborează de către o echipă coordonată de către director, pentru o perioadă de 3 – 5 ani. Acesta conține: a) prezentarea unității: istoric și starea actuală a resurselor umane, materiale și financiare, relația cu comunitatea locală și organigramă; b) analiza de nevoi, alcătuită din analiza de tip SWOT și analiza de tip PESTE; c) viziunea, misiunea și obiectivele strategice ale unității; d) planificarea tuturor activităților unității de învățământ, respectiv activități manageriale, obiective, termene, stadii de realizare, resurse necesare, responsabilități, indicatori de performanță și evaluare. (2) Planul de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B06","theme":"B","prompt":"O școală depinde de energia unui director carismatic. După plecarea lui, proiectele se opresc, deoarece nimeni nu le asumase colectiv. Ce risc privind viziunea ilustrează cazul?","options":["Transformarea dependentă de lider garantează continuitatea după plecarea sa.","Transformarea dependentă de lider poate să nu se mențină după plecarea sa.","Transformarea instituțională elimină nevoia asumării obiectivelor comune.","Transformarea instituțională exclude orice contribuție a comunității școlare."],"answer":1,"explanation":"Critica viziunii centrate pe lider evidențiază fragilitatea schimbării care nu este susținută și asumată în organizație.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 19","quote":"ani, poate (...) fi un model fals şi amăgitor (...) ipoteza mea este că cele mai multe dintre aceste şcoli intră în declin odată cu plecarea liderului (...). Directorii sunt orbiţi de propria viziune atunci când","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H04","theme":"H","prompt":"Profesorii oferă permanent sarcini simple unui grup etichetat drept slab, fără să creeze oportunități de progres. Ce intervenție este mai apropiată de analiza așteptărilor din Hattie?","options":["Eliminarea feedbackului către grup, pentru a evita orice presiune asupra elevilor considerați slabi.","Evaluarea grupului exclusiv prin comparație cu elevii care au cele mai mari note.","Menținerea acelorași sarcini simple, considerând nivelul actual definitiv și imposibil de schimbat.","Revizuirea așteptărilor și oferirea unor provocări adecvate, cu sprijin pentru progres."],"answer":3,"explanation":"Așteptările profesorilor influențează oportunitățile oferite elevilor. Sprijinul și provocarea adecvată nu trebuie rezervate numai celor deja considerați buni.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 4, p. 231–233","quote":"class=\"chapter\"> SECȚIUNEA 04 Așteptările Pag. 231–233 Pagina 231 Vezi pagina originală ↗ Figura 9.1. Relația dintre anii de experiență și performanța elevilor la matematică ANI DE EXPERIENȚĂ. PERFORMANȚA ELEVILOR LA MATEMATICĂ (ABATERI STANDARD).","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s4","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=7"}},{"id":"L09","theme":"L","prompt":"Un câștigător al concursului solicită semnarea contractului de management educațional înainte de a prezenta evaluarea medicală. Ce răspuns respectă legea?","options":["Contractul se încheie după acordul părinților care înlocuiește evaluarea.","Contractul se încheie după o declarație personală care înlocuiește evaluarea.","Contractul se încheie imediat, iar evaluarea medicală poate fi adusă ulterior.","Contractul se încheie numai după evaluarea medicală care atestă aptitudinea."],"answer":3,"explanation":"Evaluarea medicală care atestă aptitudinea pentru funcție este o condiție prealabilă a încheierii contractului.","source":{"title":"Legea nr. 198/2023","locator":"Art. 197","quote":"Contractul de management educațional poate fi încheiat numai după prezentarea unei evaluări medicale care atestă faptul că persoana este aptă pentru funcția vizată.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R09","theme":"R","prompt":"Directorul a elaborat PDI și consideră că nu mai trebuie să întocmească plan managerial anual. Ce funcție are acesta din urmă potrivit ROFUIP?","options":["Document de acțiune pe termen scurt, pentru un an școlar.","Document de diagnoză retrospectivă, pentru întregul mandat.","Document exclusiv contabil, pentru închiderea exercițiului bugetar.","Document exclusiv curricular, pentru fiecare lecție a clasei."],"answer":0,"explanation":"Planul managerial este elaborat pentru un an școlar și transpune direcțiile și obiectivele în acțiuni pe termen scurt. Nu este înlocuit de PDI.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 35","quote":"(1) Planul managerial constituie documentul de acțiune pe termen scurt și se elaborează de către director pentru o perioadă de un an școlar. (2) Planul managerial conține adaptarea direcțiilor de acțiune ale ministerului și inspectoratului școlar la specificul unității, precum și a obiectivelor strategice ale planului de dezvoltare instituțională la perioada anului școlar respectiv. (3) Planul managerial conține toate activitățile din cadrul proiectelor naționale inițiate de Ministerul Educației și din proiectele europene din cadrul programelor UE în domeniul educației și formării profesionale pe care unitatea de învățământ le derulează în acel an. (4) Planul","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B07","theme":"B","prompt":"Directorul prezintă discursuri entuziaste despre excelență, deși datele arată absențe și dificultăți de învățare pe care nu le analizează. Ce avertisment al lui Bush se aplică?","options":["Retorica vizionară face inutilă participarea profesorilor la schimbare.","Retorica vizionară garantează automat îmbunătățirea rezultatelor școlii.","Retorica vizionară înlocuiește în mod legitim analiza nevoilor școlii.","Retorica vizionară poate ascunde distanța față de realitatea școlii."],"answer":3,"explanation":"Hoyle și Wallace pun în contrast retorica vizionară cu realitatea prozaică trăită în școli. Un discurs atrăgător nu constituie dovada schimbării.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 20","quote":"fiecare aspect din raportul OFSTED pentru şcoala lor. Hoyle şi Wallace (2005: 11) critică importanţa accentuată care se acordă viziunii. „Retorica vizionară este o formă a discursului managerial foarte răspândită în şcoli odată cu reformele din educaţie.” Autorii pun în contrast „retorica vizionară” cu „realitatea prozaică” trăită de personalul din şcoli, de elevi şi de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"P04","theme":"P","prompt":"Într-o decizie dificilă, directorul justifică alegerea prin valorile instituției și își aliniază consecvent comportamentul personal cu acestea. Ce competență specifică este evidențiată?","options":["Aderarea la principii și valori","Cercetare, inovație pedagogică și conceptualizare strategică","Conformitate juridică și etică profesională","Responsabilitate publică și relaționare instituțională"],"answer":0,"explanation":"Cazul pune în centru aderarea la principii și valori, inclusiv coerența dintre ceea ce susține managerul și felul în care acționează.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"1.4. Aderarea la principii și valori","quote":"Acționează ca model de integritate profesională, prevenind corupția, favoritismul și abuzul și asigurând alinierea organizației la valorile etice asumate. se comportă aliniat cu valorile instituționale și etica profesională, constituind un model pentru întreaga comunitate școlară; actualizează și comunică explicit viziunea și misiunea instituțională, monitorizând respectarea lor; ia decizii responsabile și argumentate, pe baza consultării comunității școlare; aplică codul de etică și gestionează cu profesionalism procedurile disciplinare — elevi și cadre didactice; ia măsuri concrete pentru prevenirea abuzurilor, favoritismului și conflictelor de interese; demonstrează imparțialitate și transparență în toate relațiile instituționale; argumentează deciziile pe baza interesului superior al copilului și le comunică în mod transparent.","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"L10","theme":"L","prompt":"După concurs, primarul intenționează să valideze rezultatele și să numească directorul. Care este succesiunea prevăzută în Legea 198?","options":["CA al DJIP/DMBIP validează; directorul general emite decizia de numire.","CA al DJIP/DMBIP validează; primarul emite decizia de numire.","CA al școlii validează; directorul general emite decizia de numire.","Consiliul local validează; inspectorul teritorial emite decizia de numire."],"answer":0,"explanation":"Articolul atribuie validarea CA al DJIP/DMBIP și numirea directorului general. Primarul are un rol distinct în managementul administrativ-financiar.","source":{"title":"Legea nr. 198/2023","locator":"Art. 198 alin. (3)","quote":"reprezentative ale asociațiilor de părinți cu activitate relevantă la nivel național. (3) Consiliul de administrație al DJIP/DMBIP validează rezultatele concursului de ocupare a funcțiilor de director și director adjunct. Directorul general al DJIP/DMBIP emite decizia de numire în funcția de director și de director adjunct. (4) Directorul, respectiv directorul adjunct al unității de învățământ de stat, numiți în urma concursului național, pot fi eliberați din funcție: a) la propunerea motivată a directorului general al DJIP/DMBIP, cu avizul consiliului de administrație al DJIP/DMBIP; b) la propunerea motivată a 2/3 dintre membrii consiliului de administrație al unității de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R10","theme":"R","prompt":"Un profesor lucrează în două școli, dar și-a declarat norma de bază numai în școala A. Școala B invocă automat abaterea disciplinară prevăzută la art. 54 pentru absența la CP. Ce distincție contează?","options":["Obligația de participare la CP privește automat fiecare școală în care predă.","Obligația de participare la CP privește exclusiv școala cu cei mai mulți elevi.","Obligația de participare la CP privește exclusiv școala unde este diriginte.","Obligația de participare la CP privește școala unde a declarat norma de bază."],"answer":3,"explanation":"ROFUIP distinge dreptul de participare în toate școlile de obligația participării în școala în care profesorul declară norma de bază.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 54 alin. (3)","quote":"a participa la ședințele consiliului profesoral din unitatea de învățământ unde declară, în scris, la începutul fiecărui an școlar, că au norma de bază. Absența nemotivată de la ședințele consiliului profesoral din unitatea de învățământ unde are norma de bază se consideră abatere disciplinară și se sancționează conform legii. Cvorumul necesar pentru întrunirea în ședință a consiliului profesoral este de 2/3 din numărul total al membrilor, cadre didactice cu norma de bază în unitatea de învățământ. Hotărârile se adoptă prin vot deschis sau secret, cu cel puțin jumătate plus unu din numărul total al membrilor consiliului profesoral cu norma de bază în unitate, și sunt","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B08","theme":"B","prompt":"Conducerea stabilește o nouă direcție educațională, dar asigură și orarul, resursele și procedurile necesare. Ce relație surprinde distincția discutată de Bush?","options":["Leadershipul înlocuiește organizarea, iar managementul elimină orice schimbare instituțională.","Leadershipul menține exclusiv rutina, iar managementul stabilește exclusiv valorile educaționale.","Leadershipul orientează schimbarea, iar managementul susține implementarea și continuitatea.","Leadershipul se reduce la orar, iar managementul se reduce la inspirația personală."],"answer":2,"explanation":"Distincția nu cere alegerea unui singur rol. Leadershipul și managementul sunt necesare și complementare, cu accente diferite asupra scopului, schimbării și implementării.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 21","quote":"serviciilor publice. Cuban (1988) oferă una dintre cele mai clare distincţii, asociind leadershipul cu schimbarea şi managementul cu „menţinerea”. De asemenea, autorul punctează importanţa ambelor dimensiuni ale activităţii organizaţionale: Prin leadership mă refer la influenţarea acţiunilor altora pentru a obţine rezultate dezirabile. Liderii sunt acei oameni","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"C04","theme":"C","prompt":"Profesorii pregătesc un proiect interdisciplinar, dar nu au timp sau cadru pentru planificare comună. Ce răspuns managerial sprijină abordarea integrată?","options":["Crearea cadrului de colaborare și proiectare didactică în echipă.","Eliminarea evaluării pentru toate activitățile interdisciplinare.","Interzicerea proiectării comune pentru a păstra izolarea disciplinelor.","Înlocuirea programelor școlare prin preferințele fiecărei echipe."],"answer":0,"explanation":"Abordarea integrată oferă posibilități de proiectare și predare în colaborare. Conducerea trebuie să susțină cadrul practic al acestei cooperări.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"O atenție specială este solicitată de abordarea integrată a curriculumului, care oferă posibilitatea proiectării didactice și predării în colaborare și/ sau în echipă. Acest aspect are implicații asupra redefinirii și constituirii normelor didactice. De asemenea, profesorul are libertatea și responsabilitatea de a aplica la clasă CN, în așa fel încât să optimizeze învățarea pentru fiecare elev și să asigure progresul individual în dezvoltarea competențelor. De exemplu, în planificarea calendaristică, în proiectarea unităților de învățare și a lecției/ activității de învățare, profesorul este autonom să se orienteze în funcție de ritmurile de învățare ale elevilor, de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L06","theme":"L","prompt":"Un CA cu 11 membri discută o hotărâre privind patrimoniul școlii. Sunt prezenți 7 membri, dintre care 4 votează pentru. Care este concluzia?","options":["Hotărârea este adoptată; patrimoniul se aprobă prin majoritate relativă.","Hotărârea este adoptată; sunt suficiente cele 4 voturi ale majorității prezente.","Hotărârea nu este adoptată; sunt necesare minimum 6 voturi pentru.","Hotărârea nu este adoptată; sunt necesare minimum 8 voturi pentru."],"answer":2,"explanation":"Pentru buget și patrimoniu se cere majoritatea membrilor CA, nu doar majoritatea celor prezenți. Din 11 membri sunt necesare cel puțin 6 voturi.","source":{"title":"Legea nr. 198/2023","locator":"Art. 128 alin. (13)","quote":"prin vot secret. Membrii consiliului de administrație care se află în conflict de interese nu participă la vot. (13) Hotărârile privind bugetul și patrimoniul unității de învățământ se iau cu majoritatea voturilor membrilor consiliului de administrație. Componența consiliului de administrație, precum și hotărârile adoptate de acesta se publică la avizierul școlar, precum și pe websiteul unității de învățământ preuniversitar. (14) Directorul unității de învățământ emite deciziile conform hotărârilor consiliului de administrație. (15) Consiliul de administrație se întrunește lunar sau ori de câte ori este necesar, la solicitarea directorului sau a unei treimi dintre membri. (16)","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}}]},{"id":3,"title":"Simularea 03","items":[{"id":"B09","theme":"B","prompt":"Școlii i se atribuie autoritatea de a decide alocarea resurselor, în cadrul legal, în locul stabilirii fiecărei utilizări la nivel central. Ce concept discutat de Bush este ilustrat?","options":["Administrare lipsită de orice răspundere publică.","Conducere exclusiv birocratică a ministerului.","Control integral exclusiv la nivel central.","Management autonom la nivel instituțional."],"answer":3,"explanation":"Managementul autonom presupune atribuirea puterii de decizie la nivelul instituției. Autonomia nu înseamnă absența cadrului legal sau a răspunderii.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 25","quote":"locale. Sistemele descentralizate, pe de altă parte, acordă mai multă putere nivelurilor subordonate. Acolo unde puterea este atribuită nivelului instituţional putem vorbi despre „management autonom”. Lauglo (1997) leagă centralizarea de birocraţie, definind‑o în felul următor: Centralismul birocratic presupune concentrarea luării deciziilor asupra unei game de probleme la","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H05","theme":"H","prompt":"După o evaluare inițială slabă, profesorul spune despre un elev că este incapabil și nu îi mai urmărește progresul. Ce schimbare este justificată de Hattie?","options":["Înlocuirea evaluării progresului cu impresia inițială despre elev.","Păstrarea etichetei fixe și folosirea ei pentru toate deciziile ulterioare.","Reducerea definitivă a oportunităților de învățare oferite elevului.","Renunțarea la eticheta fixă și reevaluarea capacității prin dovezi de învățare."],"answer":3,"explanation":"Neetichetarea presupune să nu transformăm nivelul sau impresia inițială într-o identitate fixă. Evaluarea trebuie să rămână deschisă progresului.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 5, p. 234–236","quote":"(d = 0,48). Indiferent de sexul, rasa sau performanța trecută a elevilor, așa au stat lucrurile. Neetichetarea elevilor Profesori care nu etichetează elevii Ne pricepem foarte bine să inventăm etichete și să repartizăm elevii în grupuri — adesea, grupările acestea sunt urmate de o finanțare. Problema este că etichetarea grupului poate duce la așteptări scăzute","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s5","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=10"}},{"id":"L12","theme":"L","prompt":"Un membru al CA urmează să voteze o hotărâre referitoare la propriul soț și declară că poate rămâne imparțial. Ce conduită impune legea?","options":["Nu participă la vot doar dacă îi solicită aceasta directorul.","Nu participă la vot, deoarece se află în conflict de interese.","Participă la vot, dacă alege varianta de abținere motivată.","Participă la vot, dacă își declară public legătura de familie."],"answer":1,"explanation":"Legea exclude participarea la vot a membrilor aflați în conflict de interese. Declarația de imparțialitate nu înlocuiește obligația.","source":{"title":"Legea nr. 198/2023","locator":"Art. 128 alin. (12)","quote":"calificativelor, aplicarea de sancțiuni și altele asemenea, se iau prin vot secret. Membrii consiliului de administrație care se află în conflict de interese nu participă la vot. (13) Hotărârile privind bugetul și patrimoniul unității de învățământ se iau cu majoritatea voturilor membrilor consiliului de administrație. Componența consiliului de administrație, precum și hotărârile adoptate de acesta se publică la avizierul școlar, precum și pe websiteul unității de învățământ preuniversitar. (14) Directorul unității de învățământ emite deciziile conform hotărârilor consiliului de administrație. (15) Consiliul de administrație se întrunește lunar sau ori de câte ori este necesar,","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R12","theme":"R","prompt":"La o disciplină cu 3 ore săptămânal, profesorul planifică numai 4 note pe an, invocând minimul general. Care este numărul rezultat din regula obișnuită ROFUIP pentru această disciplină?","options":["Cel puțin 3 note, aplicând doar numărul de ore săptămânale.","Cel puțin 4 note, aplicând numai pragul minim general anual.","Cel puțin 5 note, aplicând numărul de ore săptămânale plus două.","Cel puțin 6 note, aplicând numărul de ore săptămânale plus trei."],"answer":3,"explanation":"De regulă, numărul notelor este cu cel puțin trei mai mare decât numărul orelor săptămânale, dar nu sub patru. Pentru 3 ore rezultă 6 note.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 107 alin. (4)","quote":"numărul săptămânal de ore prevăzut în planul-cadru. La fiecare disciplină numărul de calificative/note acordate anual este, de regulă, cu cel puțin trei mai mare decât numărul de ore alocat săptămânal disciplinei în planul-cadru de învățământ, dar nu mai mic de patru note pe an școlar pentru fiecare disciplină. În cazul disciplinelor de studiu cu mai puțin de o oră/săptămână, numărul minim de note acordate pentru un an școlar este de două. În cazul curriculumului organizat modular, numărul de note acordate trebuie să fie corelat cu numărul de ore alocate fiecărui modul în planul de învățământ, precum și cu structura modulului, de regulă, o notă la un număr de 25 de ore.","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"P05","theme":"P","prompt":"Directorul verifică temeiul juridic al unei proceduri, previne conflictele de interese și urmărește respectarea normelor de etică profesională. Ce competență specifică este vizată?","options":["Conformitate juridică și etică profesională","Identitate digitală, inovare și eficiență managerială","Prezentarea și comunicarea informațiilor","Reziliență și managementul riscului"],"answer":0,"explanation":"Conformitatea juridică și etica privesc respectarea cadrului legal și conduita profesională. Nu este suficientă doar comunicarea ori digitalizarea documentelor.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"2.1. Conformitate juridică și etică profesională","quote":"coordonează managementul operațional — orare, regulamente, resurse; coordonează managementul financiar: elaborarea bugetului, execuția bugetară și relația cu autoritatea locală; identifică, organizează și asigură disponibilitatea resurselor aliniate cu obiectivele de performanță; aplică consecvent normele legale și procedurale în toate deciziile administrative; documentează și arhivează deciziile financiare și administrative; asigură respectarea procedurilor de achiziții publice; evită prompt și transparent conflictele de interese; gestionează eficient resursele materiale și financiare ale unității.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"C05","theme":"C","prompt":"Un debutant începe proiectarea copiind lecțiile din manual, fără să citească programa. Ce etapă esențială trebuie introdusă înaintea planificării calendaristice?","options":["Alegerea exclusivă a temelor preferate de autorul manualului folosit.","Întocmirea exclusivă a clasamentului elevilor din anul precedent.","Lectura personalizată a programei școlare, în raport cu reperele CRCNR.","Stabilirea exclusivă a datei inspecției fără examinarea programei."],"answer":2,"explanation":"Demersul orientativ pornește de la lectura CRCNR și a programei, apoi continuă cu planificarea, unitățile de învățare și lecțiile.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"Demersuri orientative de planificare și de proiectare didactică la nivel microeducațional De la CRCNR la învățarea în clasă Lectura CRCNR Lectura personalizată a programei școlare Planificarea calendaristică (stabilirea succesiunii unităților de învățare/ relațiilor dintre acestea) Proiectarea unităților de învățare Proiectarea lecțiilor/ activităților de învățare Întrebări pe care și le pune profesorul în procesul de planificare și de proiectare didactică De ce voi face? Ce voi valorifica? Cu ce voi face? Cum voi face? Cât și cât de bine am realizat? Reflecția asupra relațiilor de derivare dintre competențele specifice, generale, competențele-cheie și atributele prioritare","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L13","theme":"L","prompt":"Un titular cu licență și 4 ani vechime, fără condamnări incompatibile, vrea să candideze la conducerea unei școli obișnuite. Ce condiție din Legea 198 nu îndeplinește?","options":["Minimum 10 ani vechime în învățământ.","Minimum 2 ani experiență ca inspector școlar.","Minimum 3 ani experiență ca director adjunct.","Minimum 5 ani vechime în învățământ."],"answer":3,"explanation":"Pentru director și director adjunct al școlii legea cere cel puțin 5 ani vechime, alături de celelalte condiții. Pragul de 10 ani privește altă funcție.","source":{"title":"Legea nr. 198/2023","locator":"Art. 196 alin. (3)","quote":"care îndeplinește următoarele condiții: a) are diplomă de licență sau atestat de echivalare; b) are o vechime în învățământ de cel puțin 5 ani; c) nu a fost condamnat, pentru fapte incompatibile cu funcția didactică, în conformitate cu prevederile art. 168 alin. (7); d) a obținut avizul cultului, în cazul învățământului vocațional teologic. (4) Persoanele care au câștigat concursul sunt numite în funcțiile de director și de director adjunct pentru o perioadă de 4 ani, prin decizie a directorului general al DJIP/DMBIP. De la data numirii, în vederea îndeplinirii atribuțiilor specifice funcției, directorul și directorul adjunct încheie cu directorul general al","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R13","theme":"R","prompt":"Un elev are media aritmetică 8,50 la o disciplină. Profesorul propune media anuală 8, invocând o rotunjire neutră. Ce medie rezultă din ROFUIP?","options":["Media 10, deoarece orice fracțiune obligă la acordarea punctajului maxim.","Media 8, deoarece diferența de 50 de sutimi se rotunjește mereu în jos.","Media 8,50, deoarece media anuală la disciplină trebuie să aibă două zecimale.","Media 9, deoarece diferența de 50 de sutimi se rotunjește în favoarea elevului."],"answer":3,"explanation":"Media anuală pe disciplină se rotunjește la cel mai apropiat întreg; la 50 de sutimi, în favoarea elevului. Nu se confundă cu media anuală generală.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 109 alin. (1)","quote":"încheie anual o singură medie, calculată prin rotunjirea mediei aritmetice a notelor la cel mai apropiat număr întreg. La o diferență de 50 de sutimi, rotunjirea se face în favoarea elevului. Media, respectiv calificativul la purtare rezultat la finalul anului școlar ca medie a notelor acordate pentru fiecare interval de învățare, luând în considerare comportamentul elevului, se diminuează în mod corespunzător cu unul sau mai multe puncte, în cazul beneficiarilor primari care au înregistrat un număr de absențe nemotivate, în conformitate cu prevederile prezentului Regulament – cadru, precum și cu prevederile Statutului elevului. Mediile se consemnează în catalog cu","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B10","theme":"B","prompt":"Două școli primesc autonomie similară, dar obțin rezultate diferite. Un director susține că simpla descentralizare garantează eficiența. Ce precizează Bush?","options":["Rezultatele depind de natura și calitatea leadershipului și managementului intern.","Rezultatele depind exclusiv de vechimea persoanei care ocupă funcția de director.","Rezultatele sunt garantate exclusiv prin transferul formal al puterii de decizie.","Rezultatele sunt independente de modul concret de folosire a resurselor școlii."],"answer":0,"explanation":"Autonomia creează posibilități, dar nu produce automat eficiență. Calitatea conducerii și a managementului intern rămâne esențială.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 27","quote":"condiţiile unice (ibid.: 249). Se poate considera că şcolile şi colegiile autonome sunt mai eficiente, însă totul depinde de natura şi de calitatea leadershipului intern şi a managementului. Cercetarea realizată de Dellar (1998) în 30 de şcoli secundare din Australia, spre exemplu, demonstrează că managementul local avea succes acolo unde climatul şcolar era pozitiv, cu","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H06","theme":"H","prompt":"Elevii spun despre un profesor: cunoaște materia, dar nu simțim că îi pasă de noi. Ce dimensiune este vizată direct în analiza lui Hattie?","options":["Calificarea formală, în recunoașterea exclusivă a diplomei.","Claritatea profesorului, în organizarea exclusivă a orarului.","Credibilitatea profesorului, în relația percepută de elevi.","Eficacitatea colectivă, în distribuirea exclusivă a sarcinilor."],"answer":2,"explanation":"Credibilitatea nu se reduce la cunoașterea materiei. Percepția elevilor asupra grijii și relației cu profesorul este relevantă pentru această dimensiune.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 6, p. 237–238","quote":"class=\"chapter\"> SECȚIUNEA 06 Credibilitatea profesorului / Claritatea profesorului Pag. 237–238 Pagina 237 Vezi pagina originală ↗ Credibilitatea profesorului Credibilitatea profesorului reprezintă credința elevilor că pot învăța de la un anumit profesor pentru","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s6","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=13"}},{"id":"L14","theme":"L","prompt":"Un director susține că numai CA răspunde public pentru performanțele școlii, el ocupându-se doar de execuție. Ce relație de răspundere prevede legea?","options":["Directorul își asumă răspunderea numai față de părinți.","Directorul își asumă răspunderea publică alături de CA.","Directorul transferă răspunderea integral autorității locale.","Directorul transferă răspunderea integral consiliului profesoral."],"answer":1,"explanation":"Conducerea executivă nu îl exonerează pe director: acesta își asumă răspunderea publică pentru performanțe împreună cu CA.","source":{"title":"Legea nr. 198/2023","locator":"Art. 195 alin. (2) lit. c)","quote":"executivă a acesteia; b) este ordonatorul de credite al unității de învățământ; c) își asumă, alături de consiliul de administrație, răspunderea publică pentru performanțele unității de învățământ pe care o conduce; d) propune spre aprobare consiliului de administrație regulamentul de organizare și funcționare a unității de învățământ; e) propune spre aprobare consiliului de administrație proiectul de buget și raportul de execuție bugetară; f) răspunde, după caz, de selecția, angajarea, evaluarea periodică, formarea, motivarea și încetarea raporturilor de muncă ale personalului din unitatea de învățământ; g) îndeplinește alte atribuții stabilite de consiliul de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R14","theme":"R","prompt":"Un elev de gimnaziu are cel puțin media 5 la toate disciplinele, dar media anuală 5 la purtare. Conducerea dorește să îl declare promovat. Ce condiție nu este îndeplinită?","options":["Minimum media anuală 6 la purtare.","Minimum media anuală 7 la toate disciplinele.","Minimum media anuală 8 la toate disciplinele.","Minimum media anuală 9 la purtare."],"answer":0,"explanation":"Promovarea cere și minimum media anuală 6 la purtare, pe lângă media 5/calificativul Suficient la discipline. Condițiile se cumulează.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 115","quote":"sfârșitul anului școlar, obțin la fiecare disciplină de studiu/modul cel puțin media anuală 5/calificativul \"Suficient\", iar la purtare, media anuală 6/calificativul \"Suficient\". Elevii liceelor pedagogice, ai liceelor teologice și ai liceelor militare care obțin la purtare media anuală mai mică de 8 nu mai pot continua studiile la aceste profiluri. Acești elevi sunt obligați să se transfere, pentru anul școlar următor, la alte profiluri/licee, cu respectarea legislației în vigoare și a regulamentelor de organizare și funcționare a unităților în cauză.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B11","theme":"B","prompt":"Directorul preia integral modelul de organizare al unei fabrici și îl aplică profesorilor fără analiză, invocând eficiența industrială. Ce etapă cere precauția lui Bush?","options":["Analiza viabilității modelului în contextul specific al organizației educaționale.","Aplicarea identică a modelului înaintea examinării contextului educațional.","Eliminarea autonomiei profesorilor pentru apropierea de modelul industrial.","Înlocuirea finalităților educaționale cu obiectivele financiare ale fabricii."],"answer":0,"explanation":"Teoriile generale nu se transferă mecanic în școli. Viabilitatea lor trebuie analizată în raport cu particularitățile educației.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 29","quote":"Teoriile clasice ale managementului nu pot fi transpuse în mediul organizaţiilor cu profil educaţional fără o analiză prealabilă a viabilităţii lor în contextul unic al acestora (...). Prin urmare, trebuie să fim atenţi atunci când vrem să gestionăm sau să ameliorăm (...) domeniul educaţiei cu tehnici de „management modern” împrumutate din domeniul afacerilor,","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"P06","theme":"P","prompt":"Școala identifică vulnerabilități financiare și operaționale. Directorul pregătește măsuri preventive și alternative pentru continuitatea activității în situații dificile. Ce competență specifică aplică?","options":["Conformitate juridică și etică profesională","Identitate digitală, inovare și eficiență managerială","Prezentarea și comunicarea informațiilor","Reziliență și managementul riscului"],"answer":3,"explanation":"Identificarea, prevenirea și gestionarea riscurilor, împreună cu adaptarea în situații dificile, indică reziliența și managementul riscului.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"2.2. Reziliență și managementul riscului","quote":"Identifică și evaluează riscurile organizaționale, elaborează planuri de continuitate și intervenție și sprijină reziliența comunității școlare în situații de criză. identifică și evaluează sistematic riscurile organizaționale — financiare, juridice, operaționale, de securitate; elaborează planuri de continuitate și intervenție pentru situații de criză, actualizate periodic; instituie mecanisme de control intern și de prevenire a riscurilor; comunică rapid și clar în situații critice, menținând funcționarea instituției; evaluează impactul crizelor asupra comunității școlare și ia măsuri de remediere; revizuiește procedurile pe baza lecțiilor învățate din situațiile de criză anterioare; manifestă inițiativă și spirit antreprenorial pentru a răspunde agil provocărilor.","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"L15","theme":"L","prompt":"Consiliul profesoral propune, prin vot secret a 2/3 dintre membri, eliberarea directorului numit prin concurs. Care este etapa obligatorie prevăzută de lege pentru această cale?","options":["Realizarea unei consultări a comitetelor de părinți.","Realizarea unei evaluări exclusiv de către primar.","Realizarea unei noi probe scrise de concurs.","Realizarea unui audit de către DJIP/DMBIP."],"answer":3,"explanation":"Auditul este obligatoriu pentru propunerea consiliului profesoral. Nu trebuie confundată această cale cu alte temeiuri de eliberare din funcție.","source":{"title":"Legea nr. 198/2023","locator":"Art. 198 alin. (4) lit. c)","quote":"c) la propunerea consiliului profesoral, cu votul secret a 2/3 dintre membri. În această situație, este obligatorie realizarea unui audit de către DJIP/DMBIP. Rezultatele auditului se analizează în consiliul de administrație al DJIP/DMBIP. În funcție de hotărârea consiliului de administrație al DJIP/DMBIP, directorul general emite decizia de eliberare din funcție a directorului, respectiv directorului adjunct al unității de învățământ; d) pentru încălcarea cu vinovăție a obligațiilor stabilite prin contractul de management, cu respectarea procedurii de cercetare disciplinară prevăzută de prezenta lege. (5) Directorul unității de învățământ particular și","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R15","theme":"R","prompt":"Un elev din clasa I prezintă dificultăți de învățare consemnate în raportul de evaluare. Echipa propune repetenția ca intervenție de sprijin. Ce regulă se aplică?","options":["Nu poate fi lăsat repetent; continuă cu sprijin remedial potrivit regulamentului.","Nu poate primi sprijin remedial decât după repetarea aceleiași clase.","Poate fi lăsat repetent prin simpla recomandare a comitetului de părinți.","Poate fi lăsat repetent prin simplul acord al majorității părinților clasei."],"answer":0,"explanation":"La sfârșitul clasei pregătitoare și al clasei I elevii nu pot fi lăsați repetenți. Dificultățile impun măsurile de remediere/recuperare prevăzute.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 120","quote":"de reînscriere în aceeași unitate de învățământ sau în altă unitate de învățământ\". La sfârșitul clasei pregătitoare și al clasei I elevii nu pot fi lăsați repetenți. Elevii care, pe parcursul anului școlar, au manifestat dificultăți de învățare, menționate în raportul de evaluare a dezvoltării fizice, socioemoționale, cognitive, a limbajului și a comunicării, precum și a dezvoltării capacităților și atitudinilor față de învățare, rămân în colectivele în care au învățat și intră, pe parcursul anului școlar următor, într-un program de remediere/recuperare școlară, realizat de un învățător/institutor/profesor pentru învățământul primar împreună cu un specialist de la centrul județean de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B12","theme":"B","prompt":"Directorul discută cu profesorii despre învățarea elevilor, susține formarea și încurajează reflecția asupra lecțiilor. Ce orientare a leadershipului este dominantă?","options":["Leadershipul exclusiv tranzacțional, centrat pe schimbul de avantaje.","Leadershipul instruirii, centrat pe predare și învățare.","Managementul exclusiv financiar, centrat pe economiile bugetare.","Managementul exclusiv ierarhic, centrat pe raportarea către superiori."],"answer":1,"explanation":"Cazul corespunde orientării asupra activităților nucleu ale școlii și comportamentului profesorilor în lucrul cu elevii.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 30","quote":"dezvoltarea elevilor”. Definiţia lui Bush şi Glover punctează direcţia procesului de influenţare: Leadershipul instruirii este centrat pe predare şi învăţare, precum şi pe comportamentul profesorilor în lucrul cu elevii. Influenţa liderilor ţinteşte spre favorizarea învăţării cu ajutorul profesorului. Accentul cade pe direcţia şi impactul influenţei şi mai puţin pe procesul","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"C06","theme":"C","prompt":"Profesorul examinează derivarea competențelor specifice din competențe generale, competențe-cheie și atributele prioritare. La ce întrebare de proiectare răspunde în primul rând?","options":["Cât și cât de bine am realizat?","Ce voi valorifica?","Cu ce voi face?","De ce voi face?"],"answer":3,"explanation":"Întrebarea De ce voi face? orientează reflecția asupra competențelor și a relațiilor dintre nivelurile acestora, înaintea alegerii conținuturilor și resurselor.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"lecțiilor/ activităților de învățare Întrebări pe care și le pune profesorul în procesul de planificare și de proiectare didactică De ce voi face? Ce voi valorifica? Cu ce voi face? Cum voi face? Cât și cât de bine am realizat? Reflecția asupra relațiilor de derivare dintre competențele specifice, generale, competențele-cheie și atributele prioritare Selectarea conținuturilor învățării, prin raportare la competențele vizate și la standardele de învățare Analiza resurselor curriculare de suport, a celor de timp Stabilirea succesiunii lecțiilor, proiectarea lecțiilor/ activităților de învățare Conceperea modalităților și instrumentelor de evaluare Raportarea la","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L11","theme":"L","prompt":"Directorul nu convoacă reprezentanții sindicali și ai părinților prevăzuți de lege, motivând că nu votează în CA. Ce trebuie corectat?","options":["Observatorii prevăzuți de lege pot participa doar după votul membrilor CA.","Observatorii prevăzuți de lege sunt convocați numai când există vot secret.","Observatorii prevăzuți de lege sunt convocați numai pentru aprobarea bugetului.","Observatorii prevăzuți de lege trebuie convocați la toate ședințele CA."],"answer":3,"explanation":"Statutul de observator nu înlătură obligația directorului de a convoca persoanele prevăzute de lege la toate ședințele.","source":{"title":"Legea nr. 198/2023","locator":"Art. 128 alin. (5)","quote":"ședințele consiliului de administrație și semnează hotărârile adoptate. (5) La ședințele consiliului de administrație participă, cu statut de observator, reprezentanții federațiilor sindicale reprezentative la nivel de sector de negociere colectivă învățământ preuniversitar care au membri în unitatea de învățământ și ai asociației de părinți membre a federațiilor părinților cu activitate relevantă la nivel național, iar pentru unitățile de învățământ gimnazial sau liceal, președintele consiliului școlar al elevilor cu statut de observator. Președintele consiliului de administrație convoacă observatorii la toate ședințele consiliului de administrație. (6) În învățământul","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R11","theme":"R","prompt":"O disciplină are 100 de ore anual. Un elev are deja 18 absențe motivate prin cererile părintelui și solicită încă 5 la aceeași disciplină; plafonul anual de 40 nu este epuizat. Câte mai încap în limita procentuală?","options":["Cel mult 2 absențe, pentru a nu depăși 20% din orele disciplinei.","Cel mult 4 absențe, deoarece plafonul procentual se rotunjește în sus.","Nicio absență, deoarece cererile părinților nu pot motiva ore de curs.","Toate cele 5 absențe, deoarece plafonul general anual nu este epuizat."],"answer":0,"explanation":"20% din 100 = 20 de ore. Din acest plafon sunt deja utilizate 18, deci mai încap 2. Limita anuală de 40 de ore nu înlocuiește limita pe disciplină.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 94 alin. (5)","quote":"în evidență fișele medicale/carnetele de sănătate ale beneficiarilor primari. În limita a 40 de ore de curs pe an școlar, fără a depăși 20% din numărul orelor alocate unei discipline, absențele pot fi motivate doar pe baza cererilor scrise ale părintelui sau reprezentantului legal al elevului sau ale elevului major, adresate învățătorului/ institutorului/profesorului pentru învățământul primar/profesorului diriginte al clasei, avizate în prealabil de motivare de către directorul unității de învățământ. Prin excepție de la prevederile alin. (5), pentru elevele gravide și elevii părinți absențele pot fi motivate pentru un număr de ore de curs, în limita a 100 de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}}]},{"id":4,"title":"Simularea 04","items":[{"id":"H07","theme":"H","prompt":"Profesorul explică multe informații, dar elevii nu știu ce urmăresc să învețe sau cum recunosc un rezultat reușit. Ce dimensiune trebuie întărită?","options":["Claritatea profesorului privind învățarea urmărită și criteriile de reușită.","Credibilitatea diplomei profesorului privind numărul de ani de studiu.","Eficacitatea colectivă privind numărul întâlnirilor administrative lunare.","Personalitatea directorului privind modul de repartizare a sălilor."],"answer":0,"explanation":"Claritatea înseamnă a face inteligibile intențiile învățării și reperele reușitei. Volumul informațiilor prezentate nu garantează înțelegerea lor de către elevi.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 6, p. 237–238","quote":"class=\"chapter\"> SECȚIUNEA 06 Credibilitatea profesorului / Claritatea profesorului Pag. 237–238 Pagina 237 Vezi pagina originală ↗ Credibilitatea profesorului Credibilitatea profesorului reprezintă credința elevilor că pot învăța de la un anumit profesor pentru că profesorul este","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s6","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=13"}},{"id":"L17","theme":"L","prompt":"Părintele unui elev minor din învățământul obligatoriu refuză să asigure participarea acestuia la cursuri, invocând că educația este exclusiv sarcina școlii. Ce prevede legea?","options":["Părintele are doar dreptul de a recomanda participarea minorului la cursuri.","Părintele are obligația de a asigura participarea minorului la cursuri.","Părintele poate suspenda obligația printr-o cerere depusă la secretariat.","Părintele poate transfera obligația integral comitetului de părinți al clasei."],"answer":1,"explanation":"Obligația privind participarea la cursuri pe durata învățământului obligatoriu aparține și părintelui sau reprezentantului legal.","source":{"title":"Legea nr. 198/2023","locator":"Art. 14 alin. (1)","quote":"(1) Părinții sau reprezentantul legal au obligația să asigure participarea la cursuri a beneficiarului primar minor pe întreaga perioadă a învățământului obligatoriu. Nerespectarea prezentei obligații constituie contravenție și se sancționează potrivit dispozițiilor art. 148 alin. (1) lit. a). (2) Statul sprijină părinții sau reprezentantul legal în vederea exercitării responsabilităților privind creșterea, îngrijirea, dezvoltarea și educarea copiilor. În acest scop, în unitățile de învățământ se organizează cursuri de educație parentală pentru formarea și dezvoltarea abilităților parentale pentru părinți","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R17","theme":"R","prompt":"Un elev de liceu cere schimbarea profilului în timpul cursurilor, fără vreo situație excepțională justificată. Care este perioada obișnuită pentru un asemenea transfer?","options":["Numai prima zi de cursuri din fiecare interval.","Numai ziua încheierii situației școlare anuale.","Orice săptămână de cursuri, la alegerea elevului.","Vacanța de vară, pentru anul școlar următor."],"answer":3,"explanation":"Transferurile liceale cu schimbarea filierei, profilului sau specializării se fac, de regulă, în vacanța de vară, pentru anul următor. Cazul exclude situațiile excepționale.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 144","quote":"mod excepțional în cazurile precizate la alin. (5); de la învățământul cu frecvență redusă la cel cu frecvență zi/seral, numai în perioada vacanței de vară. Transferurile în învățământul liceal, inclusiv în sistem dual, cu schimbarea filierei/ profilului/specializării/calificării, se efectuează, de regulă, în perioada vacanței de vară, pentru anul școlar următor. Prin excepție de la prevederile alin. (3), unitățile de învățământ liceal militar pot efectua transferuri la clasa a IX-a, în primele 30 de zile de la începerea anului școlar, în condițiile prevăzute prin reglementări emise de Ministerul Apărării Naționale. Transferul beneficiarilor primari în timpul cursurilor","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"P07","theme":"P","prompt":"Directorul introduce un sistem informațional, dezvoltă competențele digitale ale echipei, asigură protecția datelor și verifică eficiența noii soluții. Ce competență specifică este dominantă?","options":["Conformitate juridică și etică profesională","Identitate digitală, inovare și eficiență managerială","Prezentarea și comunicarea informațiilor","Reziliență și managementul riscului"],"answer":1,"explanation":"Digitalizarea este folosită pentru inovare și eficiență managerială, cu atenție la securitate și impact. Conformitatea este prezentă, dar nu epuizează ansamblul.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"2.3. Identitate digitală, inovare și eficiență managerială","quote":"Utilizează eficient tehnologia și resursele digitale în managementul instituțional, monitorizând sistematic progresul în atingerea obiectivelor de performanță. utilizează platforme digitale și instrumente de management informațional în activitatea curentă; monitorizează progresul în atingerea obiectivelor de performanță instituțională într-un mod sistematic; sprijină transformarea digitală a școlii și dezvoltarea competențelor digitale ale personalului; asigură securitatea datelor și conformitatea cu normele GDPR; introduce soluții digitale inovatoare validate și evaluează impactul lor asupra eficienței instituționale.","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"C07","theme":"C","prompt":"Profesorul selectează conținuturile pe care le va folosi pentru competențele vizate și standardele de învățare. Ce întrebare îi ghidează această etapă?","options":["Ce voi valorifica?","Cu ce voi face?","Cum voi face?","De ce voi face?"],"answer":0,"explanation":"Selectarea conținuturilor în raport cu competențele și standardele răspunde întrebării Ce voi valorifica? Nu se confundă cu analiza resurselor de suport.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"activităților de învățare Întrebări pe care și le pune profesorul în procesul de planificare și de proiectare didactică De ce voi face? Ce voi valorifica? Cu ce voi face? Cum voi face? Cât și cât de bine am realizat? Reflecția asupra relațiilor de derivare dintre competențele specifice, generale, competențele-cheie și atributele prioritare Selectarea conținuturilor învățării, prin raportare la competențele vizate și la standardele de învățare Analiza resurselor curriculare de suport, a celor de timp Stabilirea succesiunii lecțiilor, proiectarea lecțiilor/ activităților de învățare Conceperea modalităților și instrumentelor de evaluare Raportarea la standardele de învățare Ca","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L18","theme":"L","prompt":"Pentru o abatere gravă, conducerea dorește exmatricularea imediată a unui elev din învățământul obligatoriu, fără audiere și fără contestație. Ce garanție este omisă?","options":["Procedura curriculară care garantează schimbarea specializării.","Procedura disciplinară care garantează apărarea și contestația.","Procedura electorală care garantează votul tuturor părinților.","Procedura financiară care garantează plata unei despăgubiri."],"answer":1,"explanation":"Legea limitează exmatricularea la situațiile grave și impune o procedură care garantează dreptul la apărare și contestație. Gravitatea invocată nu permite omiterea ei.","source":{"title":"Legea nr. 198/2023","locator":"Art. 13 alin. (2)","quote":"al celorlalți beneficiari primari. Exmatricularea poate fi dispusă numai după parcurgerea unei proceduri disciplinare care garantează dreptul la apărare și contestație. (3) Pe durata școlarizării în învățământul preuniversitar, cu excepția învățământului postliceal, copiii/elevii beneficiază de alocația de stat pentru copii, în conformitate cu prevederile Legii nr. 61/1993 privind alocația de stat pentru copii, republicată, cu modificările și completările ulterioare. (4) Prin excepție de la prevederile alin. (1), elevii din cadrul filierei tehnologice, care nu optează pentru continuarea studiilor liceale după obținerea unui certificat de calificare de nivel 3, sunt","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R18","theme":"R","prompt":"După aprobarea transferului, școala primitoare intenționează să solicite situația școlară după 12 zile lucrătoare. Care este termenul prevăzut pentru solicitare?","options":["În termen de 10 zile lucrătoare de la aprobarea transferului.","În termen de 15 zile lucrătoare de la aprobarea transferului.","În termen de 20 de zile lucrătoare de la aprobarea transferului.","În termen de 5 zile lucrătoare de la aprobarea transferului."],"answer":3,"explanation":"Școala primitoare solicită situația în 5 zile lucrătoare. Cele 10 zile lucrătoare privesc trimiterea de către școala de proveniență după primirea solicitării.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 150","quote":"După aprobarea transferului, unitatea de învățământ primitoare este obligată să solicite situația școlară a elevului în termen de 5 zile lucrătoare. Unitatea de învățământ de la care se transferă elevul este obligată să trimită la unitatea de învățământ primitoare situația școlară a celui transferat, în termen de 10 zile lucrătoare de la primirea solicitării. Până la primirea situației școlare de către unitatea de învățământ la care s-a transferat, elevul transferat participă la cursuri în calitate de audient.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B14","theme":"B","prompt":"Profesorii se implică mai mult într-o schimbare după ce contribuie la definirea ei, spre deosebire de o reformă anterioară impusă. Cum explică Bush această diferență?","options":["Asumarea schimbării ca aparținându-le favorizează angajamentul.","Eliminarea valorilor profesionale favorizează asumarea schimbării.","Excluderea profesorilor din decizie favorizează inovarea susținută.","Impunerea schimbării fără consultare favorizează întotdeauna angajamentul."],"answer":0,"explanation":"Sentimentul că schimbarea le aparține sporește probabilitatea entuziasmului și a implicării, în comparație cu impunerea ei din exterior.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 19","quote":"şcolari. Există o probabilitate mai mare ca profesorii şi liderii să manifeste entuziasm faţă de schimbare atunci când simt că aceasta le „aparţine”, şi nu atunci când le este impusă. Pe baza cercetărilor efectuate în şcolile din Canada, Hargreaves (2004) afirmă că profesorii asociază schimbările iniţiate de ei înşişi cu o experienţă emoţională pozitivă, în timp ce","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H08","theme":"H","prompt":"Profesorii analizează împreună dovezi de progres și construiesc convingerea că acțiunea lor comună poate îmbunătăți învățarea. Ce concept este ilustrat?","options":["Abilitatea verbală exclusiv individuală a profesorului.","Autoevaluarea exclusiv individuală a profesorului.","Credibilitatea exclusiv formală a directorului.","Eficacitatea colectivă a profesorilor."],"answer":3,"explanation":"Centrul este credința comună în capacitatea colectivului de a produce rezultate, legată de examinarea și îmbunătățirea practicii.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 7, p. 239–240","quote":"class=\"chapter\"> SECȚIUNEA 07 Eficacitatea colectivă a profesorilor și impactul lor Pag. 239–240 Pagina 239 Vezi pagina originală ↗ împărtășesc credința că, prin efortul lor unit, pot depăși greutăți și pot obține rezultatele dorite, grupurile sunt mai eficiente. Acest","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s7","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=15"}},{"id":"L19","theme":"L","prompt":"Un partid solicită o activitate de promovare electorală în spațiile școlii. Directorul propune aprobarea dacă toate partidele primesc același timp. Ce rezultă din lege?","options":["Propaganda politică este interzisă în spațiile destinate educației.","Propaganda politică este interzisă numai în timpul examenelor.","Propaganda politică este permisă dacă părinții votează favorabil.","Propaganda politică este permisă dacă timpul este împărțit egal."],"answer":0,"explanation":"Interdicția privește manifestările și propaganda de natură politică în spațiile educaționale, inclusiv cadrul online prevăzut de lege. Echilibrul între partide nu o înlătură.","source":{"title":"Legea nr. 198/2023","locator":"Art. 11 alin. (1)","quote":"republicată, cu modificările și completările ulterioare, cu excepția măsurilor afirmative dispuse de lege. Sunt interzise manifestările și propaganda de natură politică și prozelitismul religios. (2) În unitățile de învățământ preuniversitar și în toate spațiile educației și formării profesionale, precum și în cadrul activităților desfășurate în mediul online de unitățile de învățământ preuniversitar pot fi luate măsuri cu scopul de a proteja anumite categorii vulnerabile de beneficiari primari, în vederea asigurării dreptului la educație al acestora, respectându-se interesul superior al beneficiarului primar. (3) Încălcarea prevederilor alin. (1) de către personalul din învățământul","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R19","theme":"R","prompt":"Pentru transferul la o clasă cu predare intensivă a unei limbi străine se pregătește testul de aptitudini și cunoștințe. Cine desemnează comisia care îl elaborează?","options":["Directorul unității de învățământ de proveniență.","Directorul unității de învățământ primitoare.","Președintele comitetului de părinți al clasei primitoare.","Președintele consiliului elevilor din școala primitoare."],"answer":1,"explanation":"Testul este elaborat la nivelul școlii la care se face transferul de o comisie desemnată de directorul acestei unități.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 143","quote":"limba modernă; testul de aptitudini și cunoștințe va fi elaborat la nivelul unității de învățământ la care elevul se transferă, de către o comisie desemnată în acest sens de directorul unității de învățământ; la nivel liceal, începând cu clasa a IX-a, elevii care se transferă la clasele cu predare intensivă, respectiv bilingvă a unei limbi de circulație internațională vor susține examene de diferență (după caz) și un test de verificare a competențelor lingvistice în unitatea de învățământ la care se transferă. Subiectele aferente testelor/probelor vor fi elaborate la nivelul unității de învățământ de către o comisie desemnată în acest sens de directorul unității de învățământ.","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B15","theme":"B","prompt":"Două echipe analizează aceleași date despre absențe, dar formulează explicații diferite. Directorul afirmă că datele dictează singure o soluție unică. Ce arată Bush?","options":["Dovezile elimină necesitatea oricărei interpretări profesionale.","Dovezile justifică automat prima soluție propusă de director.","Dovezile necesită interpretare înainte de a ghida acțiunea.","Dovezile sunt inutile dacă există mai multe explicații posibile."],"answer":2,"explanation":"Faptele nu oferă singure o rețetă de acțiune: sunt interpretate prin concepte, experiențe și perspective. Diferențele trebuie examinate, nu ignorate.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 2, p. 39","quote":"practicii: 1. Utilizarea faptelor ca unic instrument de ghidare în acţiune este nesatisfăcătoare, deoarece toate dovezile necesită interpretare. Viaţa în şcoli şi în colegii este prea complexă pentru a le permite practicienilor să ia decizii numai pe baza","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"P08","theme":"P","prompt":"Directorul adaptează mesajele pentru profesori, părinți și autorități, organizează clar informațiile și verifică dacă destinatarii le-au înțeles. Ce competență specifică este evidențiată?","options":["Conformitate juridică și etică profesională","Identitate digitală, inovare și eficiență managerială","Prezentarea și comunicarea informațiilor","Reziliență și managementul riscului"],"answer":2,"explanation":"Comportamentele vizează prezentarea și comunicarea informațiilor către publicuri diferite. Instrumentul digital, dacă există, nu este scopul principal al cazului.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"2.4. Prezentarea și comunicarea informațiilor","quote":"Prezentarea și comunicarea informațiilor reprezintă componenta prin care datele, resursele, deciziile și informațiile instituționale sunt prezentate clar, corect și transparent.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"L20","theme":"L","prompt":"Două școli formează un consorțiu pentru folosirea comună a laboratoarelor. Un partener afirmă că noul consorțiu devine automat o persoană juridică distinctă. Cum este definit legal?","options":["Instituție județeană care înlocuiește școlile membre.","Instituție subordonată automat unei universități partenere.","Structură administrativă cu personalitate juridică proprie.","Structură asociativă fără personalitate juridică."],"answer":3,"explanation":"Consorțiul școlar este o structură asociativă fără personalitate juridică. Asocierea nu produce automat o nouă persoană juridică.","source":{"title":"Legea nr. 198/2023","locator":"Art. 21 alin. (2)","quote":"autoritățile administrației publice locale pot decide înființarea consorțiilor școlare. (2) Consorțiile școlare sunt structuri asociative, fără personalitate juridică, constituite din două sau mai multe unități de învățământ preuniversitar. (3) Consorțiile școlare se înființează între două sau mai multe unități de învățământ preuniversitar de stat ori particulare și confesionale autorizate să funcționeze provizoriu/ acreditate, în baza unui contract de parteneriat, conform modelului prevăzut în metodologia aprobată prin ordin al ministrului educației. Contractul de parteneriat stabilește modul de colaborare între unitățile de învățământ preuniversitar semnatare ale contractului și","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R20","theme":"R","prompt":"Doi gemeni sunt repartizați în clase diferite. Părintele cere transferul unuia în clasa celuilalt. Care soluție corespunde regulii speciale din ROFUIP?","options":["Transferul este interzis deoarece gemenii trebuie școlarizați în clase distincte.","Transferul poate fi aprobat de CA, în clasa celui cu media mai mare sau invers.","Transferul poate fi aprobat exclusiv de comitetul de părinți al clasei.","Transferul poate fi aprobat exclusiv în clasa geamănului cu media mai mare."],"answer":1,"explanation":"ROFUIP permite, la cerere, transferul gemenilor în clasa celui cu media mai mare sau invers, cu aprobarea CA al școlii.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 145","quote":"Gemenii, tripleții etc. se pot transfera în clasa celui cu media mai mare sau invers, la cererea părintelui/reprezentantului legal sau la cererea beneficiarilor primari, dacă aceștia sunt majori, cu aprobarea consiliului de administrație al unității de învățământ","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B16","theme":"B","prompt":"Un director aplică într-o școală nouă exact soluția care a funcționat în vechea instituție, fără să examineze nevoile acesteia. Ce limită a experienței ilustrează cazul?","options":["Experiența exclude utilitatea cunoștințelor provenite de la alte persoane.","Experiența garantează transferul identic al soluțiilor între toate școlile.","Experiența înlocuiește analiza nevoilor atunci când directorul este titular.","Experiența poate deveni un ghid insuficient într-un context diferit."],"answer":3,"explanation":"Bush arată că experiența poate fi nefolositoare ca unic ghid când practicianul începe să opereze în alt context. Este necesară interpretarea noii situații.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 2, p. 40","quote":"Experienţa poate fi în mod particular nefolositoare, folosită ca unic ghid de acţiune, atunci când practicianul începe să opereze într‑un alt context. Variabilele organizaţionale pot determina ca practica într‑o şcoală sau un colegiu să aibă puţină relevanţă într‑un mediu nou. O conştientizare mai bună a teoriei şi practicii poate fi utilă în încercarea managerului","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"C08","theme":"C","prompt":"Profesorul verifică materialele de suport și timpul disponibil pentru o unitate de învățare. Ce întrebare a proiectării exprimă această analiză?","options":["Cât și cât de bine am realizat?","Ce voi valorifica?","Cu ce voi face?","De ce voi face?"],"answer":2,"explanation":"Analiza resurselor curriculare de suport și a celor de timp răspunde întrebării Cu ce voi face?.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"învățare Întrebări pe care și le pune profesorul în procesul de planificare și de proiectare didactică De ce voi face? Ce voi valorifica? Cu ce voi face? Cum voi face? Cât și cât de bine am realizat? Reflecția asupra relațiilor de derivare dintre competențele specifice, generale, competențele-cheie și atributele prioritare Selectarea conținuturilor învățării, prin raportare la competențele vizate și la standardele de învățare Analiza resurselor curriculare de suport, a celor de timp Stabilirea succesiunii lecțiilor, proiectarea lecțiilor/ activităților de învățare Conceperea modalităților și instrumentelor de evaluare Raportarea la standardele de învățare Ca urmare a","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L16","theme":"L","prompt":"La contractul educațional, CA adaugă o clauză prin care copilul pierde accesul la cursuri dacă familia nu donează bani. Cum se apreciază clauza?","options":["Este nepermisă numai dacă nu a fost publicată pe site.","Este nepermisă, deoarece afectează interesul superior al elevului.","Este permisă, dacă familia a semnat contractul fără obiecții.","Este permisă, deoarece orice hotărâre a CA completează legea."],"answer":1,"explanation":"Clauzele suplimentare sunt posibile, dar nu pot afecta interesul superior al elevului. Semnătura părintelui nu legitimează încălcarea drepturilor copilului.","source":{"title":"Legea nr. 198/2023","locator":"Art. 14 alin. (4)","quote":"specificul fiecărei unități, prin hotărâre a consiliului de administrație, pot fi adăugate și alte clauze, a căror natură nu poate afecta interesul superior al antepreșcolarului, al preșcolarului sau al elevului. (5) În unitățile de învățământ preuniversitar din sistemul de apărare, ordine publică și securitate națională, elevii și, în cazul celor minori, împreună cu părinții sau reprezentantul legal al acestora, încheie un contract educațional, al cărui conținut se stabilește prin ordin al conducătorului ministerului de resort, în care sunt înscrise drepturile și obligațiile reciproce ale părților. (6) Direcțiile județene de învățământ preuniversitar/Direcția Municipiului","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R16","theme":"R","prompt":"Școala primitoare aprobă un transfer, dar școala de proveniență pretinde un drept de veto prin avizul său. Cum sunt diferențiate actele CA potrivit ROFUIP?","options":["Acord al CA de proveniență și aviz consultativ al CA primitor.","Acord al CA primitor și aviz consultativ al CA de proveniență.","Acord exclusiv al dirigintelui și aviz obligatoriu al comitetului de părinți.","Acord exclusiv al primarului și aviz obligatoriu al consiliului clasei."],"answer":1,"explanation":"ROFUIP atribuie acordul CA al unității primitoare; avizul CA al unității de proveniență este consultativ. Aceste acte nu au aceeași funcție.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 138","quote":"Transferul beneficiarilor primari ai educației se face cu acordul consiliului de administrație al unității de învățământ primitoare și cu avizul consultativ al consiliului de administrație al unității de învățământ de la care se transferă. Consiliul de administrație al unității de învățământ la care se solicită transferul motivează, în scris, refuzul de aprobare a cererii. (la 18-10-2024, sintagma: Transferul beneficiarilor primari ai educației antepreșcolare face a fost înlocuită de RECTIFICAREA nr. 5.726 din 6 august 2024, publicată în MONITORUL OFICIAL nr. 1046 din 18 octombrie 2024 ) În cazul copiilor victime sau martori ai violenței domestice, inspectoratele școlare","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B13","theme":"B","prompt":"Directorul demonstrează o practică didactică, urmărește aplicarea ei și discută profesional cu profesorii despre rezultate. Ce triadă din Southworth este ilustrată?","options":["Control, sancționare și excludere.","Modelare, monitorizare și dialog.","Planificare, contabilizare și achiziție.","Selecție, clasare și certificare."],"answer":1,"explanation":"Southworth identifică modelarea, monitorizarea și dialogul ca strategii prin care liderii pot influența învățarea. Observarea are aici și funcție de sprijin profesional.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 31","quote":"Importanţa leadershipului şi a managementului educaţional 31 • modelare; • monitorizare; • dialog. Modelarea înseamnă puterea exemplului. Liderii centraţi pe învăţare sunt modele pentru ceilalţi pentru că sunt preocupaţi de actul predării, de învăţare şi de specificul grupurilor de elevi,","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}}]},{"id":5,"title":"Simularea 05","items":[{"id":"L22","theme":"L","prompt":"Școala stabilește oferta CDEOȘ pentru gimnaziu exclusiv după preferințele profesorilor, fără a consulta elevii și părinții. Ce trebuie adăugat procesului?","options":["Consultarea elevilor și părinților, împreună cu analiza resurselor disponibile.","Consultarea exclusivă a absolvenților, împreună cu analiza taxelor propuse.","Consultarea exclusivă a furnizorilor, împreună cu analiza veniturilor acestora.","Consultarea exclusivă a primarului, împreună cu analiza calendarului electoral."],"answer":0,"explanation":"CA stabilește CDEOȘ în urma consultării elevilor și părinților și pe baza resurselor disponibile. Preferința personalului nu este criteriu suficient.","source":{"title":"Legea nr. 198/2023","locator":"Art. 86 alin. (5)","quote":"vocațională, consiliul de administrație al unității de învățământ stabilește curriculumul la decizia elevului din oferta școlii, în urma consultării elevilor, părinților/ reprezentantului legal și pe baza resurselor disponibile. (6) Pentru învățământul liceal tehnologic, CDEOȘ este elaborat de unitatea de învățământ, în parteneriat cu operatorii economici/autoritățile administrației publice locale, pentru adaptarea formării profesionale a elevilor la nevoile locale ale pieței muncii și se implementează pe durata stagiilor de pregătire practică, în funcție de numărul de ore alocat prin planurile-cadru. (7) Proiectarea și aprobarea CDEOȘ pentru filiera tehnologică se stabilesc","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R22","theme":"R","prompt":"La ședința generală a părinților, un cadru didactic dorește să discute public situația individuală a unui copil. Cum trebuie organizată discuția potrivit ROFUIP?","options":["Individual, numai după acordul tuturor comitetelor de părinți din școală.","Individual, numai în prezența părintelui sau reprezentantului legal al copilului.","Public, dacă informațiile sunt prezentate fără documente scrise despre copil.","Public, dacă majoritatea părinților votează discutarea situației copilului."],"answer":1,"explanation":"În adunarea generală se discută problemele generale ale colectivului. Situația unui beneficiar primar se discută individual cu părintele său.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 160","quote":"generale ale colectivului de beneficiari primari, și nu situația concretă a unui beneficiar primar. Situația unui beneficiar primar se discută individual, numai în prezența părintelui/ reprezentantului legal al beneficiarului primar respectiv.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"P09","theme":"P","prompt":"Directorul organizează evaluarea internă, urmărește indicatorii școlii și coordonează raportarea rezultatelor către structurile competente. Ce competență specifică corespunde direct acestui circuit?","options":["Colectarea datelor, analiza și formularea de strategii de îmbunătățire a calității","Managementul incluziunii și al diversității în profilurile de învățare","Monitorizare, evaluare internă și raportare","Responsabilitate publică și relaționare instituțională"],"answer":2,"explanation":"Cazul urmărește ciclul de monitorizare, evaluare internă și raportare. Colectarea datelor pentru proiectarea strategiilor este legată, dar are un accent distinct.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"3.1. Monitorizare, evaluare internă și raportare","quote":"implementează standardele ARACIP și monitorizează respectarea lor la nivelul unității; creează mecanisme de monitorizare și raportare a rezultatelor educaționale, cu termene și responsabilități clare; utilizează instrumente standardizate de evaluare internă; organizează sesiuni de analiză a datelor cu echipa și elaborează planuri de îmbunătățire; coordonează comisii și activități de evaluare internă, implicând întreaga echipă; monitorizează implementarea măsurilor corective și ajustează planurile în funcție de rezultate; elaborează rapoarte de autoevaluare și le aduce la cunoștința comunității; corelează procesul de evaluare cu obiectivele strategice ale instituției.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"C09","theme":"C","prompt":"După selectarea conținuturilor și resurselor, profesorul stabilește succesiunea lecțiilor și proiectează activitățile. Ce întrebare de proiectare este acum centrală?","options":["Cât și cât de bine am realizat?","Cu ce voi face?","Cum voi face?","De ce voi face?"],"answer":2,"explanation":"Stabilirea succesiunii lecțiilor și proiectarea activităților de învățare răspund întrebării Cum voi face?.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"pe care și le pune profesorul în procesul de planificare și de proiectare didactică De ce voi face? Ce voi valorifica? Cu ce voi face? Cum voi face? Cât și cât de bine am realizat? Reflecția asupra relațiilor de derivare dintre competențele specifice, generale, competențele-cheie și atributele prioritare Selectarea conținuturilor învățării, prin raportare la competențele vizate și la standardele de învățare Analiza resurselor curriculare de suport, a celor de timp Stabilirea succesiunii lecțiilor, proiectarea lecțiilor/ activităților de învățare Conceperea modalităților și instrumentelor de evaluare Raportarea la standardele de învățare Ca urmare a reflecției ghidate","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L23","theme":"L","prompt":"Părintele unui elev minor dorește schimbarea opțiunii privind frecventarea Religiei. Școala îi cere votul CA pentru a accepta modificarea. Ce este prevăzut de lege?","options":["Schimbarea opțiunii se face prin avizul profesorului de religie.","Schimbarea opțiunii se face prin cererea scrisă a părintelui.","Schimbarea opțiunii se face prin hotărârea consiliului profesoral.","Schimbarea opțiunii se face prin votul majorității părinților clasei."],"answer":1,"explanation":"Înscrierea și schimbarea opțiunii se fac prin cererea scrisă a elevului major sau a părintelui pentru minor. Legea nu condiționează schimbarea de votul CA.","source":{"title":"Legea nr. 198/2023","locator":"Art. 87 alin. (2)","quote":"de a participa la ora de religie, conform confesiunii proprii. (2) Înscrierea elevului pentru a frecventa orele de religie se face prin cererea scrisă a elevului major sau a părinților/ reprezentantului legal, pentru elevul minor. Schimbarea acestei opțiuni se face tot prin cererea scrisă a elevului major sau a părinților/ reprezentantului legal, pentru elevul minor. În cazul în care elevul nu frecventează orele de religie, situația școlară se încheie fără disciplina Religie. În mod similar se procedează și pentru elevul căruia, din motive obiective, nu i s-au asigurat condițiile pentru frecventarea orelor la această disciplină. Elevului care nu frecventează orele de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R23","theme":"R","prompt":"La alegerea comitetului de părinți al clasei se propun un președinte și patru membri. Ce componență prevede ROFUIP?","options":["Un președinte și cinci membri.","Un președinte și doi membri.","Un președinte și patru membri.","Un președinte și trei membri."],"answer":1,"explanation":"Comitetul clasei este format din trei persoane: un președinte și doi membri. Nu se confundă cu conducerea consiliului reprezentativ al părinților.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 162","quote":"are loc în primele 15 zile calendaristice de la începerea cursurilor anului școlar. Comitetul de părinți pe grupă/clasă se compune din 3 persoane: un președinte și 2 membri. În prima ședință după alegere, membrii comitetului decid responsabilitățile fiecăruia, pe care le comunică educatorului/educatoarei/profesorului pentru educație timpurie/profesorului pentru învățământ preșcolar/profesorului pentru învățământ primar/profesorului diriginte. Comitetul de părinți pe grupă/clasă reprezintă interesele părinților sau ale reprezentanților legali ai beneficiarilor primari ai clasei în adunarea generală a părinților/ reprezentanților legali, în consiliul profesoral, în","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B18","theme":"B","prompt":"O analiză bazată exclusiv pe organigramă explică rolurile, dar nu explică interesele și emoțiile profesorilor. Ce caracteristică a teoriilor discutată de Bush se observă?","options":["Caracterul administrativ: o teorie există numai dacă este aprobată prin regulament.","Caracterul exhaustiv: o teorie explică integral orice dimensiune a organizației.","Caracterul invariabil: o teorie produce aceleași rezultate în orice instituție.","Caracterul selectiv: o teorie evidențiază unele aspecte și lasă altele în plan secund."],"answer":3,"explanation":"Teoriile sunt parțiale și selective. Faptul că o perspectivă explică structura nu înseamnă că explică suficient toate relațiile și comportamentele.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 2, p. 44","quote":"Şi management educaŢional 2. Teoriile tind să fie selective sau parţiale, în sensul că evidenţiază anumite aspecte ale instituţiei în detrimentul altora. Adoptarea unui model teoretic duce la neglijarea altor abordări. Şcolile şi colegiile sunt evident prea complexe pentru a fi analizate pe baza unei singure dimensiuni. De exemplu, o explicaţie a instituţiilor","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H10","theme":"H","prompt":"Directorul află că unele efecte medii ale formării inițiale sunt mici și propune renunțarea la formarea profesorilor. Ce răspuns reflectă mesajul lui Hattie?","options":["Identificarea și îmbunătățirea programelor de succes, pe baza dovezilor impactului.","Păstrarea tuturor programelor identice, fără examinarea rezultatelor lor diferite.","Renunțarea la toate programele, deoarece o medie mică le invalidează pe fiecare.","Selectarea exclusiv după diplomă, fără verificarea practicii și a impactului."],"answer":0,"explanation":"Mesajul nu este abandonarea formării, ci învățarea din programele care demonstrează succes și ajustarea lor în funcție de dovezi.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 9, p. 243–243","quote":"nu este că ar trebui să renunțăm la formarea profesorilor, deoarece mărimea efectului general este mică, ci că ar trebui să celebrăm programele de succes bazate pe dovezile impactului lor, să le învățăm și să le ajustăm. Putem crește standardele formării profesionale doar dacă știm care sunt acestea și la ce se referă, dacă construim o bază cu dovezi de programe de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s9","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=19"}},{"id":"L24","theme":"L","prompt":"Un director dorește să modifice programa unei discipline obligatorii, apoi să o declare programă națională aprobată de CA. Cine aprobă programele obligatorii potrivit legii?","options":["Directorul școlii, prin decizie, după consultarea comisiei pentru curriculum.","Ministrul educației, prin ordin, după elaborarea de organismele abilitate.","Președintele CA, prin hotărâre, după consultarea consiliului profesoral.","Primarul localității, prin dispoziție, după consultarea consiliului local."],"answer":1,"explanation":"Adaptarea didactică nu este aprobarea unei programe naționale. Programele disciplinelor obligatorii sunt elaborate de organismele abilitate și aprobate prin ordin al ministrului.","source":{"title":"Legea nr. 198/2023","locator":"Art. 88 alin. (2)","quote":"obligatorii din învățământul preuniversitar sunt elaborate de instituțiile și organismele abilitate ale Ministerului Educației și se aprobă prin ordin al ministrului educației. Notă A se vedea ORDINUL nr. 3.716 din 21 aprilie 2026 privind aprobarea programelor școlare asociate disciplinelor prevăzute în planurile-cadru pentru învățământul liceal, publicat în MONITORUL OFICIAL nr. 410 din 14 mai 2026. (3) Planurile-cadru ale învățământului liceal includ „Istoria evreilor. Holocaustul“ și „Istoria comunismului din România“, ca discipline școlare, parte a trunchiului comun. (4) Programa școlară, manualele, materialele didactice și metodologiile specifice pentru disciplina","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R24","theme":"R","prompt":"Conducerea programează evaluarea personalului administrativ în septembrie pentru anul școlar precedent. Ce perioadă și referință prevede ROFUIP?","options":["1–30 iunie, pentru anul calendaristic în curs.","1–30 septembrie, pentru anul școlar anterior.","1–31 ianuarie, pentru anul calendaristic anterior.","1–31 martie, pentru anul școlar în curs."],"answer":2,"explanation":"Personalul administrativ este evaluat în perioada 1–31 ianuarie pentru anul calendaristic anterior. Nu se aplică automat calendarul evaluării personalului didactic.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 51","quote":"fișelor de evaluare aduse la cunoștință la începutul anului școlar. (2) Evaluarea personalului administrativ se realizează în perioada 1 – 31 ianuarie a fiecărui an, pentru anul calendaristic anterior. (3) Conducerea unității de învățământ va comunica în scris personalului didactic/didactic auxiliar/administrativ rezultatul evaluării conform fișei specifice.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B19","theme":"B","prompt":"Echipa de conducere valorifică fermitatea, cooperarea, empatia și capacitatea de negociere, fără să le rezerve unui singur gen. Ce propunere descrisă de Bush ilustrează?","options":["Înlocuirea completă a conducerii masculine printr-o conducere exclusiv feminină.","Menținerea exclusivă a controlului competitiv drept normă a conducerii.","Separarea obligatorie a atribuțiilor manageriale în funcție de gen.","Sinteza androgină, care valorifică o gamă largă de calități în echipă."],"answer":3,"explanation":"Modelul androgin permite valorificarea unei game largi de calități întâlnite la bărbați și femei, în special prin abordarea în echipă.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 2, p. 46","quote":"pentru a combate teoriile de management educaţional sau pentru a conduce la reconceptualizarea acestora cu scopul de a include şi bărbaţii, şi femeile (...). Sunt necesare cercetări care contestă stereotipurile tradiţionale cu privire la ceea ce constituie un comportament şi un proces de management adecvat. Asocierea managementului cu masculinitatea nu a","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"P10","theme":"P","prompt":"Directorul explică public rezultatele și deciziile școlii și menține relații instituționale responsabile cu autoritățile și comunitatea. Ce competență specifică este în prim-plan?","options":["Monitorizare, evaluare internă și raportare","Prezentarea și comunicarea informațiilor","Relaționare, comunicare și gestionarea conflictelor","Responsabilitate publică și relaționare instituțională"],"answer":3,"explanation":"Accentul este asumarea responsabilității publice și relaționarea instituțională, nu doar tehnica prezentării unui mesaj sau soluționarea unui conflict interpersonal.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"3.2. Responsabilitate publică și relaționare instituțională","quote":"Comunică public informații relevante pentru a consolida încrederea în instituție și asigură o comunicare activă, proactivă și transparentă cu toți actorii ecosistemului educațional. comunică public, cu regularitate, informații privind rezultatele, resursele și deciziile instituționale; realizează o comunicare activă și proactivă cu actorii ecosistemului educațional local; manifestă disponibilitate pentru a răspunde public cu privire la utilizarea resurselor și impactul acestora; integrează feedbackul elevilor, părinților și partenerilor în procesele decizionale; asigură transparența cheltuielilor în relația cu factorii interesați.","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"L25","theme":"L","prompt":"Un profesor folosește rezultatele evaluării numai pentru clasificarea elevilor și refuză ajustarea predării. Ce finalitate legală a evaluării este neglijată?","options":["Compararea și publicarea exclusivă a ierarhiilor școlare.","Controlarea și sancționarea exclusivă a conduitei elevilor.","Ordonarea și premierea exclusivă a celor mai buni elevi.","Orientarea și optimizarea procesului de predare-învățare."],"answer":3,"explanation":"Evaluarea are scop de orientare și optimizare a predării-învățării, precum și de gestionare a propriilor rezultate ale învățării. Clasamentul singur nu acoperă aceste scopuri.","source":{"title":"Legea nr. 198/2023","locator":"Art. 95 alin. (1)","quote":"(1) Scopurile evaluării sunt orientarea și optimizarea procesului de predare-învățare, precum și gestionarea propriilor rezultate ale învățării. (2) Toate evaluările se realizează pe baza standardelor naționale de evaluare pentru fiecare disciplină, domeniu de studiu și modul de pregătire. Pentru toate disciplinele din învățământul primar, gimnazial și liceal, filierele teoretică, vocațională, precum și tehnologică, pentru disciplinele din trunchiul comun, standardele naționale de evaluare se elaborează de către Centrul Național pentru Curriculum și Evaluare, denumit în","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R25","theme":"R","prompt":"În vacanță, cataloagele pe suport letric rămân în cancelarie, într-un dulap deschis. Ce măsură respectă ROFUIP?","options":["Păstrarea în cancelarie, fără evidența accesului.","Păstrarea la secretariat, în condiții de securitate.","Predarea către comitetul de părinți al fiecărei clase.","Predarea către fiecare elev major din clasă."],"answer":1,"explanation":"În cursul anului, cataloagele sunt păstrate securizat în cancelarie; în vacanțe, la secretariat, în aceleași condiții de securitate.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 75","quote":"încheind un proces-verbal în acest sens. În perioada cursurilor, cataloagele se păstrează în cancelarie, într-un fișet securizat, iar în perioada vacanțelor școlare, la secretariat, în aceleași condiții de siguranță. În situații speciale, atribuțiile prevăzute la alin. (1) și (2) pot fi îndeplinite, prin delegare de sarcini, și de către cadre didactice sau personal didactic auxiliar, din cadrul unității de învățământ, cu acordul prealabil al personalului solicitat. Condiționarea de orice beneficii a eliberării actelor de studii, a documentelor școlare sau a caracterizărilor este interzisă. Secretarul-șef/Secretarul răspunde de gestionarea actelor de studii și a documentelor","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B20","theme":"B","prompt":"La selecția liderilor, școala apreciază agresivitatea competitivă, controlul și confruntarea, ignorând negocierea și rezolvarea comună a problemelor. Ce critică din Bush este relevantă?","options":["Imaginea managerială descrisă garantează accesul egal la toate funcțiile de conducere.","Imaginea masculină stereotipă poate privilegia controlul în detrimentul colaborării.","Imaginea organizațională descrisă plasează colaborarea înaintea competiției.","Imaginea profesională descrisă elimină orice stereotip din selecția liderilor."],"answer":1,"explanation":"Analiza discută o imagine stereotipă a managementului centrată pe competiție și control, care poate funcționa ca barieră în accesul la conducere.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 2, p. 45","quote":"a managementului, ce poate părea neatractivă pentru femei. Acest model include „comportamentul competitiv agresiv, evidenţierea controlului în defavoarea negocierii şi colaborării şi urmărirea competiţiei în detrimentul rezolvării problemelor comune” (Al‑Khalifa, 1992: 100). Dominaţia masculină sau „androcentricitatea” managementului","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"C10","theme":"C","prompt":"Profesorul concepe instrumentele prin care va verifica nivelul atins de elevi în raport cu standardele. Ce întrebare a proiectării îi organizează demersul?","options":["Cât și cât de bine am realizat?","Ce voi valorifica?","Cu ce voi face?","De ce voi face?"],"answer":0,"explanation":"Conceperea evaluării și raportarea la standardele de învățare răspund întrebării Cât și cât de bine am realizat?.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"le pune profesorul în procesul de planificare și de proiectare didactică De ce voi face? Ce voi valorifica? Cu ce voi face? Cum voi face? Cât și cât de bine am realizat? Reflecția asupra relațiilor de derivare dintre competențele specifice, generale, competențele-cheie și atributele prioritare Selectarea conținuturilor învățării, prin raportare la competențele vizate și la standardele de învățare Analiza resurselor curriculare de suport, a celor de timp Stabilirea succesiunii lecțiilor, proiectarea lecțiilor/ activităților de învățare Conceperea modalităților și instrumentelor de evaluare Raportarea la standardele de învățare Ca urmare a reflecției ghidate de întrebările","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L21","theme":"L","prompt":"După evaluare, doi elevi au dificultăți diferite. Directorul cere un plan identic pentru amândoi, fără consultarea familiilor. Ce abordare corespunde legii?","options":["Planuri adaptate nevoilor, construite prin interacțiunea profesor-elev-părinte.","Planuri identice pentru clasă, construite exclusiv după succesiunea manualului.","Planuri limitate la absențe, construite exclusiv de compartimentul secretariat.","Planuri stabilite de furnizor, construite exclusiv după prețul resurselor."],"answer":0,"explanation":"Planul individualizat pornește de la evaluări, ține cont de nevoile și ritmul elevului și se dezvoltă prin interacțiunea profesorului, elevului și părintelui.","source":{"title":"Legea nr. 198/2023","locator":"Art. 85 alin. (3)-(5)","quote":"transdisciplinare, interdisciplinare sau pluridisciplinare. (3) În vederea atingerii competențelor vizate, cadrele didactice realizează planuri individualizate de învățare. Acestea reprezintă un instrument de planificare și monitorizare a învățării la nivelul fiecărui elev, care stă la baza individualizării oportunităților de învățare pe care le oferă școala. (4) Planul individual de învățare are următoarele caracteristici: a) pornește de la rezultatele evaluărilor elevului cu caracter formativ și sumativ; b) ia în considerare nevoile de învățare ale fiecărui elev, care sunt diferite și, prin urmare, trebuie abordate diferit; c) valorifică experiențele de învățare anterioare ale","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R21","theme":"R","prompt":"Un părinte declară că va lua legătura cu dirigintele numai la sfârșitul anului școlar. Ce frecvență minimă prevede ROFUIP pentru cunoașterea evoluției copilului?","options":["Minimum o dată pe an, prin mijloace stabilite de comun acord.","Minimum o dată pe ciclu, prin mijloace stabilite de comun acord.","Minimum o dată pe lună, prin mijloace stabilite de comun acord.","Minimum o dată pe săptămână, prin prezență obligatorie la școală."],"answer":2,"explanation":"Obligația este minimum o dată pe lună. Comunicarea poate folosi mijloace convenite; nu înseamnă obligatoriu prezență fizică la fiecare contact.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 157","quote":"de sănătate a celorlalți beneficiari primari din colectivitate/unitatea de învățământ. Părintele/reprezentantul legal are obligația ca, minimum o dată pe lună, să ia legătura cu profesorul pentru învățământul antepreșcolar/preșcolar/învățătorul/institutorul/profesorul pentru învățământul primar/profesorul diriginte pentru a cunoaște evoluția copilului/elevului, prin mijloace stabilite de comun acord. Prezența părintelui sau a reprezentantului legal va fi consemnată în caietul educatorului/educatoarei/profesorului pentru educație timpurie/ învățătorului/institutorului/profesorului pentru învățământ preșcolar/primar/profesorului diriginte, cu nume, dată și semnătură.","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B17","theme":"B","prompt":"O echipă explică un conflict prin distribuția puterii, alta prin valori culturale. Ambele identifică aspecte susținute de observații. Ce atitudine teoretică este adecvată?","options":["Acceptarea unei singure perspective doar pentru că este mai veche.","Examinarea mai multor perspective care pot fi valide simultan.","Înlocuirea observațiilor cu alegerea aleatorie a unei teorii universale.","Respingerea tuturor perspectivelor care nu confirmă poziția directorului."],"answer":1,"explanation":"În educație pot exista mai multe perspective valide simultan. Ele pot ilumina aspecte diferite ale aceleiași situații, fără a deveni teorii complete.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 2, p. 41","quote":"acest sens, perspectiva este o susţinere mai slabă a cunoştinţelor decât o teorie ştiinţifică. În educaţie, mai multe perspective pot fi valide simultan: Înţelegerea noastră a proceselor de utilizare a cunoaşterii este concepută nu atât ca un set de date, descoperiri sau generalizări, cât ca perspective distincte ce combină date, valori şi presupoziţii într‑un filtru","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H09","theme":"H","prompt":"Un program de formare inițială este apărat doar prin tradiție și opiniile formatorilor, fără date despre pregătirea absolvenților. Ce solicitare rezultă din Hattie?","options":["Eliminarea evaluării programului pentru a proteja autonomia formatorilor.","Examinarea dovezilor privind efectele programului și pregătirea pentru predare.","Înlocuirea dovezilor de impact cu numărul de opinii favorabile ale organizatorilor.","Păstrarea programului neschimbat numai pentru că a fost utilizat mult timp."],"answer":1,"explanation":"Hattie critică insuficiența datelor despre formarea inițială și susține examinarea programelor prin dovezi de impact, nu doar prin tradiție.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 8, p. 241–242","quote":"devină profesori. Mai mult, e surprinzător că formarea viitorilor profesori pare atât de lipsită de date; poate că așa învață ei să ignore dovezile, să pună preț pe îndemânare și să caute dovezi pozitive că schimbă lucrurile (undeva, cumva, cu cineva). Trei până la cinci ani de pregătire par să ducă la profesori care reproduc, profesori care îl copiază pe","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s8","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=17"}}]},{"id":6,"title":"Simularea 06","items":[{"id":"R27","theme":"R","prompt":"Administratorul financiar propune să numească singur comisia de inventariere. Cine emite actul de numire potrivit ROFUIP?","options":["Contabilul, prin notă internă.","Directorul, prin decizie.","Dirigintele, prin proces-verbal.","Primarul, prin dispoziție."],"answer":1,"explanation":"Inventarierea este realizată de comisia de inventariere numită prin decizia directorului. Compartimentul financiar nu își atribuie singur această competență.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 84","quote":"Inventarierea bunurilor unității de învățământ se realizează de către comisia de inventariere, numită prin decizia directorului. Modificările care se operează în listele ce cuprind bunurile aflate în proprietatea unității de învățământ se supun aprobării consiliului de administrație de către director, la propunerea administratorului de patrimoniu, în baza solicitării compartimentelor funcționale.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"P11","theme":"P","prompt":"Directorul coordonează adaptări pentru elevi cu CES, colaborează cu serviciile de sprijin și verifică participarea și progresul elevilor vulnerabili. Ce competență specifică este vizată direct?","options":["Asigurarea succesului școlar al elevilor și a performanței cadrelor didactice","Colectarea datelor, analiza și formularea de strategii de îmbunătățire a calității","Leadership incluziv, stare de bine a elevilor și a personalului școlii, securitate și siguranță școlară","Managementul incluziunii și al diversității în profilurile de învățare"],"answer":3,"explanation":"Intervențiile sunt organizate în raport cu incluziunea și diversitatea profilurilor de învățare, cu servicii de sprijin și monitorizarea impactului măsurilor.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"3.3. Managementul incluziunii și al diversității în profilurile de învățare","quote":"asigură educația incluzivă la nivelul unității și implementează măsuri specifice pentru copiii cu CES; gestionează diversitatea culturală, lingvistică și socioeconomică a comunității școlare; implementează măsuri de echitate educațională și previne orice formă de discriminare; promovează egalitatea de șanse și valorizează diversitatea ca resursă instituțională; monitorizează impactul măsurilor de incluziune asupra participării și rezultatelor elevilor; colaborează cu centrele de resurse și asistență educațională, direcțiile generale de asistență socială și protecția copilului și alte instituții de suport pentru elevii vulnerabili.","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"C11","theme":"C","prompt":"Profesorul stabilește unitățile de învățare, succesiunea lor și bugetul de timp pentru întregul an. Ce document rezultă direct din acest nivel al proiectării?","options":["Planificarea calendaristică a disciplinei.","Planul de management administrativ-financiar.","Proiectul detaliat al unei singure lecții.","Raportul anual de evaluare internă."],"answer":0,"explanation":"Planificarea calendaristică organizează unitățile de învățare, succesiunea, competențele și timpul. Proiectul lecției are altă scară de detaliu.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"așa fel încât să optimizeze învățarea pentru fiecare elev și să asigure progresul individual în dezvoltarea competențelor. De exemplu, în planificarea calendaristică, în proiectarea unităților de învățare și a lecției/ activității de învățare, profesorul este autonom să se orienteze în funcție de ritmurile de învățare ale elevilor, de nivelurile lor de performanță și de potențialul lor de învățare. Schemele de mai jos ilustrează demersul logic secvențial al planificării și proiectării activității didactice la clasă (planificarea calendaristică, proiectarea unității de învățare, proiectarea lecției/ activității de învățare). Toate aceste componente ale proiectării sunt interdependente","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L28","theme":"L","prompt":"Consiliul profesoral propune oferta CDEOȘ, iar elevii și părinții au fost consultați. Cine aprobă oferta la nivelul școlii potrivit Legii 198?","options":["Compartimentul secretariat al unității de învățământ.","Consiliul de administrație al unității de învățământ.","Consiliul reprezentativ al părinților din unitatea de învățământ.","Consiliul școlar al elevilor din unitatea de învățământ."],"answer":1,"explanation":"Propunerea aparține consiliului profesoral, consultarea privește elevii și părinții, iar aprobarea aparține CA.","source":{"title":"Legea nr. 198/2023","locator":"Art. 128 alin. (9) lit. c)","quote":"unității de învățământ; c) aprobă, la propunerea consiliului profesoral și după consultarea consiliului școlar al elevilor și părinților, curriculumul la decizia elevului din oferta școlii; d) analizează și aprobă propunerile de colaborare cu terții, în condițiile legii și cu respectarea principiului interesului superior al beneficiarului primar; e) aprobă planul de încadrare cu personal didactic de predare și didactic auxiliar, precum și schema de personal administrativ, în conformitate cu normele metodologice aprobate prin ordin al ministrului educației; f) aprobă programe de dezvoltare profesională a salariaților, la propunerea consiliului profesoral; g) stabilește sancțiunile","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R28","theme":"R","prompt":"Un spațiu temporar disponibil al școlii urmează să fie închiriat. Directorul dorește să decidă singur, invocând conducerea executivă. Ce bază cere ROFUIP?","options":["Hotărârea CA, în condițiile legii.","Hotărârea comitetului de părinți.","Hotărârea consiliului clasei.","Hotărârea consiliului elevilor."],"answer":0,"explanation":"ROFUIP prevede închirierea bunurilor temporar disponibile în baza hotărârii CA, în condițiile legii. Conducerea executivă nu înlocuiește aprobarea.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 86","quote":"Bunurile, care sunt temporar disponibile și care sunt în proprietatea sau administrarea unității de învățământ, pot fi închiriate în baza hotărârii consiliului de administrație.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B22","theme":"B","prompt":"Conducerea pune în centrul vieții școlii valorile și tradițiile comune, iar directorul urmărește să fie un reper etic. Ce pereche din matricea Bush este relevantă?","options":["Cultural – moral.","Formal – managerial.","Politic – tranzacțional.","Subiectiv – postmodern."],"answer":0,"explanation":"Accentul pe valori, credințe și tradiții comune indică modelul cultural. Leadershipul moral este asocierea din tabel.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 2, p. 51","quote":"Colegial Participativ Transformaţional Distribuit Politic Tranzacţional Subiectiv Postmodern Emoţional De ambiguitate Circumstanţial Cultural Moral Al instruirii Sursa: adaptat după Bush şi Glover, 2002. Leadershipul instruirii, deseori descris ca fiind leadership centrat pe învăţare, nu se leagă de niciun model de management, deoarece se concentrează asupra","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H12","theme":"H","prompt":"Un mentor observă practica profesorului, stabilește împreună cu el obiective, identifică o intervenție și oferă sprijin până la atingerea lor. Ce demers din Hattie este ilustrat?","options":["Clasificare formală bazată exclusiv pe numărul de diplome.","Coaching individualizat, contextualizat și orientat spre obiective.","Evaluare administrativă bazată exclusiv pe vechimea profesorului.","Inspecție financiară bazată exclusiv pe justificarea cheltuielilor."],"answer":1,"explanation":"Modelele de coaching au în comun analiza situației, stabilirea obiectivelor, intervenția și sprijinul până la realizare. Nu se reduc la o inspecție administrativă.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 11, p. 246–246","quote":"impactul asupra performanței elevilor. Numitorul comun al multor modele de instruire include analizarea situației curente standard, stabilirea de obiective, identificarea intervenției și oferirea de sprijin până la îndeplinirea obiectivelor (adesea cu observații și reacții din partea clasei). Instruirea tinde să fie „individualizată, consumatoare de timp, cu o durată de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s11","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=22"}},{"id":"L29","theme":"L","prompt":"O școală cu secții de predare în limba unei minorități are director și director adjunct. Conducerea afirmă că niciunul nu trebuie să cunoască limba secției. Ce cere legea?","options":["Numai profesorul diriginte are obligația cunoașterii limbii respective.","Numai secretarul școlii are obligația cunoașterii limbii respective.","Toți reprezentanții părinților au obligația cunoașterii limbii respective.","Unul dintre directori are obligația cunoașterii limbii respective."],"answer":3,"explanation":"Pentru școlile cu secții de predare în limbile minorităților, legea cere ca unul dintre directori să cunoască limba respectivă.","source":{"title":"Legea nr. 198/2023","locator":"Art. 195 alin. (1)","quote":"În cazul unităților de învățământ cu secții de predare în limbile minorităților naționale/studiul limbii minorității naționale, unul dintre directori are obligația cunoașterii limbii respective. În aceste cazuri, numirea directorului se face cu consultarea organizației care reprezintă minoritatea respectivă în Parlamentul României sau, dacă minoritatea nu are reprezentare parlamentară, cu consultarea Grupului parlamentar al minorităților naționale. (2) Directorul unității de învățământ de stat are următoarele atribuții: a) este reprezentantul legal al unității de învățământ și realizează conducerea executivă a acesteia; b) este ordonatorul de credite al unității de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R29","theme":"R","prompt":"O comisie permanentă își încetează activitatea după prima lună de cursuri, afirmând că va fi reînființată la nevoie. Cum este definită activitatea ei?","options":["Se desfășoară exclusiv în prima lună de cursuri.","Se desfășoară exclusiv în vacanțele elevilor.","Se desfășoară numai în ziua emiterii deciziei.","Se desfășoară pe tot parcursul anului școlar."],"answer":3,"explanation":"Comisiile permanente funcționează pe tot parcursul anului școlar. Cele temporare și ocazionale au un regim diferit.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 71","quote":"interculturalității; comisia pentru formare și dezvoltare în cariera didactică. Comisiile cu caracter permanent își desfășoară activitatea pe tot parcursul anului școlar, comisiile cu caracter temporar își desfășoară activitatea doar în anumite perioade ale anului școlar, iar comisiile cu caracter ocazional sunt înființate ori de câte ori se impune constituirea unei astfel de comisii, pentru rezolvarea unor probleme specifice apărute la nivelul unității de învățământ. Comisiile cu caracter temporar și ocazional vor fi stabilite de fiecare unitate de învățământ, prin regulamentul de organizare și funcționare a unității de învățământ.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B23","theme":"B","prompt":"Profesorii participă la definirea politicii școlii prin discuție profesională și căutarea consensului, iar conducerea facilitează participarea. Ce pereche din matricea Bush este potrivită?","options":["Colegial – participativ.","Cultural – managerial.","Formal – tranzacțional.","Politic – postmodern."],"answer":0,"explanation":"Modelul colegial presupune implicarea membrilor și acord profesional. Leadershipul participativ este una dintre asocierile sale din tabel.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 2, p. 51","quote":"de management Tabelul 2.1. Tipologia modelelor de management şi leadership Modelul de management Modelul de leadership Formal Managerial Colegial Participativ Transformaţional Distribuit Politic Tranzacţional Subiectiv Postmodern Emoţional De ambiguitate Circumstanţial Cultural Moral Al instruirii Sursa: adaptat după Bush şi Glover, 2002. Leadershipul","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"P12","theme":"P","prompt":"Conducerea colectează rezultate și date despre participare, identifică tipare și cauze, apoi formulează strategii de îmbunătățire a calității. Ce competență specifică descrie întregul demers?","options":["Asigurarea succesului școlar al elevilor și a performanței cadrelor didactice","Colectarea datelor, analiza și formularea de strategii de îmbunătățire a calității","Managementul implementării curriculumului și al proceselor de evaluare","Managementul incluziunii și al diversității în profilurile de învățare"],"answer":1,"explanation":"Demersul merge de la colectarea și analiza datelor la formularea strategiilor de îmbunătățire. Simplul raport descriptiv nu acoperă această funcție.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"3.4. Colectarea datelor, analiza și formularea de strategii de îmbunătățire a calității","quote":"Utilizează metode de cercetare empirică și analize de date pentru a fundamenta deciziile curriculare, organizaționale și de dezvoltare profesională. colectează și analizează date relevante privind performanța școlii — rezultate evaluări, rate de participare, feedback; derulează analize de nevoi, studii de satisfacție a beneficiarilor și cercetare-acțiune la nivel instituțional; utilizează indicatori statistici relevanți pentru decizii privind curriculum, evaluare și dezvoltare profesională; formulează strategii de îmbunătățire a calității bazate pe evidențe și le monitorizează implementarea; organizează sesiuni de analiză și reflecție cu echipa pe baza datelor colectate.","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"L30","theme":"L","prompt":"Un câștigător al concursului este informat că mandatul său de director va fi de 5 ani. Ce durată prevede textul Legii 198 pentru numirea în urma concursului?","options":["Un mandat de 3 ani, prin decizia directorului general.","Un mandat de 4 ani, prin decizia directorului general.","Un mandat de 5 ani, prin decizia directorului general.","Un mandat de 6 ani, prin decizia directorului general."],"answer":1,"explanation":"Durata prevăzută de lege este de 4 ani pentru director și director adjunct numiți după concurs. Nu se confundă durata mandatului cu durata altor documente manageriale.","source":{"title":"Legea nr. 198/2023","locator":"Art. 196 alin. (4)","quote":"vocațional teologic. (4) Persoanele care au câștigat concursul sunt numite în funcțiile de director și de director adjunct pentru o perioadă de 4 ani, prin decizie a directorului general al DJIP/DMBIP. De la data numirii, în vederea îndeplinirii atribuțiilor specifice funcției, directorul și directorul adjunct încheie cu directorul general al DJIP/DMBIP un contract de management educațional. (5) În urma selectării prin concurs, directorul supune avizării consiliului de administrație al unității de învățământ și, ulterior, primarului, în vederea aprobării, planul de management administrativ-financiar pentru perioada mandatului de 4 ani și încheie cu primarul un contract","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R30","theme":"R","prompt":"Un responsabil propune ca profesorii diriginți să fie desemnați de părinți, fără hotărâre CA. Cine îi numește potrivit ROFUIP?","options":["Comitetul de părinți, anual, în baza votului clasei.","Consiliul elevilor, anual, în baza votului profesorilor.","Directorul, anual, în baza hotărârii CA.","Primarul, anual, în baza hotărârii consiliului local."],"answer":2,"explanation":"Profesorii diriginți sunt numiți anual de director în baza hotărârii CA. Consultarea și continuitatea nu mută competența de numire către părinți.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 65","quote":"Profesorii diriginți sunt numiți, anual, de către directorul unității de învățământ, în baza hotărârii consiliului de administrație. La numirea profesorilor diriginți se are în vedere, în măsura posibilităților, principiul continuității, astfel încât clasa să aibă același diriginte pe parcursul unui nivel de învățământ. De regulă, poate fi numit profesor diriginte un cadru didactic titular sau suplinitor care a dobândit definitivarea/licențierea în învățământ, are cel puțin o jumătate din norma didactică în unitatea de învățământ și predă la clasa respectivă.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B24","theme":"B","prompt":"Directorul coordonează școala prin funcții oficiale, sarcini delimitate, proceduri și autoritate ierarhică. Ce pereche din matricea Bush corespunde orientării?","options":["Colegial – tranzacțional.","Cultural – postmodern.","Formal – managerial.","Politic – participativ."],"answer":2,"explanation":"Modelul formal evidențiază structura oficială și rolurile instituționale; leadershipul managerial este asocierea din matricea de sinteză.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 2, p. 51","quote":"cu cele şase modele de management Tabelul 2.1. Tipologia modelelor de management şi leadership Modelul de management Modelul de leadership Formal Managerial Colegial Participativ Transformaţional Distribuit Politic Tranzacţional Subiectiv Postmodern Emoţional De ambiguitate Circumstanţial Cultural Moral Al instruirii Sursa: adaptat după Bush şi Glover, 2002.","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"C12","theme":"C","prompt":"Profesorul detaliază conținuturile unei unități, le structurează în lecții și le asociază competențelor, activităților și evaluării. Ce document elaborează?","options":["Planul anual de achiziții publice.","Programul concediilor personalului.","Proiectul unității de învățare.","Raportul anual asupra calității."],"answer":2,"explanation":"Proiectul unității de învățare detaliază relația dintre competențe, conținuturi, lecții, activități, resurse și evaluare pentru unitatea respectivă.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"urmare a reflecției ghidate de întrebările anterioare, profesorul realizează următoarele documente școlare: planificarea calendaristică, proiectul unității de învățare, proiectul lecției. Planificarea calendaristică – rezultat al unui proces de elaborare a răspunsurilor la întrebări precum: Care sunt unitățile de învățare prin care ajung la competențele specifice din programa școlară? În ce succesiune vor fi abordate acestea? Care sunt relațiile dintre unitățile de învățare (intra- și interdisciplinar)? Care sunt competențele specifice asociate fiecărei unități de învățare? Care este bugetul de timp asociat fiecărei unități de învățare? Care sunt conținuturile învățării","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L26","theme":"L","prompt":"Într-un proiect, echipa înscrie părinții la categoria beneficiarilor primari și elevii la cea a beneficiarilor secundari. Ce încadrare trebuie corectată?","options":["Elevii sunt beneficiari primari, iar părinții sunt beneficiari secundari.","Elevii sunt beneficiari terțiari, iar părinții sunt beneficiari primari.","Elevii și părinții sunt exclusiv beneficiari secundari ai educației.","Elevii și părinții sunt exclusiv beneficiari terțiari ai educației."],"answer":0,"explanation":"Legea distinge beneficiarii primari, între care elevii, de beneficiarii secundari, între care părinții sau reprezentanții legali.","source":{"title":"Legea nr. 198/2023","locator":"Art. 105 alin. (1)-(3)","quote":"preuniversitar sunt antepreșcolarii, preșcolarii și elevii, precum și persoanele adulte înscrise într-o unitate de învățământ. (2) Beneficiarii secundari ai învățământului preuniversitar sunt părinții, tutorii sau reprezentanții legali ai antepreșcolarilor, ai preșcolarilor și ai elevilor. (3) Beneficiarii terțiari ai sistemului de învățământ preuniversitar sunt comunitatea locală și societatea în ansamblul ei. (4) Drepturile și îndatoririle elevilor sunt prevăzute în Statutul elevului, aprobat prin ordin al ministrului educației, în urma consultării Consiliului Național al Elevilor și a altor asociații reprezentative la nivel național ale elevilor. Notă A se vedea ORDINUL","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R26","theme":"R","prompt":"O ofertă de mobilier expiră astăzi. Directorul dorește să angajeze cheltuiala, deși sursa de finanțare nu este asigurată. Ce regulă se aplică?","options":["Cheltuiala nu poate fi angajată fără sursă de finanțare asigurată.","Cheltuiala nu poate fi verificată decât după recepția mobilierului.","Cheltuiala poate fi angajată dacă furnizorul promite o reducere.","Cheltuiala poate fi angajată dacă părinții promit donații viitoare."],"answer":0,"explanation":"ROFUIP interzice angajarea cheltuielilor fără sursă de finanțare. Urgența comercială nu constituie o excepție.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 80","quote":"Este interzisă angajarea de cheltuieli dacă nu este asigurată sursa de finanțare. Resursele extrabugetare ale unității pot fi folosite exclusiv de aceasta, conform hotărârii consiliului de administrație.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B21","theme":"B","prompt":"Directorul negociază cu grupurile de profesori și oferă resurse în schimbul sprijinului pentru o reorganizare. Disputele se încheie prin compromis. Ce pereche din tabelul Bush corespunde cazului?","options":["Cultural – moral.","Formal – managerial.","Politic – tranzacțional.","Subiectiv – postmodern."],"answer":2,"explanation":"Interesele, negocierea și schimbul de sprijin indică modelul politic; în matrice îi corespunde leadershipul tranzacțional.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 2, p. 51","quote":"management şi leadership Modelul de management Modelul de leadership Formal Managerial Colegial Participativ Transformaţional Distribuit Politic Tranzacţional Subiectiv Postmodern Emoţional De ambiguitate Circumstanţial Cultural Moral Al instruirii Sursa: adaptat după Bush şi Glover, 2002. Leadershipul instruirii, deseori descris ca fiind leadership centrat pe","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H11","theme":"H","prompt":"După un curs, toți profesorii completează chestionare de satisfacție favorabile. Directorul declară automat că învățarea elevilor s-a îmbunătățit. Ce dovadă mai trebuie urmărită?","options":["Numărul diplomelor tipărite și satisfacția formatorilor.","Numărul fotografiilor publicate și prestigiul locației.","Schimbarea practicii la clasă și efectele asupra elevilor.","Schimbarea siglei cursului și popularitatea organizatorului."],"answer":2,"explanation":"Satisfacția profesorilor nu este echivalentă cu efectul asupra elevilor. Dezvoltarea profesională trebuie examinată și prin schimbarea practicii și îmbunătățirea învățării.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 10, p. 244–245","quote":"Programe de dezvoltare profesională Mult prea frecvent, formarea profesională este evaluată în funcție de efectele asupra profesorului (satisfacție, plăcere și învățare percepută din cursuri) și mult mai puțin în funcție de efectele asupra îmbunătățirii reale a practicii din clasă și de efectele asupra elevilor. *Wade (1985) a împărțit rezultatele în patru","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s10","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=20"}},{"id":"L27","theme":"L","prompt":"Directorul finalizează PDI și solicită consiliului profesoral să îl aprobe definitiv. Cine are atribuția de aprobare potrivit Legii 198?","options":["Consiliul de administrație, la propunerea directorului.","Consiliul profesoral, la propunerea comisiei de inventariere.","Consiliul reprezentativ al părinților, la propunerea dirigintelui.","Consiliul școlar al elevilor, la propunerea profesorilor."],"answer":0,"explanation":"CA aprobă PDI/PAS la propunerea directorului. Dezbaterea și avizarea în alte structuri nu echivalează cu aprobarea finală.","source":{"title":"Legea nr. 198/2023","locator":"Art. 128 alin. (9) lit. b)","quote":"următoarele atribuții principale: a) adoptă proiectul de buget și avizează execuția bugetară la nivelul unității de învățământ; b) aprobă planul de dezvoltare instituțională, respectiv planul de acțiune al unității de învățământ preuniversitar, la propunerea directorului unității de învățământ; c) aprobă, la propunerea consiliului profesoral și după consultarea consiliului școlar al elevilor și părinților, curriculumul la decizia elevului din oferta școlii; d) analizează și aprobă propunerile de colaborare cu terții, în condițiile legii și cu respectarea principiului interesului superior al beneficiarului primar; e) aprobă planul de încadrare cu personal didactic de predare și didactic","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}}]},{"id":7,"title":"Simularea 07","items":[{"id":"P13","theme":"P","prompt":"Directorul corelează nevoile de personal cu încadrarea, distribuirea responsabilităților, evaluarea și dezvoltarea profesională a angajaților. Ce competență specifică este centrală?","options":["Antreprenoriat educațional și inovație","Cercetare, inovație pedagogică și conceptualizare strategică","Managementul implementării curriculumului și al proceselor de evaluare","Managementul resurselor umane"],"answer":3,"explanation":"Cazul reunește funcțiile managementului resurselor umane. Resursele financiare sau proiectarea curriculumului pot avea legături, dar nu sunt centrul situației.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"4.1. Managementul resurselor umane","quote":"analizează periodic nevoile de formare ale personalului; elaborează și implementează planul de formare continuă la nivelul unității, corelat cu prioritățile strategice; sprijină cadrele didactice debutante și facilitează inserția lor profesională — mentorat, coaching; utilizează tehnici de motivare a personalului didactic și administrativ; distribuie responsabilitățile în mod echilibrat și transparent; creează oportunități pentru dezvoltarea competențelor digitale ale personalului; gestionează cu profesionalism procedurile disciplinare atunci când este necesar; monitorizează nivelul de satisfacție și implicare al personalului.","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"C13","theme":"C","prompt":"Înaintea unei lecții, profesorul verifică ce achiziții anterioare au elevii și cum le poate folosi pentru noile standarde de învățare. Ce analizează?","options":["Exclusiv dotările administrative ale cabinetului directorului.","Exclusiv rezultatele financiare ale partenerilor școlii.","Preferințele editoriale ale autorilor de manuale școlare.","Prerechizitele învățării și valorificarea lor în lecție."],"answer":3,"explanation":"Proiectarea lecției include întrebarea privind prerechizitele elevilor și folosirea lor pentru standardele vizate. Nu pornește doar de la conținutul nou.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"operaționalizare, conduc progresiv la atingerea standardelor de învățare, nesubstituindu-se descriptorilor nivelurilor de performanță.) Ce prerechizite ale învățării au elevii și cum vor fi valorificate acestea pentru realizarea standardelor de învățare vizate? Care sunt cele mai relevante conținuturi, din punct de vedere calitativ și cantitativ, pentru standardele de învățare vizate? Cum organizez, selectez, adaptez și integrez conținuturile învățării din lecție, inclusiv în funcție de nevoile de învățare ale elevilor? Care sunt activitățile de învățare cele mai relevante pentru standardele de învățare și pentru conținuturile învățării vizate? Cum adaptez activitățile de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L33","theme":"L","prompt":"O școală cu internat și cantină identifică sursa pentru subvențiile acestor servicii. Unde sunt prevăzute ele în lege?","options":["În bugetele personale obligatorii ale profesorilor diriginți.","În cotizațiile obligatorii ale tuturor elevilor din școală.","În finanțarea complementară a unităților de învățământ.","În finanțarea de bază exclusiv pentru salariile profesorilor."],"answer":2,"explanation":"Articolul include explicit subvențiile pentru internate și cantine la finanțarea complementară.","source":{"title":"Legea nr. 198/2023","locator":"Art. 140 alin. (2) lit. b)","quote":"de stat cu această destinație, pentru următoarele categorii de cheltuieli: a) investiții, reparații capitale și curente, consolidări; b) subvenții pentru internate și cantine; c) cheltuieli pentru evaluarea periodică națională a elevilor; d) cheltuieli pentru examinarea medicală obligatorie periodică a salariaților din învățământul preuniversitar; e) cheltuieli pentru concursuri școlare și activități educative extrașcolare, centre de excelență organizate în cadrul sistemului de învățământ; f) cheltuieli pentru asigurarea securității și sănătății, pentru personalul angajat, beneficiarii primari; g) gestionarea situațiilor de urgență; h) cheltuieli pentru asigurarea suplinirii cadrelor","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R33","theme":"R","prompt":"Conducerea condiționează aprecierea elevilor de participarea la o excursie extrașcolară cu taxă. Ce principiu din ROFUIP este încălcat?","options":["Accesul la activități extrașcolare exclusiv pentru elevii cu medii foarte mari.","Accesul la activități extrașcolare exclusiv prin participarea obligatorie a tuturor.","Accesul la activități extrașcolare exclusiv prin plata unei contribuții uniforme.","Accesul la activități extrașcolare fără impunerea obligativității și fără discriminare."],"answer":3,"explanation":"Cadrele didactice motivează participarea și sprijină accesul fără obligativitate și fără discriminare. Nu transformă excursia în condiție de apreciere școlară.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 99","quote":"activități educaționale extrașcolare și îi motivează pentru implicarea în activități extrașcolare, sprijinind accesul la aceste activități fără impunerea obligativității și fără nicio discriminare. Evaluarea activității educaționale extrașcolare derulate la nivelul unității de învățământ este parte a evaluării instituționale a respectivei unități de învățământ.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B26","theme":"B","prompt":"Un cercetător refuză să lege exclusiv leadershipul instruirii de un singur model de management. Ce justificare oferă Bush pentru această poziționare?","options":["Privește direcția influenței spre învățare și predare, nu natura procesului de influență.","Privește exclusiv conformitatea financiară a școlii, nu activitatea de predare-învățare.","Privește exclusiv puterea de negociere a grupurilor, nu rezultatele procesului didactic.","Privește exclusiv structura ierarhică a școlii, nu comportamentul cadrelor didactice."],"answer":0,"explanation":"Leadershipul instruirii nu este legat de un singur model deoarece se definește prin orientarea spre predare și învățare, nu printr-o singură natură a influenței.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 2, p. 51","quote":"deseori descris ca fiind leadership centrat pe învăţare, nu se leagă de niciun model de management, deoarece se concentrează asupra direcţiei influenţării, învăţării şi predării, şi nu asupra naturii proceselor de influenţă. Acest model a fost discutat în capitolul 1, iar celelalte nouă modele de leadership vor fi abordate în cadrul modelului de management","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H14","theme":"H","prompt":"Un profesor rezolvă corect problemele, dar nu anticipează erorile elevilor și nu găsește explicații potrivite. Ce distincție din Hattie este relevantă?","options":["Cunoașterea materiei face inutilă adaptarea explicațiilor la gândirea elevilor.","Cunoașterea materiei garantează automat înțelegerea tuturor dificultăților elevilor.","Cunoașterea materiei înlocuiește toate strategiile de evaluare a înțelegerii.","Cunoașterea materiei nu este identică cu înțelegerea pedagogică a conținutului."],"answer":3,"explanation":"Modelul prezentat distinge cunoașterea conținutului de cunoașterea conținutului și a elevilor, a predării sau a programei. A ști materia nu e suficient pentru a o face accesibilă.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 13, p. 249–250","quote":"Pagina 249 Vezi pagina originală ↗ și colaboratorii (2008) în funcție de două categorii principale: cunoașterea materiei și cunoașterea conținutului pedagogic (figura 9.2). În cazul matematicii, de exemplu, au argumentat că această cunoaștere de către profesori viza raționamentul matematic, cunoașterea elevilor și „poate chiar un tip special de raționament despre gândirea","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s13","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=25"}},{"id":"L34","theme":"L","prompt":"Școala obține venituri proprii din activități educaționale legal înființate. Un partener propune reducerea finanțării publice cu aceeași sumă. Ce prevede legea?","options":["Veniturile proprii diminuează automat finanțarea complementară cu suma încasată.","Veniturile proprii diminuează automat finanțarea de bază cu suma încasată.","Veniturile proprii diminuează automat toate subvențiile publice cu suma încasată.","Veniturile proprii nu diminuează finanțarea de bază, complementară sau specială."],"answer":3,"explanation":"Veniturile proprii nu diminuează categoriile de finanțare publică enumerate și trebuie folosite în scopul pentru care au fost încasate.","source":{"title":"Legea nr. 198/2023","locator":"Art. 142 alin. (2)","quote":"odată cu bugetul instituției publice de care aparțin. (2) Veniturile proprii ale activităților înființate pe lângă unitățile de învățământ nu diminuează finanțarea de bază, complementară sau specială și sunt utilizate în scopul pentru care au fost încasate. La sfârșitul anului bugetar, excedentele rezultate din execuția bugetelor activităților finanțate integral din venituri proprii se reportează pentru bugetul anului următor și vor fi utilizate cu aceeași destinație. (3) Directorul și consiliul de administrație al unității de învățământ sau, după caz, al unității de educație extrașcolară răspund de încadrarea în bugetul aprobat, în condițiile legii.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R34","theme":"R","prompt":"În timpul unei evaluări scrise se constată fraudă. Profesorul dorește să acorde nota 5 ca avertisment. Ce rezultat prevede ROFUIP pentru frauda constatată?","options":["Nota 1 sau, după caz, calificativul Insuficient.","Nota 4 sau, după caz, calificativul Suficient.","Nota 5 sau, după caz, calificativul Bine.","Nota 6 sau, după caz, calificativul Foarte bine."],"answer":0,"explanation":"ROFUIP prevede nota 1 sau calificativul Insuficient pentru frauda constatată la evaluările scrise, în condițiile articolului.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 106","quote":"specifice din programele școlare, stă la baza planurilor individuale de învățare realizate de către profesorul de la clasă. Pentru frauda constatată la evaluările scrise, inclusiv la probele scrise din cadrul examenelor/concursurilor organizate la nivelul unității de învățământ, conform prezentului regulament, se acordă nota 1 sau, după caz, calificativul insuficient. Elevii vor beneficia pe parcursul unui an școlar de cel puțin un plan individualizat de învățare, elaborat în urma evaluărilor susținute și după interpretarea rezultatelor de către cadrul didactic, care va fi folosit pentru consolidarea cunoștințelor, pentru întreprinderea unor acțiuni de învățare","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B27","theme":"B","prompt":"Sarcinile se suprapun între două compartimente. Directorul revede rolurile, responsabilitățile și circuitele de lucru. Ce interpretare din modelul structural susține intervenția?","options":["Problemele pot fi rezolvate numai prin eliminarea tuturor regulilor instituției.","Problemele pot proveni din structuri nepotrivite și pot cere restructurare.","Problemele provin exclusiv din preferințele personale ale beneficiarilor.","Problemele provin obligatoriu din lipsa unei viziuni carismatice a directorului."],"answer":1,"explanation":"Modelul structural leagă unele disfuncții de structuri și sisteme neadecvate. Cazul vizează tocmai delimitarea formală a muncii.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 57","quote":"6. Problemele organizaţionale îşi au de obicei originea în structurile nepotrivite sau sistemele inadecvate şi pot fi rezolvate prin restructurare sau crearea de noi sisteme. Ipotezele structurale identificate de Bolman şi Deal, inclusiv orientarea scopurilor, raţionalitatea, exercitarea autorităţii şi referinţa la sisteme, corespund caracteristicilor centrale","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"P14","theme":"P","prompt":"Directorul urmărește aplicarea curriculumului, coerența predării și evaluării și adaptarea proceselor didactice la nevoile elevilor. Ce competență specifică este ilustrată?","options":["Asigurarea succesului școlar al elevilor și a performanței cadrelor didactice","Colectarea datelor, analiza și formularea de strategii de îmbunătățire a calității","Managementul implementării curriculumului și al proceselor de evaluare","Managementul incluziunii și al diversității în profilurile de învățare"],"answer":2,"explanation":"Managementul implementării curriculumului și al proceselor de evaluare vizează direct organizarea și monitorizarea acestor procese la nivelul școlii.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"4.2. Managementul implementării curriculumului și al proceselor de evaluare","quote":"Coordonează elaborarea și implementarea curriculumului, asigurând coerența verticală și orizontală și monitorizând calitatea procesului didactic și echitatea evaluării. coordonează elaborarea și implementarea curriculumului, inclusiv a curriculumului la decizia elevului din oferta școlii, cu implicarea elevilor; asigură coerența verticală și orizontală a curriculumului la nivelul unității; verifică alinierea planificărilor didactice la curriculum și oferă feedback constructiv cadrelor didactice; monitorizează calitatea procesului didactic prin observări de lecții, analiza documentară și discuții profesionale; monitorizează coerența și echitatea evaluării la nivel instituțional; încurajează utilizarea evaluării formative ca instrument de îmbunătățire a învățării; corelează datele privind rezultatele elevilor cu deciziile curriculare și de ","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"L35","theme":"L","prompt":"La sfârșitul anului, o activitate finanțată integral din venituri proprii are excedent. Directorul vrea să îl transfere unei activități fără legătură cu destinația inițială. Ce soluție respectă legea?","options":["Excedentul se cheltuie integral în decembrie, indiferent de destinația inițială.","Excedentul se distribuie automat angajaților, indiferent de destinația inițială.","Excedentul se reportează pentru anul următor, păstrând aceeași destinație.","Excedentul se transferă automat primăriei, indiferent de destinația inițială."],"answer":2,"explanation":"Excedentele activităților finanțate integral din venituri proprii se reportează și sunt utilizate cu aceeași destinație.","source":{"title":"Legea nr. 198/2023","locator":"Art. 142 alin. (2)","quote":"încasate. La sfârșitul anului bugetar, excedentele rezultate din execuția bugetelor activităților finanțate integral din venituri proprii se reportează pentru bugetul anului următor și vor fi utilizate cu aceeași destinație. (3) Directorul și consiliul de administrație al unității de învățământ sau, după caz, al unității de educație extrașcolară răspund de încadrarea în bugetul aprobat, în condițiile legii.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R35","theme":"R","prompt":"Un elev a fost scutit medical de efort fizic numai o parte din an și are o singură notă la sport. Profesorul dorește să încheie media pe baza ei. Ce regulă se aplică?","options":["Media nu se încheie la nicio disciplină dacă există scutire la sport.","Media nu se încheie, fiind necesare minimum două note pentru această situație.","Media se încheie automat cu nota 10 pentru orice perioadă de scutire.","Media se încheie, fiind suficientă o singură notă pentru această situație."],"answer":1,"explanation":"Pentru scutirea pe o perioadă determinată, media la această disciplină se încheie numai dacă există cel puțin două calificative/note. Altfel media anuală se calculează fără această disciplină.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 112 alin. (4)","quote":"determinată în timpul anului școlar, li se încheie media la această disciplină, pentru anul școlar respectiv, numai dacă au obținut cel puțin 2 calificative/note. În caz contrar, acestor elevi nu li se încheie media la această disciplină și, respectiv, media anuală se calculează fără media de la această disciplină. (la 15-07-2025, Alineatul (4), Articolul 112, Sectiunea 1, Capitolul III, Titlul VII a fost modificat de Punctul 2., Articolul I din ORDINUL nr. 4.498 din 8 iulie 2025, publicat în MONITORUL OFICIAL nr. 663 din 15 iulie 2025 ) Elevii scutiți medical nu sunt obligați să vină în echipament sportiv la orele de educație fizică și sport, dar trebuie să aibă","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B28","theme":"B","prompt":"Școala atribuie activitățile complexe unor persoane cu expertiză specifică, în loc să ceară tuturor aceleași sarcini. Ce argument structural susține alegerea?","options":["Specializarea elimină orice nevoie de coordonare între compartimente.","Specializarea înlocuiește complet scopurile educaționale ale instituției.","Specializarea poate crește expertiza și performanța individuală.","Specializarea transformă automat orice profesor în director executiv."],"answer":2,"explanation":"În abordarea structurală, diviziunea muncii și specializarea permit niveluri mai ridicate de expertiză și performanță. Coordonarea rămâne necesară.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 57","quote":"funcţionează mai eficient în momentul în care tulburările de mediu şi preferinţele personale sunt limitate de norme şi raţiune. 4. Specializarea permite un nivel mai ridicat de expertiză şi performanţă individuală. 5. Coordonarea şi controlul sunt esenţiale pentru eficacitate. 6. Problemele organizaţionale îşi au de obicei originea în structurile nepotrivite","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"C14","theme":"C","prompt":"Descriptorii de performanță sunt suficient de expliciți pentru a ghida lecția. Un profesor susține că obiectivele de învățare trebuie întotdeauna să înlocuiască descriptorii. Ce precizează CRCNR?","options":["Descriptorii sunt eliminați atunci când profesorul folosește un manual nou.","Obiectivele înlocuiesc obligatoriu descriptorii în toate lecțiile proiectate.","Obiectivele pot sprijini atingerea standardelor, fără a substitui descriptorii.","Standardele nu mai sunt relevante după formularea obiectivelor lecției."],"answer":2,"explanation":"CRCNR explică rolul obiectivelor operaționalizate în atingerea standardelor și precizează că ele nu se substituie descriptorilor nivelurilor de performanță.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"de învățare care să îl conducă pe elev la atingerea standardelor de învățare vizate prin lecția pe care o proiectez? Dacă da, voi formula obiectivele de învățare ale lecției. Dacă nu, mă voi orienta după descriptorii nivelurilor de performanță din structura standardului național de evaluare. (În cadrul CRCNR, obiectivele de învățare reflectă așteptările referitoare la ce va învăța elevul pe parcursul lecției. Acestea, prin operaționalizare, conduc progresiv la atingerea standardelor de învățare, nesubstituindu-se descriptorilor nivelurilor de performanță.) Ce prerechizite ale învățării au elevii și cum vor fi valorificate acestea pentru realizarea standardelor de învățare vizate?","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L31","theme":"L","prompt":"Echipa de buget trebuie să încadreze salariile și contribuțiile aferente personalului. Din ce categorie de finanțare fac parte acestea potrivit legii?","options":["Finanțarea complementară a unității de învățământ.","Finanțarea de bază a unității de învățământ.","Finanțarea exclusivă din donațiile părinților.","Finanțarea exclusivă din sponsorizări externe."],"answer":1,"explanation":"Cheltuielile cu salariile și contribuțiile aferente sunt prevăzute la finanțarea de bază. Nu sunt transferate obligatoriu către donații sau sponsorizări.","source":{"title":"Legea nr. 198/2023","locator":"Art. 139 alin. (2) lit. a)","quote":"articole de cheltuieli, în funcție de care se calculează costul standard per antepreșcolar/preșcolar/elev, după cum urmează: a) cheltuieli cu salariile, sporurile, indemnizațiile și alte drepturi salariale în bani, stabilite prin lege, precum și contribuțiile aferente acestora, prin bugetul Ministerului Educației; b) cheltuieli cu formarea continuă, din sume defalcate din unele venituri ale bugetului de stat, prin bugetele locale; c) cheltuieli cu bunuri și servicii, din sume defalcate din unele venituri ale bugetului de stat, prin bugetele locale; d) cheltuieli de transport pentru personalul din învățământul preuniversitar care nu dispune de locuință în unitatea","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R31","theme":"R","prompt":"Un profesor este propus ca diriginte simultan la două clase, pentru a acoperi un deficit. Ce limită stabilește ROFUIP?","options":["Poate îndeplini atribuțiile la două formațiuni de studiu.","Poate îndeplini atribuțiile la o singură formațiune de studiu.","Poate îndeplini atribuțiile la toate clasele unde predă.","Poate îndeplini atribuțiile la trei formațiuni de studiu."],"answer":1,"explanation":"Regula permite unui cadru didactic atribuțiile de profesor diriginte la o singură formațiune de studiu. Nevoia organizatorică nu modifică limita.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 64","quote":"din învățământul gimnazial, liceal, profesional și postliceal. Un cadru didactic poate îndeplini atribuțiile de profesor diriginte la o singură formațiune de studiu. În cazul învățământului primar, atribuțiile dirigintelui revin învățătorului/ institutorului/ profesorului pentru învățământul primar. (3) În cazul învățământului antepreșcolar și preșcolar, atribuțiile dirigintelui revin educatorului/profesorului pentru educație timpurie.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B25","theme":"B","prompt":"În analiza unei reforme, directorul urmărește sensurile diferite pe care fiecare profesor le atribuie experienței școlare. Ce asociere din tabelul Bush poate susține această perspectivă individuală?","options":["Cultural – managerial.","Formal – moral.","Politic – participativ.","Subiectiv – postmodern."],"answer":3,"explanation":"Modelele subiective privilegiază interpretările indivizilor. Tabelul le asociază leadershipului postmodern și emoțional; dintre variante este corectă prima pereche.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 2, p. 51","quote":"de management Modelul de leadership Formal Managerial Colegial Participativ Transformaţional Distribuit Politic Tranzacţional Subiectiv Postmodern Emoţional De ambiguitate Circumstanţial Cultural Moral Al instruirii Sursa: adaptat după Bush şi Glover, 2002. Leadershipul instruirii, deseori descris ca fiind leadership centrat pe învăţare, nu se leagă de niciun","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H13","theme":"H","prompt":"Profesorii își vizionează lecțiile filmate și urmăresc cine vorbește, cine este ignorat și unde apar dovezi de învățare. Care este scopul educațional al demersului?","options":["Documentarea exclusivă a aspectului vestimentar al profesorilor.","Examinarea predării prin perspectiva elevilor și a învățării produse.","Numărarea exclusivă a gesturilor profesorului fără legătură cu învățarea.","Selectarea exclusivă a celor mai atractive imagini pentru promovare."],"answer":1,"explanation":"Analiza video poate face vizibile interacțiuni și efecte pe care profesorul nu le observă în timpul lecției, sprijinind reflecția și schimbarea practicii.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 12, p. 247–248","quote":"class=\"chapter\"> SECȚIUNEA 12 Micropredarea/analiza video a lecțiilor Pag. 247–248 Pagina 247 Vezi pagina originală ↗ că instruirea (0,04) era foarte puțin diferită de programele extrașcolare (0,02), de oferirea de stimulente (0,01), de programele de vară (0,03), de formarea","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s12","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=23"}},{"id":"L32","theme":"L","prompt":"Școala pregătește bugetul pentru consolidarea clădirii și reparații capitale. Ce categorie legală cuprinde aceste cheltuieli?","options":["Finanțarea complementară destinată investițiilor și reparațiilor.","Finanțarea de bază destinată exclusiv drepturilor salariale.","Finanțarea exclusivă prin contractele personale ale profesorilor.","Finanțarea individuală obligatorie din contribuțiile elevilor."],"answer":0,"explanation":"Investițiile, reparațiile capitale și consolidările sunt prevăzute la finanțarea complementară.","source":{"title":"Legea nr. 198/2023","locator":"Art. 140 alin. (2) lit. a)","quote":"de stat, aprobate anual prin legea bugetului de stat cu această destinație, pentru următoarele categorii de cheltuieli: a) investiții, reparații capitale și curente, consolidări; b) subvenții pentru internate și cantine; c) cheltuieli pentru evaluarea periodică națională a elevilor; d) cheltuieli pentru examinarea medicală obligatorie periodică a salariaților din învățământul preuniversitar; e) cheltuieli pentru concursuri școlare și activități educative extrașcolare, centre de excelență organizate în cadrul sistemului de învățământ; f) cheltuieli pentru asigurarea securității și sănătății, pentru personalul angajat, beneficiarii primari; g) gestionarea situațiilor de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R32","theme":"R","prompt":"Dirigintele dorește ca întâlnirile de prezentare a situației fiecărui elev să fie întotdeauna publice, cu toți părinții. Ce recomandă ROFUIP pentru întâlnirea cu părintele?","options":["Caracter exclusiv scris, fără posibilitatea participării elevului.","Caracter exclusiv telefonic, fără nicio programare prealabilă.","Caracter individual, pe baza unei programări prealabile.","Caracter public, pe baza majorității părinților prezenți."],"answer":2,"explanation":"Întâlnirea este recomandată ca individuală, programată în prealabil. La solicitarea părintelui sau dirigintelui poate participa și elevul.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 67","quote":"legali ai acestora și se afișează la avizier sau pe site-ul unității de învățământ. Întâlnirea cu părinții/reprezentanții legali se recomandă a fi individuală, în conformitate cu o programare stabilită în prealabil. La această întâlnire, la solicitarea părintelui/reprezentantului legal sau a dirigintelui, poate participa și elevul.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}}]},{"id":8,"title":"Simularea 08","items":[{"id":"C15","theme":"C","prompt":"Directorul consideră că managementul curriculumului se încheie odată cu alegerea opționalelor. Ce concluzie rezultă din capitolul 10?","options":["Managementul curriculumului aparține exclusiv furnizorilor de opționale.","Managementul curriculumului exclude complet predarea disciplinelor obligatorii.","Managementul curriculumului nu se reduce la CDEOȘ sau la CS flexibil.","Managementul curriculumului se reduce exclusiv la alegerea opționalelor."],"answer":2,"explanation":"Managementul privește întreaga implementare curriculară, resursele, formarea, monitorizarea și calitatea predării-învățării-evaluării, nu doar opționalele.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"de exemplu, colaborarea dintre mai multe școli, colaborarea dintre școală și comunitate; managementul curriculumului la nivelul școlii nu se reduce la managementul CDEOȘ și/ sau CS flexibil; asigurarea cadrului optim de funcționare a comisiilor cu atribuții în domeniul curriculumului și al formării profesorilor din școală. Ca structuri specializate, aceste comisii contribuie la managementul curriculumului la nivelul școlii, prin: identificarea nevoilor de formare ale profesorilor, în domeniul curriculumului, prin analize de nevoi periodice și sistematice; identificarea programelor de formare acreditate adecvate nevoilor de formare identificate, pentru a le recomanda","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L38","theme":"L","prompt":"Un profesor tratează manualul ca document care înlocuiește programa și standardele naționale. Ce distincție din lege trebuie restabilită?","options":["Manualul este document managerial; programa este exclusiv document contabil.","Manualul este instrument de sprijin; programa este document curricular reglator.","Manualul este normă juridică superioară; programa este recomandare editorială.","Manualul este programă națională; standardele sunt exclusiv criterii locale."],"answer":1,"explanation":"Curriculumul național include planurile-cadru, programele și standardele naționale de evaluare. Manualele sunt instrumente de sprijin pentru implementare.","source":{"title":"Legea nr. 198/2023","locator":"Art. 85 alin. (7)-(8)","quote":"școlare și standardele naționale de evaluare. (8) Manualele școlare alternative și metodologiile specifice de aplicare reprezintă instrumente de sprijin în vederea implementării curriculumului național.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R38","theme":"R","prompt":"După încheierea cursurilor, dirigintele amână o lună comunicarea scrisă a situației de corigență către familie. Care este termenul ROFUIP?","options":["Cel mult 10 zile de la încheierea cursurilor.","Cel mult 15 zile de la încheierea cursurilor.","Cel mult 30 de zile de la încheierea cursurilor.","Cel mult 7 zile de la încheierea cursurilor."],"answer":3,"explanation":"Situațiile de corigență, amânare, repetenție sau abandon se comunică în scris în cel mult șapte zile de la încheierea cursurilor.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 127","quote":"sau, după caz, beneficiarilor primari majori de către învățător/institutor/profesorul pentru învățământul primar/profesorul diriginte, în cel mult 7 zile de la încheierea cursurilor. Pentru elevii amânați sau corigenți, învățătorul/institutorul/profesorul pentru învățământul primar/profesorul diriginte comunică în scris părinților/reprezentantului legal programul de desfășurare a examenelor de corigență și perioada de încheiere a situației școlare. Nu pot fi făcute publice, fără acordul părintelui/reprezentantului legal sau al elevului/ absolventului major, documentele elevului, cu excepția situației prevăzute de Legea nr. 272/2004 privind protecția și promovarea","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B30","theme":"B","prompt":"Conducerea fixează obiectivele fără să țină cont de opiniile comunității și reduce schimburile externe la strictul necesar. Ce imagine sistemică este apropiată?","options":["Leadership distribuit, care transferă expertiza în toate grupurile.","Leadership moral, care derivă automat din orice procedură internă.","Sistem deschis, care pune schimbul reciproc în centrul deciziilor.","Sistem închis, care minimizează tranzacțiile cu mediul exterior."],"answer":3,"explanation":"Sistemele închise acordă puțină importanță influenței externe în stabilirea scopurilor și activităților. Cazul descrie această limitare.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 60","quote":"sau închise Teoriile sistemice sunt deseori împărţite în deschise sau închise în termeni de relaţii ale organizaţiei cu mediul ei extern. Sistemele închise tind să minimalizeze tranzacţiile cu mediul extern şi pun puţin preţ pe opinia externă în determinarea scopurilor şi activităţilor organizaţiei. Presupunerile structurale ale lui Bolman şi Deal (1991), menţionate","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H16","theme":"H","prompt":"Feedbackul elevilor contrazice convingerea profesorului că toate relațiile sunt pozitive. Profesorul examinează dovezile și își schimbă metodele. Ce tip de reflecție este ilustrat?","options":["Apărarea rutinelor prin respingerea tuturor informațiilor contradictorii.","Confirmarea selectivă a presupunerilor prin ignorarea opiniilor elevilor.","Înlocuirea examinării dovezilor cu reafirmarea autorității profesorului.","Revizuirea presupunerilor despre practică în lumina dovezilor primite."],"answer":3,"explanation":"Reflecțiile capitolului arată valoarea formării care pune la îndoială presupunerile și teoriile profesorilor despre propria practică.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 15, p. 255–256","quote":"clasa prin ochii elevilor. Efectul puternic al activității lui Bishop este că, după ce au văzut aceste rezultate, profesorii și-au schimbat repede metodele. Formarea profesională care pune la îndoială presupunerile și teoriile profesorilor despre practica pedagogică poate fi foarte eficientă. Puterea relațiilor pozitive profesori-elevi este esențială","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s15","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=31"}},{"id":"L39","theme":"L","prompt":"Un consorțiu dorește ca elevii școlilor membre să folosească împreună un laborator. Un director afirmă că legea permite numai schimbul de personal. Care este concluzia?","options":["Folosirea comună a resurselor materiale este exclusă pentru consorțiu.","Folosirea comună a resurselor materiale este prevăzută pentru consorțiu.","Folosirea comună este permisă doar după desființarea școlilor membre.","Folosirea comună este permisă doar după unificarea tuturor cataloagelor."],"answer":1,"explanation":"Utilizarea în comun a resurselor materiale este unul dintre avantajele prevăzute explicit pentru consorțiile școlare.","source":{"title":"Legea nr. 198/2023","locator":"Art. 21 alin. (6) lit. b)","quote":"să funcționeze provizoriu/acreditate și asigură: a) prioritate la mobilitatea personalului între unitățile membre ale consorțiului; b) utilizarea în comun a resurselor materiale ale unităților de învățământ din consorțiu; c) lărgirea oportunităților de învățare oferite beneficiarilor primari și sprijin suplimentar oferit elevilor în risc de excluziune; d) recunoașterea reciprocă a rezultatelor învățării și evaluării acestora; e) participarea la proiecte și programe ale Uniunii Europene, în mod special din domeniul educației, cel digital și al noilor tehnologii folosite în scop educațional, inovativ și cultural. (7) Retragerea sau excluderea din consorțiul școlar a unei","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R39","theme":"R","prompt":"Școala primește atestatul de echivalare pentru un elev audient, dar dorește să îi definitiveze înscrierea după două luni. Ce termen prevede ROFUIP?","options":["Maximum 15 zile de la primirea atestatului de echivalare.","Maximum 30 de zile de la primirea atestatului de echivalare.","Maximum 45 de zile de la primirea atestatului de echivalare.","Maximum 60 de zile de la primirea atestatului de echivalare."],"answer":0,"explanation":"În maximum 15 zile de la primirea atestatului, elevul audient este înscris în catalog și registrul matricol, cu transferarea mențiunilor din documentele provizorii.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 125","quote":"elevul audient, elevul va fi înscris la clasa pentru care optează părinții, pe răspunderea acestora asumată prin semnătură. În termen de maximum 15 zile de la primirea atestatului de echivalare emis de inspectoratele școlare județene/ Inspectoratului Școlar al Municipiului București, elevul audient este înscris în catalogul clasei și i se transferă din catalogul provizoriu toate mențiunile cu privire la activitatea desfășurată – note, absențe etc. Elevii străini care au acte de studii, au depus documentele în vederea echivalării studiilor și care cunosc limba română, sunt școlarizați, conform prevederilor legale în vigoare, după finalizarea procedurii de echivalare.","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B31","theme":"B","prompt":"La recrutare, o școală folosește calificările și experiența dovedită, în locul relațiilor personale. Ce trăsătură a birocrației ideale este ilustrată?","options":["Selecția și progresul în carieră pe bază de apartenență informală.","Selecția și progresul în carieră pe bază de merit.","Selecția și progresul în carieră pe bază de negociere politică.","Selecția și progresul în carieră pe bază de simpatie personală."],"answer":1,"explanation":"Modelul birocratic ideal discutat de Bush leagă recrutarea și cariera de merit, calificări și experiență, nu de relații personale.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 63","quote":"poate fi considerată un exemplu de birocraţie. 6. În birocraţii, recrutarea şi progresul în carieră al personalului sunt determinate de merit. Numirile sunt făcute pe baza calificărilor şi experienţei şi promovarea depinde de expertiza demonstrată în poziţia prezentă şi cele anterioare. Şcolile şi colegiile îndeplinesc acest criteriu, în sensul că proceduri","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"P16","theme":"P","prompt":"Directorul corelează sprijinul acordat elevilor cu dezvoltarea profesorilor și urmărește sistematic progresul în învățare și performanța profesională. Ce competență specifică exprimă cel mai direct finalitatea?","options":["Asigurarea succesului școlar al elevilor și a performanței cadrelor didactice","Colectarea datelor, analiza și formularea de strategii de îmbunătățire a calității","Leadership incluziv, stare de bine a elevilor și a personalului școlii, securitate și siguranță școlară","Managementul incluziunii și al diversității în profilurile de învățare"],"answer":0,"explanation":"Finalitatea explicită este succesul școlar al elevilor împreună cu performanța cadrelor didactice. Datele sunt un mijloc pentru atingerea ei.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"4.4. Asigurarea succesului școlar al elevilor și a performanței cadrelor didactice","quote":"elaborează planuri individuale de dezvoltare profesională corelate cu nevoile identificate; susține procesele de mentorat, coaching și observare inter pares — peer observation; facilitează accesul cadrelor didactice la programe de dezvoltare profesională relevante și de calitate; monitorizează impactul formării continue asupra practicii didactice și a rezultatelor elevilor; asigură responsabilizarea cadrelor didactice cu privire la impactul practicilor pedagogice asupra succesului elevilor; valorifică expertiza internă a personalului în procesul de formare și mentorat colegial; promovează o cultură a învățării organizaționale și a comunităților de practică profesională.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"L40","theme":"L","prompt":"Un părinte sesizează nerespectarea contractului educațional. Școala afirmă că DJIP/DMBIP poate verifica numai din proprie inițiativă. Ce permite legea?","options":["Verificarea din oficiu sau la sesizarea persoanelor prevăzute de lege.","Verificarea exclusiv după încheierea ciclului școlar al copilului.","Verificarea exclusiv după o hotărâre a comitetului de părinți.","Verificarea exclusiv după un vot favorabil al consiliului profesoral."],"answer":0,"explanation":"Legea permite verificarea din oficiu și la sesizarea părintelui, elevului major sau directorului. Sesizarea nu este exclusă de existența controlului din oficiu.","source":{"title":"Legea nr. 198/2023","locator":"Art. 14 alin. (6)","quote":"în continuare DJIP/DMBIP, verifică modul de respectare de către părți a prevederilor contractului educațional prevăzut la alin. (4) și (5) din oficiu sau la sesizarea părintelui/ reprezentantului legal/elevului major sau a directorului unității de învățământ preuniversitar și pot dispune aplicarea măsurilor sau sancțiunilor prevăzute în metodologia aprobată prin ordin al ministrului educației. (7) Pentru sprijinirea părinților în asigurarea participării la cursuri a beneficiarului primar minor și a respectării contractului educațional, unitățile de învățământ preuniversitar pot solicita intervenția direcțiilor generale județene de asistență socială și protecția","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R40","theme":"R","prompt":"Un transfer excepțional bine motivat ar depăși efectivul maxim cu 3 elevi. CA cere aprobarea inspectoratului ca și cum limita ar fi de 4. Ce distincție prevede ROFUIP pentru transferuri?","options":["CA al școlii poate aproba cel mult 3 peste maxim, fără altă aprobare.","CA al școlii poate aproba orice depășire, dacă transferul este motivat.","ISJ/ISMB poate aproba cel mult 2 peste maxim; peste 2 aprobă ministerul.","ISJ/ISMB poate aproba cel mult 4 peste maxim; peste 4 aprobă ministerul."],"answer":2,"explanation":"La transfer, art. 139 distinge maximum doi elevi aprobați de inspectorat de depășirile mai mari, aprobate de minister. Nu se preia automat regula din alt articol despre efective.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 139","quote":"în numărul maxim de beneficiari primari ai educației la grupă/formațiunea de studiu, ISJ/ISMB poate aproba depășirea efectivului maxim cu cel mult 2 beneficiari peste efectivul maxim, pe baza justificării din partea consiliului de administrație al unității de învățământ. Pentru situațiile excepționale în care se solicită depășirea cu peste 2 beneficiari primari a numărului maxim de antepreșcolari/preșcolari/elevi la grupă/formațiunea de studiu, aprobarea va fi dată de Ministerul Educației, conform metodologiei în vigoare.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B32","theme":"B","prompt":"Profesorii completează rapoarte tot mai numeroase, iar timpul pentru sprijinirea elevilor scade. Conducerea apreciază succesul numai după completarea formularelor. Ce risc apare?","options":["Autonomia didactică înlocuiește toate obligațiile instituției școlare.","Birocrația devine scop în sine, în loc să servească educației.","Birocrația elimină automat orice cost administrativ al educației.","Colaborarea profesională devine prea importantă în raport cu documentele."],"answer":1,"explanation":"Critica vizează inversarea relației mijloc-scop: aparatul birocratic ajunge rațiunea de a fi, deși ar trebui subordonat finalităților educaționale.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 64","quote":"ei devin o influenţă prea dominantă asupra modului de operare al şcolilor şi colegiilor. Există teama că birocraţia poate deveni raţiunea de a fi a organizaţiei, în loc ca aceasta să fie subordonată scopurilor educaţionale. Birocraţia este modelul preferat pentru multe sisteme educaţionale, incluzând Republica Cehă (Svecova, 2000), China (Bush et al., 1998),","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"C16","theme":"C","prompt":"Școala alcătuiește schema orară a unei clase. Directorul propune copierea mecanică a unei liste generale, fără opțiunile elevilor. Ce funcție are schema orară?","options":["Înlocuiește programa fiecărei discipline prin decizia exclusivă a directorului școlii.","Înlocuiește standardele naționale prin preferințele individuale ale profesorilor.","Particularizează exclusiv programul administrativ al personalului auxiliar al școlii.","Particularizează planul-cadru pentru clasă, incluzând componentele și opțiunile aplicabile."],"answer":3,"explanation":"Schema orară particularizează planul-cadru pentru o anumită clasă și include orele componentelor aplicabile, inclusiv opțiunile elevilor pentru CDEOȘ.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"calitatea activității de predare-învățare-evaluare etc.; realizarea schemelor orare pe baza planurilor-cadru de învățământ în vigoare; schema orară particularizează planul-cadru de învățământ pentru o anumită clasă, incluzând orele alocate pentru disciplinele din trunchiul comun și orele pentru CS flexibil și CDEOȘ, ca rezultat al opțiunilor elevilor; abilitarea profesorilor pentru aplicarea la clasă a unor noi programe școlare pornind de la recunoașterea rolului acestora, ca practicieni în educație, în producerea schimbării; este necesar ca profesorii să înțeleagă cerințele programei școlare și să le transpună în documentele de proiectare și în activitatea desfășurată cu elevii;","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L36","theme":"L","prompt":"Doi elevi din clase paralele aleg același opțional. Directorul consideră că o grupă comună este interzisă în principiu. Ce posibilitate recunoaște Legea 198?","options":["CDEOȘ se poate desfășura cu elevi din clase diferite.","CDEOȘ se poate desfășura exclusiv cu elevi din aceeași bancă.","CDEOȘ se poate desfășura exclusiv cu întreaga clasă de proveniență.","CDEOȘ se poate desfășura exclusiv în afara programului școlar."],"answer":0,"explanation":"Legea permite desfășurarea CDEOȘ cu elevi din clase diferite și implementarea în sistem modular, în condițiile aplicabile.","source":{"title":"Legea nr. 198/2023","locator":"Art. 86 alin. (4)","quote":"de propriile nevoi și interese de cunoaștere. (4) Implementarea CDEOȘ, conform alin. (3) este obligatorie, se poate desfășura cu elevi din clase diferite și poate fi implementată în sistem modular. (5) Pentru învățământul primar, gimnazial și liceal, filiera teoretică și filiera vocațională, consiliul de administrație al unității de învățământ stabilește curriculumul la decizia elevului din oferta școlii, în urma consultării elevilor, părinților/ reprezentantului legal și pe baza resurselor disponibile. (6) Pentru învățământul liceal tehnologic, CDEOȘ este elaborat de unitatea de învățământ, în parteneriat cu operatorii economici/autoritățile administrației publice locale,","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R36","theme":"R","prompt":"Un elev are medii anuale sub 5 la două discipline și medie de promovare la purtare. Nu există alte situații speciale. Cum se încadrează potrivit ROFUIP?","options":["Amânat, deoarece orice medie sub 5 amână situația.","Corigent, fiind vorba de cel mult două discipline.","Promovat, deoarece purtarea compensează disciplinele.","Repetent, fiind suficientă orice medie sub 5."],"answer":1,"explanation":"Regula generală încadrează la corigență mediile sub 5 la cel mult două discipline. Nu se confundă o medie nepromovată cu imposibilitatea de a definitiva situația.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 119","quote":"Sunt declarați corigenți elevii care obțin calificativul \"Insuficient'/medii anuale sub 5 la cel mult două discipline de studiu, precum și elevii amânați care nu promovează examenul de încheiere a situației școlare la cel mult două discipline de studiu. În cazul în care curriculumul este organizat modular, sunt declarați corigenți: elevii care obțin medii sub 5 la modulele ce se finalizează pe parcursul anului școlar, indiferent de numărul modulelor nepromovate; elevii care obțin medii sub 5 la cel mult două module care se finalizează la sfârșitul anului școlar, precum și elevii amânați care nu promovează examenul de încheiere a situației","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B29","theme":"B","prompt":"Școala își adaptează oferta după dialogul cu familiile și partenerii, influențând la rândul ei comunitatea. Cum descrie teoria sistemelor relația?","options":["Entitate exclusiv contabilă, fără schimburi de resurse sau informații.","Sistem deschis, cu granițe permeabile și interacțiune în ambele sensuri.","Sistem închis, cu granițe etanșe și ignorarea schimbărilor din comunitate.","Structură exclusiv ierarhică, fără vreo legătură cu mediul din jur."],"answer":1,"explanation":"Interacțiunea reciprocă dintre școală și mediu este definitorie pentru sistemul deschis. Nu este suficientă simpla existență a unei organigrame.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 61","quote":"a fost abandonat şi a început căutarea unor modele mai folositoare”. Teoria alternativă este cea a „sistemelor deschise”, ce presupune graniţe permeabile şi o relaţie interactivă, în două sensuri, între şcoli şi colegii şi mediul extern. Hoy şi Miskel (1987: 29) afirmă că „sistemele din şcoli sunt acum considerate sisteme deschise, care trebuie să se adapteze","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H15","theme":"H","prompt":"O lecție urmărește numai reproducerea informațiilor, fără relații, explicații sau utilizări. Ce reechilibrare este susținută de concluziile capitolului?","options":["Conectarea cunoașterii de suprafață cu înțelegerea profundă și utilizarea ei.","Eliminarea oricărei cunoașteri de bază în favoarea discuțiilor fără conținut.","Înlocuirea înțelegerii cu parcurgerea mai rapidă a tuturor paginilor manualului.","Menținerea reproducerii informațiilor ca unic indicator al întregii învățări."],"answer":0,"explanation":"Concluziile discută echilibrul dintre cunoașterea de suprafață și cea profundă. Nu justifică nici eliminarea bazelor, nici reducerea învățării la memorare.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 14, p. 251–254","quote":"importanța cunoașterii conținutului. Cercetarea lui Picker argumentează că, atunci când există un echilibru între experiențele de suprafață (cunoașterea teoretică, knowing-that) și cele profunde (cunoașterea procedurală, knowing-how) de la oră, impactul asupra procesului de învățare al elevilor este maximizat. Dar, când în clasă există o proporție ridicată","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s14","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=27"}},{"id":"L37","theme":"L","prompt":"Un elev nu frecventează Religia conform opțiunii legale. Profesorul propune nota 1 pentru a putea încheia situația școlară. Cum se procedează?","options":["Situația școlară se amână până la schimbarea opțiunii.","Situația școlară se blochează până la votul părinților.","Situația școlară se încheie cu nota 1 la Religie.","Situația școlară se încheie fără disciplina Religie."],"answer":3,"explanation":"Lipsa participării în condițiile opțiunii legale nu este evaluată cu nota 1. Legea prevede încheierea situației fără disciplina Religie.","source":{"title":"Legea nr. 198/2023","locator":"Art. 87 alin. (2)","quote":"reprezentantului legal, pentru elevul minor. În cazul în care elevul nu frecventează orele de religie, situația școlară se încheie fără disciplina Religie. În mod similar se procedează și pentru elevul căruia, din motive obiective, nu i s-au asigurat condițiile pentru frecventarea orelor la această disciplină. Elevului care nu frecventează orele de religie i se va asigura prezența în unitatea de învățământ pe durata derulării cursurilor. (3) Disciplina Religie poate fi predată numai de personalul didactic calificat, conform prevederilor prezentei legi, și avizat de cultele religioase recunoscute oficial de stat, în conformitate cu metodologia aprobată prin ordin al","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R37","theme":"R","prompt":"Un elev nepromovat la o singură corigență dorește reexaminare și intenționează să depună cererea după trei zile. Care este termenul de depunere prevăzut?","options":["24 de ore de la afișarea rezultatelor corigenței.","48 de ore de la afișarea rezultatelor corigenței.","5 zile lucrătoare de la afișarea rezultatelor corigenței.","7 zile calendaristice de la afișarea rezultatelor corigenței."],"answer":0,"explanation":"Cererea se depune în 24 de ore. Reexaminarea se desfășoară în două zile de la cerere, fără a depăși începutul cursurilor noului an.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 122","quote":"în cazuri justificate, o singură dată pe an școlar. Cererea de reexaminare se depune la secretariatul unității de învățământ, în termen de 24 de ore de la afișarea rezultatelor examenului de corigență. Reexaminarea se desfășoară în termen de două zile de la data depunerii cererii, dar nu mai târziu de data începerii cursurilor noului an școlar. Comisia de reexaminare se numește prin decizie a directorului și este formată din alte cadre didactice decât cele care au făcut examinarea anterioară. În situația în care în unitatea de învățământ nu există alte cadre didactice decât cele care au făcut examinarea anterioară, în comisie pot fi numite și cadre didactice din alte","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"P15","theme":"P","prompt":"Echipa testează o soluție pedagogică, analizează dovezile rezultate și folosește concluziile pentru dezvoltarea strategică a școlii. Directorul susține cercetarea și inovarea. Ce competență specifică este dominantă?","options":["Antreprenoriat educațional și inovație","Cercetare, inovație pedagogică și conceptualizare strategică","Dezvoltare și transformare organizațională","Managementul schimbării, adaptare și gestionarea presiunilor"],"answer":1,"explanation":"Cazul integrează cercetarea, inovarea pedagogică și conceptualizarea strategică. Nu este doar administrarea unui proiect extern sau introducerea unei aplicații digitale.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"4.3. Cercetare, inovație pedagogică și conceptualizare strategică","quote":"Promovează inovația pedagogică, utilizarea datelor educaționale și participarea cadrelor didactice în proiecte de cercetare-acțiune și diseminarea bunelor practici. promovează inovația pedagogică și utilizarea metodelor activ-participative centrate pe elev; facilitează participarea cadrelor didactice în proiecte educaționale, cercetare-acțiune și schimb de bune practici; utilizează datele și indicatorii educaționali pentru îmbunătățirea demersurilor curriculare; sprijină implementarea practicilor pedagogice bazate pe dovezi.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}}]},{"id":9,"title":"Simularea 09","items":[{"id":"L43","theme":"L","prompt":"Pentru o funcție de conducere vacantă, un titular este propus pentru detașare în interesul învățământului, fără acordul său. Ce condiție lipsește potrivit textului legii?","options":["Acordul colectiv al părinților absolvenților.","Acordul scris al persoanei solicitate.","Acordul unanim al tuturor elevilor școlii.","Acordul verbal al tuturor furnizorilor școlii."],"answer":1,"explanation":"Asigurarea conducerii interimare prin această cale cere și acordul scris al persoanei solicitate, pe lângă decizia și avizul prevăzute.","source":{"title":"Legea nr. 198/2023","locator":"Art. 198 alin. (6)","quote":"prin detașare în interesul învățământului, prin decizia directorului general, cu avizul consiliului de administrație al DJIP/DMBIP și cu acordul scris al persoanei solicitate.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R43","theme":"R","prompt":"O școală primară obișnuită, fără profil artistic/sportiv și fără excepție privind limba minorităților, dorește test competitiv pentru clasa pregătitoare. Ce regulă se aplică?","options":["Examinarea pentru înscrierea în prima clasă din primar este decisă de elevi.","Examinarea pentru înscrierea în prima clasă din primar este decisă de părinți.","Examinarea pentru înscrierea în prima clasă din primar este interzisă.","Examinarea pentru înscrierea în prima clasă din primar este obligatorie."],"answer":2,"explanation":"Regula generală interzice examinările pentru înscrierea în prima clasă a învățământului primar. Enunțul exclude explicit excepțiile prevăzute de regulament.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 128","quote":"aprobate prin ordin al ministrului educației. Se interzice organizarea unor examinări în vederea înscrierii beneficiarilor primari în prima clasă a învățământului primar. În clasa pregătitoare sunt înscriși copiii care au împlinit vârsta de 6 ani până la data începerii anului școlar. La solicitarea scrisă a părinților/reprezentanților legali, pot fi înscriși în clasa pregătitoare și copiii care împlinesc vârsta de 6 ani până la sfârșitul anului calendaristic, dacă dezvoltarea lor psihosomatică este corespunzătoare. Fac excepție de la prevederile alin. (3) unitățile de învățământ cu predare în limbile minorităților naționale, care pot organiza testări ale nivelului cunoașterii limbii de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B34","theme":"B","prompt":"La elaborarea bugetului, directorul nu copiază sumele de anul trecut, ci reanalizează justificarea tuturor ariilor de cheltuire. Ce tehnică descrie Bush?","options":["Bugetarea exclusiv incrementală.","Bugetarea în bază zero.","Delegarea exclusiv ierarhică.","Negocierea exclusiv informală."],"answer":1,"explanation":"Bugetarea în bază zero presupune o perspectivă nouă asupra tuturor ariilor de cheltuire, nu doar ajustări incrementale ale bugetului anterior.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 68","quote":"68 Leadership Şi management educaŢional 4. Bugetarea în bază zero. Aceasta implică abordarea unei noi perspective în toate ariile de cheltuire, nu numai modificarea incrementală a modelelor de cheltuire anterioare. 5. Alegerea celor mai adecvate opţiuni. Odată ce tiparele de","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H18","theme":"H","prompt":"Profesorii declară individual că sunt competenți, dar nu examinează nicio practică sau dovadă comună. Directorul numește aceasta automat eficacitate colectivă. Ce distincție este necesară?","options":["Convingerea comună privind capacitatea echipei este identică oricărei diplome individuale.","Convingerea comună privind capacitatea echipei exclude analiza învățării elevilor.","Convingerea comună privind capacitatea echipei nu se reduce la opinii individuale separate.","Convingerea comună privind capacitatea echipei rezultă automat din numărul profesorilor."],"answer":2,"explanation":"Eficacitatea colectivă privește colectivul și capacitatea sa de a influența rezultatele; nu este simpla însumare a aprecierilor individuale despre sine.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 7, p. 239–240","quote":"class=\"chapter\"> SECȚIUNEA 07 Eficacitatea colectivă a profesorilor și impactul lor Pag. 239–240 Pagina 239 Vezi pagina originală ↗ împărtășesc credința că, prin efortul lor unit, pot depăși greutăți și pot obține rezultatele dorite, grupurile sunt mai eficiente. Acest","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s7","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=15"}},{"id":"L44","theme":"L","prompt":"Autoritatea locală evaluează nerespectarea planului administrativ-financiar și propune eliberarea directorului. Cine are hotărârea finală potrivit textului Legii 198?","options":["Consiliul local, fără nicio implicare a structurii județene.","Consiliul părinților, după votul secret al membrilor săi.","DJIP/DMBIP, după propunerea autorității publice locale.","Primarul, fără nicio implicare a structurii județene."],"answer":2,"explanation":"Autoritatea locală poate propune eliberarea, dar legea atribuie hotărârea finală DJIP/DMBIP. Propunerea nu este decizie finală.","source":{"title":"Legea nr. 198/2023","locator":"Art. 196 alin. (7)","quote":"și poate propune consiliului de administrație al DJIP/DMBIP eliberarea din funcție a directorului unității de învățământ preuniversitar. Hotărârea finală aparține DJIP/DMBIP.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R44","theme":"R","prompt":"Înaintea evaluării naționale, comitetul de organizare solicită familiilor un fond de protocol pentru buna desfășurare. Cum se apreciază solicitarea?","options":["Este interzisă constituirea fondului numai dacă directorul primește numerar.","Este interzisă constituirea unui asemenea fond pentru examenele naționale.","Este permisă constituirea fondului dacă părinții semnează acordul colectiv.","Este permisă constituirea fondului dacă suma este egală pentru toate familiile."],"answer":1,"explanation":"Interdicția privește fondurile de protocol sau orice alt fond destinat derulării examenelor/evaluărilor naționale. Denumirea și acordul colectiv nu o înlătură.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 181","quote":"Se interzice constituirea de fonduri de protocol sau a oricărui alt fond destinat derulării examenelor/evaluărilor naționale.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B35","theme":"B","prompt":"Un profesor conduce o inițiativă datorită expertizei recunoscute de colegi, fără să primească un post superior în organigramă. Ce îl diferențiază de simpla delegare ierarhică?","options":["Influența exclude orice colaborare între membrii organizației școlare.","Influența presupune obligatoriu transferul tuturor obligațiilor directorului.","Influența rezultă exclusiv din ordinul superiorului și din rangul nou atribuit.","Influența se bazează pe calități personale, independent de poziția desemnată."],"answer":3,"explanation":"Bush distinge leadershipul distribuit, bazat pe expertiză și calități, de simpla distribuire ierarhică a sarcinilor de sus în jos.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 69","quote":"de leadership distribuit şi ceea ce el descrie ca fiind „structurile de putere ierarhică ale şcolilor”. Leadershipul distribuit este independent de ierarhie, se bazează pe calităţi personale, şi nu pe poziţii desemnate. În ciuda acestui model emergent şi datorită autorităţii legale a directorilor, ierarhia rămâne importantă în şcoli şi colegii. În anumite societăţi,","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"P18","theme":"P","prompt":"Directorul conectează școala la rețele profesionale și coordonează participarea la proiecte naționale și internaționale, favorizând schimbul de experiență. Ce competență specifică este dominantă?","options":["Asigurarea succesului școlar al elevilor și a performanței cadrelor didactice","Cercetare, inovație pedagogică și conceptualizare strategică","Participarea la rețele și proiecte naționale și internaționale","Responsabilitate publică și relaționare instituțională"],"answer":2,"explanation":"Centrul situației îl constituie participarea în rețele și proiecte, nu doar obținerea unei finanțări sau dezvoltarea unei idei antreprenoriale.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"5.2. Participarea la rețele și proiecte naționale și internaționale","quote":"valorifică oportunitățile programului Erasmus+ pentru a întări dimensiunea europeană a școlii; participă și implică școala în proiecte de tip eTwinning, Școală Europeană și altele similare; facilitează și stimulează participarea cadrelor didactice în proiecte de mobilități și parteneriat strategic; creează și întreține rețele de colaborare interinstituțională.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"L45","theme":"L","prompt":"După hotărârile CA, directorul trebuie să emită acte pentru îndeplinirea atribuțiilor sale. Ce instrumente sunt prevăzute de Legea 198?","options":["Decizii și note de serviciu.","Hotărâri judecătorești și sentințe.","Legi și ordonanțe de urgență.","Ordine ministeriale și decrete."],"answer":0,"explanation":"Directorul emite decizii și note de serviciu. Celelalte acte aparțin altor autorități și nu rezultă din competența sa managerială.","source":{"title":"Legea nr. 198/2023","locator":"Art. 195 alin. (5)","quote":"cu prevederile regulamentului de organizare și funcționare al acesteia. (5) În îndeplinirea atribuțiilor, directorul emite decizii și note de serviciu. (6) În unitățile de învățământ liceal militar, atribuțiile prevăzute la alin. (2) sunt exercitate de către comandant.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R45","theme":"R","prompt":"Un elev cu CES utilizează un echipament de comunicare pe care este autorizat să îl folosească. Profesorul invocă interdicția generală pentru a-l prelua automat. Ce precizează ROFUIP?","options":["Prevederile restrictive impun preluarea oricărui echipament, inclusiv cel autorizat.","Prevederile restrictive nu se aplică echipamentului autorizat pentru elevul cu CES.","Prevederile restrictive se suspendă numai după acordul tuturor colegilor elevului.","Prevederile restrictive se suspendă numai după votul tuturor părinților clasei."],"answer":1,"explanation":"ROFUIP prevede explicit excepția pentru echipamentele pe care elevii cu CES sunt autorizați să le folosească.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 182","quote":"solicitarea cadrului didactic, în situația folosirii lor în procesul educativ. Prevederile nu se aplică echipamentelor pe care elevii cu CES sunt autorizați să le folosească. Nerespectarea prevederilor referitoare la utilizarea telefoanelor/a altor echipamente de comunicații electronice poate duce la preluarea echipamentului de către personalul unității de învățământ în vederea predării, după caz, către părinți/reprezentanți legali ai beneficiarilor primari minori sau beneficiarilor primari majori conform regulamentului de organizare și funcționare al unității de învățământ.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B36","theme":"B","prompt":"Directorul crede că numirea sa îi asigură automat acceptarea tuturor inițiativelor în clase. Profesorii nu le aplică. Ce limită a autorității poziționale este evidențiată?","options":["Implementarea are nevoie și de consimțământul colegilor profesioniști.","Implementarea depinde exclusiv de numărul nivelurilor ierarhice.","Implementarea este garantată de simpla existență a deciziei scrise.","Implementarea exclude judecata profesională a cadrelor didactice."],"answer":0,"explanation":"În organizațiile profesionale, autoritatea formală nu garantează implementarea la clasă. Liderii au nevoie de acceptarea colegilor pentru aplicarea inițiativelor.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 75","quote":"în fruntea şcolilor şi colegiilor are însă limitări serioase. Deşi autoritatea formală este a directorilor, aceştia au nevoie de consimţământul colegilor dacă doresc ca iniţiativele sau politicile să fie adoptate în cadrul departamentelor şi la clasă. Este deja un truism că personalul trebuie să „deţină” deciziile dacă se doreşte ca aceştia să le implementeze","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"C18","theme":"C","prompt":"Directorul urmărește implementarea curriculumului numai pentru a identifica vinovați, fără feedback sau sprijin. Ce orientare recomandă CRCNR pentru monitorizare?","options":["Comparare exclusivă a numărului de pagini din proiectele didactice.","Control exclusiv al existenței documentelor, fără analiza practicii.","Sancționare automată înaintea examinării nevoilor profesorilor.","Sprijin și motivare pentru îmbunătățirea implementării curriculumului."],"answer":3,"explanation":"Strategiile de monitorizare a implementării curriculumului la nivelul clasei și școlii au rol de sprijin și motivare. Documentele nu sunt singurul obiect al monitorizării.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"nivelul școlii; dezvoltarea unor strategii de monitorizare a implementării curriculumului la nivelul clasei și al școlii, în general, cu rol de sprijin şi motivare; asigurarea resurselor necesare implementării CN; spații, resurse materiale adecvate, climatul organizației școlare etc.; încurajarea implementării inovațiilor curriculare – disponibilitatea pentru abordări flexibile, deschiderea către pilotarea de soluții educaționale inovative etc.; diversificarea ofertei educaționale a școlii, prin CDEOȘ și/ sau CS flexibil, pentru a răspunde nevoilor și intereselor elevilor școlii; aceasta presupune, de exemplu, colaborarea dintre mai multe școli, colaborarea dintre școală","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L41","theme":"L","prompt":"La constituirea comisiei de concurs, organizatorul vrea să acorde reprezentanților mediului economic doar statut de observatori. Ce precizează Legea 198?","options":["Reprezentanții mediului economic fac parte din comisia de concurs.","Reprezentanții mediului economic înlocuiesc toți membrii comisiei.","Reprezentanții mediului economic sunt exclusiv observatori la concurs.","Reprezentanții mediului economic sunt excluși din orice etapă."],"answer":0,"explanation":"Legea îi include în comisie pe reprezentanții mediului economic și de afaceri. Observatorii sunt o categorie distinctă, enumerată separat.","source":{"title":"Legea nr. 198/2023","locator":"Art. 198 alin. (2)","quote":"preuniversitar se stabilește conform metodologiei aprobate prin ordin al ministrului educației. Din comisia de concurs fac parte și reprezentanți ai mediului economic și de afaceri. La organizarea și desfășurarea concursului pentru ocuparea funcției de director și director adjunct al unității de învățământ preuniversitar participă cu statut de observator reprezentanți ai federațiilor sindicale reprezentative la nivel de negociere colectivă învățământ preuniversitar, un reprezentant al elevilor, desemnat de Consiliul Național al Elevilor, și un reprezentant desemnat de federațiile reprezentative ale asociațiilor de părinți cu activitate relevantă la nivel național. (3) Consiliul de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R41","theme":"R","prompt":"Un elev schimbă profilul liceal. Comisia propune diferențe la toate disciplinele clasei primitoare, fără analizarea studiilor parcurse. Cum se stabilesc disciplinele de diferență?","options":["Prin alegerea aleatorie a trei discipline.","Prin alegerea exclusivă a dirigintelui clasei.","Prin compararea celor două planuri-cadru.","Prin votul exclusiv al comitetului de părinți."],"answer":2,"explanation":"Compararea planurilor-cadru determină disciplinele/modulele la care se susțin diferențe. Nu se impune automat examen la toate disciplinele.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 140","quote":"și promovarea evaluării prin examene de diferență. Disciplinele/Modulele la care se susțin examene de diferență se stabilesc prin compararea celor două planuri-cadru. Modalitățile de susținere a acestor diferențe se stabilesc de către consiliul de administrație al unității de învățământ, la propunerea membrilor comisiei pentru curriculum.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B33","theme":"B","prompt":"Echipa definește problema, examinează alternativele și alege o intervenție, apoi urmărește rezultatele ei. Ce accent diferențiază modelul rațional discutat de Bush?","options":["Interpretarea exclusiv personală a fiecărui participant.","Negocierea politică pentru împărțirea avantajelor.","Procesul managerial de luare a deciziilor.","Ritualul cultural de transmitere a tradițiilor."],"answer":2,"explanation":"Modelul rațional pune accentul pe procesul de decizie, chiar dacă acesta operează într-o structură și urmărește obiective organizaționale.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 65","quote":"entuziasm, ceea ce poate conduce la eşec. Modelele raţionale Abordările raţionale diferă de alte modele formale în sensul că evidenţiază procesul managerial în locul structurii sau scopurilor organizaţionale. Atenţia cade asupra procesului de luare a deciziilor, şi nu asupra cadrului structural care limitează, dar nu determină deciziile manageriale. Deşi calitatea","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H17","theme":"H","prompt":"Doi elevi au rezultate similare, dar profesorul presupune că elevul mai atractiv fizic are potențial academic mai mare. Ce risc analizează Hattie în acest context?","options":["Aplicarea unui criteriu național obligatoriu pentru evaluarea potențialului.","Demonstrarea automată a unei diferențe reale de competență între elevi.","Distorsionarea estimării performanței prin prejudecăți legate de atractivitate.","Estimarea obiectivă a performanței printr-un indicator academic suficient."],"answer":2,"explanation":"Textul discută prejudecățile prin care atractivitatea fizică poate influența estimările profesorilor. Impresia nu înlocuiește dovezile despre învățare.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 5, p. 234–236","quote":"Pag. 234–236 Pagina 234 Vezi pagina originală ↗ (Patzer, 2012). Suntem mai predispuși să-l angajăm și să-l votăm pe candidatul mai atractiv fizic, iar elevii pretind că învață mai multe de la profesorii mai atractivi (Hosoda et al., 2003; Olivola & Todorov, 2010; Westfall et al., 2016). *Ritts și colaboratorii (1992) au raportat o mărime a efectului d =","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s5","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=10"}},{"id":"L42","theme":"L","prompt":"Organizatorul cere unei singure școli să desemneze observatorul elevilor pentru concursul de directori. Cine îl desemnează potrivit Legii 198?","options":["Consiliul Național al Elevilor.","Consiliul profesoral al școlii.","Consiliul reprezentativ al părinților.","Consiliul școlar al elevilor."],"answer":0,"explanation":"Legea indică desemnarea reprezentantului elevilor de către Consiliul Național al Elevilor, nu de către consiliul unei singure școli.","source":{"title":"Legea nr. 198/2023","locator":"Art. 198 alin. (2)","quote":"federațiilor sindicale reprezentative la nivel de negociere colectivă învățământ preuniversitar, un reprezentant al elevilor, desemnat de Consiliul Național al Elevilor, și un reprezentant desemnat de federațiile reprezentative ale asociațiilor de părinți cu activitate relevantă la nivel național. (3) Consiliul de administrație al DJIP/DMBIP validează rezultatele concursului de ocupare a funcțiilor de director și director adjunct. Directorul general al DJIP/DMBIP emite decizia de numire în funcția de director și de director adjunct. (4) Directorul, respectiv directorul adjunct al unității de învățământ de stat, numiți în urma concursului național, pot fi eliberați din funcție: a) la","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R42","theme":"R","prompt":"La transfer, școala cere examen de diferență la un opțional din CDEOȘ pe care elevul nu l-a studiat. Ce regulă ROFUIP se aplică?","options":["Nu se susțin diferențe pentru disciplinele din CDEOȘ.","Se susțin diferențe la toate opționalele clasei primitoare.","Se susțin diferențe numai la opționalele cu o oră săptămânal.","Se susțin diferențe numai la opționalele fără manual național."],"answer":0,"explanation":"ROFUIP exclude examenele de diferență pentru disciplinele din CDEOȘ. Aceasta este distinctă de preluarea opționalelor clasei la transfer.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 123","quote":"se consemnează în registrul matricol, fără a fi luate în calcul pentru media anuală a elevului pentru fiecare an de studiu încheiat. Nu se susțin examene de diferență pentru disciplinele din curriculumul la decizia elevului din oferta școlii. În cazul beneficiarilor primari transferați în timpul anului școlar, aceștia preiau disciplinele opționale ale clasei în care se transferă. În cazul transferului beneficiarilor primari corigenți la cel mult două discipline/module, cu schimbarea profilului/specializării/calificării profesionale, și care nu vor mai studia la unitatea de învățământ primitoare disciplinele/modulele respective, se vor susține doar examenele de diferență.","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"P17","theme":"P","prompt":"Doi colegi au un conflict care afectează echipa. Directorul ascultă perspectivele, facilitează comunicarea și negociază o soluție acceptabilă. Ce competență specifică este aplicată?","options":["Antreprenoriat educațional și inovație","Atragerea de resurse extrabugetare","Participarea la rețele și proiecte naționale și internaționale","Relaționare, comunicare și gestionarea conflictelor"],"answer":3,"explanation":"Situația se centrează pe relaționare, comunicare și gestionarea conflictelor. Nu descrie participarea într-o rețea sau atragerea de finanțare.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"5.1. Relaționare, comunicare și gestionarea conflictelor","quote":"Asigură o comunicare clară, empatică și adaptată interlocutorului, mediind conflictele cu imparțialitate și menținând un climat relațional pozitiv în interiorul și exteriorul școlii. formulează mesaje verbale și scrise clare, coerente și adaptate interlocutorului — personal, părinți, elevi, autorități; utilizează tehnici de ascultare activă și empatie în relațiile cu membrii comunității școlare; comunică deciziile instituționale în mod transparent, clar și la timp; organizează consultări periodice cu profesori, părinți și elevi pe teme relevante; mediază conflictele cu calm, diplomație și imparțialitate.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"C17","theme":"C","prompt":"Comisia recomandă același curs curricular tuturor profesorilor an după an, fără analiză. Ce etapă trebuie introdusă pentru fundamentarea formării?","options":["Analize exclusiv ale vechimii profesorilor, fără legătură cu aplicarea curriculumului.","Analize periodice și sistematice ale nevoilor de formare ale profesorilor.","Selectarea cursurilor exclusiv după distanța față de sediul organizatorului.","Selectarea cursurilor exclusiv după numărul de fotografii de promovare."],"answer":1,"explanation":"Comisiile contribuie prin identificarea nevoilor, alegerea programelor adecvate și valorificarea formării în școală și în clase. Recomandarea nu trebuie să fie mecanică.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"managementul curriculumului la nivelul școlii, prin: identificarea nevoilor de formare ale profesorilor, în domeniul curriculumului, prin analize de nevoi periodice și sistematice; identificarea programelor de formare acreditate adecvate nevoilor de formare identificate, pentru a le recomanda profesorilor; valorificarea rezultatelor activităților de formare în domeniul curriculumului, la nivelul școlii și al claselor; consilierea curriculară a profesorilor, în aplicarea și evaluarea curriculumului în școală – aspecte critice, bune practici, inovare etc.; facilitarea unei culturi a reflecției asupra întregului proces de aplicare a curriculumului în școală și de evaluare a impactului","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}}]},{"id":10,"title":"Simularea 10","items":[{"id":"R48","theme":"R","prompt":"Adjunctul solicită concediu de odihnă. Secretariatul îl trimite obligatoriu la inspectorul general pentru aprobare, ca pe director. Cine aprobă concediul adjunctului?","options":["Administratorul de patrimoniu.","Consiliul reprezentativ al părinților.","Directorul unității de învățământ.","Secretarul consiliului profesoral."],"answer":2,"explanation":"ROFUIP diferențiază aprobarea concediului directorului de cea a adjunctului: concediul adjunctului este aprobat de directorul școlii.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 27","quote":"(1) Perioada concediului anual de odihnă al directorului adjunct se aprobă de către directorul unității de învățământ. (2) Rechemarea din concediu a directorului adjunct se poate realiza de către directorul unității de învățământ sau de către inspectorul școlar general al ISJ/ISMB, cu respectarea obligațiilor legale de către angajator.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B38","theme":"B","prompt":"Directorul respinge opinia unui profesor specialist, afirmând că funcția îi conferă automat competență superioară în orice disciplină. Ce tensiune identifică Bush?","options":["Autoritatea expertizei derivă exclusiv din nivelul ierarhic ocupat.","Autoritatea expertizei poate intra în conflict cu autoritatea funcției.","Autoritatea funcției elimină nevoia de specializare profesională.","Autoritatea funcției garantează cunoașterea tuturor disciplinelor."],"answer":1,"explanation":"În școli, expertiza este distribuită. Autoritatea profesională a specialistului poate limita puterea practică a autorității poziționale.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 81","quote":"sunt susţinuţi în acest demers de autoritatea ce vine în virtutea poziţiei lor oficiale. Organizaţiile profesioniste au un etos diferit, expertiza fiind distribuită în cadrul instituţiei: Modelele tradiţionale de organizaţie şcolară favorizau ierarhia la vârfuri, ce concentrează puterea şi responsabilitatea de leadership în funcţia de director. Pe măsură ce","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H20","theme":"H","prompt":"Un elev nu cere ajutor fiindcă se teme că va fi ridiculizat pentru greșeli. Directorul propune construirea unui climat relațional sigur. Ce justificare oferă Hattie?","options":["Relațiile pozitive fac inutilă evaluarea progresului fiecărui elev.","Relațiile pozitive înlocuiesc toate obiectivele și conținuturile învățării.","Relațiile pozitive presupun eliminarea tuturor provocărilor de învățare.","Relațiile pozitive susțin siguranța, feedbackul și participarea la învățare."],"answer":3,"explanation":"Relația pozitivă nu înseamnă absența exigenței. Ea oferă siguranța și comunicarea necesare pentru feedback, autoevaluare și învățare.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 15, p. 255–256","quote":"profesională care pune la îndoială presupunerile și teoriile profesorilor despre practica pedagogică poate fi foarte eficientă. Puterea relațiilor pozitive profesori-elevi este esențială pentru ca procesul de învățare să aibă loc. Această relație presupune ca elevilor să li se spună că profesorului îi pasă de formarea lor ca elevi și că este capabil „să le înțeleagă","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s15","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=31"}},{"id":"L49","theme":"L","prompt":"În timpul anului școlar, școala primește informația că planul-cadru a fost revizuit și dorește să schimbe imediat orarul pe baza noii versiuni. Ce regulă generală prevede legea?","options":["Modificările planurilor-cadru nu produc efecte în anul școlar în curs.","Modificările planurilor-cadru produc efecte imediat după votul elevilor.","Modificările planurilor-cadru produc efecte imediat după votul părinților.","Modificările planurilor-cadru produc efecte retroactiv pentru toate clasele."],"answer":0,"explanation":"Articolul precizează că modificările planurilor-cadru nu produc efecte în timpul anului școlar în curs. Cazul se raportează la această regulă generală.","source":{"title":"Legea nr. 198/2023","locator":"Art. 86 alin. (1)","quote":"opționale, precum și bugetul de timp alocat acestora. Planurile-cadru vor fi evaluate și, după caz, revizuite periodic, iar modificările nu vor produce efecte în timpul anului școlar în curs. (2) Trunchiul comun se constituie din disciplinele/domeniile de studiu/modulele de pregătire obligatorii, pentru toți elevii din învățământul primar, gimnazial și liceal indiferent de filieră, profil și specializare/calificare profesională, și se stabilește la nivel central prin ordin al ministrului educației. (3) Curriculumul la decizia elevului din oferta școlii, denumit în continuare CDEOȘ, se constituie din disciplinele/domeniile de studiu, este propus pentru toți elevii din","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R49","theme":"R","prompt":"CP alege reprezentanții cadrelor didactice în CA. Directorul cere vot deschis pentru a cunoaște susținătorii fiecărui candidat. Cum prevede ROFUIP această alegere?","options":["Prin vot consultativ al consiliului elevilor.","Prin vot deschis al consiliului profesoral.","Prin vot nominal al comitetelor de părinți.","Prin vot secret al consiliului profesoral."],"answer":3,"explanation":"Alegerea reprezentanților personalului didactic în CA se face prin vot secret al CP. Preferința directorului nu schimbă modalitatea prevăzută.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 55","quote":"analizează, dezbate și validează raportul privind calitatea învățământului din unitatea de învățământ, care se face public; alege, prin vot secret, reprezentanții personalului didactic în consiliul de administrație; gestionează și asigură calitatea actului didactic; stabilește și monitorizează aplicarea Codului de etică profesională elaborat în conformitate cu Codul-cadru de etică profesională aprobat prin ordin al ministrului educației; propune consiliului de administrație premierea și acordarea titlului de \"Profesorul anului\" personalului didactic de predare cu rezultate deosebite la catedră; propune consiliului de administrație inițierea procedurii legale pentru","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B39","theme":"B","prompt":"Școala declară drept obiectiv doar „educație excelentă pentru toți”, fără repere operaționale. Profesorii nu pot decide ce activități au prioritate. Ce limită a modelelor formale apare?","options":["Scopurile oficiale elimină orice conflict între prioritățile diferitelor grupuri.","Scopurile oficiale înlocuiesc necesitatea oricărei alocări de resurse.","Scopurile oficiale prea generale asigură automat aceeași interpretare tuturor.","Scopurile oficiale prea generale pot avea relevanță operațională redusă."],"answer":3,"explanation":"Bush arată că obiectivele formale sunt adesea vagi și generale, ceea ce le poate limita utilitatea pentru deciziile concrete.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 79","quote":"obiectivelor unei instituţii educaţionale. Obiectivele formale pot avea o relevanţă operaţională scăzută, pentru că sunt deseori vagi şi generale, deoarece pot fi obiective diferite ce necesită aceleaşi resurse, scopurile putând fi stabilite de indivizi sau grupuri sau chiar de liderii organizaţiei. Cum am menţionat anterior (p. 71), obiectivele pot","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"P20","theme":"P","prompt":"Directorul identifică finanțări externe, pregătește aplicații de proiect, negociază sprijin privat și urmărește continuitatea intervențiilor după finanțare. Ce competență specifică este evidențiată?","options":["Antreprenoriat educațional și inovație","Atragerea de resurse extrabugetare","Managementul resurselor umane","Relaționare, comunicare și gestionarea conflictelor"],"answer":1,"explanation":"Acțiunile sunt orientate spre atragerea și mobilizarea resurselor extrabugetare. Colaborarea și negocierea sunt folosite aici în serviciul finanțării intervențiilor.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"5.4. Atragerea de resurse extrabugetare","quote":"Captează resurse financiare și materiale din comunitate, activând sectorul privat și nonguvernamental, și asigură coerența dintre obiectivele instituționale și activitățile de fundraising și parteneriat. identifică surse de finanțare extrabugetară și inițiază aplicații de proiect relevante pentru nevoile școlii; captează resurse financiare și materiale din comunitate, activând sectorul privat și nonguvernamental; utilizează tehnici de negociere și mediere în gestionarea parteneriatelor; asigură coerența dintre obiectivele instituționale și activitățile de fundraising; coordonează implementarea proiectelor externe și asigură continuitatea după finalizarea finanțării; menține legătura cu comunitatea și promovează imaginea instituției la nivel local și regional; încurajează participarea comunității în proiecte educaționale.","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"L50","theme":"L","prompt":"După evaluări, profesorul elaborează planul individualizat de învățare al elevului. Secretarul propune să îl includă numai în dosarul personal al profesorului. Unde îl situează legea?","options":["În contractul de muncă al profesorului.","În dosarul de achiziții al instituției.","În portofoliul educațional al elevului.","În registrul contabil al școlii."],"answer":2,"explanation":"Planul individualizat este parte componentă a portofoliului educațional al elevului. Rolul său este planificarea și monitorizarea învățării acestuia.","source":{"title":"Legea nr. 198/2023","locator":"Art. 85 alin. (5)","quote":"f) este dezvoltat în urma interacțiunii dintre profesor, elev și părinte. (5) Planul individualizat de învățare este parte componentă a portofoliului educațional al elevului. (6) În învățământul preuniversitar se aplică curriculumul național, care oferă oportunități de învățare pentru elevi, astfel încât fiecare să își valorifice potențialul, în funcție de pregătire, nevoi și interese de cunoaștere, în vederea integrării și participării active în societate. (7) Curriculumul național este ansamblul coerent al elementelor care reglementează activitatea personalului didactic din învățământul preuniversitar și include planurile-cadru de învățământ, programele școlare și standardele","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R50","theme":"R","prompt":"La o disciplină teoretică de gimnaziu, profesorul planifică numai evaluări orale pentru întregul an. Ce cerință ROFUIP trebuie inclusă în proiectare?","options":["Cel puțin două evaluări prin lucrare scrisă sau test pe an școlar.","Cel puțin o evaluare prin lucrare scrisă sau test la doi ani.","Cel puțin o evaluare scrisă numai la finalizarea ciclului școlar.","Cel puțin patru evaluări scrise în fiecare săptămână de curs."],"answer":0,"explanation":"Pentru nivelurile și disciplinele prevăzute, cu excepția celor preponderent practice, sunt necesare cel puțin două evaluări scrise/teste pe an școlar.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 104","quote":"gimnazial, liceal, profesional și în cel postliceal, elevii vor avea la fiecare disciplină/modul, cu excepția celor preponderent practice, cel puțin două evaluări prin lucrare scrisă/test pe an școlar.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B40","theme":"B","prompt":"După analiza școlii, echipa constată că organigrama explică responsabilitățile, dar nu și toate conflictele și adaptările la mediu. Cum pot fi folosite modelele formale?","options":["Ca descrieri parțiale utile, completate cu alte perspective.","Ca explicații complete, care fac inutile toate celelalte perspective.","Ca rețete universale, aplicabile identic oricărei instituții.","Ca teorii definitiv invalidate, fără nicio utilizare în școli."],"answer":0,"explanation":"Criticile nu anulează orice utilitate a modelelor formale. Ele rămân descrieri parțiale, care trebuie folosite cu înțelegerea limitelor lor.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 83","quote":"ale teoriilor formale. Totuşi, aceste perspective alternative nu au reuşit să elimine modelele formale, care rămân valide ca descrieri parţiale ale organizaţiei şi managementului în educaţie. Modelele formale sunt inadecvate, însă au în continuare o mare contribuţie pentru ca şcolile şi colegiile să poată fi înţelese ca organizaţii. Owens şi Shakeshaft (1992)","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"C20","theme":"C","prompt":"Regulile informale ale școlii descurajează reflecția și adaptarea resurselor pentru elevii vulnerabili. De ce trebuie conducerea să examineze și cultura școlii?","options":["Cultura școlii poate înlocui integral toate documentele curriculare naționale.","Cultura școlii transferă responsabilitatea învățării exclusiv în sarcina familiei.","Valorile, normele și tradițiile influențează aplicarea curriculumului și echitatea învățării.","Valorile, normele și tradițiile nu au nicio legătură cu aplicarea curriculumului."],"answer":2,"explanation":"Managementul curriculumului este influențat și de valorile, normele, credințele și tradițiile organizației. Acestea pot susține sau limita comunitatea de învățare și accesul efectiv la educație.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"a profesorilor, în aplicarea și evaluarea curriculumului în școală – aspecte critice, bune practici, inovare etc.; facilitarea unei culturi a reflecției asupra întregului proces de aplicare a curriculumului în școală și de evaluare a impactului acestuia asupra învățării. Inspectorul școlar – consilier pentru managementul curriculumului la nivelul școlii. În transpunerea CN la nivelul fiecărei școli, inspectorul școlar are roluri precum: consilierea echipei manageriale, a echipelor de profesori și a profesorilor, în proiectarea, implementarea și evaluarea CN; asigurarea coerenței dintre curriculumul oficial și cel aplicat în școală; dezvoltarea, selectarea și","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L46","theme":"L","prompt":"Directorul transmite proiectul de buget și execuția bugetară către CA. Secretarul le consemnează pe ambele ca fiind doar avizate. Ce acțiuni prevede legea pentru CA?","options":["Adoptă proiectul de buget și avizează execuția bugetară.","Avizează proiectul de buget și adoptă execuția bugetară.","Înregistrează proiectul de buget și arhivează execuția bugetară.","Publică proiectul de buget și respinge execuția bugetară."],"answer":0,"explanation":"Articolul folosește verbe diferite pentru cele două documente: adoptă proiectul și avizează execuția. Nu trebuie uniformizate atribuțiile.","source":{"title":"Legea nr. 198/2023","locator":"Art. 128 alin. (9) lit. a)","quote":"o sancțiune disciplinară neradiată. (9) Consiliul de administrație are următoarele atribuții principale: a) adoptă proiectul de buget și avizează execuția bugetară la nivelul unității de învățământ; b) aprobă planul de dezvoltare instituțională, respectiv planul de acțiune al unității de învățământ preuniversitar, la propunerea directorului unității de învățământ; c) aprobă, la propunerea consiliului profesoral și după consultarea consiliului școlar al elevilor și părinților, curriculumul la decizia elevului din oferta școlii; d) analizează și aprobă propunerile de colaborare cu terții, în condițiile legii și cu respectarea principiului interesului superior al beneficiarului","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R46","theme":"R","prompt":"Un elev este oprit de la cursuri pentru că nu poartă uniforma școlii. Directorul invocă regulamentul intern. Ce regulă ROFUIP limitează măsura?","options":["Sunt interzise măsurile care limitează accesul la educație pentru lipsa uniformei.","Sunt interzise măsurile de sprijin dacă elevul nu a cumpărat uniforma.","Sunt permise măsurile de excludere dacă majoritatea părinților susține uniforma.","Sunt permise măsurile de excludere dacă uniforma este menționată în regulament."],"answer":0,"explanation":"Regulamentul propriu nu poate legitima o măsură interzisă de ROFUIP. Articolul dă explicit exemplul sancționării elevilor care nu poartă uniforma.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 183","quote":"efectuarea de către aceștia a serviciului pe școală, interzicerea participării la cursuri sau sancționarea beneficiarilor primari care nu poartă uniforma unității de învățământ sau altele asemenea. În scopul protejării beneficiarilor primari și prevenirii traficului de minori, fiecare unitate de învățământ va implementa măsuri proactive de identificare și prevenire a cazurilor de trafic de persoane. În organizarea activităților de informare și educare pentru elevi și părinți/reprezentanți legali cu scopul de a crește gradul de conștientizare privind pericolele traficului de persoane, precum și modalitățile de prevenire ale acestuia, unitățile de învățământ vor colabora cu","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B37","theme":"B","prompt":"Un raport descrie școala ca pe un mecanism independent de percepțiile și contribuțiile oamenilor. Ce critică a modelelor formale formulează perspectiva lui Greenfield?","options":["Tratarea organizației ca entitate separată dovedește că percepțiile nu contează.","Tratarea organizației ca entitate separată elimină orice limită a modelului formal.","Tratarea organizației ca entitate separată explică integral comportamentul tuturor.","Tratarea organizației ca entitate separată subestimează contribuția indivizilor."],"answer":3,"explanation":"Problema entității privește tendința de a considera organizația independentă de oamenii care o construiesc și îi dau sens.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 80","quote":"în literatura secolului XXI pentru nevoia profesorilor de a „deţine” schimbarea. 3. Modelele formale se concentrează pe organizaţie ca entitate şi ignoră sau subestimează contribuţia indivizilor. Ele pornesc de la ipoteza că oamenii ocupă poziţii prestabilite în structură, iar comportamentul lor reflectă poziţia lor organizaţională, nu calităţile şi experienţa","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H19","theme":"H","prompt":"La finalul explicației, profesorul cere elevilor să reformuleze ce au de realizat și să folosească reperele de succes pentru autoevaluare. Ce urmărește direct?","options":["Aprobarea de către elevi a distribuirii administrative a sarcinilor profesorilor.","Confirmarea de către elevi a prestigiului diplomei deținute de profesor.","Înțelegerea de către elevi a învățării urmărite și a criteriilor de reușită.","Memorarea de către elevi a tuturor articolelor din regulamentul școlii."],"answer":2,"explanation":"Verificarea înțelegerii intențiilor și criteriilor susține claritatea. Simplul fapt că profesorul a formulat un mesaj nu dovedește că elevii l-au înțeles.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 6, p. 237–238","quote":"class=\"chapter\"> SECȚIUNEA 06 Credibilitatea profesorului / Claritatea profesorului Pag. 237–238 Pagina 237 Vezi pagina originală ↗ Credibilitatea profesorului Credibilitatea profesorului reprezintă credința elevilor că pot învăța de la un anumit profesor pentru că profesorul este","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s6","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=13"}},{"id":"L47","theme":"L","prompt":"CA adoptă hotărâri, dar directorul refuză publicarea lor, motivând că a informat verbal diriginții. Ce obligație prevede legea?","options":["Comunicarea hotărârilor numai telefonic către profesorii diriginți.","Păstrarea hotărârilor exclusiv într-un dosar accesibil conducerii.","Publicarea hotărârilor la avizier și pe websiteul unității.","Transmiterea hotărârilor numai către membrii comitetelor de părinți."],"answer":2,"explanation":"Legea prevede publicarea componenței CA și a hotărârilor adoptate la avizier și pe website. Informarea verbală nu înlocuiește publicarea.","source":{"title":"Legea nr. 198/2023","locator":"Art. 128 alin. (13)","quote":"Componența consiliului de administrație, precum și hotărârile adoptate de acesta se publică la avizierul școlar, precum și pe websiteul unității de învățământ preuniversitar. (14) Directorul unității de învățământ emite deciziile conform hotărârilor consiliului de administrație. (15) Consiliul de administrație se întrunește lunar sau ori de câte ori este necesar, la solicitarea directorului sau a unei treimi dintre membri. (16) Metodologia-cadru de organizare și funcționare a consiliului de administrație este aprobată prin ordin al ministrului educației. (17) Reprezentantul desemnat al primarului/primarului de sector, respectiv reprezentantul desemnat al","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R47","theme":"R","prompt":"Școala cere semnarea unui nou contract educațional în fiecare lună și consideră contractul inițial expirat. Care este valabilitatea prevăzută de ROFUIP?","options":["Numai perioada până la prima ședință cu părinții.","Numai prima lună de la înscrierea în unitatea școlară.","Numai primul interval de cursuri al fiecărui an școlar.","Toată perioada de școlarizare în cadrul acelei unități."],"answer":3,"explanation":"Contractul este valabil pe toată perioada de școlarizare în unitate. Modificările legale se realizează prin mecanismele prevăzute, nu prin expirare lunară inventată.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 171","quote":"Contractul educațional este valabil pe toată perioada de școlarizare în cadrul unității de învățământ. Contractul educațional se încheie în două exemplare originale, unul pentru părinte sau reprezentant legal/elev major, altul pentru unitatea de învățământ, și își produce efectele de la data semnării. Unitatea de învățământ arhivează exemplarul contractului educațional pe toată perioada de școlarizare a elevului și pentru încă doi ani din momentul în care elevul părăsește unitatea de învățământ. Consiliul de administrație al unității de învățământ preuniversitar monitorizează","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"P19","theme":"P","prompt":"Directorul identifică oportunități educaționale noi și sprijină inițiative care transformă idei în soluții viabile pentru școală și comunitate. Ce competență specifică este ilustrată?","options":["Antreprenoriat educațional și inovație","Atragerea de resurse extrabugetare","Cercetare, inovație pedagogică și conceptualizare strategică","Dezvoltare și transformare organizațională"],"answer":0,"explanation":"Antreprenoriatul educațional și inovația implică identificarea oportunităților și construirea unor inițiative cu valoare educațională. Atragerea resurselor este o competență distinctă.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"5.3. Antreprenoriat educațional și inovație","quote":"Identifică oportunități de valorificare a resurselor instituționale, influențează organizația în direcția atingerii obiectivelor și asigură implicarea factorilor interesați în rezolvarea provocărilor specifice. influențează organizația în direcția atingerii obiectivelor strategice asumate; dezvoltă inițiative pentru valorificarea resurselor de infrastructură și a capacității umane a instituției; asigură participarea și implicarea factorilor interesați în adresarea provocărilor specifice — lipsa resurselor, sprijin socioeconomic etc.; introduce soluții inovatoare validate și evaluează impactul lor asupra rezultatelor elevilor; promovează cultura experimentării responsabile și a îmbunătățirii continue; reprezintă public instituția într-un mod coerent, profesionist și convingător.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"C19","theme":"C","prompt":"Inspectorul discută cu profesorii despre coerența dintre programa oficială și practica la clasă și oferă consiliere pentru adaptare. Ce rol descrie CRCNR?","options":["Autor exclusiv al tuturor proiectelor de lecție ale profesorilor.","Consilier pentru managementul curriculumului la nivelul școlii.","Evaluator exclusiv al cheltuielilor materiale din bugetul școlii.","Înlocuitor permanent al comisiei pentru curriculum din școală."],"answer":1,"explanation":"Capitolul descrie consilierea echipelor și profesorilor, asigurarea coerenței curricularului și monitorizarea prin dialog profesional.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"a reflecției asupra întregului proces de aplicare a curriculumului în școală și de evaluare a impactului acestuia asupra învățării. Inspectorul școlar – consilier pentru managementul curriculumului la nivelul școlii. În transpunerea CN la nivelul fiecărei școli, inspectorul școlar are roluri precum: consilierea echipei manageriale, a echipelor de profesori și a profesorilor, în proiectarea, implementarea și evaluarea CN; asigurarea coerenței dintre curriculumul oficial și cel aplicat în școală; dezvoltarea, selectarea și aplicarea de instrumente de monitorizare a implementării CN, relevante pentru curriculumul centrat pe competențe; monitorizarea implementării CN, prin","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L48","theme":"L","prompt":"Directorul prezintă raportul anual asupra calității numai în CA și consideră încheiată comunicarea. Care acțiune completează obligația legală?","options":["Îl comunică exclusiv primarului și îl păstrează în cabinetul propriu.","Îl prezintă exclusiv secretarului și îl elimină după încheierea ședinței.","Îl prezintă structurilor prevăzute și îl postează pe site-ul școlii.","Îl transmite exclusiv furnizorilor și îl arhivează în dosarul contabil."],"answer":2,"explanation":"Legea enumeră consiliul profesoral, elevii, structurile părinților și informarea autorităților; raportul se postează și pe site. O singură prezentare în CA nu acoperă obligația.","source":{"title":"Legea nr. 198/2023","locator":"Art. 195 alin. (2) lit. h)","quote":"din unitatea de învățământ; g) îndeplinește alte atribuții stabilite de consiliul de administrație, conform legii; h) prezintă anual un raport asupra calității educației în unitatea de învățământ sau în instituția pe care o conduce. Raportul este prezentat în fața consiliului profesoral, a consiliului școlar al elevilor, a consiliului reprezentativ al părinților și a conducerii asociației de părinți, acolo unde există. Raportul este adus la cunoștința autorităților administrației publice locale și a DJIP/DMBIP și postat pe site-ul unității de învățământ; i) coordonează colectarea și transmite DJIP/DMBIP datele statistice pentru sistemul național de indicatori privind educația; j)","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}}]},{"id":11,"title":"Simularea 11","items":[{"id":"B42","theme":"B","prompt":"Conducerea anunță că există consens asupra priorităților, dar profesorii și părinții descriu scopuri diferite. Ce demers de analiză este justificat?","options":["Acceptarea declarației ca dovadă suficientă a consensului organizațional.","Eliminarea tuturor opiniilor care nu coincid cu declarația directorului.","Examinarea intereselor și a modului în care sunt construite scopurile.","Înlocuirea consultării cu multiplicarea aceleiași liste de obiective."],"answer":2,"explanation":"Scopurile atribuite organizației pot ascunde interese diferite. Analiza lor presupune verificarea acordului real, nu presupunerea lui dintr-un document.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 15","quote":"să presupunem că cei mai mulţi dintre profesori doresc ca şcoala sau colegiul în care lucrează să adopte politici concordante propriilor interese şi preferinţe. Acest aspect va fi explorat pe parcursul volumului, cu precădere în capitolul 6. Stabilirea obiectivelor Procesul de determinare a obiectivelor organizaţiei se află în centrul managementului educaţional.","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H22","theme":"H","prompt":"Un director vrea să aleagă profesorii exclusiv printr-un test de personalitate. Ce concluzie prudentă rezultă din discuția lui Hattie?","options":["Trăsăturile elimină necesitatea pregătirii și a dezvoltării profesionale a profesorului.","Trăsăturile garantează performanța, indiferent de modul în care este predată materia.","Trăsăturile permit ignorarea totală a experiențelor reale de învățare ale elevilor.","Trăsăturile pot conta, dar nu înlocuiesc dovezile despre practica didactică."],"answer":3,"explanation":"Discuția despre personalitate nu justifică folosirea ei drept predictor suficient pentru performanța fiecărui profesor.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 2, p. 229–229","quote":"cea mai puternică se corelează cu maximizarea performanței elevilor, prin manifestarea de siguranță în calitate de profesor, de entuziasm față de slujbă și de discernământ. Ceilalți factori ai personalității au puține sau zero corelații. Tabelul 9.3. Corelațiile între atributele de personalitate ale profesorului și progresul în performanța elevilor","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s2","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=5"}},{"id":"L54","theme":"L","prompt":"O unitate particulară autorizată provizoriu este omisă din descrierea sistemului național, pe motiv că numai școlile acreditate aparțin acestuia. Ce corecție este necesară?","options":["Sistemul include numai unitățile de stat deja acreditate.","Sistemul include numai unitățile particulare deja acreditate.","Sistemul include și unitățile autorizate să funcționeze provizoriu.","Sistemul include unitățile autorizate doar după prima absolvire."],"answer":2,"explanation":"Sistemul cuprinde unitățile de stat, particulare și confesionale autorizate provizoriu sau acreditate. Autorizarea provizorie nu înseamnă situarea în afara sistemului.","source":{"title":"Legea nr. 198/2023","locator":"Art. 12 alin. (1)","quote":"național de învățământ preuniversitar este constituit din totalitatea unităților de învățământ de stat, particulare și confesionale, autorizate să funcționeze provizoriu/ acreditate. (2) Unitățile de învățământ preuniversitar de stat, particulare și confesionale se înființează pe niveluri de învățământ, prin ordin al ministrului educației, în condițiile prezentei legi. (3) Învățământul preuniversitar este organizat pe niveluri, forme de învățământ, filiere și profiluri, după caz, asigurând condițiile necesare pentru dobândirea competențelor-cheie și pentru profesionalizarea progresivă, în acord cu profilul educațional al absolventului fiecărui nivel de învățământ. (4) Sistemul național de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R54","theme":"R","prompt":"La clasa a II-a se propune începerea cursurilor la 7:30, pentru eliberarea sălilor. Ce interval-limită prevede regulamentul pentru această clasă?","options":["Începere nu înainte de 7:00 și terminare nu după 13:00.","Începere nu înainte de 7:30 și terminare nu după 14:30.","Începere nu înainte de 8:00 și terminare nu după 14:00.","Începere nu înainte de 9:00 și terminare nu după 16:00."],"answer":2,"explanation":"Pentru pregătitoare, clasa I și clasa a II-a, cursurile nu încep înainte de 8:00 și nu se termină după 14:00.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 11","quote":"de consiliul de administrație al unității de învățământ. Cursurile pentru elevii din clasa pregătitoare și din clasele I și a II-a nu vor începe înainte de ora 8.00 și nu se vor termina mai târziu de ora 14.00. În învățământul primar, ora de curs este de 45 de minute, cu o pauză de 15 minute după fiecare oră și o pauză de 20 de minute după cea de-a doua oră de curs. La clasa pregătitoare și la clasa I, activitățile de predare-învățare-evaluare acoperă 30 – 35 de minute, restul de timp fiind destinat activităților liber alese, recreative. În situațiile în care clasele din învățământul primar funcționează împreună cu alte clase din nivelurile superioare de învățământ, ora de curs este","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B43","theme":"B","prompt":"O metodă nouă a fost prezentată profesorilor numai printr-o circulară. Aplicarea rămâne formală. Ce pas ar susține implementarea schimbării?","options":["Implicarea celor care aplică metoda în înțelegerea și asumarea ei.","Înlocuirea dialogului profesional cu verificarea numărului de exemplare.","Măsurarea succesului exclusiv prin confirmările de primire ale circularei.","Trimiterea aceleiași circulare fără discutarea dificultăților de aplicare."],"answer":0,"explanation":"Schimbarea are nevoie de angajamentul practicienilor. Comunicarea formală a unei decizii nu creează automat înțelegere și asumare.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 17","quote":"în anumite instituţii de învăţământ. Guvernele au puterea constituţională de a‑şi impune voinţa, dar inovaţiile de succes reclamă angajamentul celor care trebuie să implementeze aceste schimbări. Dacă profesorii şi liderii consideră că o iniţiativă este nepotrivită pentru copiii sau pentru elevii lor, este improbabil ca aceştia să o implementeze cu entuziasm.","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"P22","theme":"P","prompt":"Școala funcționează prin practici izolate. Directorul creează mecanisme de învățare organizațională, implică actorii în inovare și transformă datele în îmbunătățiri instituționale. Ce competență este centrală?","options":["Cercetare, inovație pedagogică și conceptualizare strategică","Conformitate juridică și etică profesională","Dezvoltare și transformare organizațională","Managementul schimbării, adaptare și gestionarea presiunilor"],"answer":2,"explanation":"Este urmărită dezvoltarea întregii organizații prin participare, inovare și învățare, nu numai executarea unei schimbări punctuale.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"1.2. Dezvoltare și transformare organizațională","quote":"Implică activ actorii ecosistemului educațional și conduce procesele de inovare instituțională, adoptând decizii fundamentate pe date. consultă și implică profesori, elevi și părinți în inițiativele de îmbunătățire instituțională; adoptă decizii manageriale fundamentate pe date și indicatori de performanță relevanți; aplică tehnici de coaching și feedback constructiv în lucrul cu personalul didactic și administrativ; mobilizează personalul și stimulează cultura organizațională orientată spre performanță și colaborare; gestionează conflictele și crizele la diferite niveluri cu calm și profesionalism; valorifică bunele practici interne și externe și stimulează învățarea organizațională; asigură un răspuns agil la nevoile organizației prin mobilizarea și atragerea resurselor relevante.","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"L55","theme":"L","prompt":"La consilierea unui adult se prezintă liceul seral ca având obligatoriu aceeași durată de patru ani ca liceul de zi. Ce durată trebuie indicată potrivit legii?","options":["Cinci ani pentru forma cu frecvență seral.","Patru ani pentru forma cu frecvență seral.","Șase ani pentru forma cu frecvență seral.","Trei ani pentru forma cu frecvență seral."],"answer":0,"explanation":"Pentru liceul seral și liceul cu frecvență redusă, articolul 15 prevede durata de cinci ani, prin excepție de la durata obișnuită.","source":{"title":"Legea nr. 198/2023","locator":"Art. 15 alin. (3)","quote":"alin. (1) lit. d), în cazul învățământului liceal, organizat la forma cu frecvență redusă, respectiv la forma cu frecvență seral, durata învățământului este de 5 ani. (4) Prin excepție de la prevederile alin. (1), în cazul alternativelor educaționale, durata fiecărui nivel de învățământ este aprobată prin ordinul ministrului educației de funcționare a alternativei.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R55","theme":"R","prompt":"La grădiniță, numărul copiilor din fiecare grupă de vârstă este sub minimul legal. Ce soluție de organizare permite expres ROFUIP?","options":["Constituirea de grupe eterogene, în situația prevăzută.","Constituirea obligatorie a unei clase de învățământ primar.","Eliminarea tuturor activităților până la atingerea mediei naționale.","Înlocuirea înscrierii copiilor cu o simplă evidență a părinților."],"answer":0,"explanation":"Pentru efective sub minimul fiecărei grupe de vârstă sau frați de vârste diferite, regulamentul permite constituirea grupelor eterogene.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 13","quote":"și completările ulterioare, pentru fiecare grupă de vârstă sau, în cazul existenței fraților de vârste diferite, se pot constitui și grupe eterogene. În situații excepționale, formațiunile de antepreșcolari, preșcolari sau de elevi pot funcționa cu cel mult 2 beneficiari sub efectivul minim și, respectiv, cu cel mult 4 beneficiari peste efectivul maxim prevăzut la art. 23 alin. (1) din Legea învățământului preuniversitar nr. 198/2023, cu modificările și completările ulterioare, după caz, cu aprobarea inspectoratului școlar, pe baza unei justificări din partea consiliului de administrație al unității de învățământ care solicită exceptarea de la prevederilealin. (1). (la","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B44","theme":"B","prompt":"Un mentor fără funcție de conducere schimbă practicile unei echipe prin argumente și încredere profesională. Ce criteriu susține identificarea leadershipului?","options":["Existența obligatorie a unei indemnizații de conducere.","Influența exercitată asupra acțiunii colegilor.","Numărul de documente semnate în numele instituției.","Poziția obligatorie de președinte al consiliului de administrație."],"answer":1,"explanation":"Leadershipul este un proces de influență; nu este limitat la persoanele care au autoritate oficială.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 18","quote":"în poziţii formale, precum cea de director, în timp ce primul poate fi exercitat de oricine din şcoală sau din colegiu. Leadershipul este independent de autoritatea poziţiei, însă managementul este direct legat de aceasta. • Procesul este intenţionat. Individul care doreşte să îşi exercite influenţa o face pentru a atinge anumite scopuri. • Influenţa poate fi exercitată atât de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"C22","theme":"C","prompt":"O școală are materiale moderne, dar profesorii nu au timp de pregătire și sprijin pentru utilizare. Ce perspectivă asupra resurselor este necesară?","options":["Analiza exclusivă a dimensiunii depozitului cu materiale didactice.","Analiza exclusivă a numărului de echipamente cumpărate în ultimul an.","Analiza exclusivă a valorii facturilor pentru mobilierul din săli.","Analiza împreună a resurselor umane, materiale, financiare și de timp."],"answer":3,"explanation":"Resursele curriculumului nu sunt numai materiale. Organizarea lor presupune corelarea oamenilor, timpului și finanțării cu utilizarea educațională.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"a documentelor curriculare reglatoare. O provocare în implementarea Curriculum Național centrat pe formarea de competențe este utilizarea resurselor școlii (umane, materiale, financiare, de timp), plecând de la identificarea nevoilor reale de învățare pe care le au elevii, de la cunoașterea specificului comunității din care face parte școala, astfel încât: elevii să își valorifice propriul traseu de învățare, să particularizeze acest traseu, prin disciplinele opționale pe care le pot alege, să se implice activ în învățare, conștienți că achizițiile dobândite le sunt utile pentru viață, pe termen lung, în afara școlii; profesorii să acționeze ca agenți care induc învățarea, o","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L51","theme":"L","prompt":"Un liceu își păstrează oferta de pregătire deși nevoile elevilor și cererea de calificări din zonă s-au schimbat. Ce principiu cere corelarea ofertei cu aceste realități?","options":["Principiul datelor deschise.","Principiul descentralizării decizionale.","Principiul relevanței.","Principiul transparenței."],"answer":2,"explanation":"Relevanța presupune o ofertă realistă, actualizată și corelată cu dezvoltarea elevilor, cunoașterea, valorile socioculturale și cerințele pieței muncii.","source":{"title":"Legea nr. 198/2023","locator":"Art. 3 lit. c)","quote":"căruia activitățile de învățământ se raportează la standarde de calitate și la bune practici naționale, europene și internaționale; c) principiul relevanței - presupune o ofertă educațională realistă, actualizată și corelată cu nevoile elevilor de dezvoltare personală, cu domeniile de cunoaștere, cu valorile socioculturale și cu cerințele pieței muncii; d) principiul eficienței - în baza căruia se urmărește obținerea de rezultate educaționale preconizate, prin gestionarea resurselor existente; e) principiul descentralizării decizionale - presupune redistribuirea autorității decizionale de la nivelurile centrale către cele locale, pentru a răspunde adecvat nevoilor","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R51","theme":"R","prompt":"Un părinte solicită înscrierea copilului la o școală din afara circumscripției. Există locuri în planul aprobat. Care soluție corespunde ROFUIP?","options":["Cererea este interzisă în toate cazurile, indiferent de locurile disponibile.","Cererea poate fi aprobată de CA al școlii solicitate, în limita planului.","Cererea se aprobă exclusiv de comitetul de părinți al clasei solicitate.","Cererea se aprobă exclusiv de școala din circumscripția domiciliului."],"answer":1,"explanation":"Părintele poate cere o altă școală decât cea de circumscripție. CA al unității solicitate aprobă înscrierea în limita planului de școlarizare.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 8","quote":"din partea părintelui sau a reprezentantului legal. Părintele/reprezentantul legal are dreptul de a solicita școlarizarea copilului la o altă unitate de învățământ decât aceea la care domiciliul său este arondat. Înscrierea se face în urma unei solicitări scrise din partea părintelui, a tutorelui sau a reprezentantului legal și se aprobă de către consiliul de administrație al unității de învățământ la care se solicită înscrierea, în limita planului de școlarizare aprobat, după asigurarea școlarizării beneficiarilor primari din circumscripția școlară a unității de învățământ respective. Prin excepție de la prevederile alin. (4), înscrierea în unitățile de învățământ cu nivel","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B41","theme":"B","prompt":"Școala raportează că toate formularele au fost completate, deși elevii vulnerabili nu mai participă la activități. Ce întrebare combate cel mai direct managerialismul?","options":["Câte formulare suplimentare putem cere înainte de următoarea ședință?","Cum putem demonstra că respectarea formatului este singurul rezultat?","Cum putem înlocui obiectivele educaționale cu termene administrative?","În ce măsură procedurile servesc scopurilor educaționale urmărite?"],"answer":3,"explanation":"Procedurile trebuie raportate la scopuri și valori. Numărul documentelor nu constituie singur dovada îndeplinirii misiunii educaționale.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 13","quote":"Dacă legătura dintre scop şi management nu este clar definită, apare pericolul alunecării în „managerialism”, cu „un accent pe proceduri în detrimentul scopurilor şi valorilor educaţionale” (Bush, 1999: 240). Managerialismul pune mai curând accent pe eficienţa managerială decât pe scopurile şi obiectivele","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H21","theme":"H","prompt":"Un profesor își apreciază eficiența numai după cât de ordonat a prezentat materia. Ce dovadă suplimentară ar trebui să caute pentru a-și cunoaște impactul?","options":["Cât de mult timp a vorbit fără întrerupere în fața clasei.","Câte materiale decorative a adăugat în prezentarea electronică.","Câte pagini are suportul de curs distribuit la fiecare lecție.","Ce au învățat elevii și cum s-a modificat înțelegerea lor."],"answer":3,"explanation":"Calitatea predării se examinează prin efectele asupra învățării, nu doar prin caracteristicile prezentării profesorului.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 1, p. 225–228","quote":"când adaugi asistenții profesorului și pozițiile de conducere, raportul dintre adulți și elevi a crescut în mod clar. Din 1987, numărul elevilor a crescut cu 19%, iar al profesorilor cu 46%. Mai cărunt Procentul profesorilor de peste 50 de ani a crescut (33% în peste 50 de țări din OCDE), dar e probabil ca această tendință să se inverseze pe măsură ce căutăm","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s1","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=1"}},{"id":"L52","theme":"L","prompt":"O școală cu predare în limba unei minorități propune eliminarea învățării limbii române din program. Ce obligație legală trebuie păstrată?","options":["Învățarea limbii române de către toți beneficiarii primari.","Învățarea limbii române numai de către elevii majori.","Învățarea limbii române numai la cererea familiilor.","Învățarea limbii române numai pentru examenele finale."],"answer":0,"explanation":"Articolul 5 face obligatorie învățarea în școală a limbii române pentru toți beneficiarii primari. Limba de predare nu înlătură această obligație.","source":{"title":"Legea nr. 198/2023","locator":"Art. 5","quote":"Învățarea în școală a limbii române, ca limbă oficială de stat, este obligatorie pentru toți beneficiarii primari ai educației. Planurile de învățământ cuprind numărul de ore necesare și suficiente învățării limbii române. Autoritățile administrației publice asigură condițiile materiale și resursele umane care să permită însușirea limbii române.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R52","theme":"R","prompt":"Într-un document managerial, anul școlar este încheiat la ultima zi de cursuri din iunie. Care interval definește anul școlar în ROFUIP?","options":["1 ianuarie–31 decembrie din același an calendaristic.","1 septembrie–30 iunie din același an școlar.","1 septembrie–31 august din anul calendaristic următor.","15 septembrie–15 iunie din același an școlar."],"answer":2,"explanation":"Anul școlar și perioada cursurilor nu sunt identice. Anul școlar începe la 1 septembrie și se încheie la 31 august din anul calendaristic următor.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 9","quote":"Anul școlar începe la 1 septembrie și se încheie la 31 august din anul calendaristic următor. Structura anului școlar, respectiv perioadele de desfășurare a cursurilor, a vacanțelor și a sesiunilor de evaluări, examene și concursuri naționale se stabilesc prin ordin al ministrului educației. În unitățile de educație timpurie, care oferă servicii esențiale în societate, atât pentru copiii cărora li se adresează, cât și pentru familiile acestora și angajatori, vacanța școlară se raportează, cu prioritate, la interesul beneficiarilor primari pentru care, în timpul acesteia, se","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"P21","theme":"P","prompt":"O schimbare de program provoacă opoziție. Directorul identifică sursele presiunii, pregătește echipa pentru tranziție și urmărește adaptarea noilor rutine. Ce competență este dominantă?","options":["Cercetare, inovație pedagogică și conceptualizare strategică","Dezvoltare și transformare organizațională","Managementul schimbării, adaptare și gestionarea presiunilor","Reziliență și managementul riscului"],"answer":2,"explanation":"Accentul cade pe conducerea schimbării și adaptarea la presiuni. Analiza rezistenței și susținerea tranziției depășesc simpla comunicare a unui orar.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"1.1. Managementul schimbării, adaptare și gestionarea presiunilor","quote":"Inițiază, conduce și consolidează procese de transformare instituțională, mobilizând resursele organizației și gestionând rezistența la schimbare pentru atingerea obiectivelor strategice. proiectează și planifică procese de schimbare pe baza unei analize clare a contextului instituțional; definește obiectivele schimbării în termeni specifici, măsurabili și comunicabili echipei; facilitează sesiuni de planificare participativă pentru a coagula echipa în jurul viziunii de transformare; gestionează rezistența la schimbare prin dialog deschis, claritate și argumente centrate pe beneficiile elevilor; monitorizează progresul transformării și ajustează strategiile pe baza feedbackului colectat sistematic; consolidează noile practici prin reguli, proceduri și rutine instituționale; utilizează metodologii recunoscute de management al schimbării, d","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"C21","theme":"C","prompt":"Școala are planificări bine scrise, dar nu verifică dacă sunt puse în practică. Ce componentă a managementului curriculumului trebuie întărită?","options":["Arhivarea exclusivă a versiunilor inițiale ale documentelor.","Înlocuirea oricărei analize cu verificarea copertei dosarelor.","Monitorizarea implementării curriculumului în activitatea reală.","Multiplicarea planificărilor fără observarea activității reale."],"answer":2,"explanation":"Managementul curriculumului leagă organizarea implementării de monitorizarea procesului; calitatea documentelor nu dovedește singură aplicarea.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"CADRUL DE REFERINȚĂ AL CURRICULUMULUI NAȚIONAL Capitolul 10 – Managementul curriculumului la nivelul școlii Material integral pentru studiu și ascultare · 20 de itemi interactivi Material integral Ascultă materialul 20 de itemi 10. Managementul curriculumului la nivelul școlii Școala – cadru de aplicare contextualizată a Curriculumului Național. Școala asigură un context structurat pentru aplicarea planurilor-cadru de învățământ și a programelor școlare (directori de școală, comisii etc.). Managementul curriculumului implică organizarea implementării curriculumului și monitorizarea acestui proces, la nivelul","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L53","theme":"L","prompt":"Un minor apatrid, cu ședere oficial recunoscută în România, solicită acces la educație. Secretariatul cere obligatoriu cetățenie română. Ce prevede legea?","options":["Acces echitabil, fără discriminare, pentru această categorie.","Acces limitat exclusiv la unitățile particulare acreditate.","Acces permis numai după împlinirea vârstei de 18 ani.","Acces permis numai după obținerea cetățeniei române."],"answer":0,"explanation":"Articolul 9 include expres minorii apatrizi a căror ședere este oficial recunoscută conform legii. Cetățenia română nu este condiția generală invocată de secretariat.","source":{"title":"Legea nr. 198/2023","locator":"Art. 9","quote":"European și ai Confederației Elvețiene, minorilor, care solicită sau au dobândit o formă de protecție în România, minorilor străini și minorilor apatrizi a căror ședere pe teritoriul României este oficial recunoscută conform legii și cetățenilor din state din afara UE, aflați legal pe teritoriul României, precum și cetățenilor britanici și membrilor familiilor acestora, ca beneficiari ai Acordului privind retragerea Regatului Unit al Marii Britanii și Irlandei de Nord din Uniunea Europeană și din Comunitatea Europeană a Energiei Atomice 2019/C 384 I/01.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R53","theme":"R","prompt":"O grădiniță propune ca un copil să rămână zilnic unsprezece ore, cu acordul familiei. Ce limită a programului individual prevede ROFUIP?","options":["Programul zilnic al copilului nu are limită cu acordul familiei.","Programul zilnic al copilului nu poate depăși 10 ore.","Programul zilnic al copilului nu poate depăși 11 ore.","Programul zilnic al copilului nu poate depăși 12 ore."],"answer":1,"explanation":"ROFUIP limitează programul zilnic al copilului din educația timpurie la zece ore. Acordul familiei nu modifică limita prevăzută.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 10","quote":"normal și/sau cu program prelungit, cu respectarea prevederilor legale în vigoare În educația timpurie, programul zilnic al copilului nu poate depăși 10 ore zilnic. Pentru toate tipurile de program menționate la alin. (1), se aplică același curriculum aprobat prin ordin de ministru. Programul de funcționare al unității de educație timpurie, particularizat la nevoile beneficiarilor primari și/sau ale zonei în care se află unitatea, se stabilește pornind de la prevederile din Curriculumul pentru educație timpurie în vigoare și se aprobă prin hotărâre a consiliului de administrație, în baza rezultatului consultărilor părinților/reprezentanților legali ai copiilor. În perioada","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}}]},{"id":12,"title":"Simularea 12","items":[{"id":"H24","theme":"H","prompt":"Profesorul spune că are așteptări mari, dar nu oferă unui grup ocazii de a aborda sarcini provocatoare. Ce trebuie analizat?","options":["Concordanța dintre așteptările declarate și oportunitățile oferite elevilor.","Concordanța dintre culoarea materialelor și designul mobilierului școlar.","Exclusiv frecvența cu care repetă expresia „așteptări înalte”.","Exclusiv numărul de afișe motivaționale montate în sala de clasă."],"answer":0,"explanation":"Așteptările au relevanță prin felul în care influențează interacțiunile și oportunitățile reale de învățare, nu numai prin declarații.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 4, p. 231–233","quote":"class=\"chapter\"> SECȚIUNEA 04 Așteptările Pag. 231–233 Pagina 231 Vezi pagina originală ↗ Figura 9.1. Relația dintre anii de experiență și performanța elevilor la matematică ANI DE EXPERIENȚĂ. PERFORMANȚA ELEVILOR LA MATEMATICĂ (ABATERI STANDARD).","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s4","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=7"}},{"id":"L59","theme":"L","prompt":"Partenerii unui consorțiu de învățământ dual propun un acord de parteneriat pentru zece ani. Ce durată minimă impune articolul 22?","options":["Cel puțin cinci ani.","Cel puțin cincisprezece ani.","Cel puțin doisprezece ani.","Cel puțin zece ani."],"answer":1,"explanation":"Acordul prin care se înființează consorțiul de învățământ dual are o durată de cel puțin 15 ani. Nu se confundă cu durata altor contracte de pregătire.","source":{"title":"Legea nr. 198/2023","locator":"Art. 22 alin. (2)","quote":"susține un sistem extins de formare duală. (2) Între partenerii prevăzuți la alin. (1) se încheie un acord de parteneriat, cu o durată de cel puțin 15 ani, prin care se înființează consorțiul de învățământ dual cu denumire proprie, formă de asociere, fără scop patrimonial, în scopul dezvoltării învățământului profesional dual, într-un anumit domeniu de pregătire, pentru calificări cerute pe piața muncii. (3) Modul de funcționare și coordonare a activității consorțiilor, conducerea acestora și controlul modului de îndeplinire a obligațiilor asumate de parteneri vor fi reglementate prin ordin al ministrului educației. Notă A se vedea ORDINUL nr. 5.437 din 8 iulie 2024 pentru","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R59","theme":"R","prompt":"Inspectoratul propune modificarea unilaterală, prin simplă adresă, a contractului de management educațional al directorului. Ce mecanism prevede ROFUIP?","options":["Act adițional, cu acordul părților semnatare.","Dispoziție a furnizorului, fără document contractual.","Hotărâre a consiliului elevilor, fără acordul părților.","Notă informală, cu acordul exclusiv al contabilului."],"answer":0,"explanation":"Contractul de management educațional se poate modifica exclusiv prin act adițional, cu acordul părților semnatare, conform articolului 20 alineatul (4).","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 20 alin. (4)","quote":"de management educațional este aprobat prin ordin al ministrului educației. Contractul de management educațional poate fi modificat exclusiv prin act adițional, cu acordul părților semnatare. (5) Contractul de management educațional poate fi încheiat numai după prezentarea unei evaluări medicale care atestă faptul că persoana este aptă pentru funcția vizată. (6) Pentru asigurarea finanțării de bază, a finanțării complementare și a finanțării suplimentare, după promovarea concursului, directorul încheie contract de management administrativ-financiar cu primarul unității administrativ-teritoriale în a cărei rază teritorială se află unitatea de învățământ, respectiv cu președintele","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B47","theme":"B","prompt":"Directorul lansează sloganuri despre transformare, dar nu discută lipsa resurselor și dificultățile profesorilor. Ce verificare este necesară?","options":["Absența oricărei discuții despre condițiile de implementare.","Legătura dintre viziunea proclamată și realitățile instituției.","Numai frecvența apariției sloganului pe materialele promoționale.","Numai numărul metaforelor din discursurile de început de an."],"answer":1,"explanation":"Retorica vizionară poate masca realitățile organizației. Viziunea trebuie evaluată în raport cu situația concretă, nu doar cu forța discursului.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 20","quote":"fiecare aspect din raportul OFSTED pentru şcoala lor. Hoyle şi Wallace (2005: 11) critică importanţa accentuată care se acordă viziunii. „Retorica vizionară este o formă a discursului managerial foarte răspândită în şcoli odată cu reformele din educaţie.” Autorii pun în contrast „retorica vizionară” cu „realitatea prozaică” trăită de personalul din şcoli, de elevi şi de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"P24","theme":"P","prompt":"Sub presiunea obținerii unui rezultat rapid, directorul își verifică alegerea față de principiile asumate și explică de ce nu renunță la valorile profesionale. Ce competență este ilustrată?","options":["Aderarea la principii și valori","Cercetare, inovație pedagogică și conceptualizare strategică","Conformitate juridică și etică profesională","Responsabilitate publică și relaționare instituțională"],"answer":0,"explanation":"Raportarea consecventă a deciziilor și comportamentelor la principii și valori este elementul central, distinct de simpla enumerare a unor reguli.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"1.4. Aderarea la principii și valori","quote":"Acționează ca model de integritate profesională, prevenind corupția, favoritismul și abuzul și asigurând alinierea organizației la valorile etice asumate. se comportă aliniat cu valorile instituționale și etica profesională, constituind un model pentru întreaga comunitate școlară; actualizează și comunică explicit viziunea și misiunea instituțională, monitorizând respectarea lor; ia decizii responsabile și argumentate, pe baza consultării comunității școlare; aplică codul de etică și gestionează cu profesionalism procedurile disciplinare — elevi și cadre didactice; ia măsuri concrete pentru prevenirea abuzurilor, favoritismului și conflictelor de interese; demonstrează imparțialitate și transparență în toate relațiile instituționale; argumentează deciziile pe baza interesului superior al copilului și le comunică în mod transparent.","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"L60","theme":"L","prompt":"O școală dorește să declare o metodă proprie drept alternativă educațională aprobată, numai prin hotărârea CA. Cine aprobă alternativele educaționale?","options":["Consiliul local, prin hotărâre.","Consiliul profesoral, prin vot.","Directorul școlii, prin decizie.","Ministrul educației, prin ordin."],"answer":3,"explanation":"Alternativele educaționale sunt aprobate prin ordin al ministrului, la propunerea direcțiilor de specialitate. Alegerea unei metode la clasă nu reprezintă această aprobare.","source":{"title":"Legea nr. 198/2023","locator":"Art. 26 alin. (2)","quote":"nr. 981 din 1 octombrie 2024 privind aprobarea Regulamentului de organizare și funcționare a învățământului preuniversitar alternativ. (2) Aprobarea alternativelor educaționale se face prin ordin al ministrului educației, la propunerea direcțiilor de specialitate din minister. (3) Autorizarea de funcționare provizorie, acreditarea, precum și evaluarea periodică a alternativelor educaționale se fac potrivit normelor metodologice aprobate prin ordin al ministrului educației, la propunerea ARACIIP. (4) Unitățile de învățământ preuniversitar alternativ dispun de autonomie organizatorică și funcțională, în conformitate cu specificul alternativei. (5) Personalul didactic de predare","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R60","theme":"R","prompt":"Directorul unei școli de stat fără adjunct pleacă în concediu și lasă atribuțiile verbal unui profesor suplinitor. Ce soluție prevede ROFUIP?","options":["Delegare automată către furnizorul serviciilor contabile.","Delegare prin decizie către alt cadru didactic titular.","Delegare prin mesaj către orice părinte din consiliul clasei.","Delegare verbală către orice salariat disponibil în școală."],"answer":1,"explanation":"În lipsa adjunctului, atribuțiile se deleagă prin decizie altui cadru didactic titular, de regulă membru al CA. O însărcinare verbală nu îndeplinește cerința.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 21 alin. (7)","quote":"în care directorul nu își poate exercita atribuțiile (concediu de odihnă, delegații și altele asemenea), acesta are obligația de a delega, prin decizie, atribuțiile către directorul adjunct sau, în cazul în care nu există funcția de director adjunct, către un alt cadru didactic titular, de regulă membru al consiliului de administrație. (8) Pentru situațiile excepționale (accident, boală și altele asemenea) în care directorul nu poate delega atribuțiile, acesta emite la începutul anului școlar decizia de delegare a atribuțiilor către directorul adjunct sau, în cazul în care nu există funcția de director adjunct, către un cadru didactic membru al consiliului de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B48","theme":"B","prompt":"O echipă are o direcție educațională nouă, dar proiectul eșuează din cauza orarului și a resurselor neorganizate. Ce relație conceptuală ilustrează cazul?","options":["Complementaritatea leadershipului și a managementului.","Independența schimbării educaționale față de administrarea resurselor.","Inutilitatea organizării atunci când viziunea este bine formulată.","Înlocuirea leadershipului prin simpla existență a unei organigrame."],"answer":0,"explanation":"Direcția și influența au nevoie de organizare și de menținerea funcționării. Leadershipul și managementul se completează.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 21","quote":"serviciilor publice. Cuban (1988) oferă una dintre cele mai clare distincţii, asociind leadershipul cu schimbarea şi managementul cu „menţinerea”. De asemenea, autorul punctează importanţa ambelor dimensiuni ale activităţii organizaţionale: Prin leadership mă refer la influenţarea acţiunilor altora pentru a obţine rezultate dezirabile. Liderii sunt acei oameni","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"C24","theme":"C","prompt":"Profesorii vor să conecteze învățarea dintre discipline, dar fiecare proiectează izolat. Ce condiție organizațională ar trebui creată?","options":["Evaluarea colaborării exclusiv după numărul de mesaje administrative.","Interdicția de a discuta resurse și activități între comisiile metodice.","Obligația de a păstra fiecare disciplină fără niciun dialog profesional.","Timp și oportunități pentru colaborarea în proiectarea curriculară."],"answer":3,"explanation":"Abordarea integrată are nevoie de colaborare profesională. Conducerea poate susține cadrul și timpul necesare acesteia.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"O atenție specială este solicitată de abordarea integrată a curriculumului, care oferă posibilitatea proiectării didactice și predării în colaborare și/ sau în echipă. Acest aspect are implicații asupra redefinirii și constituirii normelor didactice. De asemenea, profesorul are libertatea și responsabilitatea de a aplica la clasă CN, în așa fel încât să optimizeze învățarea pentru fiecare elev și să asigure progresul individual în dezvoltarea competențelor. De exemplu, în planificarea calendaristică, în proiectarea unităților de învățare și a lecției/ activității de învățare, profesorul este autonom să se orienteze în funcție de ritmurile de învățare ale elevilor, de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L56","theme":"L","prompt":"Un solicitant la nivel gimnazial a depășit cu exact patru ani vârsta clasei. Școala consideră îndeplinit pragul de vârstă pentru frecvență redusă. Cum se citește condiția legală?","options":["Depășirea trebuie să fie de cel puțin patru ani.","Depășirea trebuie să fie de cel puțin trei ani.","Depășirea trebuie să fie de mai mult de patru ani.","Depășirea trebuie să fie de mai mult de trei ani."],"answer":2,"explanation":"La gimnaziu, textul cere depășirea cu mai mult de patru ani. Exact patru ani nu îndeplinesc acest criteriu; organizarea urmează metodologia aplicabilă.","source":{"title":"Legea nr. 198/2023","locator":"Art. 17 alin. (2)","quote":"obligatoriu este învățământ cu frecvență. Pentru persoanele care au depășit cu mai mult de 3 ani vârsta clasei în învățământul primar, cu mai mult de 4 ani vârsta clasei în învățământul gimnazial, respectiv cu mai mult de 5 ani vârsta clasei în învățământul liceal, învățământul obligatoriu se poate organiza și în forma de învățământ cu frecvență redusă, în conformitate cu prevederile metodologiei aprobate prin ordin al ministrului educației sau prin programul „A doua șansă“. Notă A se vedea ORDINUL nr. 7.822 din 18 decembrie 2024 pentru aprobarea Metodologiei privind organizarea și funcționarea învățământului obligatoriu la forma de învățământ cu frecvență redusă publicat în","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R56","theme":"R","prompt":"La trecerea într-un nou nivel, școala repartizează elevii fără să țină seama de limbile moderne deja studiate. Ce regulă trebuie urmărită, de regulă?","options":["Alegerea limbilor exclusiv în ordinea alfabetică a profesorilor.","Continuitatea studiului limbilor moderne, ținând cont de ofertă.","Renunțarea la orice limbă modernă începută în ciclul anterior.","Schimbarea anuală a ambelor limbi moderne, indiferent de ofertă."],"answer":1,"explanation":"ROFUIP cere, de regulă, continuitate. Dacă formațiunile nu pot asigura aceasta, conducerea organizează un interval care permite asocierea elevilor pentru studiu.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 15","quote":"La înscrierea în învățământul gimnazial, liceal, profesional, inclusiv dual, se asigură, de regulă, continuitatea studiului limbilor moderne, ținând cont de oferta educațională a unității de învățământ. Conducerea unității de învățământ constituie, de regulă, formațiunile de studiu astfel încât elevii să studieze aceleași limbi străine. În unitățile de învățământ în care constituirea formațiunilor de studiu nu se poate face cu respectarea prevederilor alin. (2), conducerile unităților de învățământ asigură în program un interval orar care să permită asocierea beneficiarilor primari pentru studiul limbilor moderne. În situații temeinic motivate, la solicitarea","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B45","theme":"B","prompt":"Două soluții au costuri apropiate. Directorul o alege pe cea compatibilă cu echitatea și explică valorile care îl ghidează. Ce dimensiune devine vizibilă?","options":["Dimensiunea valorică a leadershipului.","Eliminarea valorilor din decizia managerială.","Independența deciziei față de orice convingere.","Substituirea scopurilor prin rutine administrative."],"answer":0,"explanation":"Valorile personale și profesionale influențează leadershipul. Explicitarea lor ajută la înțelegerea fundamentului deciziei.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 18","quote":"vedere. Cu toate acestea, leadershipul este asociat tot mai mult cu valorile. Aşteptările sunt ca liderii să‑şi fundamenteze acţiunile pe valori personale şi profesionale clare. Greenfield şi Ribbins (1993) susţin că leadershipul începe cu „caracterul” liderilor, exprimat în termeni de valori personale, conştiinţă de sine, precum şi în capacitate","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H23","theme":"H","prompt":"La recrutare, candidatul cel mai fluent este declarat automat cel mai bun profesor, fără analizarea modului în care ajută elevii. Ce confuzie trebuie evitată?","options":["Confundarea abilității verbale cu eficiența didactică garantată.","Confundarea studiilor absolvite cu denumirea postului scos la concurs.","Confundarea unei probe practice cu lista de prezență a candidaților.","Confundarea vechimii în instituție cu existența unui contract de muncă."],"answer":0,"explanation":"Fluența verbală singură nu dovedește efectul asupra învățării. Ea trebuie raportată la practici și rezultate, fără garanții individuale nejustificate.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 3, p. 230–230","quote":"puternică pe cât au pretins mulți și, într-adevăr, slăbește odată cu experiența la clasă. Au concluzionat că „a avea profesori doar cu o bună abilitate verbală probabil că nu va schimba semnificativ lucrurile în clasele noastre” (p. 620; observați cuvântul „doar”). Este posibil ca o competență academică sau intelectuală generalizată să fie un factor esențial în primii ani,","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s3","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=6"}},{"id":"L57","theme":"L","prompt":"O persoană juridică dorește să înființeze o școală și solicită să sară direct la acreditare. Care succesiune este prevăzută de lege?","options":["Acreditarea definitivă, apoi autorizarea de funcționare provizorie.","Aprobarea de către părinți, apoi acreditarea automată.","Autorizarea de funcționare provizorie, apoi acreditarea.","Înscrierea absolvenților la examen, apoi autorizarea provizorie."],"answer":2,"explanation":"Procesul de înființare cuprinde autorizarea de funcționare provizorie, urmată de procedura de acreditare pentru unitatea care îndeplinește condițiile.","source":{"title":"Legea nr. 198/2023","locator":"Art. 19 alin. (2)","quote":"Excelență, denumite în continuare centre de excelență. (2) Procesul de înființare a unei unități de învățământ preuniversitar cuprinde două etape, care se desfășoară astfel: a) orice persoană juridică de drept public sau privat, interesată în furnizarea de educație, se supune procesului de evaluare și parcurge procedura de autorizare de funcționare provizorie, potrivit dispozițiilor art. 237-239; b) unitatea autorizată să funcționeze provizoriu care îndeplinește condițiile parcurge procedura de acreditare prevăzută la art. 240-245. (3) Ordinele ministrului educației emise în urma finalizării procesului de autorizare provizorie/acreditare se comunică, în termen de 5","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R57","theme":"R","prompt":"O școală de stat este chemată în judecată. Directorul spune că apărarea instituției este opțională dacă litigiul pare neimportant. Ce obligație are?","options":["Să asigure apărarea numai după finalizarea procesului.","Să asigure dreptul la apărare și reprezentarea unității.","Să asigure reprezentarea numai dacă părinții solicită acest lucru.","Să transfere automat reprezentarea către consiliul elevilor."],"answer":1,"explanation":"Directorul, reprezentant legal, are obligația de a asigura apărarea și reprezentarea școlii în toate litigiile în care aceasta este implicată.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 17 alin. (1)","quote":"implicată unitatea de învățământ de stat, directorul, în calitate de reprezentant legal, este obligat să asigure dreptul la apărare și reprezentarea unității în fața instanțelor de judecată sau a altor organe de specialitate. (2) La solicitarea scrisă a directorului, inspectoratele școlare asigură, prin consilierul juridic, consultanță de specialitate pentru unitățile de învățământ de stat. Aceasta constă în analiza documentelor, explicarea legislației și a procedurilor, evaluarea riscurilor și oferirea de soluții punctuale, precum și îndrumare în redactarea cererilor, notificărilor, întâmpinărilor sau a altor documente cu specific juridic. (3) Nerespectarea obligațiilor","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"P23","theme":"P","prompt":"Mai mulți elevi și profesori spun că se simt nesiguri în școală. Directorul pune siguranța, respectul și starea de bine în centrul acțiunii instituționale. Ce competență corespunde cel mai direct?","options":["Asigurarea succesului școlar al elevilor și a performanței cadrelor didactice","Colectarea datelor, analiza și formularea de strategii de îmbunătățire a calității","Leadership incluziv, stare de bine a elevilor și a personalului școlii, securitate și siguranță școlară","Managementul incluziunii și al diversității în profilurile de învățare"],"answer":2,"explanation":"Cazul combină explicit incluziunea, starea de bine și securitatea comunității școlare, reunite în competența 1.3.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"1.3. Leadership incluziv, stare de bine a elevilor și a personalului școlii, securitate și siguranță școlară","quote":"creează și întreține un climat în care elevii se simt protejați, respectați și valorizați; implementează și monitorizează protocoalele de siguranță fizică — PSI, SSM, proceduri de urgență; asigură funcționarea mecanismelor antihărțuire și antibullying și intervine prompt în situații de criză; promovează măsuri de protecție a copilului — prevenirea abuzului, neglijării, violenței; monitorizează indicatori ai climatului școlar — siguranță, incluziune, stare de bine — și acționează pe baza lor; sprijină personalul și elevii în perioade de stres și situații dificile; inspiră încredere și gestionează echipe diverse printr-un stil de conducere empatic și participativ.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"C23","theme":"C","prompt":"Două clase au ritmuri diferite de învățare. Profesorul justifică adaptarea planificării în raport cu programa și nevoile fiecăreia. Ce abordare susține CRCNR?","options":["Copierea identică a fiecărei lecții, indiferent de contextul clasei.","Eliminarea evaluării pentru a evita orice diferență între clase.","Exercitarea autonomiei de proiectare în raport cu situația elevilor.","Înlocuirea programei cu preferințele comerciale ale unui furnizor."],"answer":2,"explanation":"Autonomia didactică permite decizii de proiectare adaptate contextului, în cadrul reperelor curriculare, fără a însemna abandonarea acestora.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"De exemplu, în planificarea calendaristică, în proiectarea unităților de învățare și a lecției/ activității de învățare, profesorul este autonom să se orienteze în funcție de ritmurile de învățare ale elevilor, de nivelurile lor de performanță și de potențialul lor de învățare. Schemele de mai jos ilustrează demersul logic secvențial al planificării și proiectării activității didactice la clasă (planificarea calendaristică, proiectarea unității de învățare, proiectarea lecției/ activității de învățare). Toate aceste componente ale proiectării sunt interdependente și trebuie privite global, ca un sistem unitar. Demersuri orientative de planificare și de proiectare","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L58","theme":"L","prompt":"Un adult eligibil pentru „A doua șansă” este respins deoarece nu a fost niciodată înscris la școală. Ce precizează articolul 20?","options":["Programul include exclusiv persoane care au abandonat aceeași școală.","Programul include exclusiv persoane care au absolvit ciclul primar.","Programul include exclusiv persoane care au fost înscrise anul trecut.","Programul poate include și persoane care nu au fost înscrise anterior."],"answer":3,"explanation":"Înscrierea nu este condiționată de existența unei școlarizări anterioare. Trebuie respectate criteriile de vârstă și metodologia programului, care este gratuit și cu durată flexibilă.","source":{"title":"Legea nr. 198/2023","locator":"Art. 20 alin. (1)","quote":"gimnazial și liceal, pentru persoanele care au depășit vârsta corespunzătoare clasei potrivit dispozițiilor art. 17 alin. (2), indiferent dacă persoana respectivă a mai fost sau nu înscrisă în sistemul de învățământ preuniversitar sau de momentul și motivele abandonului școlar. Înscrierea în program se face prin intermediul unei solicitări transmise online sau prin depunerea acesteia la sediul unității de învățământ din localitatea de domiciliu a solicitantului sau la cea mai apropiată unitate de învățământ. (2) Programele educaționale „A doua șansă“ se organizează de unități de învățământ acreditate/ autorizate sau de alte entități în parteneriat cu o unitate de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R58","theme":"R","prompt":"CA discută evaluarea activității directorului, care este și președinte al CA. Acesta dorește să conducă ședința. Ce regulă specială se aplică?","options":["Ședința este condusă de alt membru al CA, ales prin vot.","Ședința este condusă exclusiv de primarul localității.","Ședința este condusă obligatoriu de secretarul unității.","Ședința este condusă obligatoriu tot de directorul evaluat."],"answer":0,"explanation":"Dacă tematica vizează activitatea sau eliberarea din funcție a directorului-președinte, alt membru al CA ales prin vot conduce ședința.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 18 alin. (5)","quote":"din funcție a directorului numit în urma concursului național, iar directorul este președinte, de drept sau ales, ședința este condusă de un alt membru al consiliului de administrație ales prin votul membrilor. (6) Incompatibilitățile privind calitatea de membru al consiliului de administrație sunt cele prevăzute în Legea învățământului preuniversitar nr. 198/2023, cu modificările și completările ulterioare și în Metodologia-cadru de organizare și funcționare a consiliilor de administrație din unitățile de învățământ preuniversitar, aprobată prin ordin al ministrului educației. (7) Ședințele consiliului de administrație se pot desfășura fizic, on-line sau hibrid, conform","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B46","theme":"B","prompt":"Un proiect reușește numai când directorul este prezent. Echipa nu are capacitatea de a-l continua singură. Ce prioritate ar reduce vulnerabilitatea?","options":["Concentrarea tuturor informațiilor și relațiilor exclusiv la director.","Dezvoltarea capacității organizației de a continua după schimbarea liderului.","Înlocuirea competențelor echipei cu dependența de intervenții personale.","Legarea fiecărei activități de aprobarea informală a aceluiași lider."],"answer":1,"explanation":"Dependența de o singură persoană amenință continuitatea. Susținerea capacității colective răspunde problemei plecării liderului.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 19","quote":"ani, poate (...) fi un model fals şi amăgitor (...) ipoteza mea este că cele mai multe dintre aceste şcoli intră în declin odată cu plecarea liderului (...). Directorii sunt orbiţi de propria viziune atunci când","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}}]},{"id":13,"title":"Simularea 13","items":[{"id":"L64","theme":"L","prompt":"Pentru un copil care împlinește șase ani până la 31 august, familia cere justificat amânarea înscrierii în pregătitoare cu doi ani. Ce limită stabilește legea?","options":["Amânarea poate fi de maximum doi ani.","Amânarea poate fi de maximum trei ani.","Amânarea poate fi de maximum un an.","Amânarea poate fi fără limită de timp."],"answer":2,"explanation":"În cazuri justificate și la cererea scrisă a părintelui, amânarea prevăzută la articolul 31 alineatul (5) este de maximum un an.","source":{"title":"Legea nr. 198/2023","locator":"Art. 31 alin. (5)","quote":"pregătitoare a copiilor care împlinesc vârsta de 6 ani până la data de 31 august a anului în care se face înscrierea poate fi amânată cu maximum un an. (6) La solicitarea scrisă a părinților/reprezentanților legali pot fi înscriși în învățământul de masă în clasa pregătitoare și copiii cu CES cu vârste cuprinse între 6 și 8 ani până la data de 31 august a anului în care se face înscrierea. (7) La solicitarea scrisă a părinților/reprezentanților legali, pot fi înscriși în învățământul special în clasa pregătitoare copiii cu CES, cu vârste cuprinse între 6 și 8 ani împliniți până la data de 31 decembrie a anului în care se face înscrierea. (la 29-06-2024, Alineatul (7),","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R64","theme":"R","prompt":"Școala programează aprobarea raportului anual asupra calității educației abia după trei luni de la începutul anului școlar. Care este termenul prevăzut?","options":["Primele douăsprezece săptămâni de la începutul anului școlar.","Primele opt săptămâni de la începutul anului școlar.","Primele patru săptămâni de la începutul anului școlar.","Ultimele patru săptămâni de la sfârșitul anului școlar."],"answer":2,"explanation":"Analiza, dezbaterea și validarea în CP, urmate de aprobarea în CA la propunerea directorului, sunt prevăzute în primele patru săptămâni.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 30 alin. (2)","quote":"se dezbate și se validează de către consiliul profesoral și se aprobă de către consiliul de administrație, la propunerea directorului, în primele patru săptămâni de la începutul anului școlar. (3) Raportul se prezintă de către director în fața consiliului profesoral, a consiliului școlar al beneficiarilor primari, a consiliului reprezentativ al părinților/reprezentanților legali și a conducerii asociației de părinți, acolo unde există.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B51","theme":"B","prompt":"O firmă propune școlii propriul model de conducere. Directorul analizează dacă acesta se potrivește misiunii și contextului educațional înainte să îl adopte. Ce atitudine este justificată?","options":["Acceptarea automată a oricărui model utilizat în economie.","Considerarea școlii ca având un singur scop comercial.","Evaluarea critică a viabilității transferului de modele.","Respingerea tuturor ideilor care provin din alte sectoare."],"answer":2,"explanation":"Modelele din alte sectoare pot fi utile, dar transferul necesită evaluarea viabilității în contextul și scopurile educației.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 29","quote":"Teoriile clasice ale managementului nu pot fi transpuse în mediul organizaţiilor cu profil educaţional fără o analiză prealabilă a viabilităţii lor în contextul unic al acestora (...). Prin urmare, trebuie să fim atenţi atunci când vrem să gestionăm sau să ameliorăm (...) domeniul educaţiei cu tehnici de „management modern” împrumutate din domeniul afacerilor,","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"P26","theme":"P","prompt":"O avarie ar putea bloca activitatea. Conducerea evaluează vulnerabilitățile, pregătește continuitatea și organizează reacția la situații neprevăzute. Ce competență este dominantă?","options":["Conformitate juridică și etică profesională","Identitate digitală, inovare și eficiență managerială","Prezentarea și comunicarea informațiilor","Reziliență și managementul riscului"],"answer":3,"explanation":"Identificarea riscurilor, pregătirea reacției și menținerea capacității de funcționare aparțin rezilienței și managementului riscului.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"2.2. Reziliență și managementul riscului","quote":"Identifică și evaluează riscurile organizaționale, elaborează planuri de continuitate și intervenție și sprijină reziliența comunității școlare în situații de criză. identifică și evaluează sistematic riscurile organizaționale — financiare, juridice, operaționale, de securitate; elaborează planuri de continuitate și intervenție pentru situații de criză, actualizate periodic; instituie mecanisme de control intern și de prevenire a riscurilor; comunică rapid și clar în situații critice, menținând funcționarea instituției; evaluează impactul crizelor asupra comunității școlare și ia măsuri de remediere; revizuiește procedurile pe baza lecțiilor învățate din situațiile de criză anterioare; manifestă inițiativă și spirit antreprenorial pentru a răspunde agil provocărilor.","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"L65","theme":"L","prompt":"Un gimnaziu fără clase primare își creează singur regulile de înscriere în clasa a V-a. Ce referință normativă trebuie să respecte?","options":["Metodologia aprobată prin ordin al ministrului educației.","Procedura aleasă exclusiv de comitetul de părinți.","Procedura stabilită exclusiv de furnizorul catalogului electronic.","Regula votată exclusiv de elevii claselor terminale."],"answer":0,"explanation":"Înscrierea în clasa a V-a în unitățile fără nivel primar urmează metodologia aprobată prin ordin al ministrului. Autonomia nu permite înlocuirea acesteia.","source":{"title":"Legea nr. 198/2023","locator":"Art. 32 alin. (4)","quote":"și funcționează cu program de dimineață, începând cu anul 2030. (4) Înscrierea elevilor în clasa a V-a la unitățile de învățământ care nu dețin clase de nivel primar se realizează în conformitate cu prevederile metodologiei aprobate prin ordin al ministrului educației. Secţiunea a 4-a Învățământul liceal","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R65","theme":"R","prompt":"PDI și planul managerial sunt finalizate, dar conducerea refuză comunicarea lor către reprezentanții părinților. Ce obligație prevede ROFUIP?","options":["Arhivarea exclusivă la contabilitate, fără comunicare către structurile părinților.","Publicarea exclusivă a titlurilor, fără comunicarea documentelor de prognoză.","Publicarea pe site și transmiterea electronică către structurile părinților indicate.","Transmiterea exclusivă către furnizorii care au contracte comerciale active."],"answer":2,"explanation":"Documentele de prognoză sunt de interes public: se publică pe site și se transmit electronic consiliului reprezentativ al părinților și conducerii asociației, unde există.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 33 alin. (3)","quote":"în scopul optimizării managementului unității de învățământ. (3) Documentele de prognoză se postează pe site-ul unității de învățământ și se transmit, în format electronic, consiliului reprezentativ al părinților/reprezentanților legali și conducerii asociației de părinți, acolo unde există, fiind documente care conțin informații de interes public.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B52","theme":"B","prompt":"Conducerea dedică ședințele exclusiv logisticii. Datele despre învățare nu sunt discutate niciodată. Ce ar introduce leadershipul instruirii?","options":["Atenție exclusivă pentru evidența mobilierului.","Atenție exclusivă pentru imaginea din presă.","Atenție exclusivă pentru ordinea documentelor.","Atenție explicită pentru predare și învățare."],"answer":3,"explanation":"Leadershipul instruirii pune în centru predarea și învățarea, inclusiv sprijinul pentru dezvoltarea practicilor profesorilor.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 30","quote":"dezvoltarea elevilor”. Definiţia lui Bush şi Glover punctează direcţia procesului de influenţare: Leadershipul instruirii este centrat pe predare şi învăţare, precum şi pe comportamentul profesorilor în lucrul cu elevii. Influenţa liderilor ţinteşte spre favorizarea învăţării cu ajutorul profesorului. Accentul cade pe direcţia şi impactul influenţei şi mai puţin pe procesul","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"C26","theme":"C","prompt":"Profesorul începe proiectarea prin stabilirea achizițiilor și competențelor pe care elevii trebuie să le dezvolte. Ce decizie clarifică astfel?","options":["Finalitatea demersului de învățare.","Inventarul mobilierului din sală.","Ordinea alfabetică a numelor elevilor.","Sursa comercială a consumabilelor."],"answer":0,"explanation":"Întrebarea „De ce voi face?” orientează proiectarea spre competențe și finalități. Alegerea mijloacelor trebuie să servească aceste achiziții.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"lecțiilor/ activităților de învățare Întrebări pe care și le pune profesorul în procesul de planificare și de proiectare didactică De ce voi face? Ce voi valorifica? Cu ce voi face? Cum voi face? Cât și cât de bine am realizat? Reflecția asupra relațiilor de derivare dintre competențele specifice, generale, competențele-cheie și atributele prioritare Selectarea conținuturilor învățării, prin raportare la competențele vizate și la standardele de învățare Analiza resurselor curriculare de suport, a celor de timp Stabilirea succesiunii lecțiilor, proiectarea lecțiilor/ activităților de învățare Conceperea modalităților și instrumentelor de evaluare Raportarea la","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L61","theme":"L","prompt":"Un fondator susține că o școală particulară poate fi evaluată după standarde de calitate inferioare celor pentru stat. Ce relație stabilește legea?","options":["Criteriile sunt identice numai pentru personalul administrativ.","Criteriile, standardele și indicatorii sunt facultativi.","Criteriile, standardele și indicatorii sunt identici.","Standardele sunt stabilite exclusiv de fiecare finanțator."],"answer":2,"explanation":"Articolul 27 impune aceleași criterii, standarde de calitate și indicatori de performanță pentru învățământul particular/confesional și pentru cel de stat.","source":{"title":"Legea nr. 198/2023","locator":"Art. 27 alin. (2)","quote":"și indicatorii de performanță pe care trebuie să le îndeplinească unitățile de învățământ preuniversitar particular și confesional sunt identice cu cele pe care trebuie să le îndeplinească unitățile de învățământ de stat. (3) Unitățile de învățământ particular și confesional sunt unități libere, deschise, autonome atât din punct de vedere organizatoric, cât și economico-financiar, având drept fundament proprietatea privată, garantată de Constituția României, republicată, și dobândesc personalitate juridică de la data autorizării de funcționare provizorie. (4) Autorizarea de funcționare provizorie, acreditarea și evaluarea periodică a unităților de învățământ","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R61","theme":"R","prompt":"O urgență instituțională impune rechemarea directorului din concediu. Cine dispune rechemarea, în condițiile legii?","options":["Administratorul de patrimoniu, prin notă.","Inspectorul școlar general, prin decizie.","Președintele comitetului de părinți, prin cerere.","Secretarul consiliului clasei, prin convocator."],"answer":1,"explanation":"Rechemarea pentru forță majoră sau interese urgente este dispusă prin decizia inspectorului școlar general, cu respectarea obligațiilor legale ale angajatorului.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 23 alin. (3)","quote":"școlar general. (3) Rechemarea din concediul de odihnă a directorilor din unitățile de învățământ preuniversitar se face în caz de forță majoră sau pentru interese urgente care impun prezența acestora la locul de muncă, cu respectarea obligațiilor legale de către angajator, și se dispune prin decizie a inspectorului școlar general.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B49","theme":"B","prompt":"Autoritatea centrală permite școlii să decidă cum utilizează o parte din resurse. La ce nivel se deplasează decizia în procesul descris de Bush?","options":["Spre eliminarea responsabilității conducerii.","Spre exclusivitatea organismelor centrale.","Spre furnizorul comercial al manualelor.","Spre nivelul instituțional al școlii."],"answer":3,"explanation":"Autonomia deplasează o parte din autoritatea decizională către nivelul instituției. Nu înseamnă eliminarea răspunderii sau a cadrului general.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 25","quote":"locale. Sistemele descentralizate, pe de altă parte, acordă mai multă putere nivelurilor subordonate. Acolo unde puterea este atribuită nivelului instituţional putem vorbi despre „management autonom”. Lauglo (1997) leagă centralizarea de birocraţie, definind‑o în felul următor: Centralismul birocratic presupune concentrarea luării deciziilor asupra unei game de probleme la","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H25","theme":"H","prompt":"După un rezultat inițial slab, profesorul interpretează orice eroare nouă ca dovadă că elevul „nu poate”. Ce acțiune ar reduce efectul etichetării?","options":["Excluderea elevului din orice activitate care cere efort cognitiv.","Menținerea aceleiași etichete indiferent de rezultatele viitoare.","Reexaminarea judecății prin dovezi actuale despre progres.","Renunțarea la sarcini care ar putea contrazice prima impresie."],"answer":2,"explanation":"Etichetele pot fixa percepții și așteptări. Datele actuale și progresul trebuie să poată modifica judecata inițială.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 5, p. 234–236","quote":"(d = 0,48). Indiferent de sexul, rasa sau performanța trecută a elevilor, așa au stat lucrurile. Neetichetarea elevilor Profesori care nu etichetează elevii Ne pricepem foarte bine să inventăm etichete și să repartizăm elevii în grupuri — adesea, grupările acestea sunt urmate de o finanțare. Problema este că etichetarea grupului poate duce la așteptări scăzute","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s5","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=10"}},{"id":"L62","theme":"L","prompt":"Un angajator consideră că diploma unei școli particulare acreditate are doar valoarea unei adeverințe interne. Ce efect juridic prevede legea?","options":["Are efecte numai dacă angajatorul a finanțat școala respectivă.","Are efecte numai după repetarea studiilor într-o școală de stat.","Are valoare numai în relația contractuală cu fondatorul școlii.","Are valoarea și efectele actelor de studii din învățământul de stat."],"answer":3,"explanation":"Diplomele și certificatele din învățământul particular acreditat produc efectele actelor de studii eliberate în învățământul de stat.","source":{"title":"Legea nr. 198/2023","locator":"Art. 28 alin. (4)","quote":"beneficiază de manuale școlare, conform legii. (4) Diplomele și certificatele acordate în învățământul particular acreditat au valoarea și produc efectele actelor de studii eliberate în învățământul de stat. Secţiunea a 7-a Educație extrașcolară","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R62","theme":"R","prompt":"Echipa de conducere dorește stocarea digitală a documentelor manageriale și validarea lor electronică. Se afirmă că ROFUIP permite numai semnătura olografă. Ce prevede textul?","options":["Validarea documentelor digitale este interzisă în toate cazurile.","Validarea documentelor digitale este rezervată exclusiv părinților.","Validarea documentelor se face exclusiv prin semnătură olografă.","Validarea documentelor se poate face și prin semnătură electronică."],"answer":3,"explanation":"În funcție de resurse, documentele pot fi stocate digital, iar validarea lor se poate face și prin semnătură electronică, cu respectarea cadrului legal.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 28 alin. (2)","quote":"constituite la nivelul unității de învățământ vor fi stocate în format digital. Validarea acestor documente se poate face și prin semnătură electronică.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"P25","theme":"P","prompt":"Înainte de aplicarea unei proceduri, directorul examinează legalitatea și implicațiile etice și corectează practicile neconforme. Ce competență specifică este cea mai apropiată?","options":["Conformitate juridică și etică profesională","Identitate digitală, inovare și eficiență managerială","Prezentarea și comunicarea informațiilor","Reziliență și managementul riscului"],"answer":0,"explanation":"Conformitatea juridică și etica profesională privesc fundamentarea și exercitarea responsabilă a deciziei în cadrul legal și deontologic.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"2.1. Conformitate juridică și etică profesională","quote":"coordonează managementul operațional — orare, regulamente, resurse; coordonează managementul financiar: elaborarea bugetului, execuția bugetară și relația cu autoritatea locală; identifică, organizează și asigură disponibilitatea resurselor aliniate cu obiectivele de performanță; aplică consecvent normele legale și procedurale în toate deciziile administrative; documentează și arhivează deciziile financiare și administrative; asigură respectarea procedurilor de achiziții publice; evită prompt și transparent conflictele de interese; gestionează eficient resursele materiale și financiare ale unității.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"C25","theme":"C","prompt":"Un profesor tratează programa ca pe o listă de titluri de copiat. Ce ar presupune lectura ei personalizată?","options":["Alegerea activităților fără raportare la achizițiile urmărite prin programă.","Copierea exclusivă a titlurilor din cuprinsul unui manual comercial.","Corelarea competențelor, conținuturilor și sugestiilor cu situația clasei.","Înlocuirea competențelor cu ordinea preferată de furnizorul auxiliarului."],"answer":2,"explanation":"Lectura personalizată presupune înțelegerea și corelarea componentelor programei, în vederea proiectării pentru contextul concret.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"Demersuri orientative de planificare și de proiectare didactică la nivel microeducațional De la CRCNR la învățarea în clasă Lectura CRCNR Lectura personalizată a programei școlare Planificarea calendaristică (stabilirea succesiunii unităților de învățare/ relațiilor dintre acestea) Proiectarea unităților de învățare Proiectarea lecțiilor/ activităților de învățare Întrebări pe care și le pune profesorul în procesul de planificare și de proiectare didactică De ce voi face? Ce voi valorifica? Cu ce voi face? Cum voi face? Cât și cât de bine am realizat? Reflecția asupra relațiilor de derivare dintre competențele specifice, generale, competențele-cheie și atributele prioritare","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L63","theme":"L","prompt":"Într-o localitate, cererea pentru educație timpurie depășește locurile disponibile. Se analizează organizarea unei ludoteci. Ce încadrare permite legea?","options":["Activitate care nu poate face parte din oferta de educație timpurie.","Instituție care înlocuiește automat toate grădinițele din localitate.","Serviciu de educație timpurie complementar, ca structură a unei unități.","Serviciu rezervat exclusiv elevilor înscriși în învățământul liceal."],"answer":2,"explanation":"În situațiile prevăzute la articolul 30 pot exista servicii complementare precum ludoteca, grupul de joacă sau grădinița comunitară, ca structuri ale unităților de învățământ.","source":{"title":"Legea nr. 198/2023","locator":"Art. 30 alin. (3)","quote":"din circumscripția școlară sau din unitatea administrativ-teritorială se pot dezvolta servicii de educație timpurie complementare de tip ludotecă, grup de joacă, grădiniță comunitară și altele asemenea, care vor funcționa ca structuri ale unităților de învățământ din acea unitate administrativ-teritorială sau din alte unități administrativ-teritoriale. (4) Standardele de calitate pentru unitățile de educație timpurie ori serviciile de educație timpurie complementare se aprobă prin hotărâre a Guvernului, inițiată de Ministerul Educației, la propunerea ARACIIP. Regulamentul de organizare și funcționare a unităților de educație timpurie se aprobă prin ordin al","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R63","theme":"R","prompt":"Secretariatul trebuie să clasifice raportul anual de evaluare internă a calității. În ce categorie de documente manageriale intră potrivit ROFUIP?","options":["Documente de achiziție.","Documente de diagnoză.","Documente de evidență.","Documente de prognoză."],"answer":1,"explanation":"Raportul anual de evaluare internă a calității este enumerat expres între documentele de diagnoză, alături de celelalte rapoarte anuale indicate.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 29 alin. (1)","quote":"(1) Documentele de diagnoză ale unității de învățământ sunt: a) rapoartele anuale ale comisiilor și compartimentelor din unitatea de învățământ; b) raportul anual asupra calității educației din unitatea de învățământ; c) raportul anual de evaluare internă a calității. (2) Conducerea unității de învățământ poate elabora și alte documente de diagnoză privind domenii specifice de interes, care să contribuie la dezvoltarea instituțională și la atingerea obiectivelor educaționale.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B50","theme":"B","prompt":"După descentralizare, directorul nu dezvoltă competențe de analiză sau mobilizare a echipei și așteaptă progres automat. Ce presupunere trebuie revizuită?","options":["Autonomia face irelevantă capacitatea de decizie a școlii.","Autonomia garantează aceleași rezultate indiferent de conducere.","Autonomia înlătură orice nevoie de dezvoltare profesională.","Autonomia produce rezultate prin calitatea exercitării leadershipului."],"answer":3,"explanation":"Oportunitățile oferite de autonomie depind de capacitatea instituțională și de calitatea leadershipului. Transferul formal de competențe nu garantează progres.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 27","quote":"condiţiile unice (ibid.: 249). Se poate considera că şcolile şi colegiile autonome sunt mai eficiente, însă totul depinde de natura şi de calitatea leadershipului intern şi a managementului. Cercetarea realizată de Dellar (1998) în 30 de şcoli secundare din Australia, spre exemplu, demonstrează că managementul local avea succes acolo unde climatul şcolar era pozitiv, cu","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H26","theme":"H","prompt":"Elevii apreciază competența profesorului, dar spun că acesta nu este disponibil când au nevoie de ajutor. Ce aspect al credibilității merită investigat?","options":["Dimensiunea fizică a sălii în care se desfășoară lecția.","Grija percepută de elevi și relația de încredere.","Numărul de ani de la achiziționarea manualului folosit.","Numărul de documente pe care profesorul le are în dosar."],"answer":1,"explanation":"Credibilitatea nu se reduce la cunoașterea disciplinei. Felul în care elevii percep încrederea și grija profesorului este relevant.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 6, p. 237–238","quote":"class=\"chapter\"> SECȚIUNEA 06 Credibilitatea profesorului / Claritatea profesorului Pag. 237–238 Pagina 237 Vezi pagina originală ↗ Credibilitatea profesorului Credibilitatea profesorului reprezintă credința elevilor că pot învăța de la un anumit profesor pentru","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s6","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=13"}}]},{"id":14,"title":"Simularea 14","items":[{"id":"R69","theme":"R","prompt":"Un salariat distribuie public detalii despre viața familială a unui elev, fără temei legal. Ce interdicție din ROFUIP este relevantă?","options":["Acțiunile care afectează imaginea publică și viața privată a elevului.","Exclusiv comunicările care au fost trimise pe hârtie la secretariat.","Exclusiv comunicările care privesc elevii aflați în clasele terminale.","Numai acțiunile care se desfășoară în timpul examenelor naționale."],"answer":0,"explanation":"Interdicția privește acțiunile care afectează imaginea publică, viața intimă, privată sau familială a beneficiarului primar ori a altor salariați.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 39 alin. (4)","quote":"preuniversitar îi este interzis să desfășoare și să încurajeze acțiuni de natură să afecteze imaginea publică a beneficiarului primar și viața intimă, privată sau familială a acestuia sau ale celorlalți salariați din unitate. (5) Personalului din învățământul preuniversitar îi este interzis să aplice pedepse corporale, precum și să agreseze verbal, fizic sau emoțional beneficiarii primari și/sau colegii. (6) Personalului didactic de predare din învățământul preuniversitar îi este interzis să desfășoare activități de pregătire suplimentară/meditații contracost cu beneficiarii primari de la clasa/clasele la care este încadrat în anul școlar în curs, conform procedurii pentru completarea","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B55","theme":"B","prompt":"Aceeași lipsă de participare este explicată de director prin dezinteres, iar de profesori prin lipsa timpului. Ce rol poate avea teoria în analiză?","options":["Dovedește automat că o singură persoană are dreptate.","Elimină nevoia de a examina dovezile situației.","Înlocuiește faptele cu o soluție universal obligatorie.","Oferă perspective de interpretare a situației."],"answer":3,"explanation":"Teoriile oferă cadre de interpretare. Perspectivele concurente cer confruntare cu situația concretă, nu selectare arbitrară.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 2, p. 39","quote":"practicii: 1. Utilizarea faptelor ca unic instrument de ghidare în acţiune este nesatisfăcătoare, deoarece toate dovezile necesită interpretare. Viaţa în şcoli şi în colegii este prea complexă pentru a le permite practicienilor să ia decizii numai pe baza","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"P28","theme":"P","prompt":"Aceleași rezultate trebuie prezentate profesorilor și familiilor. Directorul adaptează forma, limbajul și nivelul de detaliu pentru fiecare public. Ce competență se evidențiază?","options":["Conformitate juridică și etică profesională","Identitate digitală, inovare și eficiență managerială","Prezentarea și comunicarea informațiilor","Reziliență și managementul riscului"],"answer":2,"explanation":"Selectarea, structurarea și comunicarea adecvată a informației pentru destinatari diferiți sunt centrale în competența 2.4.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"2.4. Prezentarea și comunicarea informațiilor","quote":"Prezentarea și comunicarea informațiilor reprezintă componenta prin care datele, resursele, deciziile și informațiile instituționale sunt prezentate clar, corect și transparent.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"L70","theme":"L","prompt":"Conducerea află despre un incident școlar care creează suspiciunea unei infracțiuni și propune doar mediere internă. Ce obligație trebuie îndeplinită?","options":["Așteptarea finalizării anului școlar înaintea oricărei sesizări.","Așteptarea unei hotărâri judecătorești înaintea oricărei sesizări.","Sesizarea exclusivă a comitetului de părinți pentru arbitraj.","Sesizarea poliției și colaborarea cu organele de anchetă."],"answer":3,"explanation":"Suspiciunea comiterii unei infracțiuni declanșează obligația conducerii de a sesiza poliția. Gestionarea educațională internă nu înlocuiește sesizarea.","source":{"title":"Legea nr. 198/2023","locator":"Art. 65 alin. (8)","quote":"generale de asistență socială și protecția copilului pentru managementul acestora, în interesul superior al copilului. (8) Dacă există suspiciunea comiterii unei infracțiuni, conducerea unităților de învățământ are obligația să sesizeze poliția și să colaboreze cu organele de anchetă. (9) Unitățile de învățământ sunt obligate să stabilească și să pună în aplicare măsuri de sprijin pentru victimă/victime, respectiv măsuri de sprijin și sancțiuni pentru autor/autori adecvate la gravitatea cazului de violență, la cauzele/efectele posibile ale situației de violență și la nevoile educaționale/profesionale, relaționale, sociale, psihologice și fizice ale celor implicați, la nivelul unității de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R70","theme":"R","prompt":"Pentru menținerea în funcție, un cadru didactic prezintă certificatul medical și cazierul judiciar. Ce alt document enumeră expres articolul 45?","options":["Certificatul de atestare fiscală al familiei.","Certificatul de integritate comportamentală.","Certificatul de urbanism al domiciliului.","Certificatul energetic al locuinței personale."],"answer":1,"explanation":"Pe lângă certificatul medical de medicina muncii și cazierul judiciar, articolul 45 prevede certificatul de integritate comportamentală.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 45","quote":"medicul specializat de medicina muncii, care atestă că este apt pentru prestarea activității în învățământ, precum și cazierul judiciar și certificatul de integritate comportamentală.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B56","theme":"B","prompt":"O intervenție reușită într-o școală mică este introdusă într-un liceu mare fără ajustări. Rezultatele sunt slabe. Ce problemă teoretică apare?","options":["Adaptarea prea precisă la resursele și nevoile locale.","Aplicarea excesivă a reflecției asupra situației locale.","Consultarea prea atentă a datelor din instituția primitoare.","Transferul unei soluții fără analiza contextului."],"answer":3,"explanation":"Utilitatea unei explicații sau soluții într-un context nu dovedește potrivirea ei automată într-altul.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 2, p. 40","quote":"Experienţa poate fi în mod particular nefolositoare, folosită ca unic ghid de acţiune, atunci când practicianul începe să opereze într‑un alt context. Variabilele organizaţionale pot determina ca practica într‑o şcoală sau un colegiu să aibă puţină relevanţă într‑un mediu nou. O conştientizare mai bună a teoriei şi practicii poate fi utilă în încercarea managerului","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"C28","theme":"C","prompt":"O activitate necesită două ore și materiale care nu sunt disponibile. Înainte să o includă, ce dimensiune trebuie revizuită?","options":["Exclusiv denumirea decorativă a activității.","Exclusiv numărul de fotografii din raportul final.","Exclusiv ordinea numelor din catalogul clasei.","Resursele și timpul necesare pentru realizare."],"answer":3,"explanation":"Întrebarea „Cu ce voi face?” privește resursele și timpul. O proiectare realistă verifică disponibilitatea lor.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"învățare Întrebări pe care și le pune profesorul în procesul de planificare și de proiectare didactică De ce voi face? Ce voi valorifica? Cu ce voi face? Cum voi face? Cât și cât de bine am realizat? Reflecția asupra relațiilor de derivare dintre competențele specifice, generale, competențele-cheie și atributele prioritare Selectarea conținuturilor învățării, prin raportare la competențele vizate și la standardele de învățare Analiza resurselor curriculare de suport, a celor de timp Stabilirea succesiunii lecțiilor, proiectarea lecțiilor/ activităților de învățare Conceperea modalităților și instrumentelor de evaluare Raportarea la standardele de învățare Ca urmare a","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L66","theme":"L","prompt":"Un liceu teoretic, fără aprobare derogatorie, școlarizează numai jumătate dintre elevi în filiera proprie. Ce cerință trebuie verificată?","options":["Minimum două treimi dintre elevi în filiera specifică.","Minimum jumătate dintre elevi în filiera specifică.","Minimum o treime dintre elevi în filiera specifică.","Minimum un sfert dintre elevi în filiera specifică."],"answer":0,"explanation":"Principiul asumării filierei cere minimum 2/3 pentru unitățile teoretice și vocaționale. Sunt prevăzute derogări ministeriale; liceele tehnologice sunt exceptate.","source":{"title":"Legea nr. 198/2023","locator":"Art. 33 alin. (3)-(5)","quote":"se încadrează în prevederile alin. (2) lit. a) și b) funcționează cu respectarea principiului asumării filierei, în sensul de a școlariza minimum 2/3 dintre elevi corespunzător filierei specifice unității, inclusiv în structurile arondate. Ministerul Educației stabilește criteriile de încadrare a unei unități de învățământ liceal în una dintre cele trei filiere, teoretică, vocațională sau tehnologică, prin metodologie aprobată prin ordin al ministrului educației. (4) Prin excepție de la prevederile alin. (3), cu aprobarea Ministerului Educației, pentru situații justificate, unitățile de învățământ liceal pot școlariza mai puțin de 2/3 dintre elevi corespunzător filierei","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R66","theme":"R","prompt":"Planul de dezvoltare a controlului intern managerial conține doar o listă de obiective, fără acțiuni sau responsabili. Ce componente trebuie adăugate?","options":["Acțiuni, responsabilități și termene de realizare.","Exclusiv mediile anuale ale elevilor din clasele terminale.","Numai denumirile comitetelor de părinți din școală.","Numai preferințele comerciale ale furnizorilor locali."],"answer":0,"explanation":"ROFUIP cere ca planul de dezvoltare a sistemului de control intern managerial să cuprindă obiective, acțiuni, responsabilități, termene și alte componente.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 36","quote":"procedurilor formalizate pe activități. Planul de dezvoltare a sistemului de control intern managerial va cuprinde obiectivele, acțiunile, responsabilitățile, termenele, precum și alte componente.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B53","theme":"B","prompt":"Directorul demonstrează o strategie didactică pentru ca profesorii să o poată observa și discuta. Ce practică a leadershipului instruirii folosește?","options":["Externalizarea tuturor responsabilităților.","Modelarea unei practici profesionale.","Negocierea unei coaliții politice.","Retragerea din sprijinirea predării."],"answer":1,"explanation":"Modelarea face vizibile practicile urmărite și permite învățarea profesională prin observare și reflecție.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 31","quote":"Importanţa leadershipului şi a managementului educaţional 31 • modelare; • monitorizare; • dialog. Modelarea înseamnă puterea exemplului. Liderii centraţi pe învăţare sunt modele pentru ceilalţi pentru că sunt preocupaţi de actul predării, de învăţare şi de specificul grupurilor de elevi,","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H27","theme":"H","prompt":"O sarcină are multe instrucțiuni, dar elevii o interpretează diferit și nu știu ce înseamnă un produs reușit. Ce intervenție vizează claritatea?","options":["Adăugarea mai multor instrucțiuni fără verificarea înțelegerii.","Explicitarea scopului și a criteriilor de reușită înțelese de elevi.","Înlocuirea explicației cu avertismentul că sarcina va fi notată.","Păstrarea criteriilor secrete până după finalizarea produselor."],"answer":1,"explanation":"Claritatea cere ca elevii să înțeleagă ce urmăresc și cum recunosc reușita. Volumul instrucțiunilor nu dovedește înțelegerea.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 6, p. 237–238","quote":"class=\"chapter\"> SECȚIUNEA 06 Credibilitatea profesorului / Claritatea profesorului Pag. 237–238 Pagina 237 Vezi pagina originală ↗ Credibilitatea profesorului Credibilitatea profesorului reprezintă credința elevilor că pot învăța de la un anumit profesor pentru că profesorul este","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s6","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=13"}},{"id":"L67","theme":"L","prompt":"Un contract individual de pregătire practică în sistem dual interzice elevului continuarea studiilor după absolvire. Cum se apreciază clauza?","options":["Este nepermisă numai dacă practica se desfășoară în alt județ.","Este nepermisă: contractul nu poate limita opțiunile de continuare a studiilor.","Este permisă: operatorul economic stabilește definitiv traseul educațional.","Este permisă: semnătura părintelui înlocuiește protecția prevăzută de lege."],"answer":1,"explanation":"Articolul 35 protejează explicit opțiunile ulterioare de continuare a studiilor în cadrul contractului individual de pregătire practică.","source":{"title":"Legea nr. 198/2023","locator":"Art. 35 alin. (8) lit. b)","quote":"al elevului minor, operatorul economic și unitatea de învățământ, contract care stabilește drepturile și obligațiile părților, prin care nu se pot limita opțiunile ulterioare de continuare a studiilor. (9) În învățământul liceal tehnologic dual, tutorii de practică răspund, în condițiile stabilite prin contractul de parteneriat, de organizarea și derularea pregătirii practice organizate de angajator, realizarea evaluării elevilor practicanți, prin consultare cu cadrul didactic coordonator de practică, și inițierea, în colaborare cu acesta, după caz, a programelor de recuperare/măsurilor remediale/stagiilor suplimentare de pregătire practică. Responsabilitățile tutorelui și ale","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R67","theme":"R","prompt":"Organigrama este arhivată drept document de prognoză. În ce categorie o enumeră ROFUIP?","options":["Documente manageriale de cercetare.","Documente manageriale de diagnoză.","Documente manageriale de evidență.","Documente manageriale de prognoză."],"answer":2,"explanation":"Organigrama, statul de funcții, schema orară/programul zilnic și planul de școlarizare sunt documente manageriale de evidență.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 37","quote":"Documentele manageriale de evidență sunt: a) statul de funcții; b) organigrama unității de învățământ; c) schema orară a unității de învățământ/programul zilnic al unității de învățământ antepreșcolar/preșcolar; d) planul de școlarizare.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"P27","theme":"P","prompt":"Școala introduce fluxuri digitale pentru a reduce munca repetitivă. Directorul urmărește utilizarea responsabilă, competențele echipei și eficiența proceselor. Ce competență este descrisă?","options":["Conformitate juridică și etică profesională","Identitate digitală, inovare și eficiență managerială","Prezentarea și comunicarea informațiilor","Reziliență și managementul riscului"],"answer":1,"explanation":"Scopul este inovarea și eficiența managerială prin instrumente digitale, cu responsabilitate în utilizare, nu doar distribuirea unor mesaje.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"2.3. Identitate digitală, inovare și eficiență managerială","quote":"Utilizează eficient tehnologia și resursele digitale în managementul instituțional, monitorizând sistematic progresul în atingerea obiectivelor de performanță. utilizează platforme digitale și instrumente de management informațional în activitatea curentă; monitorizează progresul în atingerea obiectivelor de performanță instituțională într-un mod sistematic; sprijină transformarea digitală a școlii și dezvoltarea competențelor digitale ale personalului; asigură securitatea datelor și conformitatea cu normele GDPR; introduce soluții digitale inovatoare validate și evaluează impactul lor asupra eficienței instituționale.","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"C27","theme":"C","prompt":"Pentru aceleași competențe, profesorul compară mai multe conținuturi posibile. Ce criteriu trebuie să ghideze selecția?","options":["Contribuția conținuturilor la competențele și standardele vizate.","Numărul de pagini copiate dintr-un singur auxiliar comercial.","Poziția conținuturilor în reclama furnizorului de materiale.","Preferința de a folosi numai conținuturi deja dictate anul trecut."],"answer":0,"explanation":"Selecția conținuturilor răspunde întrebării „Ce voi valorifica?” și se raportează la competențele și standardele urmărite.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"activităților de învățare Întrebări pe care și le pune profesorul în procesul de planificare și de proiectare didactică De ce voi face? Ce voi valorifica? Cu ce voi face? Cum voi face? Cât și cât de bine am realizat? Reflecția asupra relațiilor de derivare dintre competențele specifice, generale, competențele-cheie și atributele prioritare Selectarea conținuturilor învățării, prin raportare la competențele vizate și la standardele de învățare Analiza resurselor curriculare de suport, a celor de timp Stabilirea succesiunii lecțiilor, proiectarea lecțiilor/ activităților de învățare Conceperea modalităților și instrumentelor de evaluare Raportarea la standardele de învățare Ca","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L68","theme":"L","prompt":"O unitate cu profil sportiv dorește înscrierea elevilor fără verificarea aptitudinilor specifice, numai după media generală. Ce condiție legală este omisă?","options":["Înscrierea pe baza domiciliului directorului unității.","Înscrierea pe baza recomandării unui sponsor local.","Înscrierea pe baza testării aptitudinilor specifice.","Înscrierea pe baza vechimii părinților în asociație."],"answer":2,"explanation":"În învățământul de artă și sportiv, elevii pot fi înscriși numai pe baza testării aptitudinilor specifice. Media nu substituie această condiție.","source":{"title":"Legea nr. 198/2023","locator":"Art. 46 alin. (1) lit. b)","quote":"învățământul sportiv: a) școlarizarea se realizează, de regulă, începând cu învățământul primar; b) elevii pot fi înscriși numai pe baza testării aptitudinilor specifice; c) planurile-cadru de învățământ sunt adaptate specificului acestui învățământ; d) studiul disciplinelor de specialitate se realizează pe clase, pe grupe sau individual, potrivit criteriilor stabilite prin ordin al ministrului educației; e) programele școlare pentru învățământul liceal de artă și pentru învățământul liceal sportiv respectă obiectivele educaționale stabilite pentru profilul respectiv. (2) Pentru activitatea sportivă și artistică de performanță, la propunerea autorităților administrației publice locale, a","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R68","theme":"R","prompt":"La o școală cu personalitate juridică se pregătește angajarea unui administrator. Cu cine se încheie contractul individual de muncă?","options":["Cu asociația de părinți, prin președintele acesteia.","Cu consiliul elevilor, prin președintele în funcție.","Cu fiecare clasă, prin profesorul diriginte desemnat.","Cu unitatea de învățământ, prin reprezentantul său legal."],"answer":3,"explanation":"Angajarea personalului didactic de predare, auxiliar și administrativ la unitățile cu PJ se face prin contract individual cu unitatea, prin reprezentantul legal.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 38 alin. (3)","quote":"didactic de predare, didactic auxiliar și administrativ în unitățile de învățământ cu personalitate juridică se realizează prin încheierea contractului individual de muncă cu unitatea de învățământ, prin reprezentantul său legal.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B54","theme":"B","prompt":"O echipă contribuie la formularea reformei, dar directorul elimină toate propunerile sale și prezintă rezultatul ca produs propriu. Ce resursă a schimbării este afectată?","options":["Existența unei autorități externe care aprobă inventarul.","Necesitatea de a respecta exclusiv proceduri contabile.","Obligația de a menține aceleași soluții în orice context.","Sentimentul că schimbarea le aparține celor implicați."],"answer":3,"explanation":"Participarea are efect când construiește asumare și apartenență. Consultarea fără influență reală poate slăbi acest sentiment.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 1, p. 19","quote":"şcolari. Există o probabilitate mai mare ca profesorii şi liderii să manifeste entuziasm faţă de schimbare atunci când simt că aceasta le „aparţine”, şi nu atunci când le este impusă. Pe baza cercetărilor efectuate în şcolile din Canada, Hargreaves (2004) afirmă că profesorii asociază schimbările iniţiate de ei înşişi cu o experienţă emoţională pozitivă, în timp ce","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H28","theme":"H","prompt":"O echipă atribuie toate dificultățile familiilor și refuză să discute ce poate schimba în propria predare. Ce perspectivă ar susține eficacitatea colectivă?","options":["Convingerea că analiza comună trebuie evitată pentru a păstra liniștea.","Convingerea că influența profesorilor este nulă în orice situație educațională.","Convingerea că simpla apartenență la aceeași școală dovedește eficacitatea.","Convingerea fundamentată că acțiunea comună a profesorilor poate produce progres."],"answer":3,"explanation":"Eficacitatea colectivă privește încrederea în capacitatea comună de influență asupra învățării, legată de acțiune și de dovezi.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 7, p. 239–240","quote":"class=\"chapter\"> SECȚIUNEA 07 Eficacitatea colectivă a profesorilor și impactul lor Pag. 239–240 Pagina 239 Vezi pagina originală ↗ împărtășesc credința că, prin efortul lor unit, pot depăși greutăți și pot obține rezultatele dorite, grupurile sunt mai eficiente. Acest","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s7","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=15"}},{"id":"L69","theme":"L","prompt":"La nivel județean se definitivează sistemul-cadru de protecție a unităților școlare. Cine îl aprobă potrivit articolului 63?","options":["Directorul fiecărei școli.","Prefectul județului.","Președintele consiliului elevilor.","Primarul fiecărei localități."],"answer":1,"explanation":"Sistemul-cadru județean este elaborat sub coordonarea prefectului și se aprobă de prefect. Regulamentele fiecărei școli reprezintă un nivel distinct.","source":{"title":"Legea nr. 198/2023","locator":"Art. 63 alin. (2)","quote":"preuniversitar, a siguranței elevilor și a personalului didactic de către reprezentanții autorităților prevăzute la alin. (1), care se aprobă de prefect. (3) În fiecare unitate de învățământ preuniversitar, consiliul de administrație, după consultarea consiliului profesoral, a consiliului școlar al elevilor, a consiliului reprezentativ al părinților și asociației de părinți, acolo unde există, aprobă un regulament de ordine interioară, cu precizarea condițiilor de acces în școală al profesorilor, elevilor și al vizitatorilor. Regulamentul este publicat pe site-ul unității de învățământ și comunicat autorităților prevăzute la alin. (1). (4) Prin bugetul de stat, din sumele","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}}]},{"id":15,"title":"Simularea 15","items":[{"id":"B59","theme":"B","prompt":"La selecția echipei se presupune că empatia este exclusiv feminină și fermitatea exclusiv masculină. Ce precauție sugerează discuția lui Bush?","options":["Alegerea liderului exclusiv după stereotipul majorității.","Evaluarea numai a conformării la roluri tradiționale de gen.","Evitarea atribuirii rigide a calităților de conducere după sex.","Excluderea oricărei calități relaționale din selecția liderilor."],"answer":2,"explanation":"Competențele și comportamentele nu trebuie închise în opoziții rigide între bărbați și femei. Diversitatea calităților este relevantă pentru conducere.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 2, p. 46","quote":"pentru a combate teoriile de management educaţional sau pentru a conduce la reconceptualizarea acestora cu scopul de a include şi bărbaţii, şi femeile (...). Sunt necesare cercetări care contestă stereotipurile tradiţionale cu privire la ceea ce constituie un comportament şi un proces de management adecvat. Asocierea managementului cu masculinitatea nu a","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"P30","theme":"P","prompt":"Comunitatea cere explicații despre deciziile instituției. Directorul prezintă rezultatele și întreține un dialog responsabil cu autoritățile și partenerii. Ce competență este predominantă?","options":["Monitorizare, evaluare internă și raportare","Prezentarea și comunicarea informațiilor","Relaționare, comunicare și gestionarea conflictelor","Responsabilitate publică și relaționare instituțională"],"answer":3,"explanation":"Cazul urmărește asumarea responsabilității publice și relaționarea instituțională, dincolo de transmiterea tehnică a unei informări.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"3.2. Responsabilitate publică și relaționare instituțională","quote":"Comunică public informații relevante pentru a consolida încrederea în instituție și asigură o comunicare activă, proactivă și transparentă cu toți actorii ecosistemului educațional. comunică public, cu regularitate, informații privind rezultatele, resursele și deciziile instituționale; realizează o comunicare activă și proactivă cu actorii ecosistemului educațional local; manifestă disponibilitate pentru a răspunde public cu privire la utilizarea resurselor și impactul acestora; integrează feedbackul elevilor, părinților și partenerilor în procesele decizionale; asigură transparența cheltuielilor în relația cu factorii interesați.","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"L75","theme":"L","prompt":"Echipa școlii limitează educația incluzivă exclusiv la copiii cu certificat de dizabilitate. Ce sferă stabilește legea?","options":["Exclusiv beneficiarii primari care au fost orientați spre învățământul special.","Exclusiv beneficiarii primari care primesc o bursă socială în anul curent.","Totalitatea beneficiarilor primari, cu atenție specială pentru cei expuși excluderii.","Totalitatea profesorilor titulari, fără raportare la particularitățile elevilor."],"answer":2,"explanation":"Incluziunea privește toți beneficiarii primari și nevoile lor unice. Atenția specială acordată vulnerabilității nu restrânge principiul la o singură categorie.","source":{"title":"Legea nr. 198/2023","locator":"Art. 67 alin. (2)","quote":"asigurarea stării de bine, cu accent pe nevoile și pe particularitățile individuale ale fiecărui copil. (2) Educația incluzivă vizează totalitatea beneficiarilor primari cu caracteristici, interese, abilități și nevoi de învățare unice, cu o atenție specială în ceea ce privește copiii expuși riscului de marginalizare, excludere sau de a avea rezultate școlare scăzute. (3) Se consideră în risc de excluziune școlară beneficiarii primari care sunt în risc de stigmatizare, discriminare, desconsiderare a identității lor culturale, segregare, abandon școlar și insucces școlar din cauza apartenenței lor la una sau mai multe categorii: statut social, economic sau cultural, minoritate națională,","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R75","theme":"R","prompt":"Consiliul clasei analizează progresul individual al elevilor numai o dată pe an. Care este minimul prevăzut pentru această analiză?","options":["Cel puțin de două ori pe an.","Cel puțin de patru ori pe lună.","Cel puțin o dată la doi ani.","Cel puțin o dată la trei ani."],"answer":0,"explanation":"Analiza progresului în învățare și a comportamentului fiecărui elev se face cel puțin de două ori pe an. Aceasta nu se confundă cu frecvența ședințelor consiliului clasei.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 58","quote":"Consiliul clasei are următoarele atribuții: analizează de cel puțin două ori pe an progresul în învățare și comportamentul fiecărui elev; stabilește măsuri de sprijin atât pentru elevii cu dificultăți de învățare sau de comportament, cât și pentru elevii cu rezultate deosebite, contribuind la realizarea și adaptarea periodică a planurilor individualizate de învățare ale beneficiarilor primari; stabilește notele/calificativele, respectiv mediile la purtare pentru fiecare elev al clasei, în funcție de frecvența și comportamentul acestora în activitatea școlară și extrașcolară; propune consiliului","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B60","theme":"B","prompt":"O școală recompensează doar competiția agresivă pentru influență și descurajează cooperarea. Ce componentă a culturii leadershipului trebuie examinată?","options":["Absența oricărei legături între putere și stilul de conducere.","Asocierea conducerii cu dominația și controlul.","Eliminarea stereotipurilor prin acceptarea tuturor vocilor.","Existența unei comunități care valorifică dialogul egal."],"answer":1,"explanation":"Discuția critică vizează asocierea conducerii cu competiția, controlul și dominația, care poate marginaliza alte calități și moduri de participare.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 2, p. 45","quote":"a managementului, ce poate părea neatractivă pentru femei. Acest model include „comportamentul competitiv agresiv, evidenţierea controlului în defavoarea negocierii şi colaborării şi urmărirea competiţiei în detrimentul rezolvării problemelor comune” (Al‑Khalifa, 1992: 100). Dominaţia masculină sau „androcentricitatea” managementului","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"C30","theme":"C","prompt":"Profesorul verifică dacă instrumentul de evaluare măsoară ceea ce și-a propus să dezvolte prin activități. Ce relație urmărește?","options":["Coerența evaluării cu achizițiile și standardele de învățare.","Concordanța dintre orarul contabilului și numărul elevilor.","Egalitatea numărului de pagini dintre toate manualele.","Identitatea culorilor dintre test și mobilierul clasei."],"answer":0,"explanation":"Întrebarea „Cât și cât de bine am realizat?” cere evaluarea nivelului atins în raport cu achizițiile și standardele urmărite.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"le pune profesorul în procesul de planificare și de proiectare didactică De ce voi face? Ce voi valorifica? Cu ce voi face? Cum voi face? Cât și cât de bine am realizat? Reflecția asupra relațiilor de derivare dintre competențele specifice, generale, competențele-cheie și atributele prioritare Selectarea conținuturilor învățării, prin raportare la competențele vizate și la standardele de învățare Analiza resurselor curriculare de suport, a celor de timp Stabilirea succesiunii lecțiilor, proiectarea lecțiilor/ activităților de învățare Conceperea modalităților și instrumentelor de evaluare Raportarea la standardele de învățare Ca urmare a reflecției ghidate de întrebările","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L71","theme":"L","prompt":"În proiectul de supraveghere audio-video sunt incluse holurile, sala de sport și vestiarele. Ce spațiu trebuie eliminat potrivit interdicției exprese?","options":["Exteriorul clădirilor, alături de sălile de clasă.","Holurile, alături de sălile de festivități.","Sălile de sport, alături de holurile internatelor.","Vestiarele, alături de grupurile sanitare."],"answer":3,"explanation":"Textul permite supravegherea în spațiile enumerate, dar exclude vestiarele și grupurile sanitare. Scopul de siguranță nu înlătură această limită.","source":{"title":"Legea nr. 198/2023","locator":"Art. 66 alin. (4)","quote":"în exteriorul clădirilor, pe holuri, în sălile de festivități, pe holurile căminelor sau internatelor, precum și în sălile de sport, cu excepția vestiarelor și a grupurilor sanitare. (5) Unitatea de învățământ preuniversitar își asumă răspunderea cu privire la respectarea prevederilor Regulamentului (UE) 2016/679 al Parlamentului European și al Consiliului din 27 aprilie 2016 privind protecția persoanelor fizice în ceea ce privește prelucrarea datelor cu caracter personal și privind libera circulație a acestor date și de abrogare a Directivei 95/46/CE (Regulamentul general privind protecția datelor), precum și ale Legii nr. 190/2018 privind măsuri de punere în aplicare a","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R71","theme":"R","prompt":"Administratorul de patrimoniu trimite personalul de îngrijire să lucreze la locuința sa. Ce regulă ROFUIP încalcă?","options":["Personalul subordonat poate fi folosit numai pentru activități necesare unității.","Personalul subordonat poate fi folosit pentru orice nevoie personală a șefului.","Personalul subordonat poate lucra în afara școlii doar fără pontaj.","Personalul subordonat poate lucra în locuințe private dacă primește sarcini verbale."],"answer":0,"explanation":"Administratorul nu poate folosi personalul subordonat în alte activități decât cele necesare unității de învățământ.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 49 alin. (4)","quote":"administratorului de patrimoniu schimbarea acestor sectoare. (4) Administratorul de patrimoniu nu poate folosi personalul subordonat în alte activități decât cele necesare unității de învățământ. (5) Administratorul de patrimoniu sau, în lipsa acestuia, altă persoană din cadrul compartimentului administrativ, desemnată de către director, verifică periodic, în limita competențelor, elementele bazei materiale a unității de învățământ, în vederea asigurării securității beneficiarilor primari/personalului din unitate.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B57","theme":"B","prompt":"Datele arată simultan roluri formale, negocieri între grupuri și tradiții puternice. Ce abordare analitică este adecvată?","options":["Excluderea oricărei perspective după identificarea primei reguli.","Folosirea complementară a mai multor perspective teoretice.","Presupunerea că doar organigrama explică întreaga organizație.","Presupunerea că toate teoriile se anulează reciproc în orice caz."],"answer":1,"explanation":"Mai multe teorii pot fi valide simultan pentru dimensiuni diferite ale aceleiași instituții.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 2, p. 41","quote":"acest sens, perspectiva este o susţinere mai slabă a cunoştinţelor decât o teorie ştiinţifică. În educaţie, mai multe perspective pot fi valide simultan: Înţelegerea noastră a proceselor de utilizare a cunoaşterii este concepută nu atât ca un set de date, descoperiri sau generalizări, cât ca perspective distincte ce combină date, valori şi presupoziţii într‑un filtru","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H29","theme":"H","prompt":"Un furnizor de formare invocă numai prestigiul instituției și nu prezintă efecte asupra practicii sau învățării. Ce întrebare este relevantă?","options":["Câte sigle pot fi adăugate pe certificatul de absolvire?","Ce culoare a fost aleasă pentru mapa participanților?","Ce denumire mai solemnă ar putea primi același program?","Ce dovezi există despre rezultatele pregătirii oferite?"],"answer":3,"explanation":"Prestigiul și tradiția nu substituie examinarea dovezilor privind eficiența pregătirii profesorilor.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 8, p. 241–242","quote":"devină profesori. Mai mult, e surprinzător că formarea viitorilor profesori pare atât de lipsită de date; poate că așa învață ei să ignore dovezile, să pună preț pe îndemânare și să caute dovezi pozitive că schimbă lucrurile (undeva, cumva, cu cineva). Trei până la cinci ani de pregătire par să ducă la profesori care reproduc, profesori care îl copiază pe","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s8","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=17"}},{"id":"L72","theme":"L","prompt":"Școala dorește păstrarea obișnuită a tuturor înregistrărilor audio-video timp de șase luni, fără cercetări care să justifice prelungirea. Care este perioada legală de referință?","options":["Nouăzeci de zile, cu excepția cazurilor temeinic justificate.","O sută optzeci de zile, fără vreo justificare suplimentară.","Șaizeci de zile, cu excepția cazurilor temeinic justificate.","Treizeci de zile, cu excepția cazurilor temeinic justificate."],"answer":3,"explanation":"Păstrarea obișnuită este de 30 de zile. Pentru cercetarea sesizărilor, cazurile temeinic justificate permit prelungirea până la finalizarea cercetărilor, apoi ștergerea automată.","source":{"title":"Legea nr. 198/2023","locator":"Art. 66 alin. (6) lit. d)","quote":"d) de a asigura stocarea și păstrarea, în condiții de siguranță și confidențialitate, a înregistrărilor audio-video pentru o perioadă de 30 de zile, cu excepția cazurilor temeinic justificate când această perioadă se prelungește până la finalizarea cercetărilor privind sesizările formulate, după care aceste informații se șterg automat; e) de a nu folosi înregistrările audio-video în vederea evaluării profesionale a cadrelor didactice sau în soluționarea contestațiilor privind evaluarea elevilor la orele de curs; f) de a asigura funcționarea corespunzătoare a sistemelor de supraveghere audio-video; g) de a pune la dispoziția organelor de urmărire penală înregistrările","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R72","theme":"R","prompt":"Pentru un angajat din personalul administrativ se pregătește cercetarea disciplinară. Care este cadrul legal indicat expres de articolul 53?","options":["Exclusiv metodologia de admitere în liceu.","Exclusiv regulamentul de evaluare a elevilor.","Legea burselor aplicată beneficiarilor primari.","Legea nr. 53/2003 — Codul muncii."],"answer":3,"explanation":"Răspunderea disciplinară a personalului administrativ se stabilește potrivit Codului muncii. Nu se transferă automat procedurile specifice altor categorii.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 53","quote":"Personalul administrativ răspunde disciplinar în conformitate cu prevederile Legii nr. 53/2003 – Codul muncii, republicată, cu modificările și completările ulterioare.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"P29","theme":"P","prompt":"Directorul organizează evaluarea internă a unui program, urmărește realizarea indicatorilor și pregătește raportarea rezultatelor. Ce competență specifică este dominantă?","options":["Colectarea datelor, analiza și formularea de strategii de îmbunătățire a calității","Managementul incluziunii și al diversității în profilurile de învățare","Monitorizare, evaluare internă și raportare","Responsabilitate publică și relaționare instituțională"],"answer":2,"explanation":"Accentul este pe monitorizare, evaluare internă și raportare. Analiza cauzelor pentru o nouă strategie ar fi un accent suplimentar, diferit.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"3.1. Monitorizare, evaluare internă și raportare","quote":"implementează standardele ARACIP și monitorizează respectarea lor la nivelul unității; creează mecanisme de monitorizare și raportare a rezultatelor educaționale, cu termene și responsabilități clare; utilizează instrumente standardizate de evaluare internă; organizează sesiuni de analiză a datelor cu echipa și elaborează planuri de îmbunătățire; coordonează comisii și activități de evaluare internă, implicând întreaga echipă; monitorizează implementarea măsurilor corective și ajustează planurile în funcție de rezultate; elaborează rapoarte de autoevaluare și le aduce la cunoștința comunității; corelează procesul de evaluare cu obiectivele strategice ale instituției.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"C29","theme":"C","prompt":"Profesorul a stabilit competențele, conținuturile și resursele. Acum alege sarcinile, metodele și succesiunea experiențelor de învățare. Ce componentă decide?","options":["Categoria contabilă a mobilierului.","Denumirea juridică a finanțatorului.","Identitatea furnizorului catalogului.","Modul de realizare a învățării."],"answer":3,"explanation":"Întrebarea „Cum voi face?” orientează selecția și organizarea activităților prin care vor fi dezvoltate achizițiile urmărite.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"pe care și le pune profesorul în procesul de planificare și de proiectare didactică De ce voi face? Ce voi valorifica? Cu ce voi face? Cum voi face? Cât și cât de bine am realizat? Reflecția asupra relațiilor de derivare dintre competențele specifice, generale, competențele-cheie și atributele prioritare Selectarea conținuturilor învățării, prin raportare la competențele vizate și la standardele de învățare Analiza resurselor curriculare de suport, a celor de timp Stabilirea succesiunii lecțiilor, proiectarea lecțiilor/ activităților de învățare Conceperea modalităților și instrumentelor de evaluare Raportarea la standardele de învățare Ca urmare a reflecției ghidate","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L73","theme":"L","prompt":"Directorul propune folosirea imaginilor camerelor de siguranță pentru acordarea calificativelor profesorilor. Cum se aplică articolul 66?","options":["Înregistrările nu pot fi folosite numai în anul de debut.","Înregistrările nu pot fi folosite pentru evaluarea profesională.","Înregistrările pot fi folosite dacă profesorii au vechime mică.","Înregistrările pot fi folosite dacă școala deține camerele."],"answer":1,"explanation":"Este interzisă folosirea înregistrărilor pentru evaluarea profesională a profesorilor și pentru soluționarea contestațiilor privind evaluarea elevilor la ore.","source":{"title":"Legea nr. 198/2023","locator":"Art. 66 alin. (6) lit. e)","quote":"privind sesizările formulate, după care aceste informații se șterg automat; e) de a nu folosi înregistrările audio-video în vederea evaluării profesionale a cadrelor didactice sau în soluționarea contestațiilor privind evaluarea elevilor la orele de curs; f) de a asigura funcționarea corespunzătoare a sistemelor de supraveghere audio-video; g) de a pune la dispoziția organelor de urmărire penală înregistrările audio-video, dacă există o solicitare în acest sens. (7) Unitățile de învățământ cu sistem de supraveghere audio-video garantează caracterul confidențial și privat al înregistrărilor audio-video. (8) Înregistrările audio-video din spațiul școlar prevăzut la alin. (4)","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R73","theme":"R","prompt":"Secretarul CP păstrează procesele-verbale, dar aruncă documentele anexate ședințelor. Ce set documentar prevede ROFUIP?","options":["Exclusiv convocatoarele, fără registru de procese-verbale.","Exclusiv mesajele informale trimise înaintea ședințelor.","Registrul de procese-verbale, fără niciun document anexat.","Registrul de procese-verbale, însoțit de dosarul cu anexe."],"answer":3,"explanation":"Documentele CP includ registrul de procese-verbale însoțit de dosarul cu anexele, precum și tematica, graficul și dovezile convocării.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 56","quote":"consiliului profesoral/dovezi ale convocării prin mijloace electronice; registrul de procese-verbale al consiliului profesoral, însoțit de dosarul cu anexele proceselor- verbale.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B58","theme":"B","prompt":"Un raport explică foarte bine procedurile, dar nu explică rezistența profesorilor. Cum trebuie tratată limita sa?","options":["Ca dovadă că orice procedură este inutilă în educație.","Ca dovadă că percepțiile oamenilor nu pot influența schimbarea.","Ca efect al accentului pus pe anumite aspecte în detrimentul altora.","Ca motiv pentru a renunța complet la analiza organizațională."],"answer":2,"explanation":"Modelele selectează anumite dimensiuni și pot neglija altele. Limita cere completarea perspectivei, nu negarea întregii analize.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 2, p. 44","quote":"Şi management educaŢional 2. Teoriile tind să fie selective sau parţiale, în sensul că evidenţiază anumite aspecte ale instituţiei în detrimentul altora. Adoptarea unui model teoretic duce la neglijarea altor abordări. Şcolile şi colegiile sunt evident prea complexe pentru a fi analizate pe baza unei singure dimensiuni. De exemplu, o explicaţie a instituţiilor","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H30","theme":"H","prompt":"O medie modestă a efectelor formării este folosită pentru a declara toate programele echivalente și inutile. Ce analiză este mai justificată?","options":["Eliminarea diferențelor dintre programe printr-o singură etichetă.","Examinarea caracteristicilor și dovezilor programelor care au succes.","Presupunerea că orice program produce automat aceleași rezultate.","Renunțarea la verificarea practicii pentru toate programele viitoare."],"answer":1,"explanation":"O medie nu descrie identic fiecare program. Contează identificarea caracteristicilor programelor reușite și a efectelor lor.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 9, p. 243–243","quote":"nu este că ar trebui să renunțăm la formarea profesorilor, deoarece mărimea efectului general este mică, ci că ar trebui să celebrăm programele de succes bazate pe dovezile impactului lor, să le învățăm și să le ajustăm. Putem crește standardele formării profesionale doar dacă știm care sunt acestea și la ce se referă, dacă construim o bază cu dovezi de programe de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s9","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=19"}},{"id":"L74","theme":"L","prompt":"Un părinte solicită acces la imaginile unui incident, prin cerere scrisă și motivată cu intervalul precizat. Ce modalitate prevede legea după aprobarea directorului?","options":["Acces numai prin vizualizarea înregistrărilor.","Predarea obligatorie a parolei sistemului de supraveghere.","Publicarea obligatorie a imaginilor pe site-ul școlii.","Transmiterea obligatorie a întregii arhive pe e-mail."],"answer":0,"explanation":"Accesul persoanelor enumerate de lege se face pe baza cererii aprobate de director, numai prin vizualizare. Cererea precizează și perioada solicitată.","source":{"title":"Legea nr. 198/2023","locator":"Art. 66 alin. (9)-(10)","quote":"(9) Accesul la înregistrările audio-video se face în baza unei cereri scrise, motivată, aprobată de directorul unității de învățământ, numai prin vizualizarea acestora, de către următoarele categorii de persoane: a) părintele sau reprezentantul legal al elevului minor, elevul major sau personalul unității de învățământ preuniversitar; b) reprezentații DJIP/DMBIP, ai Ministerului Educației și ai direcției generale de asistență socială și protecția copilului; c) psihologul/consilierul școlar din unitatea de învățământ preuniversitar, cu acordul părintelui sau reprezentantului legal al elevului minor sau al elevului major. (10) Cererea prevăzută la alin. (9) trebuie să conțină și","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R74","theme":"R","prompt":"Consiliul clasei este programat o singură dată pentru întregul an școlar. Ce frecvență minimă de întrunire prevede ROFUIP?","options":["Cel puțin o dată în fiecare interval de cursuri.","Cel puțin o dată la fiecare doi ani școlari.","Exclusiv când este modificat regulamentul școlii.","Exclusiv la încheierea ultimului an din ciclu."],"answer":0,"explanation":"Consiliul clasei se întrunește cel puțin o dată în fiecare interval de cursuri și ori de câte ori este necesar, la solicitările prevăzute.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 57","quote":"diriginte, în cazul învățământului gimnazial, liceal, profesional și postliceal. Consiliul clasei se întrunește cel puțin o dată, în fiecare interval de cursuri sau ori de câte ori este necesar, la solicitarea învățătorului/institutorului/profesorului pentru învățământul primar, respectiv a profesorului diriginte, a reprezentanților părinților/ reprezentanților legali și ai beneficiarilor primari. În situații obiective, cum ar fi calamități, intemperii, epidemii, pandemii, alte situații excepționale, ședințele consiliului clasei se pot desfășura, după caz, în format hibrid sau online, prin mijloace electronice de comunicare în sistem de videoconferință.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}}]},{"id":16,"title":"Simularea 16","items":[{"id":"P32","theme":"P","prompt":"Datele despre participare și rezultate arată diferențe între clase. Directorul caută cauze, verifică tipare și formulează o strategie de îmbunătățire. Ce competență este dominantă?","options":["Asigurarea succesului școlar al elevilor și a performanței cadrelor didactice","Colectarea datelor, analiza și formularea de strategii de îmbunătățire a calității","Managementul implementării curriculumului și al proceselor de evaluare","Managementul incluziunii și al diversității în profilurile de învățare"],"answer":1,"explanation":"Datele sunt colectate și analizate pentru fundamentarea strategiei de calitate. Acest demers depășește simpla raportare a indicatorilor.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"3.4. Colectarea datelor, analiza și formularea de strategii de îmbunătățire a calității","quote":"Utilizează metode de cercetare empirică și analize de date pentru a fundamenta deciziile curriculare, organizaționale și de dezvoltare profesională. colectează și analizează date relevante privind performanța școlii — rezultate evaluări, rate de participare, feedback; derulează analize de nevoi, studii de satisfacție a beneficiarilor și cercetare-acțiune la nivel instituțional; utilizează indicatori statistici relevanți pentru decizii privind curriculum, evaluare și dezvoltare profesională; formulează strategii de îmbunătățire a calității bazate pe evidențe și le monitorizează implementarea; organizează sesiuni de analiză și reflecție cu echipa pe baza datelor colectate.","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"L80","theme":"L","prompt":"Un elev termină perioada de școlarizare în spital în februarie. Școala de proveniență îi spune că poate reveni doar în septembrie. Ce drept trebuie respectat?","options":["Revenirea în unitate exclusiv după repetarea ultimei clase.","Revenirea în unitate exclusiv la începutul anului următor.","Revenirea în unitate numai după un nou concurs de admitere.","Revenirea în unitate oricând în timpul anului școlar."],"answer":3,"explanation":"Elevul beneficiază de rezervarea locului și poate reveni în unitatea de proveniență oricând în cursul anului școlar, conform articolului 72 alineatul (4).","source":{"title":"Legea nr. 198/2023","locator":"Art. 72 alin. (4)","quote":"de învățământ la care a fost școlarizat anterior înscrierii în „Școala din spital“ și are dreptul de a reveni în unitatea de învățământ, oricând în timpul anului școlar. (5) Preșcolarilor cuprinși în forma de școlarizare din spital în grupa mare, diagnosticați cu boli cronice invalidante, cu afecțiuni maligne, cu alte boli amenințătoare de viață sau cu afecțiuni care necesită spitalizare îndelungată și/sau imobilizare la domiciliu, li se rezervă loc la clasa pregătitoare în unitatea de învățământ din circumscripția arondată. (6) Elevii cuprinși în forma de școlarizare din spital în clasa a VIII-a, diagnosticați cu boli cronice invalidante, cu afecțiuni maligne, cu alte boli amenințătoare","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R80","theme":"R","prompt":"Un elev a promovat clasa a VI-a, fără admitere specială pentru clasa următoare. Școala îi condiționează continuarea de o nouă cerere de admitere. Ce regulă se aplică?","options":["Înscrierea de drept în anul următor.","Repetarea obligatorie a procedurii de admitere.","Retragerea automată dacă nu depune cerere.","Transferul obligatoriu către altă unitate."],"answer":0,"explanation":"Elevii promovați sunt înscriși de drept în anul următor, dacă nu există prevederi specifice de admitere aprobate prin ordin al ministrului.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 92","quote":"Elevii promovați vor fi înscriși de drept în anul următor, dacă nu există prevederi specifice de admitere în clasa respectivă, aprobate prin ordin al ministrului educației.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B64","theme":"B","prompt":"Într-o analiză, decizia este explicată prin poziția ocupată, lanțul de comandă și responsabilitățile oficiale. Ce model este folosit?","options":["Modelul cultural.","Modelul formal.","Modelul politic.","Modelul subiectiv."],"answer":1,"explanation":"Modelul formal privilegiază structura, rolurile și autoritatea asociată pozițiilor oficiale.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 2, p. 51","quote":"cu cele şase modele de management Tabelul 2.1. Tipologia modelelor de management şi leadership Modelul de management Modelul de leadership Formal Managerial Colegial Participativ Transformaţional Distribuit Politic Tranzacţional Subiectiv Postmodern Emoţional De ambiguitate Circumstanţial Cultural Moral Al instruirii Sursa: adaptat după Bush şi Glover, 2002.","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"C32","theme":"C","prompt":"O unitate de învățare conține numai teme, fără activități și evaluare asociate competențelor. Ce coerență trebuie construită?","options":["Între competențe, conținuturi, activități, resurse și evaluare.","Între dimensiunea dulapului și culoarea dosarului proiectului.","Între forma ștampilei și ordinea semnăturilor pe copertă.","Între numărul de coli și prețul tonerului din secretariat."],"answer":0,"explanation":"Proiectarea unității de învățare leagă componentele procesului, în loc să rămână un simplu inventar de conținuturi.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"urmare a reflecției ghidate de întrebările anterioare, profesorul realizează următoarele documente școlare: planificarea calendaristică, proiectul unității de învățare, proiectul lecției. Planificarea calendaristică – rezultat al unui proces de elaborare a răspunsurilor la întrebări precum: Care sunt unitățile de învățare prin care ajung la competențele specifice din programa școlară? În ce succesiune vor fi abordate acestea? Care sunt relațiile dintre unitățile de învățare (intra- și interdisciplinar)? Care sunt competențele specifice asociate fiecărei unități de învățare? Care este bugetul de timp asociat fiecărei unități de învățare? Care sunt conținuturile învățării","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L76","theme":"L","prompt":"Un elev cu dislexie este tratat ca și cum dificultatea sa ar reprezenta lipsă de efort. Ce obligație de sprijin indică articolul 68 pentru tulburările specifice de învățare?","options":["Aplicarea exclusivă a acelorași metode, fără sprijin specific.","Asigurarea educației prin metode psihopedagogice specifice.","Înlocuirea automată a tuturor activităților școlare cu teme.","Suspendarea școlarizării până la dispariția completă a dificultății."],"answer":1,"explanation":"Pentru dislexie, disgrafie, disortografie și discalculie, legea prevede metode psihopedagogice specifice și o metodologie de suport.","source":{"title":"Legea nr. 198/2023","locator":"Art. 68 alin. (5)","quote":"beneficiarilor primari cu tulburări specifice de învățare (TSI), dislexie, disgrafie, disortografie, discalculie, este asigurată prin metode psihopedagogice specifice acestei categorii. Metodologia privind asigurarea suportului necesar pentru elevii cu tulburări specifice de învățare este aprobată prin ordin al ministrului educației. (6) Evaluarea și diagnosticarea beneficiarilor primari cu tulburări de neurodezvoltare se vor face inclusiv prin aplicarea de teste specifice standardizate pentru fiecare arie de neurodezvoltare evaluată, conform unui protocol național de evaluare complexă, aprobat prin ordin comun al ministrului educației și al ministrului sănătății. (7) Învățământul","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R76","theme":"R","prompt":"Comisia pentru curriculum are nevoie de un responsabil. Directorul dorește numirea fără propunerea CP. Care este traseul prevăzut?","options":["Propunere a furnizorului de manuale și acord al secretariatului.","Propunere a primarului și vot exclusiv al personalului administrativ.","Propunere prin vot în consiliul elevilor și decizie a contabilului.","Propunere prin vot în CP, hotărâre CA și decizie a directorului."],"answer":3,"explanation":"Responsabilul este propus prin vot de CP din rândul personalului didactic titular cu rezultate deosebite; numirea se face prin decizia directorului, în baza hotărârii CA.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 72","quote":"emite decizia de constituire a Comisiei pentru curriculum. Activitatea Comisiei pentru curriculum este coordonată de un responsabil, propus prin vot, de către consiliul profesoral, din rândul personalului didactic de predare titular, cu rezultate deosebite obținute în activitatea didactică. Numirea responsabilului comisiei pentru curriculum se face prin decizie a directorului, emisă în baza unei hotărâri a consiliului de administrație, în urma propunerii primite din partea consiliului profesoral. În cadrul aceleiași unități de învățământ catedrele/comisiile metodice de la nivelul Comisiei pentru curriculum se constituie din cel puțin 4 cadre didactice care își","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B61","theme":"B","prompt":"Două grupuri susțin priorități diferite. Directorul construiește o coaliție și negociază sprijinul pentru alocarea resurselor. Ce model explică cel mai direct procesul?","options":["Modelul colegial.","Modelul cultural.","Modelul formal.","Modelul politic."],"answer":3,"explanation":"Negocierea intereselor, coalițiile și distribuirea resurselor sunt indicii pentru perspectiva politică.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 2, p. 51","quote":"management şi leadership Modelul de management Modelul de leadership Formal Managerial Colegial Participativ Transformaţional Distribuit Politic Tranzacţional Subiectiv Postmodern Emoţional De ambiguitate Circumstanţial Cultural Moral Al instruirii Sursa: adaptat după Bush şi Glover, 2002. Leadershipul instruirii, deseori descris ca fiind leadership centrat pe","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H31","theme":"H","prompt":"Profesorii apreciază atmosfera unui curs, dar nu schimbă nimic în practică. Ce rezultat rămâne nedemonstrat de chestionarul de satisfacție?","options":["Existența unor opinii favorabile despre organizarea întâlnirii.","Faptul că participanții au completat un chestionar.","Faptul că participanților le-a plăcut atmosfera cursului.","Impactul formării asupra practicii și învățării elevilor."],"answer":3,"explanation":"Satisfacția participanților este diferită de schimbarea practicii și de efectele asupra elevilor. Aceste rezultate cer dovezi proprii.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 10, p. 244–245","quote":"Programe de dezvoltare profesională Mult prea frecvent, formarea profesională este evaluată în funcție de efectele asupra profesorului (satisfacție, plăcere și învățare percepută din cursuri) și mult mai puțin în funcție de efectele asupra îmbunătățirii reale a practicii din clasă și de efectele asupra elevilor. *Wade (1985) a împărțit rezultatele în patru","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s10","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=20"}},{"id":"L77","theme":"L","prompt":"Un elev cu CES urmează curriculumul de masă în clasă, prin flexibilizarea predării și acces la instrumente compensatorii. Ce nivel de sprijin descrie textul legal?","options":["Sprijin special de nivel I — bazal.","Sprijin special de nivel II — suplimentar.","Sprijin special de nivel III — intensiv.","Sprijin special de nivel IV — special."],"answer":0,"explanation":"Descrierea reproduce caracteristicile nivelului I: curriculum de masă, flexibilizarea predării și instrumente compensatorii/de dispensare sau tehnologii asistive.","source":{"title":"Legea nr. 198/2023","locator":"Art. 69 alin. (3)","quote":"cu grupa mică din învățământul preșcolar, educația specială se va realiza în baza unui sistem de sprijin pe 4 niveluri, astfel: a) sprijin special de nivel I - bazal; b) sprijin special de nivel II - suplimentar; c) sprijin special de nivel III - intensiv; d) sprijin special de nivel IV - special. (3) Sprijinul special de nivel I - bazal - reprezintă o formă de educație specială de care beneficiază preșcolarii/elevii identificați cu CES‚ inclusiv dizabilități și tulburări specifice de învățare‚ în urma evaluării complexe‚ care urmează curriculumul învățământului de masă‚ în sala de clasă‚ prin flexibilizarea predării cadrului didactic de la clasă‚ în unitatea de învățământ‚","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R77","theme":"R","prompt":"Secretariatul își stabilește singur programul cu publicul, fără aprobări. Cine aprobă programul de lucru cu elevii și părinții?","options":["Administratorul de patrimoniu, în baza planului de curățenie.","Directorul, în baza hotărârii consiliului de administrație.","Președintele consiliului elevilor, în baza unui sondaj online.","Secretarul-șef, în baza propriului registru de corespondență."],"answer":1,"explanation":"Programul secretariatului cu persoanele din afara unității este aprobat de director în baza hotărârii CA, potrivit articolului 73.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 73","quote":"secretar și informatician, analist programator. Compartimentul secretariat este subordonat directorului. Secretariatul funcționează în program de lucru cu elevii, părinții sau reprezentanții legali sau alte persoane interesate din afara unității, aprobat de director, în baza hotărârii consiliului de administrație.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"P31","theme":"P","prompt":"Elevi cu profiluri de învățare diferite întâmpină bariere. Directorul organizează colaborarea cu specialiștii și verifică adaptarea sprijinului la nevoile lor. Ce competență este centrală?","options":["Asigurarea succesului școlar al elevilor și a performanței cadrelor didactice","Colectarea datelor, analiza și formularea de strategii de îmbunătățire a calității","Leadership incluziv, stare de bine a elevilor și a personalului școlii, securitate și siguranță școlară","Managementul incluziunii și al diversității în profilurile de învățare"],"answer":3,"explanation":"Gestionarea diversității profilurilor și a măsurilor de acces și participare reprezintă nucleul competenței 3.3.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"3.3. Managementul incluziunii și al diversității în profilurile de învățare","quote":"asigură educația incluzivă la nivelul unității și implementează măsuri specifice pentru copiii cu CES; gestionează diversitatea culturală, lingvistică și socioeconomică a comunității școlare; implementează măsuri de echitate educațională și previne orice formă de discriminare; promovează egalitatea de șanse și valorizează diversitatea ca resursă instituțională; monitorizează impactul măsurilor de incluziune asupra participării și rezultatelor elevilor; colaborează cu centrele de resurse și asistență educațională, direcțiile generale de asistență socială și protecția copilului și alte instituții de suport pentru elevii vulnerabili.","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"C31","theme":"C","prompt":"Planificarea anuală are unități de învățare fără timp alocat și fără succesiune clară. Ce trebuie completat pentru a deveni funcțională?","options":["Doar coperți diferite pentru fiecare disciplină.","Doar lista sponsorilor care au finanțat imprimarea.","Exclusiv numerele facturilor pentru consumabile.","Succesiunea unităților și bugetul de timp alocat."],"answer":3,"explanation":"Planificarea calendaristică organizează unitățile de învățare și timpul disponibil; nu este numai o înșiruire de titluri.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"așa fel încât să optimizeze învățarea pentru fiecare elev și să asigure progresul individual în dezvoltarea competențelor. De exemplu, în planificarea calendaristică, în proiectarea unităților de învățare și a lecției/ activității de învățare, profesorul este autonom să se orienteze în funcție de ritmurile de învățare ale elevilor, de nivelurile lor de performanță și de potențialul lor de învățare. Schemele de mai jos ilustrează demersul logic secvențial al planificării și proiectării activității didactice la clasă (planificarea calendaristică, proiectarea unității de învățare, proiectarea lecției/ activității de învățare). Toate aceste componente ale proiectării sunt interdependente","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L78","theme":"L","prompt":"O școală cere familiei să achite activitățile de educație specială, motivând că elevul are nevoie de sprijin intens. Ce regulă se aplică?","options":["Activitățile sunt gratuite numai pentru primul nivel de sprijin.","Activitățile și serviciile sunt gratuite, indiferent de nivelul de sprijin.","Serviciile devin obligatoriu cu plată după stabilirea nivelului de sprijin.","Serviciile sunt gratuite numai în prima lună de școlarizare."],"answer":1,"explanation":"Articolul 70 alineatul (4) stabilește gratuitatea tuturor activităților și serviciilor de educație specială, indiferent de nivelul sprijinului.","source":{"title":"Legea nr. 198/2023","locator":"Art. 70 alin. (4)","quote":"art. 139 alin. (2) lit. c) și alin. (6). (4) Toate activitățile și serviciile de educație specială, indiferent de nivelul de sprijin, sunt gratuite. (5) Antepreșcolarii/Preșcolarii/Elevii cu CES, școlarizați în unitățile de învățământ de masă sau în unități de învățământ special, de stat și particulare, inclusiv cei școlarizați în alt județ decât cel de domiciliu, beneficiază, pe perioada anului școlar, de una dintre următoarele forme de sprijin: a) vouchere educaționale în cuantum fix, pentru servicii de sprijin, intervenții psihopedagogice și materiale-suport, de la bugetul de stat, din sume defalcate din unele venituri ale bugetului de stat; Notă Conform alin. (2)","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R78","theme":"R","prompt":"Bugetul a fost aprobat cu alte limite decât cele estimate inițial. Ce document trebuie actualizat de director și CA pentru încadrarea achizițiilor în fonduri?","options":["Catalogul școlar al clasei pregătitoare.","Graficul audiențelor comitetului de părinți.","Programul anual de achiziții publice.","Registrul matricol al absolvenților."],"answer":2,"explanation":"Pe baza bugetului aprobat, directorul și CA actualizează programul anual de achiziții și iau măsurile necesare încadrării cheltuielilor în fondurile alocate.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 79","quote":"Pe baza bugetului aprobat, directorul și consiliul de administrație actualizează programul anual de achiziții publice, stabilind și celelalte măsuri ce se impun pentru asigurarea încadrării tuturor categoriilor de cheltuieli în limitele fondurilor alocate.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B62","theme":"B","prompt":"Noii profesori află ce contează în școală din ritualuri, povești despre foști colegi și simboluri comune. Ce model pune aceste elemente în centru?","options":["Modelul ambiguității.","Modelul cultural.","Modelul formal.","Modelul politic."],"answer":1,"explanation":"Valorile, simbolurile, ritualurile și tradițiile sunt elemente centrale ale perspectivei culturale.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 2, p. 51","quote":"Colegial Participativ Transformaţional Distribuit Politic Tranzacţional Subiectiv Postmodern Emoţional De ambiguitate Circumstanţial Cultural Moral Al instruirii Sursa: adaptat după Bush şi Glover, 2002. Leadershipul instruirii, deseori descris ca fiind leadership centrat pe învăţare, nu se leagă de niciun model de management, deoarece se concentrează asupra","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H32","theme":"H","prompt":"Un mentor oferă sfaturi la întâmplare, fără obiectiv, observare sau revenire asupra progresului. Ce demers ar structura mai bine sprijinul?","options":["O listă de impresii personale, păstrată fără legătură cu practica.","Obiective clare, observare, feedback și urmărirea efectelor intervenției.","Recomandări diferite la fiecare întâlnire, fără verificarea vreunui efect.","Un verdict final despre profesor, fără discutarea situațiilor observate."],"answer":1,"explanation":"Sprijinul profesional urmărește obiective, practici și efecte, nu numai furnizarea de sfaturi fără legătură cu observația.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 11, p. 246–246","quote":"impactul asupra performanței elevilor. Numitorul comun al multor modele de instruire include analizarea situației curente standard, stabilirea de obiective, identificarea intervenției și oferirea de sprijin până la îndeplinirea obiectivelor (adesea cu observații și reacții din partea clasei). Instruirea tinde să fie „individualizată, consumatoare de timp, cu o durată de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s11","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=22"}},{"id":"L79","theme":"L","prompt":"Pentru un elev cu CES se analizează prelungirea școlarizării, în funcție de nevoile individuale și metodologia aplicabilă. Care este limita legală a prelungirii?","options":["Până la cinci ani.","Până la doi ani.","Până la patru ani.","Până la trei ani."],"answer":3,"explanation":"Articolul 71 permite prelungirea cu până la trei ani; durata concretă depinde de nevoile individuale, dizabilitate și CES, potrivit metodologiei.","source":{"title":"Legea nr. 198/2023","locator":"Art. 71 alin. (1)","quote":"(1) Prin excepție de la prevederile art. 15, durata școlarizării elevilor cu CES poate fi prelungită cu până la 3 ani și se stabilește, în funcție de nevoile individuale, de tipul și nivelul de severitate a dizabilității și a CES, conform metodologiei aprobate prin ordin al ministrului educației. (2) Educația specială realizată în cadrul învățământului special și special integrat dispune de planuri de învățământ, de programe școlare, de programe de asistență psihopedagogică, de manuale și de metodologii didactice alternative, precum și de metode de evaluare adaptate tipului și nivelului de severitate a dizabilității și aprobate prin ordin","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R79","theme":"R","prompt":"Un copil fără cod numeric personal solicită acces la învățământul obligatoriu. Școala îl respinge automat numai din acest motiv. Ce obligație prevede ROFUIP?","options":["Înscrierea exclusiv într-o unitate particulară cu taxă.","Înscrierea potrivit normelor aplicabile persoanelor fără CNP.","Respingerea până la împlinirea vârstei de optsprezece ani.","Respingerea până la obținerea cetățeniei române."],"answer":1,"explanation":"ROFUIP obligă unitățile să înscrie persoanele fără CNP pentru accesul la învățământul obligatoriu, cu respectarea normelor din anexa indicată.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 89","quote":"vederea asigurării accesului la învățământul obligatoriu, unitățile de învățământ preuniversitar au obligația de a înscrie persoanele care nu dețin un cod numeric personal, în conformitate cu prevederile art. 105 alin. (11) din Legea învățământului preuniversitar nr. 198/2023, cu modificările ulterioare. Normele metodologice pentru înmatricularea persoanelor care nu dețin un cod numeric personal, sunt prevăzute în Anexa nr. 2 la prezentul regulament.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B63","theme":"B","prompt":"O decizie pedagogică este construită prin deliberarea profesioniștilor și căutarea unei soluții acceptate împreună. Ce model este dominant?","options":["Modelul colegial.","Modelul formal.","Modelul politic.","Modelul subiectiv."],"answer":0,"explanation":"Participarea profesională și consensul sunt caracteristice colegialității; nu orice reuniune de grup este însă automat colegială.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 2, p. 51","quote":"de management Tabelul 2.1. Tipologia modelelor de management şi leadership Modelul de management Modelul de leadership Formal Managerial Colegial Participativ Transformaţional Distribuit Politic Tranzacţional Subiectiv Postmodern Emoţional De ambiguitate Circumstanţial Cultural Moral Al instruirii Sursa: adaptat după Bush şi Glover, 2002. Leadershipul","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}}]},{"id":17,"title":"Simularea 17","items":[{"id":"L85","theme":"L","prompt":"Școala repartizează separat copiii din familii sărace, creând o clasă cu o concentrare disproporționată a acestui grup. Ce risc juridic rezultă?","options":["Autonomie curriculară fără legătură cu dreptul la educație.","Evaluare individuală obligatorie pentru toate clasele paralele.","Segregare școlară pe criteriul statutului socioeconomic.","Selecție profesională specifică învățământului postliceal."],"answer":2,"explanation":"Segregarea este interzisă inclusiv pe criteriul statutului socioeconomic. Separarea fizică disproporționată a unui grup nu devine legitimă prin invocarea comodității organizatorice.","source":{"title":"Legea nr. 198/2023","locator":"Art. 79 alin. (3)-(5)","quote":"(3) În învățământul preuniversitar este interzisă segregarea școlară pe criteriul etnic, al dizabilității sau al CES, pe criteriul statutului socioeconomic al familiilor, al apartenenței la o categorie defavorizată, al mediului de rezidență sau al performanțelor școlare ale beneficiarilor primari ai educației, în condițiile prevăzute de lege. (4) Segregarea este o formă gravă de discriminare prin care se restrânge sau se înlătură recunoașterea, folosința sau exercitarea, în condiții de egalitate, a dreptului la educație, a drepturilor omului și a libertăților fundamentale, precum și a drepturilor recunoscute de lege în domeniul educației, având drept consecință accesul inegal","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R85","theme":"R","prompt":"Un elev de la profil sportiv are media anuală 5 la disciplina principală de specialitate. Școala afirmă că pragul de 5 este suficient pentru menținerea profilului. Ce prag specific prevede ROFUIP?","options":["Cel puțin media 5 la disciplina principală de specialitate.","Cel puțin media 6 la disciplina principală de specialitate.","Cel puțin media 7 la disciplina principală de specialitate.","Cel puțin media 8 la disciplina principală de specialitate."],"answer":1,"explanation":"Pentru profilurile artistic și sportiv se cere minimum 6 la disciplina principală de specialitate. Articolul prevede transferul la alte profiluri pentru neîndeplinirea condițiilor specifice.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 116","quote":"Elevii de la clasele cu profil artistic sau sportiv trebuie să obțină media cel puțin 6 la disciplina principală de specialitate, pentru aceste profiluri/specializări. Elevii de la clasele cu specializările muzică, coregrafie și arta actorului trebuie să obțină cel puțin nota 6 pentru specializarea respectivă la examenul de sfârșit de an școlar. Elevii de la clasele cu specializările arte vizuale, arte plastice, arte decorative, arhitectură, arte ambientale, design, conservare-restaurare bunuri culturale trebuie să obțină la toate disciplinele practice de specialitate media anuală cel puțin 6. Elevii de la","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B68","theme":"B","prompt":"Un laborator complex este administrat de profesori cu expertiză relevantă, cu atribuții delimitate. Ce principiu structural se observă?","options":["Distribuirea aleatorie a tuturor sarcinilor.","Eliminarea expertizei profesionale.","Identitatea obligatorie a tuturor rolurilor.","Specializarea sarcinilor."],"answer":3,"explanation":"Specializarea valorifică expertiza prin distribuirea diferențiată a sarcinilor și responsabilităților.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 57","quote":"funcţionează mai eficient în momentul în care tulburările de mediu şi preferinţele personale sunt limitate de norme şi raţiune. 4. Specializarea permite un nivel mai ridicat de expertiză şi performanţă individuală. 5. Coordonarea şi controlul sunt esenţiale pentru eficacitate. 6. Problemele organizaţionale îşi au de obicei originea în structurile nepotrivite","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"C34","theme":"C","prompt":"Descriptorii standardelor sunt suficient de expliciți pentru proiectarea unei lecții. Profesorul întreabă dacă trebuie neapărat rescriși ca obiective distincte. Ce precizare oferă CRCNR?","options":["Descriptorii pot fi ignorați dacă profesorul preferă manualul.","Obiectivele pot completa descriptorii atunci când este necesar.","Obiectivele sunt exclusiv denumiri ale resurselor materiale folosite.","Obiectivele trebuie să anuleze întotdeauna descriptorii standardelor."],"answer":1,"explanation":"CRCN permite obiectivelor de învățare să completeze descriptorii când aceștia nu sunt suficient de expliciți. Nu cere înlocuirea mecanică a unor repere deja clare.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"de învățare care să îl conducă pe elev la atingerea standardelor de învățare vizate prin lecția pe care o proiectez? Dacă da, voi formula obiectivele de învățare ale lecției. Dacă nu, mă voi orienta după descriptorii nivelurilor de performanță din structura standardului național de evaluare. (În cadrul CRCNR, obiectivele de învățare reflectă așteptările referitoare la ce va învăța elevul pe parcursul lecției. Acestea, prin operaționalizare, conduc progresiv la atingerea standardelor de învățare, nesubstituindu-se descriptorilor nivelurilor de performanță.) Ce prerechizite ale învățării au elevii și cum vor fi valorificate acestea pentru realizarea standardelor de învățare vizate?","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L81","theme":"L","prompt":"Familia unui copil școlarizat în spital nu cunoaște drepturile educaționale și nu a cerut consiliere administrativă. Ce obligație există potrivit articolului 73?","options":["Consiliere din oficiu, obligatorie, prin inspectorul desemnat.","Consiliere exclusiv contra cost, prin furnizorul ales de familie.","Consiliere numai dacă familia a depus anterior o contestație.","Consiliere numai după încheierea întregii perioade de spitalizare."],"answer":0,"explanation":"Consilierea administrativă privind drepturile educaționale se asigură din oficiu de inspectorul desemnat. Nu depinde de o cerere separată de consiliere.","source":{"title":"Legea nr. 198/2023","locator":"Art. 73 alin. (1)","quote":"beneficiază de consiliere administrativă cu privire la drepturile educaționale pe care le au. Consilierea administrativă se realizează din oficiu, obligatoriu, de către un inspector desemnat de către DJIP/DMBIP, în conformitate cu metodologia-cadru aprobată prin ordin al ministrului educației. Dosarul conținând documentele școlare și orice alt act necesar pentru înscrierea la „Școala din spital“ și, ulterior perioadei de spitalizare, pentru revenirea cu prezența fizică în unitatea de învățământ de bază va fi întocmit instituțional de către inspectorul școlar desemnat, în baza cererii părintelui/ reprezentantului legal al elevului. (2) Pe toată perioada școlarizării în spital se","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R81","theme":"R","prompt":"Un elev este prezent la oră, dar profesorul îi trece absență pentru că nu și-a făcut tema. Cum se apreciază folosirea absenței?","options":["Este nepermisă doar dacă elevul are deja media încheiată.","Este nepermisă: absența nu poate fi mijloc de coerciție.","Este permisă: profesorul poate inventa motive suplimentare.","Este permisă: tema nefăcută echivalează cu lipsa fizică."],"answer":1,"explanation":"Absența se consemnează numai când elevul nu este prezent la ora de curs. Nu se utilizează ca sancțiune sau mijloc de constrângere.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 94","quote":"absență. Absența se consemnează în catalog doar în cazul în care elevul nu este prezent la ora de curs și nu poate fi folosită drept mijloc de coerciție. Motivarea absențelor se face de către educatorul/învățătorul/institutorul/profesorul pentru învățământul primar/profesorul diriginte în ziua prezentării actelor justificative. În cazul beneficiarilor primari minori, părinții sau reprezentanții legali au obligația de a prezenta personal învățătorului/institutorului/profesorului pentru învățământul primar/ profesorului diriginte actele justificative pentru absențele copilului său. Actele medicale pe baza cărora se face motivarea absențelor sunt, după caz: adeverință","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B65","theme":"B","prompt":"În loc să presupună o singură realitate, cercetătorul urmărește interpretări multiple și discursurile prin care membrii construiesc sensul reformei. Ce perspectivă din tabelul lui Bush este apropiată?","options":["Perspectiva exclusiv birocratică.","Perspectiva exclusiv ierarhică.","Perspectiva managerială formală.","Perspectiva postmodernă."],"answer":3,"explanation":"Perspectiva postmodernă acordă atenție multiplicității sensurilor și vocilor, în locul unei interpretări unice impuse.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 2, p. 51","quote":"de management Modelul de leadership Formal Managerial Colegial Participativ Transformaţional Distribuit Politic Tranzacţional Subiectiv Postmodern Emoţional De ambiguitate Circumstanţial Cultural Moral Al instruirii Sursa: adaptat după Bush şi Glover, 2002. Leadershipul instruirii, deseori descris ca fiind leadership centrat pe învăţare, nu se leagă de niciun","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H33","theme":"H","prompt":"La analiza unei lecții filmate, profesorii discută exclusiv aspectul vestimentar al colegului. Cum poate deveni analiza utilă profesional?","options":["Înlocuind observația cu votul despre cine pare mai carismatic.","Limitând observația la preferințele personale privind hainele profesorului.","Orientând observația spre interacțiuni, participare și învățarea elevilor.","Renunțând la orice întrebare despre activitatea elevilor din lecție."],"answer":2,"explanation":"Analiza video poate sprijini reflecția când urmărește procese relevante pentru predare și învățare. Observația trebuie să aibă un scop profesional.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 12, p. 247–248","quote":"class=\"chapter\"> SECȚIUNEA 12 Micropredarea/analiza video a lecțiilor Pag. 247–248 Pagina 247 Vezi pagina originală ↗ că instruirea (0,04) era foarte puțin diferită de programele extrașcolare (0,02), de oferirea de stimulente (0,01), de programele de vară (0,03), de formarea","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s12","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=23"}},{"id":"L82","theme":"L","prompt":"O școală decide să organizeze „Școala după școală” numai pentru că o altă școală are programul, fără să analizeze nevoile proprii. Pe ce trebuie fundamentată hotărârea CA?","options":["Pe o analiză de nevoi a unității de învățământ.","Pe o comparație exclusivă a denumirilor programelor altor școli.","Pe o decizie individuală a președintelui comitetului de părinți.","Pe o listă a preferințelor comerciale ale furnizorilor."],"answer":0,"explanation":"Hotărârea de derulare a programului se adoptă de CA pe baza unei analize de nevoi. Copierea unei inițiative nu ține locul fundamentării cerute de lege.","source":{"title":"Legea nr. 198/2023","locator":"Art. 74 alin. (3)","quote":"a programului „Școala după școală“ se adoptă de unitatea de învățământ preuniversitar, prin hotărârea consiliului de administrație, pe baza unei analize de nevoi. Activitățile desfășurate în cadrul acestuia pot fi extinse cu elevii după sau înaintea orelor de curs, dacă unitatea de învățământ dispune de infrastructura și de personalul de specialitate necesare implementării. (4) Statul finanțează, din bugetul de stat, din sumele defalcate din unele venituri ale bugetului de stat, în limita sumelor alocate cu această destinație, programul „Școala după școală“ pentru elevii din învățământul primar, gimnazial și liceal. Notă Conform alin. (2) al art. LI din ORDONANȚA DE URGENȚĂ nr. 156","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R82","theme":"R","prompt":"Un beneficiar înregistrează absențe la cel puțin 75% din orele prevăzute într-un an la disciplinele respective. Ce obligație are directorul potrivit articolului 95?","options":["Anunță exclusiv comitetul de părinți și suspendă orice intervenție.","Anunță exclusiv furnizorul catalogului și închide cazul administrativ.","Anunță serviciile de asistență socială și contribuie la măsuri de prevenire.","Așteaptă obligatoriu doi ani fără să informeze serviciile competente."],"answer":2,"explanation":"Directorul anunță SPAS/DAS și contribuie la stabilirea măsurilor pentru prevenirea abandonului. Informarea nu se amână până la pierderea a doi ani școlari.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 95 alin. (4)","quote":"cu modificările și completările ulterioare. (4) Directorul unității de învățământ are obligația să anunțe serviciile de asistență socială (SPAS/DAS) și să contribuie la stabilirea unor măsuri de prevenire a abandonului școlar, în cazul beneficiarilor primari care înregistrează absențe la cel puțin 75% din numărul de ore de curs prevăzut într-un an școlar la disciplinele/modulele respective.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"P33","theme":"P","prompt":"Școala are nevoie de competențe profesionale noi. Directorul corelează recrutarea, distribuirea sarcinilor și dezvoltarea personalului cu nevoile instituției. Ce competență este ilustrată?","options":["Antreprenoriat educațional și inovație","Cercetare, inovație pedagogică și conceptualizare strategică","Managementul implementării curriculumului și al proceselor de evaluare","Managementul resurselor umane"],"answer":3,"explanation":"Planificarea, folosirea și dezvoltarea personalului sunt componente ale managementului resurselor umane.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"4.1. Managementul resurselor umane","quote":"analizează periodic nevoile de formare ale personalului; elaborează și implementează planul de formare continuă la nivelul unității, corelat cu prioritățile strategice; sprijină cadrele didactice debutante și facilitează inserția lor profesională — mentorat, coaching; utilizează tehnici de motivare a personalului didactic și administrativ; distribuie responsabilitățile în mod echilibrat și transparent; creează oportunități pentru dezvoltarea competențelor digitale ale personalului; gestionează cu profesionalism procedurile disciplinare atunci când este necesar; monitorizează nivelul de satisfacție și implicare al personalului.","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"C33","theme":"C","prompt":"Elevii nu au unele achiziții necesare pentru noua lecție. Profesorul verifică mai întâi aceste achiziții și adaptează începutul demersului. Ce rol au prerechizitele?","options":["Constituie punctul de sprijin pentru construirea noii învățări.","Înlocuiesc definitiv orice competență nouă din programa școlară.","Permit eliminarea oricărei evaluări inițiale a înțelegerii.","Reprezintă exclusiv inventarul de echipamente din laborator."],"answer":0,"explanation":"Analiza prerechizitelor clarifică pe ce achiziții anterioare poate fi construită învățarea și unde sunt necesare intervenții de sprijin.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"operaționalizare, conduc progresiv la atingerea standardelor de învățare, nesubstituindu-se descriptorilor nivelurilor de performanță.) Ce prerechizite ale învățării au elevii și cum vor fi valorificate acestea pentru realizarea standardelor de învățare vizate? Care sunt cele mai relevante conținuturi, din punct de vedere calitativ și cantitativ, pentru standardele de învățare vizate? Cum organizez, selectez, adaptez și integrez conținuturile învățării din lecție, inclusiv în funcție de nevoile de învățare ale elevilor? Care sunt activitățile de învățare cele mai relevante pentru standardele de învățare și pentru conținuturile învățării vizate? Cum adaptez activitățile de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L83","theme":"L","prompt":"Mai mulți elevi au nevoie justificată de pregătire remedială în vacanță. Echipa susține că legea interzice orice activitate remedială atunci. Ce posibilitate prevede articolul 75?","options":["Activități în vacanță, exclusiv prin decizia furnizorului de manuale.","Activități în vacanță, prin decizia CA și consultarea beneficiarilor.","Activități numai după absolvirea nivelului de învățământ.","Activități numai în cursuri, fără nicio excepție justificată."],"answer":1,"explanation":"În situații justificate, activitățile remediale se pot desfășura în vacanțe sau zile libere, la decizia CA și cu consultarea beneficiarilor primari și secundari.","source":{"title":"Legea nr. 198/2023","locator":"Art. 75 alin. (5)","quote":"actualizarea și îmbunătățirea competențelor, în perspectiva deschiderii noului an școlar, activitățile remediale se pot desfășura și pe durata vacanței școlare sau a zilelor libere, la decizia consiliului de administrație al unității de învățământ, cu consultarea beneficiarilor primari și secundari ai educației. (6) Activitățile realizate în cadrul programului „Învățare remedială“ sunt evaluate periodic de către ARACIIP și au ca scop reducerea abandonului școlar/părăsirii timpurii a școlii, inclusiv creșterea performanței elevilor la evaluările naționale și suport în dobândirea tuturor competențelor-cheie prevăzute în planul-cadru, în conformitate cu prevederile metodologiei","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R83","theme":"R","prompt":"Un profesor refuză să încheie situația anuală, deși elevii au note suficiente. Ce mecanism prevede ROFUIP pentru finalizarea situației?","options":["CA desemnează un cadru didactic care să o încheie în locul acestuia.","Comitetul de părinți calculează și înscrie mediile în catalog.","Elevii își calculează mediile și le înscriu în registrul matricol.","Secretariatul declară automat toți elevii repetenți la disciplină."],"answer":0,"explanation":"În această situație, CA desemnează alt cadru didactic pentru încheierea situației școlare. Refuzul profesorului nu trebuie să blocheze drepturile elevilor.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 108","quote":"să încheie situația școlară a beneficiarilor primari și elevii au note suficiente, consiliul de administrație al unității de învățământ va desemna un cadru didactic care să le încheie situația școlară în locul acestuia. La sfârșitul fiecărui interval de cursuri, învățătorul/institutorul/profesorul pentru învățământul primar/profesorul diriginte consultă consiliul clasei pentru acordarea notei la purtare pentru intervalul respectiv, prin care este evaluat comportamentul elevului, precum și respectarea de către acesta a reglementărilor adoptate de unitatea de învățământ. La sfârșitul anului școlar, învățătorul/institutorul/profesorul pentru învățământul primar/profesorul diriginte","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B66","theme":"B","prompt":"Un formator prezintă corespondența dintre modelele de management și leadership ca fiind absolută. Ce nuanță trebuie păstrată pentru leadershipul instruirii?","options":["Poate avea legături cu mai multe modele, nu cu unul singur în mod exclusiv.","Poate exista numai într-un model cultural, fără alte legături.","Poate exista numai într-un model politic, indiferent de context.","Poate fi definit exclusiv prin regulile de evidență financiară."],"answer":0,"explanation":"Tabelul este orientativ. Focalizarea pe predare și învățare nu trebuie redusă la o asociere exclusivă și rigidă cu un singur model.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 2, p. 51","quote":"deseori descris ca fiind leadership centrat pe învăţare, nu se leagă de niciun model de management, deoarece se concentrează asupra direcţiei influenţării, învăţării şi predării, şi nu asupra naturii proceselor de influenţă. Acest model a fost discutat în capitolul 1, iar celelalte nouă modele de leadership vor fi abordate în cadrul modelului de management","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H34","theme":"H","prompt":"Un profesor stăpânește disciplina, dar nu poate explica de ce elevii greșesc în mod repetat același concept. Ce cunoaștere trebuie dezvoltată?","options":["Cunoașterea exclusivă a datelor de inventar ale laboratorului.","Cunoașterea exclusivă a procedurilor de achiziție a manualelor.","Cunoașterea exclusivă a vechimii fiecărui elev în unitate.","Cunoașterea pedagogică a conținutului și a dificultăților de învățare."],"answer":3,"explanation":"Expertiza didactică include reprezentarea conținutului pentru învățare, anticiparea dificultăților și găsirea unor explicații adecvate.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 13, p. 249–250","quote":"Pagina 249 Vezi pagina originală ↗ și colaboratorii (2008) în funcție de două categorii principale: cunoașterea materiei și cunoașterea conținutului pedagogic (figura 9.2). În cazul matematicii, de exemplu, au argumentat că această cunoaștere de către profesori viza raționamentul matematic, cunoașterea elevilor și „poate chiar un tip special de raționament despre gândirea","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s13","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=25"}},{"id":"L84","theme":"L","prompt":"O elevă gravidă solicită un program care să îi permită continuarea studiilor. Școala îi oferă numai retragerea din evidență. Ce obligație legală trebuie avută în vedere?","options":["O retragere obligatorie până când copilul împlinește trei ani.","O transferare obligatorie în învățământul particular cu taxă.","Un program adaptat nevoilor, inclusiv online acolo unde este posibil.","Un program exclusiv identic, fără posibilitatea vreunei adaptări."],"answer":2,"explanation":"Legea prevede un program de studiu adaptat pentru elevele gravide și elevii părinți, inclusiv posibilitatea învățării online acolo unde este posibil.","source":{"title":"Legea nr. 198/2023","locator":"Art. 76 alin. (2)","quote":"discriminare, inclusiv prin asigurarea unui mediu de învățare sigur și incluziv. (2) Elevele gravide și elevii părinți vor beneficia de un program de studiu adaptat nevoilor lor, care să le permită să își continue studiile, inclusiv prin oferirea posibilității de învățare online, acolo unde este posibil. (3) În vederea protejării dreptului la educație al elevelor gravide și al elevilor părinți, Ministerul Educației elaborează, în termen de 12 luni de la data intrării în vigoare a prezentei legi, o metodologie specifică privind școlarizarea elevelor gravide și a elevilor părinți, aprobată prin ordin al ministrului educației. (4) Ministerul Educației, în colaborare cu Ministerul","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R84","theme":"R","prompt":"La clasa a III-a, profesorul dorește să stabilească calificativul anual prin media aritmetică a unor numere atribuite calificativelor. Care este mecanismul ROFUIP?","options":["Alege două calificative cu frecvență maximă și decide după evaluarea sumativă și criterii.","Folosește exclusiv calificativul cel mai mic, indiferent de progresul elevului.","Preia automat ultimul calificativ, indiferent de evoluția elevului pe parcurs.","Transformă toate calificativele în note și rotunjește automat media aritmetică."],"answer":0,"explanation":"Se aleg cele două calificative cu frecvența cea mai mare; opțiunea finală ține cont de probele sumative și criterii precum progresul, efortul și motivația.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 110","quote":"la fiecare disciplină de studiu. Pentru aceste clase, calificativul pe disciplină se stabilește astfel: se aleg două calificative cu frecvența cea mai mare, acordate în timpul anului școlar, după care, în perioadele de recapitulare și de consolidare a materiei, în urma aplicării unor probe de evaluare sumativă, cadrul didactic poate opta pentru unul dintre cele două calificative, în baza următoarelor criterii: progresul sau regresul elevului; raportul efort-performanță realizată; creșterea sau descreșterea motivației elevului; realizarea unor sarcini din programul suplimentar de pregătire sau de recuperare, stabilite de cadrul didactic și care au fost aduse la cunoștința","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B67","theme":"B","prompt":"Doi responsabili aprobă aceeași operațiune, iar altele rămân fără responsabil. Ce intervenție structurală ar răspunde problemei?","options":["Clarificarea rolurilor, relațiilor și responsabilităților.","Eliminarea oricărei responsabilități individuale pentru operațiuni.","Înlocuirea structurii cu promisiunea că nu vor mai exista probleme.","Multiplicarea acelorași aprobări fără delimitarea atribuțiilor."],"answer":0,"explanation":"Restructurarea poate clarifica rolurile și relațiile. Este necesară analiza suprapunerilor și golurilor de responsabilitate.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 57","quote":"6. Problemele organizaţionale îşi au de obicei originea în structurile nepotrivite sau sistemele inadecvate şi pot fi rezolvate prin restructurare sau crearea de noi sisteme. Ipotezele structurale identificate de Bolman şi Deal, inclusiv orientarea scopurilor, raţionalitatea, exercitarea autorităţii şi referinţa la sisteme, corespund caracteristicilor centrale","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"P34","theme":"P","prompt":"Conducerea verifică dacă predarea și evaluarea urmăresc coerent curriculumul și dacă implementarea este adaptată situației elevilor. Ce competență specifică este vizată?","options":["Asigurarea succesului școlar al elevilor și a performanței cadrelor didactice","Colectarea datelor, analiza și formularea de strategii de îmbunătățire a calității","Managementul implementării curriculumului și al proceselor de evaluare","Managementul incluziunii și al diversității în profilurile de învățare"],"answer":2,"explanation":"Competența 4.2 privește managementul implementării curriculumului și al proceselor de evaluare, nu numai inovarea sau recrutarea.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"4.2. Managementul implementării curriculumului și al proceselor de evaluare","quote":"Coordonează elaborarea și implementarea curriculumului, asigurând coerența verticală și orizontală și monitorizând calitatea procesului didactic și echitatea evaluării. coordonează elaborarea și implementarea curriculumului, inclusiv a curriculumului la decizia elevului din oferta școlii, cu implicarea elevilor; asigură coerența verticală și orizontală a curriculumului la nivelul unității; verifică alinierea planificărilor didactice la curriculum și oferă feedback constructiv cadrelor didactice; monitorizează calitatea procesului didactic prin observări de lecții, analiza documentară și discuții profesionale; monitorizează coerența și echitatea evaluării la nivel instituțional; încurajează utilizarea evaluării formative ca instrument de îmbunătățire a învățării; corelează datele privind rezultatele elevilor cu deciziile curriculare și de ","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}}]},{"id":18,"title":"Simularea 18","items":[{"id":"R90","theme":"R","prompt":"Între elevul corigent și profesorul care l-a evaluat există un conflict care poate vicia examinarea. Ce soluție excepțională permite regulamentul?","options":["Excluderea elevului din sesiune, fără posibilitatea examinării.","Menținerea obligatorie a profesorului, indiferent de efectul conflictului.","Numirea altui cadru didactic de specialitate sau de specialitate înrudită.","Numirea obligatorie a unui părinte fără calificare în specialitate."],"answer":2,"explanation":"De regulă, un examinator este profesorul care a predat disciplina. În conflictul prevăzut, se poate numi alt cadru didactic calificat conform articolului.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 131","quote":"disciplina/modulul de învățământ în timpul anului școlar. În mod excepțional, în situația în care între elev și profesor există un conflict care ar putea vicia rezultatul evaluării, în comisia de examen este numit un alt cadru didactic de aceeași specialitate sau, după caz, de specialități înrudite din aceeași arie curriculară.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B72","theme":"B","prompt":"O regulă internă continuă să fie aplicată deși împiedică activitatea pentru care a fost creată. Ce risc al birocrației ilustrează situația?","options":["Expertiza înlocuiește toate responsabilitățile.","Organizația renunță complet la orice procedură.","Regulile devin scopuri în sine.","Scopurile educaționale ghidează toate regulile."],"answer":2,"explanation":"Disfuncția apare când respectarea regulii se substituie rațiunii ei de a fi și scopului pe care trebuia să îl servească.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 64","quote":"ei devin o influenţă prea dominantă asupra modului de operare al şcolilor şi colegiilor. Există teama că birocraţia poate deveni raţiunea de a fi a organizaţiei, în loc ca aceasta să fie subordonată scopurilor educaţionale. Birocraţia este modelul preferat pentru multe sisteme educaţionale, incluzând Republica Cehă (Svecova, 2000), China (Bush et al., 1998),","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"C36","theme":"C","prompt":"Schema orară este alcătuită fără să includă opțiunile aprobate pentru clasă. Ce funcție a documentului nu este îndeplinită?","options":["Certificarea calificării profesionale a fiecărui profesor titular.","Înlocuirea tuturor programelor naționale cu reguli contabile.","Particularizarea planului-cadru la situația și opțiunile clasei.","Stabilirea cuantumului burselor pentru întreaga unitate."],"answer":2,"explanation":"Schema orară particularizează planul-cadru pentru clasa respectivă. Trebuie să reflecte opțiunile și configurația curriculară aplicabilă.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"calitatea activității de predare-învățare-evaluare etc.; realizarea schemelor orare pe baza planurilor-cadru de învățământ în vigoare; schema orară particularizează planul-cadru de învățământ pentru o anumită clasă, incluzând orele alocate pentru disciplinele din trunchiul comun și orele pentru CS flexibil și CDEOȘ, ca rezultat al opțiunilor elevilor; abilitarea profesorilor pentru aplicarea la clasă a unor noi programe școlare pornind de la recunoașterea rolului acestora, ca practicieni în educație, în producerea schimbării; este necesar ca profesorii să înțeleagă cerințele programei școlare și să le transpună în documentele de proiectare și în activitatea desfășurată cu elevii;","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L86","theme":"L","prompt":"Cabinetul medical școlar propune o taxă pentru serviciile acordate elevilor din unitate. Ce regulă stabilește articolul 82?","options":["Serviciile medicale sunt gratuite numai în primul an școlar.","Serviciile medicale și stomatologice școlare sunt gratuite.","Serviciile stomatologice sunt plătite obligatoriu de familie.","Serviciile sunt gratuite numai pentru elevii din clasa pregătitoare."],"answer":1,"explanation":"Articolul 82 alineatul (2) stabilește gratuitatea serviciilor medicale și stomatologice școlare pentru antepreșcolarii, preșcolarii și elevii din unitățile indicate.","source":{"title":"Legea nr. 198/2023","locator":"Art. 82 alin. (2)","quote":"medicină școlară până în anul 2027. (2) Serviciile medicale și stomatologice școlare furnizate de un cabinet medical/stomatologic școlar sunt gratuite pentru antepreșcolarii, preșcolarii și elevii din unitățile de învățământ preuniversitar prevăzute la alin. (1). (3) Conducerea unităților de învățământ preuniversitar, cadrele didactice, personalul administrativ și auxiliar colaborează cu personalul medico-sanitar din cabinetul medical al unității de învățământ, conform ordinului comun al ministrului sănătății și al ministrului educației. Până la înființarea cabinetelor medicale potrivit alin. (1), unitățile de învățământ preuniversitar sunt arondate cabinetului medical","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R86","theme":"R","prompt":"Un elev a absentat la 55% din orele unei discipline și nu are numărul minim de note pentru încheiere. Cum se încadrează situația potrivit ROFUIP?","options":["Elev amânat la disciplina respectivă.","Elev corigent automat, indiferent de evaluări.","Elev exmatriculat automat din unitatea școlară.","Elev promovat automat la disciplina respectivă."],"answer":0,"explanation":"Pentru motivul dat, sunt relevante atât absențele la cel puțin 50% din ore, cât și lipsa numărului minim de note. Situația se încadrează la amânare.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 117","quote":"situația școlară la una sau la mai multe discipline de studiu/module din următoarele motive: au absentat, motivat și nemotivat, la cel puțin 50% din numărul de ore de curs prevăzut într-un an școlar la disciplinele/modulele respective și nu au numărul minim de calificative/ note prevăzut de prezentul regulament; au fost scutiți de frecvență de către directorul unității de învățământ în urma unor solicitări oficiale, pentru perioada participării la festivaluri și concursuri profesionale, cultural-artistice și sportive, interne și internaționale, cantonamente și pregătire specializată; au beneficiat de bursă de studiu în străinătate, recunoscută de Ministerul","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B69","theme":"B","prompt":"Școala primește semnale de la comunitate, își adaptează oferta și influențează la rândul ei partenerii locali. Ce tip de sistem descrie această interacțiune?","options":["Un sistem deschis.","Un sistem fără mediu.","Un sistem fără schimburi.","Un sistem închis."],"answer":0,"explanation":"Sistemele deschise au schimburi și relații cu mediul; granițele organizației nu elimină interdependența.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 61","quote":"a fost abandonat şi a început căutarea unor modele mai folositoare”. Teoria alternativă este cea a „sistemelor deschise”, ce presupune graniţe permeabile şi o relaţie interactivă, în două sensuri, între şcoli şi colegii şi mediul extern. Hoy şi Miskel (1987: 29) afirmă că „sistemele din şcoli sunt acum considerate sisteme deschise, care trebuie să se adapteze","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H35","theme":"H","prompt":"Elevii pot reproduce definiții, dar nu pot explica relațiile dintre concepte. Ce nivel al învățării necesită mai multă atenție?","options":["Copierea exclusivă a răspunsurilor-model.","Înțelegerea profundă și conectarea ideilor.","Memorarea exclusivă a ordinii paragrafelor.","Repetarea exclusivă a acelorași definiții."],"answer":1,"explanation":"Învățarea de suprafață nu e suficientă singură. Conectarea și explicarea ideilor dezvoltă înțelegerea profundă.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 14, p. 251–254","quote":"importanța cunoașterii conținutului. Cercetarea lui Picker argumentează că, atunci când există un echilibru între experiențele de suprafață (cunoașterea teoretică, knowing-that) și cele profunde (cunoașterea procedurală, knowing-how) de la oră, impactul asupra procesului de învățare al elevilor este maximizat. Dar, când în clasă există o proporție ridicată","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s14","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=27"}},{"id":"L87","theme":"L","prompt":"La informarea despre facilitățile de transport, școala afirmă că gratuitatea feroviară a elevilor acoperă automat și clasa I. Ce clasă indică expres articolul 83?","options":["Ambele clase, exclusiv la trenurile de noapte.","Clasa a II-a, la toate categoriile de trenuri.","Clasa I, exclusiv la trenurile de mare viteză.","Clasa I, exclusiv la trenurile din județul școlii."],"answer":1,"explanation":"Textul indică transportul feroviar la toate categoriile de trenuri, clasa a II-a, în condițiile legii. Facilitatea nu este formulată ca gratuitate generală la clasa I.","source":{"title":"Legea nr. 198/2023","locator":"Art. 83 alin. (1)","quote":"transport public local, inclusiv metropolitan și județean, rutier, naval, cu metroul, precum și feroviar la toate categoriile de trenuri, clasa a II-a, pe tot parcursul anului școlar, în scopul asigurării dreptului la educație, în conformitate cu prevederile unei hotărâri de Guvern inițiate de Ministerul Educației și Cercetării și Ministerul Transporturilor și Infrastructurii, cu consultarea structurilor asociative ale autorităților administrației publice locale. (la 18-01-2026, Alineatul (1), Articolul 83, Sectiunea a 9-a, Capitolul V, Titlul I a fost modificat de Punctul 1., Articolul I din LEGEA nr. 12 din 15 ianuarie 2026, publicată în MONITORUL OFICIAL nr. 27 din 15","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R87","theme":"R","prompt":"Un copil din grupa mică lipsește nejustificat peste 15 zile lucrătoare consecutive. Părintele primește notificarea de posibilă vacantare. Ce termen are pentru răspunsul scris?","options":["Cinci zile de la notificarea primită.","Două zile de la notificarea primită.","Treizeci de zile de la notificarea primită.","Zece zile de la notificarea primită."],"answer":0,"explanation":"Dacă părintele nu transmite răspuns scris în termen de cinci zile, copilul este considerat retras, iar locul este declarat vacant, în condițiile articolului 118.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 118","quote":"unității cu privire la motivul absenței, părintele primește o notificare cu privire la posibilitatea vacantării locului. Dacă în termen de 5 zile părintele nu transmite, în scris, un răspuns la notificarea primită, copilul este considerat retras și locul acestuia este declarat liber/vacant. Pentru copiii preșcolari din grupele mijlocii și mari care se află în situația prezentată la alin. unitatea de învățământ este obligată să prezinte părinților/reprezentanților legali opțiunile pe care aceștia le au în cazul retragerii copilului: reînscrierea acestuia în anul școlar următor sau, după caz, înscrierea într-un serviciu complementar.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"P35","theme":"P","prompt":"Profesorii pilotează o intervenție pedagogică, formulează întrebări de investigare și analizează rezultate pentru a decide dacă o extind. Ce competență este cel mai direct ilustrată?","options":["Antreprenoriat educațional și inovație","Cercetare, inovație pedagogică și conceptualizare strategică","Dezvoltare și transformare organizațională","Managementul schimbării, adaptare și gestionarea presiunilor"],"answer":1,"explanation":"Investigarea unei intervenții, utilizarea cercetării și fundamentarea inovării pedagogice corespund competenței 4.3.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"4.3. Cercetare, inovație pedagogică și conceptualizare strategică","quote":"Promovează inovația pedagogică, utilizarea datelor educaționale și participarea cadrelor didactice în proiecte de cercetare-acțiune și diseminarea bunelor practici. promovează inovația pedagogică și utilizarea metodelor activ-participative centrate pe elev; facilitează participarea cadrelor didactice în proiecte educaționale, cercetare-acțiune și schimb de bune practici; utilizează datele și indicatorii educaționali pentru îmbunătățirea demersurilor curriculare; sprijină implementarea practicilor pedagogice bazate pe dovezi.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"C35","theme":"C","prompt":"Directorul urmărește numai oferta opționalelor, fără să discute curriculumul obligatoriu sau practica de la clasă. Ce extindere este justificată?","options":["Gestionarea implementării curriculumului în ansamblul său.","Înlocuirea proceselor de învățare cu evidența cererilor de înscriere.","Limitarea definitivă a responsabilității la lista de opționale.","Renunțarea la sprijinul pentru profesori după aprobarea ofertei."],"answer":0,"explanation":"Managementul curriculumului nu se reduce la componenta aflată la decizia școlii. El include organizarea și monitorizarea implementării curriculumului.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"de exemplu, colaborarea dintre mai multe școli, colaborarea dintre școală și comunitate; managementul curriculumului la nivelul școlii nu se reduce la managementul CDEOȘ și/ sau CS flexibil; asigurarea cadrului optim de funcționare a comisiilor cu atribuții în domeniul curriculumului și al formării profesorilor din școală. Ca structuri specializate, aceste comisii contribuie la managementul curriculumului la nivelul școlii, prin: identificarea nevoilor de formare ale profesorilor, în domeniul curriculumului, prin analize de nevoi periodice și sistematice; identificarea programelor de formare acreditate adecvate nevoilor de formare identificate, pentru a le recomanda","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L88","theme":"L","prompt":"În proiectarea unei discipline, profesorul consideră că programa ocupă integral timpul disponibil. Ce pondere lasă legea la dispoziția cadrului didactic?","options":["10% din timpul alocat disciplinei.","25% din timpul alocat disciplinei.","50% din timpul alocat disciplinei.","75% din timpul alocat disciplinei."],"answer":1,"explanation":"Programa acoperă 75% din orele de predare și evaluare; 25% din timpul disciplinei sau domeniului de studiu rămâne la dispoziția cadrului didactic.","source":{"title":"Legea nr. 198/2023","locator":"Art. 89 alin. (3)","quote":"disciplină și domeniu de studiu, programa școlară acoperă 75% din orele de predare și de evaluare, lăsând la dispoziția cadrului didactic 25% din timpul alocat disciplinei/domeniului de studiu respectiv. (4) În situații justificate, Ministerul Educației poate modifica, pe durată limitată, prin ordin al ministrului educației, numărul de ore alocat disciplinelor de studiu/modulelor de pregătire prin planurile-cadru de învățământ, precum și ponderea numărului de ore de predare/ evaluare/învățare în programa școlară aprobată.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R88","theme":"R","prompt":"Un elev pleacă temporar în străinătate din clasa a VIII-a. Familia crede că rezervarea locului îi asigură automat un loc în clasa a IX-a la același liceu. Ce limită există?","options":["Rezervarea asigură orice profil liceal ales ulterior de familie.","Rezervarea înlocuiește automat procedura de admitere la liceu.","Rezervarea nu rămâne valabilă la trecerea de la gimnaziu la liceu.","Rezervarea obligă școala să înființeze o nouă clasă liceală."],"answer":2,"explanation":"Articolul 126 permite rezervarea la studii temporare în alte țări, dar exclude păstrarea ei la trecerea dintre nivelul gimnazial și cel liceal.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 126","quote":"se rezervă locul în unitatea de învățământ de unde pleacă, la solicitarea scrisă a părintelui/reprezentantului legal. Rezervarea locului nu rămâne valabilă la trecerea de la nivelul de învățământ gimnazial la nivelul de învățământ liceal. În cazul în care o persoană, indiferent de cetățenie sau statut, solicită înscrierea în sistemul de învățământ românesc după începerea cursurilor noului an școlar, se aplică procedura referitoare la recunoaștere și echivalare și, după caz, cea prevăzută la articolele precedente, dacă nu i se poate echivala anul școlar parcurs în străinătate. Elevelor gravide și beneficiarilor primari părinți, pe perioada de îngrijire a copilului, li se","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B70","theme":"B","prompt":"Conducerea evaluează instituția ignorând complet mediul social și relațiile externe. Ce ipoteză sistemică folosește implicit?","options":["Școala este tratată ca partener interdependent.","Școala este tratată ca rețea comunitară.","Școala este tratată ca sistem deschis.","Școala este tratată ca sistem închis."],"answer":3,"explanation":"Perspectiva închisă pune accent pe procesele interne și neglijează mediul. Ea poate omite influențe importante asupra funcționării școlii.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 60","quote":"sau închise Teoriile sistemice sunt deseori împărţite în deschise sau închise în termeni de relaţii ale organizaţiei cu mediul ei extern. Sistemele închise tind să minimalizeze tranzacţiile cu mediul extern şi pun puţin preţ pe opinia externă în determinarea scopurilor şi activităţilor organizaţiei. Presupunerile structurale ale lui Bolman şi Deal (1991), menţionate","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H36","theme":"H","prompt":"Profesorul primește opinii ale elevilor diferite de propria evaluare a relațiilor din clasă. Ce atitudine favorizează îmbunătățirea?","options":["Folosirea feedbackului pentru examinarea și ajustarea practicii.","Înlocuirea tuturor opiniilor elevilor cu presupunerile profesorului.","Păstrarea exclusivă a răspunsurilor care confirmă imaginea inițială.","Respingerea feedbackului pentru că elevii nu au funcție managerială."],"answer":0,"explanation":"Datele despre percepțiile elevilor pot contesta convingerile profesorului și pot ghida schimbarea. Ele cer analiză, nu respingere automată.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 15, p. 255–256","quote":"clasa prin ochii elevilor. Efectul puternic al activității lui Bishop este că, după ce au văzut aceste rezultate, profesorii și-au schimbat repede metodele. Formarea profesională care pune la îndoială presupunerile și teoriile profesorilor despre practica pedagogică poate fi foarte eficientă. Puterea relațiilor pozitive profesori-elevi este esențială","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s15","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=31"}},{"id":"L89","theme":"L","prompt":"O grădiniță își limitează curriculumul la memorarea de informații și ignoră dezvoltarea fizică, emoțională și socială. Ce orientare legală trebuie restabilită?","options":["Acumularea exclusivă a conținuturilor din disciplinele liceale.","Clasificarea exclusivă a copiilor după volumul temelor scrise.","Dezvoltarea fizică, cognitivă, emoțională și socială a copiilor.","Pregătirea exclusivă a copiilor pentru teste competitive de admitere."],"answer":2,"explanation":"Curriculumul pentru educația timpurie urmărește dezvoltarea integrată și remedierea timpurie a eventualelor întârzieri. Componenta cognitivă nu e singura finalitate.","source":{"title":"Legea nr. 198/2023","locator":"Art. 90 alin. (1)","quote":"(1) Curriculumul național pentru educația timpurie este centrat pe dezvoltarea fizică, cognitivă, emoțională și socială a copiilor, respectiv pe remedierea timpurie a eventualelor întârzieri în dezvoltare. (2) La nivelul DJIP/DMBIP, CJRAE/CMBRAE sau al altor structuri abilitate în acest sens se constituie echipe multidisciplinare menite să realizeze evaluarea, depistarea, intervenția timpurie, asistența psihopedagogică și monitorizarea corespunzătoare a tuturor copiilor identificați cu abilități cognitive scăzute și/sau socioemoționale adaptive în raport cu vârsta și nivelul lor de școlarizare. Constituirea și modul de funcționare a","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R89","theme":"R","prompt":"Un elev solicită reexaminare după nepromovarea unui examen de diferență pentru transfer între școli. Ce regulă specifică se aplică?","options":["La aceste examene de diferență nu se acordă reexaminare.","La aceste examene reexaminarea este decisă exclusiv de părinte.","La aceste examene se acordă automat două reexaminări.","La aceste examene se înlocuiește rezultatul prin media clasei."],"answer":0,"explanation":"Interdicția reexaminării privește examenele de diferență pentru transfer. Nu se confundă cu reexaminarea prevăzută pentru unele situații de corigență.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 130","quote":"La examenele de diferență pentru elevii care solicită transferul de la o unitate de învățământ la alta nu se acordă reexaminare.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B71","theme":"B","prompt":"La repartizarea unui rol, conducerea cere dovezi de competență și aplică aceleași criterii profesionale tuturor candidaților. Ce trăsătură birocratică este urmărită?","options":["Promovarea fără criterii verificabile.","Selecția exclusiv prin relații personale.","Selecția și promovarea pe merit.","Selecția și promovarea prin favoritism."],"answer":2,"explanation":"Modelul birocratic asociază numirea și promovarea cu meritul și calificarea, în opoziție cu favoritismul.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 63","quote":"poate fi considerată un exemplu de birocraţie. 6. În birocraţii, recrutarea şi progresul în carieră al personalului sunt determinate de merit. Numirile sunt făcute pe baza calificărilor şi experienţei şi promovarea depinde de expertiza demonstrată în poziţia prezentă şi cele anterioare. Şcolile şi colegiile îndeplinesc acest criteriu, în sensul că proceduri","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"P36","theme":"P","prompt":"Directorul urmărește simultan progresul elevilor și îmbunătățirea performanței profesorilor, conectând sprijinul pentru învățare cu dezvoltarea practicii didactice. Ce competență reunește cele două finalități?","options":["Asigurarea succesului școlar al elevilor și a performanței cadrelor didactice","Colectarea datelor, analiza și formularea de strategii de îmbunătățire a calității","Leadership incluziv, stare de bine a elevilor și a personalului școlii, securitate și siguranță școlară","Managementul incluziunii și al diversității în profilurile de învățare"],"answer":0,"explanation":"Competența 4.4 asociază explicit succesul școlar al elevilor cu performanța cadrelor didactice. Cazul nu se limitează la administrarea personalului.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"4.4. Asigurarea succesului școlar al elevilor și a performanței cadrelor didactice","quote":"elaborează planuri individuale de dezvoltare profesională corelate cu nevoile identificate; susține procesele de mentorat, coaching și observare inter pares — peer observation; facilitează accesul cadrelor didactice la programe de dezvoltare profesională relevante și de calitate; monitorizează impactul formării continue asupra practicii didactice și a rezultatelor elevilor; asigură responsabilizarea cadrelor didactice cu privire la impactul practicilor pedagogice asupra succesului elevilor; valorifică expertiza internă a personalului în procesul de formare și mentorat colegial; promovează o cultură a învățării organizaționale și a comunităților de practică profesională.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"L90","theme":"L","prompt":"Echipa digitală a școlii tratează securitatea cibernetică drept temă fără legătură cu competențele-cheie. Ce încadrare legală trebuie făcută?","options":["Face parte din competența digitală.","Face parte exclusiv din competența antreprenorială.","Face parte exclusiv din competența de exprimare culturală.","Face parte exclusiv din competența de multilingvism."],"answer":0,"explanation":"Articolul 91 include explicit siguranța pe internet și securitatea cibernetică în competența digitală, una dintre competențele-cheie ale curriculumului.","source":{"title":"Legea nr. 198/2023","locator":"Art. 91 lit. d)","quote":"în multilingvism; c) competență matematică și competență în științe, tehnologie și inginerie; d) competență digitală, inclusiv de siguranță pe internet și securitate cibernetică; e) competență personală, socială și de a învăța să înveți; f) competență civică, juridică și de protejare a mediului; g) competență antreprenorială; h) competență de sensibilizare și exprimare culturală.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}}]},{"id":19,"title":"Simularea 19","items":[{"id":"B76","theme":"B","prompt":"Directorul emite o instrucțiune didactică, însă profesorii o adaptează sau o ignoră în practică. Ce limită a autorității formale trebuie analizată?","options":["Capacitatea funcției de a determina automat orice comportament.","Dependența aplicării de consimțământul și acțiunea practicienilor.","Identitatea obligatorie dintre ordinul emis și efectul obținut.","Inexistența oricărei autonomii profesionale în sala de clasă."],"answer":1,"explanation":"Autoritatea poziției nu garantează controlul complet al practicii profesionale. Consimțământul și participarea profesorilor contează.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 75","quote":"în fruntea şcolilor şi colegiilor are însă limitări serioase. Deşi autoritatea formală este a directorilor, aceştia au nevoie de consimţământul colegilor dacă doresc ca iniţiativele sau politicile să fie adoptate în cadrul departamentelor şi la clasă. Este deja un truism că personalul trebuie să „deţină” deciziile dacă se doreşte ca aceştia să le implementeze","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"C38","theme":"C","prompt":"O vizită la clasă constată dificultăți de implementare. Ce folosire a constatărilor corespunde monitorizării cu rol de sprijin?","options":["Clasarea tuturor observațiilor fără nicio revenire asupra lor.","Exclusiv căutarea unui vinovat, fără discutarea dificultăților.","Feedback profesional și măsuri de îmbunătățire a implementării.","Publicarea impresiilor personale înaintea dialogului cu profesorul."],"answer":2,"explanation":"Monitorizarea are rol de sprijin: constatările trebuie să poată conduce la feedback, învățare profesională și îmbunătățire.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"nivelul școlii; dezvoltarea unor strategii de monitorizare a implementării curriculumului la nivelul clasei și al școlii, în general, cu rol de sprijin şi motivare; asigurarea resurselor necesare implementării CN; spații, resurse materiale adecvate, climatul organizației școlare etc.; încurajarea implementării inovațiilor curriculare – disponibilitatea pentru abordări flexibile, deschiderea către pilotarea de soluții educaționale inovative etc.; diversificarea ofertei educaționale a școlii, prin CDEOȘ și/ sau CS flexibil, pentru a răspunde nevoilor și intereselor elevilor școlii; aceasta presupune, de exemplu, colaborarea dintre mai multe școli, colaborarea dintre școală","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L91","theme":"L","prompt":"O clasă este prezentată ca intensivă la o limbă modernă, deși are o singură oră suplimentară față de trunchiul comun. Care este suplimentul minim prevăzut?","options":["Cel puțin cinci ore față de trunchiul comun.","Cel puțin două ore față de trunchiul comun.","Cel puțin o oră față de trunchiul comun.","Cel puțin patru ore față de trunchiul comun."],"answer":1,"explanation":"Regimul intensiv presupune cel puțin două ore suplimentare, alocate din CDEOȘ. Regimul bilingv are un prag distinct.","source":{"title":"Legea nr. 198/2023","locator":"Art. 92 alin. (3)","quote":"în regim intensiv se înțelege acea clasă din învățământul preuniversitar în care o limbă modernă se studiază într-un număr mai mare cu cel puțin 2 ore față de numărul de ore prevăzut în trunchiul comun prin planul-cadru de învățământ, care se alocă din curriculumul la decizia elevului din oferta școlii. (4) Prin clasă cu predare a unei limbi moderne în regim bilingv se înțelege acea clasă din învățământul preuniversitar în care o limbă modernă se studiază într-un număr mai mare cu cel puțin 3 ore față de numărul de ore prevăzut în trunchiul comun prin planul-cadru de învățământ, care se alocă din CDEOȘ. La clasele cu predare a unei limbi moderne în regim bilingv,","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R91","theme":"R","prompt":"La proba orală a unui examen școlar sunt 12 elevi la o disciplină. Comisia pregătește 12 bilete. Câte bilete cere regula ROFUIP?","options":["Douăsprezece bilete.","Douăzeci și patru de bilete.","Optsprezece bilete.","Treizeci și șase de bilete."],"answer":1,"explanation":"Numărul biletelor este de două ori mai mare decât numărul elevilor care susțin examenul la disciplină: 2 × 12 = 24. Fiecare bilet conține două subiecte.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 132","quote":"Proba orală a examenelor se desfășoară prin dialog cadru didactic – elev, pe baza biletelor de examen. Numărul biletelor de examen este de două ori mai mare decât numărul beneficiarilor primari care susțin examenul la disciplina/modulul respectivă/respectiv. Fiecare bilet conține două subiecte. Elevul poate schimba biletul de examen cel mult o dată. Fiecare cadru didactic examinator acordă elevului câte o/un notă/calificativ la fiecare probă susținută de acesta. Notele de la probele orale sau practice sunt întregi. Notele de la probele scrise pot fi și fracționare. Media aritmetică a notelor acordate la cele două sau trei probe, rotunjită la nota întreagă cea mai apropiată,","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B73","theme":"B","prompt":"Echipa alege o măsură înainte să definească problema sau să compare alternative. Ce etapizare ar susține abordarea rațională?","options":["Alegerea primei soluții, urmată de eliminarea tuturor datelor contrare.","Definirea problemei, analiza alternativelor și alegerea justificată.","Repetarea soluției anterioare, fără examinarea situației actuale.","Stabilirea rezultatului dorit, urmată de inventarea justificărilor."],"answer":1,"explanation":"Modelul rațional presupune o legătură explicită între problemă, alternative și decizie; aplicarea lui concretă trebuie examinată critic.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 65","quote":"entuziasm, ceea ce poate conduce la eşec. Modelele raţionale Abordările raţionale diferă de alte modele formale în sensul că evidenţiază procesul managerial în locul structurii sau scopurilor organizaţionale. Atenţia cade asupra procesului de luare a deciziilor, şi nu asupra cadrului structural care limitează, dar nu determină deciziile manageriale. Deşi calitatea","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H37","theme":"H","prompt":"La aprecierea potențialului, profesorul acordă involuntar mai multă încredere elevilor pe care îi consideră atrăgători. Ce corecție ar reduce prejudecata?","options":["Confirmarea oricărei presupuneri inițiale fără verificări ulterioare.","Înlocuirea evaluărilor cu preferințele personale ale profesorului.","Raportarea judecății exclusiv la prima impresie estetică.","Raportarea judecății la dovezi relevante despre învățare."],"answer":3,"explanation":"Atractivitatea poate distorsiona judecățile. Folosirea dovezilor relevante și examinarea propriilor prejudecăți reduc acest risc.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 5, p. 234–236","quote":"Pag. 234–236 Pagina 234 Vezi pagina originală ↗ (Patzer, 2012). Suntem mai predispuși să-l angajăm și să-l votăm pe candidatul mai atractiv fizic, iar elevii pretind că învață mai multe de la profesorii mai atractivi (Hosoda et al., 2003; Olivola & Todorov, 2010; Westfall et al., 2016). *Ritts și colaboratorii (1992) au raportat o mărime a efectului d =","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s5","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=10"}},{"id":"L92","theme":"L","prompt":"Un profesor dorește să recomande ca manual școlar alternativ un titlu aflat în afara listei aprobate de minister. Ce limită are libertatea inițiativei profesionale aici?","options":["Selecția manualelor alternative se face din lista aprobată de minister.","Selecția manualelor alternative se face exclusiv din catalogul sponsorului.","Selecția manualelor alternative se face exclusiv după votul clasei.","Selecția manualelor alternative se face fără raportare la vreo listă."],"answer":0,"explanation":"Legea recunoaște selecția și recomandarea de către profesor, dar pentru manualele alternative din lista celor aprobate de Ministerul Educației.","source":{"title":"Legea nr. 198/2023","locator":"Art. 93 alin. (3)","quote":"Personalul didactic de predare selectează și recomandă elevilor, în baza libertății inițiativei profesionale, manuale școlare alternative din lista celor aprobate de Ministerul Educației, pentru utilizarea în procesul didactic. (4) Elevii și personalul didactic de predare din învățământul de stat și din învățământul obligatoriu particular acreditat/ autorizat și confesional beneficiază de manuale școlare gratuite, atât pentru învățământul în limba română, cât și pentru cel în limbile minorităților naționale, în condițiile legii. Notă Conform punctului 1 al articolului I din LEGEA nr. 56 din 30 aprilie 2026, publicată în MONITORUL OFICIAL nr. 364 din 30 aprilie 2026 coroborat cu","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R92","theme":"R","prompt":"Un elev nu poate participa justificat la examenul de corigență. Familia dorește depunerea actelor justificative după zece zile lucrătoare. Care este termenul ROFUIP?","options":["Cel mult cincisprezece zile lucrătoare de la data examenului.","Cel mult șapte zile lucrătoare de la data examenului.","Cel mult trei zile lucrătoare de la data examenului.","Cel mult zece zile lucrătoare de la data examenului."],"answer":1,"explanation":"Actele privind motivele temeinice se depun în cel mult șapte zile lucrătoare. Data ulterioară de examinare se stabilește în condițiile articolului 134.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 134","quote":"Elevii corigenți sau amânați care nu se pot prezenta la examene din motive temeinice, dovedite cu acte, depuse în cel mult 7 zile lucrătoare de la data examenului, sunt examinați la o dată ulterioară, stabilită de consiliul de administrație, dar nu mai târziu de începerea cursurilor noului an școlar. Perioada se poate prelungi, în mod excepțional, pentru situații obiective, prin decizie a inspectoratului școlar. Pentru elevele gravide și elevii părinți aflați în perioada de îngrijire a copilului, precum și în situații excepționale, respectiv internări în spital, imobilizări la pat etc., dovedite cu acte, inspectoratul școlar poate aproba susținerea examenului","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"P37","theme":"P","prompt":"Un conflict între două echipe blochează cooperarea. Directorul clarifică perspectivele, facilitează dialogul și caută o soluție acceptabilă pentru lucru. Ce competență este predominantă?","options":["Antreprenoriat educațional și inovație","Atragerea de resurse extrabugetare","Participarea la rețele și proiecte naționale și internaționale","Relaționare, comunicare și gestionarea conflictelor"],"answer":3,"explanation":"Intervenția urmărește relaționarea, comunicarea și gestionarea conflictelor, prin ascultare și facilitarea înțelegerii.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"5.1. Relaționare, comunicare și gestionarea conflictelor","quote":"Asigură o comunicare clară, empatică și adaptată interlocutorului, mediind conflictele cu imparțialitate și menținând un climat relațional pozitiv în interiorul și exteriorul școlii. formulează mesaje verbale și scrise clare, coerente și adaptate interlocutorului — personal, părinți, elevi, autorități; utilizează tehnici de ascultare activă și empatie în relațiile cu membrii comunității școlare; comunică deciziile instituționale în mod transparent, clar și la timp; organizează consultări periodice cu profesori, părinți și elevi pe teme relevante; mediază conflictele cu calm, diplomație și imparțialitate.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"C37","theme":"C","prompt":"O nouă programă ridică dificultăți pe care oferta de formare existentă nu le tratează. Ce ar trebui să fundamenteze revizuirea formării?","options":["Alegerea cursului exclusiv după denumirea cea mai scurtă.","O analiză periodică a nevoilor profesionale reale.","Repetarea aceluiași curs pentru că există deja diapozitivele.","Stabilirea formării fără nicio legătură cu practica profesorilor."],"answer":1,"explanation":"Analiza nevoilor permite corelarea sprijinului și formării cu dificultățile reale ale implementării curriculumului.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"managementul curriculumului la nivelul școlii, prin: identificarea nevoilor de formare ale profesorilor, în domeniul curriculumului, prin analize de nevoi periodice și sistematice; identificarea programelor de formare acreditate adecvate nevoilor de formare identificate, pentru a le recomanda profesorilor; valorificarea rezultatelor activităților de formare în domeniul curriculumului, la nivelul școlii și al claselor; consilierea curriculară a profesorilor, în aplicarea și evaluarea curriculumului în școală – aspecte critice, bune practici, inovare etc.; facilitarea unei culturi a reflecției asupra întregului proces de aplicare a curriculumului în școală și de evaluare a impactului","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L93","theme":"L","prompt":"La clasa pregătitoare, profesorul propune acordarea de calificative anuale pentru a pregăti elevii pentru clasa I. Ce regulă legală se aplică?","options":["În clasa pregătitoare nu se acordă note sau calificative.","În clasa pregătitoare se acordă note doar la final de an.","În clasa pregătitoare se acordă numai calificativul Foarte bine.","În clasa pregătitoare se acordă obligatoriu note de la 1 la 10."],"answer":0,"explanation":"Clasa pregătitoare este exceptată expres de la acordarea notelor și calificativelor. Evaluarea dezvoltării se exprimă prin raportul prevăzut de lege.","source":{"title":"Legea nr. 198/2023","locator":"Art. 96 alin. (1) lit. a)","quote":"(1) Rezultatele evaluării se exprimă, după caz: a) în învățământul primar, cu excepția clasei pregătitoare, pe parcursul căreia nu se acordă note sau calificative, prin calificative: „foarte bine“, „bine“, „suficient“ sau „insuficient“; b) în învățământul gimnazial, prin note de la 1 la 10; c) în învățământul liceal și în învățământul postliceal, prin note de la 1 la 10; d) prin punctaje/coduri specifice, în cazul testelor standardizate aplicate în afara evaluărilor externe prevăzute de lege; e) prin rapoarte anuale de evaluare a dezvoltării fizice, socioemoționale, cognitive, a limbajului și a comunicării, precum și a dezvoltării capacităților și atitudinilor de învățare, pentru","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R93","theme":"R","prompt":"Pentru un copil cu CES se propune reorientarea din învățământul special spre cel de masă. Cine ia decizia, cu acordul părinților?","options":["Comisia de orientare școlară și profesională din CJRAE/CMBRAE.","Comitetul de părinți al clasei în care ar urma să intre copilul.","Compartimentul financiar-contabil al unității de învățământ în care este înscris.","Furnizorul de manuale pentru nivelul de învățământ solicitat."],"answer":0,"explanation":"Propunerea și decizia sunt distincte. Decizia aparține comisiei de orientare școlară și profesională din CJRAE/CMBRAE, cu acordul părinților sau reprezentanților legali.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 148","quote":"cauză sau de către părinții sau reprezentanții legali ai copilului și de către consilierul școlar. Decizia de reorientare se ia de către comisia de orientare școlară și profesională din cadrul centrului județean de resurse și asistență educațională/Centrului Municipiului București de Resurse și Asistență Educațională, cu acordul părinților sau al reprezentanților legali.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B74","theme":"B","prompt":"Fiecare compartiment justifică din nou activitățile și costurile, fără a considera bugetul precedent un drept câștigat. Ce tehnică este aplicată?","options":["Bugetarea exclusiv după cheltuiala anterioară.","Bugetarea fără justificarea activităților.","Bugetarea în bază zero.","Bugetarea prin copiere automată."],"answer":2,"explanation":"Bugetarea în bază zero reexaminează justificarea activităților și alocărilor, în loc să preia automat nivelurile istorice.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 68","quote":"68 Leadership Şi management educaŢional 4. Bugetarea în bază zero. Aceasta implică abordarea unei noi perspective în toate ariile de cheltuire, nu numai modificarea incrementală a modelelor de cheltuire anterioare. 5. Alegerea celor mai adecvate opţiuni. Odată ce tiparele de","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H38","theme":"H","prompt":"Școala afișează „suntem o echipă puternică”, însă profesorii nu analizează niciodată împreună rezultatele intervențiilor. Ce lipsește față de o eficacitate colectivă fundamentată?","options":["Confirmarea că toate opiniile individuale sunt obligatoriu identice.","Eliminarea întrebărilor despre efectele reale ale practicilor folosite.","Legătura dintre încrederea comună, acțiunile comune și dovezile de progres.","O formulare mai lungă a aceluiași slogan despre reușita colectivă."],"answer":2,"explanation":"Un slogan nu este suficient. Eficacitatea colectivă se raportează la capacitatea și acțiunea comună, susținute de experiențe și dovezi.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 7, p. 239–240","quote":"class=\"chapter\"> SECȚIUNEA 07 Eficacitatea colectivă a profesorilor și impactul lor Pag. 239–240 Pagina 239 Vezi pagina originală ↗ împărtășesc credința că, prin efortul lor unit, pot depăși greutăți și pot obține rezultatele dorite, grupurile sunt mai eficiente. Acest","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s7","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=15"}},{"id":"L94","theme":"L","prompt":"La finalul gimnaziului, o recomandare de orientare este prezentată familiei ca obligând elevul să aleagă un anumit liceu. Ce caracter are recomandarea?","options":["Consultativ, fiind inclusă în portofoliul educațional.","Definitiv, excluzând orice altă opțiune a elevului.","Disciplinar, înlocuind evaluarea națională a elevului.","Obligatoriu, înlocuind regulile de admitere la liceu."],"answer":0,"explanation":"Recomandările emise de consilier și diriginte au rol de orientare și caracter consultativ. Ele nu impun o alegere de studii familiei sau elevului.","source":{"title":"Legea nr. 198/2023","locator":"Art. 98 alin. (3)","quote":"de învățământ liceal se poate realiza și o recomandare sub forma unei orientări vocaționale de încadrare pe piața forței de muncă. Recomandările sunt consultative și sunt emise în baza metodologiei specifice și sunt incluse în portofoliul educațional. (4) După finalizarea învățământului obligatoriu, portofoliul educațional poate fi completat cu rezultate ale activităților de învățare pe tot parcursul vieții. (5) Portofoliul educațional este obligatoriu începând cu generația de preșcolari care intră în grupa mijlocie și generația de elevi din clasa pregătitoare, în anul școlar 2024-2025. Formatul portofoliului educațional, modalitatea de înscriere a datelor și alte detalii sunt","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R94","theme":"R","prompt":"Portarul aplică reguli improvizate pentru intrarea părinților, deoarece școala nu are procedură de acces. Cine are obligația stabilirii acesteia?","options":["Comitetul fiecărei clase, separat de conducerea unității.","Consiliul de administrație al unității de învățământ.","Elevul de serviciu din fiecare zi de activitate școlară.","Furnizorul echipamentelor de supraveghere video."],"answer":1,"explanation":"Articolul 154 atribuie CA obligația stabilirii procedurii de acces al părinților și reprezentanților legali în unitate.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 154","quote":"situații speciale prevăzute de regulamentul de organizare și funcționare a unității. Consiliul de administrație are obligația stabilirii procedurii de acces al părinților/ reprezentanților legali în unitățile de învățământ.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B75","theme":"B","prompt":"O echipă îi urmează recomandările unui specialist chiar dacă acesta nu ocupă o funcție superioară. Ce sursă de influență devine vizibilă?","options":["Autoritatea exclusivă conferită de organigramă.","Expertiza recunoscută independent de ierarhie.","Obligația de subordonare față de orice coleg mai vechi.","Puterea automată a persoanei care deține inventarul."],"answer":1,"explanation":"În organizațiile profesionale, expertiza poate constitui o sursă de influență distinctă de poziția ierarhică.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 69","quote":"de leadership distribuit şi ceea ce el descrie ca fiind „structurile de putere ierarhică ale şcolilor”. Leadershipul distribuit este independent de ierarhie, se bazează pe calităţi personale, şi nu pe poziţii desemnate. În ciuda acestui model emergent şi datorită autorităţii legale a directorilor, ierarhia rămâne importantă în şcoli şi colegii. În anumite societăţi,","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"P38","theme":"P","prompt":"Școala intră într-o comunitate profesională internațională. Directorul organizează parteneriatul și participarea la proiecte pentru schimb de practici. Ce competență este centrală?","options":["Asigurarea succesului școlar al elevilor și a performanței cadrelor didactice","Cercetare, inovație pedagogică și conceptualizare strategică","Participarea la rețele și proiecte naționale și internaționale","Responsabilitate publică și relaționare instituțională"],"answer":2,"explanation":"Accentul este participarea la rețele și proiecte naționale și internaționale, în vederea conectării și dezvoltării instituției.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"5.2. Participarea la rețele și proiecte naționale și internaționale","quote":"valorifică oportunitățile programului Erasmus+ pentru a întări dimensiunea europeană a școlii; participă și implică școala în proiecte de tip eTwinning, Școală Europeană și altele similare; facilitează și stimulează participarea cadrelor didactice în proiecte de mobilități și parteneriat strategic; creează și întreține rețele de colaborare interinstituțională.","prefixEllipsis":false,"suffixEllipsis":false,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"L95","theme":"L","prompt":"Un profesor anunță că va comunica rezultatele lucrărilor scrise după o lună. Ce termen maxim are elevul dreptul să fie respectat?","options":["15 zile lucrătoare pentru rezultatele evaluărilor scrise.","20 de zile lucrătoare pentru rezultatele evaluărilor scrise.","30 de zile lucrătoare pentru rezultatele evaluărilor scrise.","5 zile lucrătoare pentru rezultatele evaluărilor scrise."],"answer":0,"explanation":"Articolul 106 include dreptul elevului de a cunoaște rezultatele evaluărilor scrise în maximum 15 zile lucrătoare, alături de celelalte drepturi de informare.","source":{"title":"Legea nr. 198/2023","locator":"Art. 106 alin. (1) lit. h)","quote":"înaintea consemnării acestora, la planificarea materiei pe parcursul întregului an școlar, la rezultatele evaluărilor scrise în termen de maximum 15 zile lucrătoare, precum și la actele școlare proprii ce stau la baza situației școlare; i) dreptul de a fi susținuți în conformitate cu nevoile educaționale sau sociale în vederea finalizării învățământului obligatoriu. Statul și unitățile de învățământ preuniversitar sprijină elevii cu CES, inclusiv în ceea ce privește condițiile de acces, de studiu și evaluare adaptate dizabilităților, problemelor medicale sau tulburărilor specifice de învățare. Elevii cu CES au dreptul la școlarizare la domiciliu sau în unități complexe de asistență","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R95","theme":"R","prompt":"Un conflict sesizat de părinte nu s-a rezolvat prin discuții amiabile și nici prin cererea scrisă adresată conducerii. Care este pasul prevăzut de ROFUIP?","options":["Adresare exclusivă furnizorului de manuale pentru o soluție obligatorie.","Adresare exclusivă unui alt elev pentru pronunțarea unei decizii.","Adresare în scris inspectoratului școlar pentru mediere și rezolvare.","Închiderea automată a sesizării, fără posibilitatea altui demers."],"answer":2,"explanation":"Pentru starea conflictuală nerezolvată la nivelul școlii, părintele se poate adresa în scris inspectoratului. Regula nu înlătură căile legale pentru fapte de altă natură.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 156","quote":"legal consideră că starea conflictuală nu a fost rezolvată la nivelul unității de învățământ, acesta are dreptul de a se adresa, în scris, inspectoratului școlar pentru a media și rezolva starea conflictuală.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}}]},{"id":20,"title":"Simularea 20","items":[{"id":"C40","theme":"C","prompt":"În școală, regulile nescrise descurajează profesorii să ceară ajutor sau să discute ce nu funcționează. Ce factor trebuie abordat pentru îmbunătățirea curriculumului?","options":["Cultura organizațională și deschiderea spre învățare profesională.","Exclusiv culoarea antetului de pe planificările calendaristice.","Exclusiv denumirea folderelor folosite pentru arhivarea rapoartelor.","Exclusiv numărul de dulapuri în care sunt păstrate programele."],"answer":0,"explanation":"Normele și valorile informale influențează cooperarea și implementarea curriculumului. Schimbarea documentelor singură nu rezolvă barierele culturale.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"a profesorilor, în aplicarea și evaluarea curriculumului în școală – aspecte critice, bune practici, inovare etc.; facilitarea unei culturi a reflecției asupra întregului proces de aplicare a curriculumului în școală și de evaluare a impactului acestuia asupra învățării. Inspectorul școlar – consilier pentru managementul curriculumului la nivelul școlii. În transpunerea CN la nivelul fiecărei școli, inspectorul școlar are roluri precum: consilierea echipei manageriale, a echipelor de profesori și a profesorilor, în proiectarea, implementarea și evaluarea CN; asigurarea coerenței dintre curriculumul oficial și cel aplicat în școală; dezvoltarea, selectarea și","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L96","theme":"L","prompt":"După deteriorarea unui obiect, autorul nu este identificat. Conducerea propune sancționarea întregii clase pentru a obține o mărturisire. Ce limită legală se aplică?","options":["Elevii nu pot fi sancționați doar în ultima lună de cursuri.","Elevii nu pot fi supuși unor sancțiuni colective.","Elevii pot fi sancționați colectiv dacă paguba este mare.","Elevii pot fi sancționați colectiv prin votul părinților."],"answer":1,"explanation":"Legea interzice sancțiunile colective. Cercetarea unui incident trebuie să individualizeze răspunderea și să respecte drepturile elevilor.","source":{"title":"Legea nr. 198/2023","locator":"Art. 107 alin. (3)","quote":"cu privire la natura încălcării și sunt convocați la o întâlnire formală. (3) Elevii au dreptul la apărare și nu pot fi supuși unor sancțiuni colective. (4) Pentru a putea fi sancționați, faptele trebuie să se petreacă în perimetrul unității de învățământ, în cadrul activităților extrașcolare sau în cadrul activităților desfășurate în mediul online. (5) Sancțiunile ce pot fi aplicate elevilor, în funcție de gravitatea faptei, sunt: a) observație individuală; b) mustrare scrisă; c) retragerea temporară sau pe durata întregului an școlar a burselor de care beneficiază elevul; d) mutarea disciplinară la o clasă paralelă din aceeași unitate de învățământ; e) suspendarea","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R96","theme":"R","prompt":"Adunarea generală a părinților are 30 de membri. Participă 15 și se dorește adoptarea unor hotărâri. Ce rezultă din regula cvorumului?","options":["Este întrunită statutar; este suficientă prezența a 10 membri.","Este întrunită statutar; este suficientă prezența a 15 membri.","Nu este întrunită statutar; este necesară prezența a 16 membri.","Nu este întrunită statutar; este necesară prezența a 20 de membri."],"answer":2,"explanation":"Adunarea generală a părinților necesită jumătate plus unu din total: pentru 30 de membri, minimum 16. Pragul de adoptare se calculează separat dintre cei prezenți.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 161","quote":"săi. Adunarea generală a părinților/reprezentanților legali se convoacă ori de câte ori este nevoie, este valabil întrunită în prezența a jumătate plus unu din totalul părinților/ reprezentanților legali ai copiilor/beneficiarilor primari din grupa/clasa respectivă și adoptă hotărâri cu votul a jumătate plus unu din cei prezenți.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B77","theme":"B","prompt":"Un analist atribuie școlii intenții proprii, fără să examineze ce gândesc sau fac membrii săi. Ce limită a modelului formal apare?","options":["Atenția prea mare acordată sensurilor individuale ale membrilor.","Eliminarea completă a structurii din explicația instituțională.","Refuzul de a considera că școala are o organigramă.","Tratarea organizației ca entitate separată de contribuția oamenilor."],"answer":3,"explanation":"Reificarea organizației poate ascunde rolul oamenilor și al interpretărilor lor în construirea realității instituționale.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 80","quote":"în literatura secolului XXI pentru nevoia profesorilor de a „deţine” schimbarea. 3. Modelele formale se concentrează pe organizaţie ca entitate şi ignoră sau subestimează contribuţia indivizilor. Ele pornesc de la ipoteza că oamenii ocupă poziţii prestabilite în structură, iar comportamentul lor reflectă poziţia lor organizaţională, nu calităţile şi experienţa","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H39","theme":"H","prompt":"Un profesor crede că explicația a fost clară fiindcă a vorbit rar. Ce verificare oferă o dovadă mai relevantă a înțelegerii?","options":["Elevii confirmă numai că au auzit vocea profesorului.","Elevii reformulează sarcina și explică criteriile de reușită.","Profesorul numără diapozitivele prezentate la începutul orei.","Profesorul repetă că instrucțiunile sale au fost foarte clare."],"answer":1,"explanation":"Claritatea se verifică prin înțelegerea elevilor, nu doar prin intenția ori ritmul vorbirii profesorului.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 6, p. 237–238","quote":"class=\"chapter\"> SECȚIUNEA 06 Credibilitatea profesorului / Claritatea profesorului Pag. 237–238 Pagina 237 Vezi pagina originală ↗ Credibilitatea profesorului Credibilitatea profesorului reprezintă credința elevilor că pot învăța de la un anumit profesor pentru că profesorul este","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s6","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=13"}},{"id":"L97","theme":"L","prompt":"Un profesor organizează meditații cu elevii de la propria clasă și susține că acordul familiilor înlătură orice problemă disciplinară. Cum califică legea activitatea?","options":["Este exceptată expres dacă există acordul părinților.","Este permisă exclusiv în ultima lună a anului școlar.","Este permisă exclusiv pentru elevii cu note mari.","Este prevăzută expres între abaterile disciplinare."],"answer":3,"explanation":"Articolul 209 enumeră desfășurarea meditațiilor cu elevii de la propria clasă între abaterile disciplinare. Acordul familiilor nu elimină prevederea.","source":{"title":"Legea nr. 198/2023","locator":"Art. 209 alin. (2) lit. d)","quote":"elevilor; c) manifestarea convingerilor politice și prozelitismul religios în spațiul școlar; d) activitatea de desfășurare a meditațiilor cu elevii de la propria clasă; e) încălcarea dispozițiilor legii, a obligațiilor din prezentul titlu, a normelor statutului profesiei, deciziilor obligatorii ale organelor profesiei la nivel național sau ale unității de învățământ al cărei angajat este sau în cadrul căreia prestează activități de predare- învățare-evaluare cu antepreșcolarii/preșcolarii/elevii; f) fapte de natură să aducă atingere imaginii, demnității sau drepturilor copiilor/elevilor și familiilor acestora ori să prejudicieze onoarea și/sau prestigiul unității/instituției, interesul","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R97","theme":"R","prompt":"O firmă sponsorizează clasa și cere ca propriul copil să primească prioritate la recompense. Ce efect al sponsorizării este exclus de ROFUIP?","options":["Acordarea unor drepturi suplimentare copiilor sau părinților.","Informarea comitetului de părinți despre sponsorizarea clasei.","Respectarea regulilor financiare aplicabile sponsorizării școlare.","Susținerea legală a dezvoltării bazei materiale a unității."],"answer":0,"explanation":"Sponsorizarea nu atrage drepturi suplimentare pentru copii, elevi sau părinți. Sprijinul financiar nu cumpără privilegii educaționale.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 165","quote":"unei grupe/clase de către un operator economic/persoane fizice se face cunoscută comitetului de părinți. Sponsorizarea nu atrage după sine drepturi suplimentare pentru copii/elevi/părinți sau reprezentanți legali. Este interzisă și constituie abatere disciplinară implicarea copiilor/beneficiarilor primari sau a personalului din unitatea de învățământ în strângerea și/sau gestionarea fondurilor.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"P39","theme":"P","prompt":"Directorul identifică o nevoie educațională nesatisfăcută și susține transformarea unei idei noi într-o inițiativă viabilă pentru școală. Ce competență este dominantă?","options":["Antreprenoriat educațional și inovație","Atragerea de resurse extrabugetare","Cercetare, inovație pedagogică și conceptualizare strategică","Dezvoltare și transformare organizațională"],"answer":0,"explanation":"Recunoașterea oportunităților și transformarea ideilor în inițiative utile sunt caracteristice antreprenoriatului educațional și inovării.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"5.3. Antreprenoriat educațional și inovație","quote":"Identifică oportunități de valorificare a resurselor instituționale, influențează organizația în direcția atingerii obiectivelor și asigură implicarea factorilor interesați în rezolvarea provocărilor specifice. influențează organizația în direcția atingerii obiectivelor strategice asumate; dezvoltă inițiative pentru valorificarea resurselor de infrastructură și a capacității umane a instituției; asigură participarea și implicarea factorilor interesați în adresarea provocărilor specifice — lipsa resurselor, sprijin socioeconomic etc.; introduce soluții inovatoare validate și evaluează impactul lor asupra rezultatelor elevilor; promovează cultura experimentării responsabile și a îmbunătățirii continue; reprezintă public instituția într-un mod coerent, profesionist și convingător.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"C39","theme":"C","prompt":"Un inspector observă diferențe între programa oficială și aplicare și discută cu echipa soluții adaptate. Ce dimensiune a rolului său se evidențiază?","options":["Consilierea pentru implementarea curriculumului.","Eliminarea oricărei autonomii în proiectarea didactică.","Înlocuirea competențelor cu o listă de achiziții materiale.","Substituirea profesorului în fiecare decizie zilnică."],"answer":0,"explanation":"Rolul inspectorului include sprijinul și consilierea privind coerența implementării, nu numai verificarea formală a documentelor.","source":{"title":"CRCNR · capitolul 10 · OMEC nr. 4.137/2026","locator":"Capitolul 10","quote":"a reflecției asupra întregului proces de aplicare a curriculumului în școală și de evaluare a impactului acestuia asupra învățării. Inspectorul școlar – consilier pentru managementul curriculumului la nivelul școlii. În transpunerea CN la nivelul fiecărei școli, inspectorul școlar are roluri precum: consilierea echipei manageriale, a echipelor de profesori și a profesorilor, în proiectarea, implementarea și evaluarea CN; asigurarea coerenței dintre curriculumul oficial și cel aplicat în școală; dezvoltarea, selectarea și aplicarea de instrumente de monitorizare a implementării CN, relevante pentru curriculumul centrat pe competențe; monitorizarea implementării CN, prin","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/curriculum-capitolul-10/","official":"https://legislatie.just.ro/Public/DetaliiDocument/311403"}},{"id":"L98","theme":"L","prompt":"În analiza unei sancțiuni disciplinare pentru un profesor se propune reducerea salariului cu 20% pentru șase luni. Care plafon procentual este prevăzut la articolul 210?","options":["Până la 15%, pe o perioadă de 1–6 luni.","Până la 20%, pe o perioadă de 1–6 luni.","Până la 25%, pe o perioadă de 1–6 luni.","Până la 30%, pe o perioadă de 1–6 luni."],"answer":0,"explanation":"Pentru această sancțiune, legea prevede reducerea salariului de bază, cumulat când e cazul cu indemnizația, cu până la 15%, pentru 1–6 luni.","source":{"title":"Legea nr. 198/2023","locator":"Art. 210 alin. (1) lit. b)","quote":"a) avertisment scris; b) reducerea salariului de bază, cumulat, când este cazul, cu indemnizația de conducere, de îndrumare și control, cu până la 15%, pe o perioadă de 1-6 luni; c) suspendarea, pe o perioadă de până la 3 ani, a dreptului de înscriere la un concurs pentru obținerea gradației de merit, pentru ocuparea unei funcții de conducere, de îndrumare și de control ori a unei funcții didactice superioare; d) suspendarea, pe o perioadă de până la 3 ani, a dreptului de a face parte din comisiile de organizare și desfășurare a examenelor naționale; e) desfacerea disciplinară a contractului individual de muncă. (2) Pentru abaterile disciplinare prevăzute la art. 209","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R98","theme":"R","prompt":"Consiliul reprezentativ al părinților dorește să colecteze cotizații în cont propriu, invocând că reprezintă toate clasele. Ce limită prevede ROFUIP?","options":["Are dreptul să colecteze orice sumă prin simplu vot intern.","Are dreptul să impună cotizații tuturor elevilor înscriși.","Nu are dreptul să colecteze cotizații, donații sau finanțări.","Nu are dreptul să participe la activități de voluntariat."],"answer":2,"explanation":"Consiliul reprezentativ este structură fără personalitate juridică, patrimoniu și buget propriu. Nu se confundă cu asociația de părinți constituită legal.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 166","quote":"comitetelor de părinți pe grupă/clasă din unitatea de învățământ, care nu are patrimoniu, nu are buget de venituri și cheltuieli, nu are dreptul de a colecta cotizații, donații și a primi finanțări de orice fel de la persoane fizice sau juridice. Se poate implica în activitățile unității de învățământ prin acțiuni cu caracter logistic – voluntariat. La nivelul fiecărei unități de învățământ se poate constitui asociația de părinți, în conformitate cu legislația în vigoare privind asociațiile și fundațiile, care reprezintă drepturile și interesele părinților/reprezentanților legali din unitatea de învățământ, membri ai acesteia.","prefixEllipsis":true,"suffixEllipsis":false,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B78","theme":"B","prompt":"Un administrator respinge o analiză didactică doar fiindcă autorul ei are funcție inferioară. Ce tensiune este evidențiată?","options":["Absența oricărei relații între cunoaștere și influență.","Identitatea necesară dintre funcția mai înaltă și orice expertiză.","Obligația de a înlocui criteriile profesionale cu rangul formal.","Tensiunea dintre autoritatea ierarhică și expertiza profesională."],"answer":3,"explanation":"Într-o organizație profesională, rangul nu oferă automat expertiză superioară în toate domeniile. Cele două surse de autoritate pot intra în tensiune.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 81","quote":"sunt susţinuţi în acest demers de autoritatea ce vine în virtutea poziţiei lor oficiale. Organizaţiile profesioniste au un etos diferit, expertiza fiind distribuită în cadrul instituţiei: Modelele tradiţionale de organizaţie şcolară favorizau ierarhia la vârfuri, ce concentrează puterea şi responsabilitatea de leadership în funcţia de director. Pe măsură ce","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"H40","theme":"H","prompt":"Elevii ascund greșelile și evită întrebările de teamă să nu fie umiliți. Ce condiție relațională ar sprijini învățarea?","options":["Un climat de încredere în care greșelile pot fi discutate fără ridiculizare.","Un climat în care fiecare întrebare este tratată ca dovadă de incapacitate.","Un climat în care participarea este înlocuită cu tăcerea obligatorie.","Un climat în care profesorul face publică orice dificultate personală."],"answer":0,"explanation":"Relațiile pozitive și încrederea favorizează solicitarea ajutorului și discutarea dificultăților de învățare.","source":{"title":"John Hattie · capitolul 9","locator":"Capitolul 9, secțiunea 15, p. 255–256","quote":"profesională care pune la îndoială presupunerile și teoriile profesorilor despre practica pedagogică poate fi foarte eficientă. Puterea relațiilor pozitive profesori-elevi este esențială pentru ca procesul de învățare să aibă loc. Această relație presupune ca elevilor să li se spună că profesorului îi pasă de formarea lor ca elevi și că este capabil „să le înțeleagă","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://concursdirectori.ro/hattie-invatarea-vizibila-capitolul-9-profesorul/#s15","original":"https://concursdirectori.ro/wp-content/uploads/2026/09/hattie-capitolul-9-original.pdf#page=31"}},{"id":"L99","theme":"L","prompt":"Pentru cercetarea disciplinară a unui profesor, directorul propune o comisie de numai două persoane. Ce componență numerică cere articolul 211?","options":["O comisie formată din 2–3 membri.","O comisie formată din 3–5 membri.","O comisie formată din 6–8 membri.","O comisie formată din 7–9 membri."],"answer":1,"explanation":"Comisia are 3–5 membri și respectă și condițiile de reprezentare sindicală sau a salariaților și de funcție prevăzute de lege. Numărul de două persoane este insuficient.","source":{"title":"Legea nr. 198/2023","locator":"Art. 211 alin. (2)","quote":"săvârșite de personalul didactic de predare din unitățile de învățământ, se constituie o comisie de cercetare disciplinară formată din 3-5 membri, dintre care unul reprezintă federația sindicală din care face parte persoana aflată în discuție sau este un reprezentant al salariaților, iar ceilalți au funcția cel puțin egală cu a celui care a săvârșit abaterea. În situația în care la nivelul unității de învățământ nu există suficienți salariați care au funcția didactică cel puțin egală cu a salariatului cercetat, comisia de cercetare se completează cu persoane care au cel puțin aceeași funcție, desemnate de către DJIP/DMBIP, la solicitarea conducerii unității de","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R99","theme":"R","prompt":"Consiliul reprezentativ al părinților are 18 membri, iar prima ședință nu întrunește cvorumul. Câți membri sunt necesari la ședința reconvocată?","options":["Doisprezece membri, adică două treimi din total.","Nouă membri, adică exact jumătate din total.","Șase membri, adică o treime din total.","Zece membri, adică jumătate plus unu din total."],"answer":3,"explanation":"Prima ședință necesită două treimi. Pentru ședința reconvocată, ROFUIP cere jumătate plus unu din total: 10 din 18 membri.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 167","quote":"hotărârile se adoptă prin vot deschis, cu majoritatea simplă a voturilor celor prezenți. În situația în care nu se întrunește cvorumul, ședința se reconvoacă pentru o dată ulterioară, fiind statutară în prezența a jumătate plus 1 din totalul membrilor. Președintele reprezintă consiliul reprezentativ al părinților/reprezentanților legali în relația cu alte persoane fizice și juridice. Președintele prezintă, anual, raportul de activitate al consiliului reprezentativ al părinților/reprezentanților legali. În situații obiective, cum ar fi calamități, intemperii, epidemii, pandemii, alte situații excepționale, ședințele consiliului reprezentativ al părinților/reprezentanților legali","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B79","theme":"B","prompt":"Un plan promite „îmbunătățirea educației”, dar nu permite distingerea succesului de eșec. Ce dificultate a modelului rațional devine evidentă?","options":["Absența oricărei nevoi de negociere a scopurilor.","Ambiguitatea și lipsa preciziei obiectivelor.","Comparabilitatea perfectă a tuturor alternativelor.","Existența unor criterii operaționale prea clare."],"answer":1,"explanation":"Obiectivele educaționale pot fi generale, vagi sau contestate, ceea ce complică luarea deciziilor strict raționale.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 79","quote":"obiectivelor unei instituţii educaţionale. Obiectivele formale pot avea o relevanţă operaţională scăzută, pentru că sunt deseori vagi şi generale, deoarece pot fi obiective diferite ce necesită aceleaşi resurse, scopurile putând fi stabilite de indivizi sau grupuri sau chiar de liderii organizaţiei. Cum am menţionat anterior (p. 71), obiectivele pot","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}},{"id":"P40","theme":"P","prompt":"O inițiativă educațională are nevoie de finanțare suplimentară. Directorul pregătește o aplicație și negociază susținere cu parteneri externi. Ce competență este predominantă?","options":["Antreprenoriat educațional și inovație","Atragerea de resurse extrabugetare","Managementul resurselor umane","Relaționare, comunicare și gestionarea conflictelor"],"answer":1,"explanation":"Cazul urmărește explicit atragerea de resurse extrabugetare, nu doar participarea la o rețea sau administrarea unei alocări deja existente.","source":{"title":"Profilul profesional · OMEC nr. 3.934/2026","locator":"5.4. Atragerea de resurse extrabugetare","quote":"Captează resurse financiare și materiale din comunitate, activând sectorul privat și nonguvernamental, și asigură coerența dintre obiectivele instituționale și activitățile de fundraising și parteneriat. identifică surse de finanțare extrabugetară și inițiază aplicații de proiect relevante pentru nevoile școlii; captează resurse financiare și materiale din comunitate, activând sectorul privat și nonguvernamental; utilizează tehnici de negociere și mediere în gestionarea parteneriatelor; asigură coerența dintre obiectivele instituționale și activitățile de fundraising; coordonează implementarea proiectelor externe și asigură continuitatea după finalizarea finanțării; menține legătura cu comunitatea și promovează imaginea instituției la nivel local și regional; încurajează participarea comunității în proiecte educaționale.","prefixEllipsis":false,"suffixEllipsis":true,"url":"https://legislatie.just.ro/Public/DetaliiDocument/311191","study":"https://concursdirectori.ro/profilul-profesional-al-managerului-scolar/"}},{"id":"L100","theme":"L","prompt":"Un profesor refuză audierea, deși a fost înștiințat în scris cu minimum 48 de ore înainte. Conducerea consideră că cercetarea nu mai poate fi finalizată. Ce prevede legea?","options":["Refuzul anulează automat sesizarea și toate actele de cercetare.","Refuzul înlocuiește automat cercetarea cu sancțiunea maximă.","Refuzul se consemnează în proces-verbal și nu împiedică finalizarea.","Refuzul transferă automat cercetarea comitetului de părinți."],"answer":2,"explanation":"Audierea și verificarea apărării sunt obligatorii, dar refuzul persoanei legal înștiințate se constată în proces-verbal și nu blochează finalizarea cercetării.","source":{"title":"Legea nr. 198/2023","locator":"Art. 212 alin. (1)","quote":"și verificarea apărării acestuia sunt obligatorii. Refuzul celui cercetat de a se prezenta la audiere, deși a fost înștiințat în scris cu minimum 48 de ore înainte, precum și de a da declarații scrise se constată prin proces-verbal și nu împiedică finalizarea cercetării. Cadrul didactic cercetat are dreptul să cunoască toate actele cercetării și să își producă probe în apărare. (2) Cercetarea faptei și comunicarea deciziei se fac în termen de cel mult 30 de zile de la data înregistrării raportului de cercetare disciplinară, la registratura generală a unității de învățământ preuniversitar, fiindu-i adusă la cunoștință persoanei de către conducătorul instituției după aprobarea","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/271896","study":"https://ccecp.github.io/legea_educatiei_1_20/"}},{"id":"R100","theme":"R","prompt":"În protocolul de practică cu un operator economic nu se precizează nimic despre securitatea elevilor sau transport. Ce trebuie completat potrivit ROFUIP?","options":["Doar lista elevilor, fără precizarea drepturilor sau îndatoririlor acestora.","Exclusiv data semnării, fără responsabilități privind sănătatea în muncă.","Exclusiv numele sponsorului, fără responsabilități privind deplasarea elevilor.","Responsabilități clare privind securitatea, transportul și celelalte condiții prevăzute."],"answer":3,"explanation":"Protocolul stabilește clar responsabilitățile privind securitatea, sănătatea în muncă, transportul, durata activităților și drepturile/îndatoririle, între celelalte aspecte enumerate.","source":{"title":"ROFUIP · OME nr. 5.726/2024","locator":"Art. 179","quote":"securității beneficiarilor primari și a personalului unității de învățământ, respectarea normelor de sănătate și securitate în muncă, asigurarea transportului la și de la operatorul economic, durata activităților, drepturile și îndatoririle beneficiarilor primari, utilizarea fondurilor realizate, cu respectarea prevederilor legale în vigoare. De asemenea, unitățile de învățământ profesional și tehnic încheie parteneriate și protocoale de colaborare cu operatorii economici, în vederea derulării orelor de instruire practică. Unitățile de învățământ preuniversitar cu personalitate juridică ce școlarizează în învățământ profesional și tehnic dual încheie contracte de parteneriat cu","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://legislatie.just.ro/public/DetaliiDocument/286955","study":"https://ccecp.github.io/rofuip-in-cifre/grila/"}},{"id":"B80","theme":"B","prompt":"Un director folosește organigrama pentru responsabilități, perspectiva culturală pentru tradiții și cea politică pentru negocieri. Ce concluzie justifică alegerea?","options":["Folosirea mai multor modele exclude orice analiză riguroasă.","Modelele oferă explicații parțiale care se pot completa.","Toate modelele trebuie aplicate ca reguli juridice obligatorii.","Un singur model explică obligatoriu toate aspectele școlii."],"answer":1,"explanation":"Fiecare model surprinde anumite dimensiuni ale organizației. Combinarea critică a perspectivelor poate oferi o analiză mai adecvată.","source":{"title":"Tony Bush · capitolele I–III","locator":"Capitolul 3, p. 83","quote":"ale teoriilor formale. Totuşi, aceste perspective alternative nu au reuşit să elimine modelele formale, care rămân valide ca descrieri parţiale ale organizaţiei şi managementului în educaţie. Modelele formale sunt inadecvate, însă au în continuare o mare contribuţie pentru ca şcolile şi colegiile să poată fi înţelese ca organizaţii. Owens şi Shakeshaft (1992)","prefixEllipsis":true,"suffixEllipsis":true,"url":"https://ccecp.github.io/Bush_1/","study":"https://ccecp.github.io/Bush_1/"}}]}],"series":[{"from":1,"to":10,"title":"Seria I"},{"from":11,"to":20,"title":"Seria II · aspecte legislative noi"}]};
